  "sources": ["../src/server/readModel/redisConfig.ts", "../src/server/readModel/boundedRedis.ts", "../src/server/services/adminReviewCache.ts", "../src/server/services/retiredFixtureService.ts", "../src/server/services/durableReadCosts.ts", "../src/lib/matchdayState.ts", "../src/lib/seasonQualificationPolicy.ts", "../src/server/readModel/sharedReadRefresh.ts", "../src/server/firebase/circuitBreaker.ts", "../src/server/firebase/admin.ts", "../src/server/firebase/collections.ts", "../src/server/db/migrateFixtures.ts", "../src/server/db/index.ts", "../src/constants/top5Clubs.ts", "../src/server/db/seed.ts", "../src/server/services/fixtureTombstoneService.ts", "../src/types/trophies.ts", "../src/server/services/seasonInsightsService.ts", "../src/server/services/playerTrophyService.ts", "../src/server/services/adminService.ts", "../src/server/services/notificationService.ts", "../src/server/services/telegramBotService.ts", "../src/server/services/telegramAiDeadline.ts", "../src/server/services/telegramAiConfigService.ts", "../src/server/services/telegramAiCustomEmoji.ts", "../src/server/services/notificationBackupQueue.ts", "../src/lib/telegramUtils.ts", "../src/lib/ownerUtils.ts", "../src/lib/tournamentImage.ts", "../src/server/services/tournamentImageRenderer.ts", "../src/server/services/telegramNotificationQueue.ts", "../src/server/services/smartNotificationSettingsService.ts", "../src/server/services/telegramMiniAppButton.ts", "../src/server/services/smartNotificationService.ts", "../src/server/tournament/standingsProjection.ts", "../src/server/tournament/qualificationEngine.ts", "../src/server/services/competitionFixtureCounts.ts", "../src/server/services/approvedFixtureRestoration.ts", "../src/server/readModel/readModelStore.ts", "../src/server/services/notificationVisibility.ts", "../src/server/services/notificationReadState.ts", "../src/server/services/leaguePairIntegrity.ts", "../src/server/tournament/standingsEngine.ts", "../src/server/db/sqliteStandings.ts", "../src/server/services/premiumClubRule.ts", "../src/server/services/clubAdmission.ts", "../src/server/firebase/occupancySnapshot.ts", "../src/server/utils/testGuard.ts", "../src/server/outbox/redisOutbox.ts", "../src/server/tournament/domesticCupService.ts", "../src/server/tournament/knockoutEngine.ts", "../src/server/sync/mutationQueue.ts", "../src/server/tournament/fixtureEngine.ts", "../src/lib/tournamentImageBranding.ts", "../src/server/services/matchdayChannelPost.ts", "../src/server/services/competitionMatchdayService.ts", "../src/server/services/disputeResolution.ts", "../src/server/firebase/firestoreStore.ts", "../src/server/auth/sessionToken.ts", "../src/server/auth/telegramAuth.ts", "../src/lib/adminPermissions.ts", "../src/server/services/adminDangerZone.ts", "../src/lib/userSearch.ts", "../src/server/services/adminUserDirectory.ts", "../src/server/services/leagueAdminScope.ts", "../src/server/middleware/authMiddleware.ts", "../src/server/middleware/validationMiddleware.ts", "../src/server/firebase/firestoreErrorHandler.ts", "../src/server/middleware/ownershipCacheControl.ts", "../src/server/tournament/domesticCupRoundOps.ts", "../src/server/services/seasonLifecycleService.ts", "../src/server/services/quotaReadCache.ts", "../src/server/services/matchOperationsV4Service.ts", "../src/lib/fixtureOrder.ts", "../src/server/services/seasonOperationsService.ts", "../src/server/services/premiumBadgeService.ts", "../src/server/services/premiumService.ts", "../src/server/services/seasonArchiveService.ts", "../src/server/routes/seasonOperations.routes.ts", "../src/server/routes/adminCupDraw.routes.ts", "../src/server/routes/adminCupOps.routes.ts", "../src/server/routes/adminMatchControl.routes.ts", "../src/server/routes/adminNotifications.routes.ts", "../src/server/firebase/migrateSqliteToFirestore.ts", "../src/server/services/matchdayReminderService.ts", "../src/server/services/recipientDirectoryRefreshService.ts", "../src/server/services/scopedAdminReviews.ts", "../src/server/services/missingLeaguePairRepair.ts", "../src/server/routes/admin.routes.ts", "../src/server/services/telegramAiRateLimitService.ts", "../src/server/services/telegramAiAdminAccess.ts", "../src/server/services/telegramAiAdminDraft.ts", "../src/server/services/telegramAiEntities.ts", "../src/server/services/telegramAiSnapshotReader.ts", "../src/server/services/telegramAiCupStage.ts", "../src/server/services/telegramAiDataService.ts", "../src/server/services/telegramAiAdminCatalog.ts", "../src/server/services/telegramAiControlLanguage.ts", "../src/server/services/telegramAiAdminLanguage.ts", "../src/server/services/telegramAiAdminClarification.ts", "../src/server/services/telegramAiPlanRevision.ts", "../src/server/services/telegramAiCommunitySources.ts", "../src/server/services/telegramAiGroundingService.ts", "../src/server/services/telegramAiPersonality.ts", "../src/server/services/telegramAiPrompt.ts", "../src/server/services/telegramAiReadTools.ts", "../src/server/services/telegramAiFallback.ts", "../src/server/routes/consistencyGuard.routes.ts", "../src/server/routes/seasonLifecycle.routes.ts", "../src/server/routes/adminAiConfig.routes.ts", "../src/server/services/telegramAiAdminGateway.ts", "../src/server/services/telegramAiAdminReadTools.ts", "../src/server/services/telegramAiConversationCommands.ts", "../src/server/services/telegramAiNaturalAdminPlanner.ts", "../src/server/services/telegramAiAdminPlanReadiness.ts", "../src/server/services/telegramAiAdminRecordResolver.ts", "../src/server/services/telegramAiAdminOutcome.ts", "../src/server/services/telegramAiFixtureContext.ts", "../src/server/services/telegramAiAdminService.ts", "../src/server/services/telegramAiPersonalFixtureService.ts", "../src/server/services/telegramAiService.ts", "../src/server/routes/telegram.routes.ts", "../src/server/routes/tournamentImageDownload.routes.ts", "../src/server/services/tournamentImageDownload.ts", "../src/server/app.ts", "../src/server/middleware/rateLimitMiddleware.ts", "../src/server/sync/scheduleReconciliation.ts", "../src/server/routes/health.routes.ts", "../src/server/routes/auth.routes.ts", "../src/server/services/dashboardLeagueStatsService.ts", "../src/server/routes/seasons.routes.ts", "../src/server/routes/leagues.routes.ts", "../src/server/routes/clubs.routes.ts", "../src/server/services/durableClubClaim.ts", "../src/server/routes/competitions.routes.ts", "../src/server/routes/fixtures.routes.ts", "../src/server/routes/notificationsReadResilient.routes.ts", "../src/server/routes/me.routes.ts", "../src/server/services/myMatchesCanonicalService.ts", "../src/server/services/myMatchesReadService.ts", "../src/server/routes/users.routes.ts", "../src/server/routes/seasonInsights.routes.ts", "../src/server/routes/seasonOperationsConsistency.routes.ts", "../src/server/routes/premiumPrivate.routes.ts", "../src/server/services/premiumSmartNotificationService.ts", "../src/server/routes/customTournaments.routes.ts", "../src/server/services/customTournamentService.ts", "../src/server/services/customTournamentTicketService.ts", "../src/server/services/customTournamentEngine.ts", "../src/server/routes/customTournamentTickets.routes.ts", "../src/server/apiEntry.ts"],
  "sourcesContent": ["/** Resolve complete credential pairs, including Vercel Marketplace custom prefixes. */\nexport function resolveRedisConfig(env: Record<string, string | undefined>) {\n  const pairs = [\n    ['UPSTASH_REDIS_REST_URL', 'UPSTASH_REDIS_REST_TOKEN'],\n    ['KV_REST_API_URL', 'KV_REST_API_TOKEN'],\n  ];\n  const valid = ([urlName, tokenName]: string[]) => {\n    const url = env[urlName]?.trim();\n    const token = env[tokenName]?.trim();\n    if (!url || !token || /your-upstash|example/.test(url)) return null;\n    try { if (new URL(url).protocol !== 'https:') return null; } catch { return null; }\n    return { url, token, urlName, tokenName };\n  };\n  for (const pair of pairs) {\n    const config = valid(pair);\n    if (config) return config;\n  }\n  const custom = Object.keys(env).filter(name => !name.startsWith('NOTIFICATION_BACKUP_') && /_(?:UPSTASH_REDIS_REST_URL|KV_REST_API_URL)$/.test(name))\n    .map(name => valid([name, name.replace(/URL$/, 'TOKEN')])).filter(value => value !== null);\n  // Never guess which database to use when multiple integrations are configured.\n  return custom.length === 1 ? custom[0] : null;\n}\n", "import { Redis } from '@upstash/redis';\nimport { resolveRedisConfig } from './redisConfig';\n\n/** Optional cache/telemetry transport: one bounded attempt, never retries. */\nexport function getBoundedRedisClient(): Redis | null {\n  const config = resolveRedisConfig(process.env);\n  return config ? new Redis({ url: config.url, token: config.token, retry: false, enableAutoPipelining: false, signal: () => AbortSignal.timeout(1200) }) : null;\n}\n", "import { waitUntil } from '@vercel/functions';\nimport { randomUUID } from 'node:crypto';\nimport { getBoundedRedisClient } from '../readModel/boundedRedis';\n\nconst flights = new Map<string, Promise<any>>();\nconst localResults = new Map<string, { result: SharedResult; savedAt: number; epoch: number }>();\nconst epochKey = 'efluz:v1:admin:read-epoch';\nlet localEpoch = 0;\nlet invalidating: Promise<void> | null = null;\n/** Cache invalidation never replaces the authoritative authorization check. */\nexport function invalidateSharedAdminData(): Promise<void> {\n  localEpoch++;\n  localResults.clear();\n  if (invalidating) return invalidating;\n  const client = getBoundedRedisClient();\n  const work = (async () => {\n    if (!client) return;\n    let flushed;\n    do {\n      flushed = localEpoch;\n      await client.incr(epochKey);\n    } while (flushed !== localEpoch);\n  })().catch(() => { console.warn('[ADMIN_READ_CACHE_INVALIDATION_UNAVAILABLE]'); });\n  invalidating = work;\n  void work.finally(() => { if (invalidating === work) invalidating = null; });\n  if (process.env.VERCEL === '1') waitUntil(work);\n  return work;\n}\n\nexport const ADMIN_REVIEW_CACHE_PUBLISH_LUA = `\nif redis.call('GET', KEYS[1]) ~= ARGV[1] then return 0 end\nif (redis.call('GET', KEYS[4]) or '0') ~= ARGV[5] then return 0 end\nredis.call('SET', KEYS[2], ARGV[2], 'EX', ARGV[3] or 10)\nredis.call('SET', KEYS[3], ARGV[2], 'EX', ARGV[4] or 300)\nredis.call('DEL', KEYS[1])\nreturn 1\n`;\nconst unlock = `if redis.call('GET', KEYS[1]) == ARGV[1] then return redis.call('DEL', KEYS[1]) end return 0`;\ntype Result = { pendingFixtures: any[]; submissions: any[]; disputes: any[]; degraded: boolean; stale: boolean; source: string };\ntype SharedResult = { degraded: boolean; stale: boolean; source: string };\nfunction decode<T extends SharedResult>(value: unknown): { result: T; savedAt: number } | null {\n  try {\n    const entry = typeof value === 'string' ? JSON.parse(value) : value;\n    return entry && typeof (entry as any).result?.degraded === 'boolean' && typeof (entry as any).result?.stale === 'boolean' && typeof (entry as any).result?.source === 'string' && Number.isFinite((entry as any).savedAt) ? entry as any : null;\n  } catch { return null; }\n}\n/** Scope hash is server-derived; a distributed lease prevents instance fan-out.\n * A five-minute fallback is always labelled stale and never authorizes writes. */\nexport function readSharedAdminData<T extends SharedResult>(key: string, loader: () => Promise<T>, ttlSeconds = 10, fallbackSeconds = 300, bypassFresh = false): Promise<T> {\n  const flightKey = key + \":local:\" + localEpoch;\n  if (flights.has(flightKey)) return flights.get(flightKey)!;\n  const work = (async () => {\n    if (invalidating) await invalidating;\n    const generation = localEpoch;\n    const remember = (result: T) => {\n      if (!result.stale && !result.degraded && generation === localEpoch) {\n        if (localResults.size >= 128 && !localResults.has(key)) localResults.delete(localResults.keys().next().value!);\n        localResults.set(key, { result, savedAt: Date.now(), epoch: generation });\n      }\n      return result;\n    };\n    const loadLocally = async () => {\n      const saved = localResults.get(key);\n      if (!bypassFresh && saved && saved.epoch === localEpoch && Date.now() - saved.savedAt < ttlSeconds * 1000) return { ...saved.result, stale: true, degraded: true, source: 'process_stale' } as T;\n      return remember(await loader());\n    };\n    const client = getBoundedRedisClient();\n    if (!client) return loadLocally();\n    let epoch = '0';\n    try { epoch = String(await client.get(epochKey) || '0'); } catch { return loadLocally(); }\n    const scopedKey = key + ':epoch:' + epoch;\n    const freshKey = scopedKey + ':fresh', lkgKey = scopedKey + ':lkg', lockKey = scopedKey + ':lock';\n    let acquired = false;\n    const owner = randomUUID();\n    try {\n      const cached = decode<T>(await client.get(freshKey));\n      if (!bypassFresh && cached && Date.now() - cached.savedAt < ttlSeconds * 1000) return remember(cached.result);\n      acquired = Boolean(await client.set(lockKey, owner, { nx: true, ex: 30 }));\n      if (!acquired) {\n        for (let i = 0; i < 10; i++) {\n          await new Promise(resolve => setTimeout(resolve, 50));\n          const ready = decode<T>(await client.get(freshKey));\n          if (ready && Date.now() - ready.savedAt < ttlSeconds * 1000) return remember(ready.result);\n        }\n        const last = decode<T>(await client.get(lkgKey));\n        if (last && Date.now() - last.savedAt < fallbackSeconds * 1000) return { ...last.result, stale: true, degraded: true, source: 'redis_stale' };\n        throw new Error('ADMIN_REVIEWS_REFRESHING');\n      }\n    } catch (error) {\n      if ((error as Error).message === 'ADMIN_REVIEWS_REFRESHING') throw error;\n      // Redis outage retains the existing local/coalesced read path.\n      return loadLocally();\n    }\n    try {\n      const result = remember(await loader());\n      if (!result.degraded && !result.stale && generation === localEpoch) await client.eval(ADMIN_REVIEW_CACHE_PUBLISH_LUA, [lockKey, freshKey, lkgKey, epochKey], [owner, JSON.stringify({ result, savedAt: Date.now() }), ttlSeconds, fallbackSeconds, epoch]).catch(() => undefined);\n      return result;\n    } finally {\n      if (acquired) await client.eval(unlock, [lockKey], [owner]).catch(() => undefined);\n    }\n  })();\n  flights.set(flightKey, work);\n  void work.finally(() => { if (flights.get(flightKey) === work) flights.delete(flightKey); }).catch(() => undefined);\n  return work;\n}\n\nexport function readSharedAdminReview(key: string, loader: () => Promise<Result>): Promise<Result> {\n  return readSharedAdminData(key, loader);\n}\n", "/** Explicit correction of a verified production duplicate, approved by the\n * tournament owner. Canonical round: Matchday 10. Original ID, score, proof and\n * submissions are preserved. Storage is retained for audit/recovery; the\n * accidental round-10 copy cannot be listed, played or used to block progression.\n * This is deliberately not a general pair deduplicator: cup rematches and other\n * seasons must remain intact. No startup writes or additional Firestore reads.\n */\nexport const RETIRED_FIXTURES = [{\n  id: 'fix-comp-serie-a-2026-md10-inter-vs-milan',\n  seasonId: 'season-2026-27',\n  competitionId: 'comp-serie-a-2026',\n  retainedFixtureId: 'fix-comp-serie-a-2026-md1-inter-vs-milan',\n  matchday: 10,\n  roundName: 'Matchday 10',\n  scheduledAt: '2026-10-17T15:00:00.000Z',\n}] as const;\n\nexport function isRetiredFixture(id: string, seasonId?: string): boolean {\n  return RETIRED_FIXTURES.some(row => row.id === id && (!seasonId || row.seasonId === seasonId));\n}\n\nexport function correctFixtureMatchday<T extends { id: string; seasonId?: string }>(fixture: T, seasonId?: string): T {\n  const correction = RETIRED_FIXTURES.find(row => row.retainedFixtureId === fixture.id && ((!fixture.seasonId && !seasonId) || row.seasonId === (fixture.seasonId || seasonId)));\n  return correction ? { ...fixture, matchday: correction.matchday, roundName: correction.roundName, scheduledAt: correction.scheduledAt, competitionName: 'Serie A' } : fixture;\n}\n\nexport function hasFixtureMatchdayCorrection(competitionId: string, seasonId: string): boolean {\n  return RETIRED_FIXTURES.some(row => row.competitionId === competitionId && row.seasonId === seasonId);\n}\n\nexport function filterRetiredFixtures<T extends { id: string; seasonId?: string }>(fixtures: T[], seasonId?: string): T[] {\n  return fixtures.filter(fixture => !isRetiredFixture(fixture.id, fixture.seasonId || seasonId)).map(fixture => correctFixtureMatchday(fixture, seasonId));\n}\n\nexport function assertFixtureNotRetired(id: string): void {\n  if (isRetiredFixture(id)) {\n    throw Object.assign(new Error('Bu o\u2018yinning tasdiqlangan natijasi Matchday 10 ga biriktirilgan. Takroriy o\u2018yinga natija kiritib bo\u2018lmaydi.'), {\n      code: 'FIXTURE_RETIRED', statusCode: 409,\n    });\n  }\n}\n", "import { AsyncLocalStorage } from 'node:async_hooks';\nimport { waitUntil } from '@vercel/functions';\nimport type { Request, Response, NextFunction } from 'express';\nimport { getBoundedRedisClient } from '../readModel/boundedRedis';\n\ntype Buckets = Map<number, Map<string, number>>;\ntype CostContext = { buckets: Buckets; closed: boolean; endpoint: () => string };\nconst context = new AsyncLocalStorage<CostContext>();\nconst prefix = 'efluz:v1:read-cost:';\nconst hourKey = (time: number) => prefix + new Date(time).toISOString().slice(0, 13);\nexport const READ_COST_INCREMENT_LUA = `\nfor i = 1, #ARGV, 2 do redis.call('HINCRBY', KEYS[1], ARGV[i], ARGV[i + 1]) end\nredis.call('EXPIRE', KEYS[1], 604800)\nreturn 1\n`;\nfunction add(entries: Map<string, number>, key: string, amount: number) { entries.set(key, (entries.get(key) || 0) + amount); }\nfunction label(value: string) { return value.replace(/[^a-zA-Z0-9_:/ .-]/g, '_').slice(0, 120) || 'unknown'; }\nfunction collect(buckets: Buckets, collection: string, count: number, caller: string) {\n  const hour = Math.floor(Date.now() / 3600000) * 3600000;\n  let entries = buckets.get(hour);\n  if (!entries) { entries = new Map(); buckets.set(hour, entries); }\n  add(entries, 'totalReads', count);\n  add(entries, 'collection:' + label(collection), count);\n  add(entries, 'caller:' + label(caller), count);\n}\nasync function persist(entries: Map<string, number>, endpoint: string, time = Date.now()) {\n  const total = entries.get('totalReads') || 0;\n  if (!total) return;\n  const client = getBoundedRedisClient();\n  if (!client) return;\n  const values = new Map(entries);\n  add(values, 'requestsWithReads', 1);\n  add(values, 'endpoint:' + label(endpoint), total);\n  await client.eval(READ_COST_INCREMENT_LUA, [hourKey(time)], [...values].flatMap(([key, value]) => [key, value]));\n}\nasync function persistBuckets(buckets: Buckets, endpoint: string) {\n  await Promise.all([...buckets].map(([time, entries]) => persist(entries, endpoint, time)));\n}\nfunction keepAlive(work: Promise<unknown>) {\n  const safe = work.catch(() => { console.warn('[READ_COST_TELEMETRY_UNAVAILABLE] Redis write failed; no Firestore fallback.'); });\n  if (process.env.VERCEL === '1') waitUntil(safe);\n  else void safe;\n}\nlet background: Buckets | null = null;\n/** Existing tracked reads only, not the Firebase billing counter. No user data. */\nexport function recordDurableRead(collection: string, count: number, caller: string) {\n  if (!Number.isSafeInteger(count) || count <= 0) return;\n  const active = context.getStore();\n  if (active && !active.closed) { collect(active.buckets, collection, count, caller); return; }\n  if (!background) {\n    background = new Map();\n    const buffer = background;\n    keepAlive(new Promise(resolve => setTimeout(resolve, 100)).then(async () => {\n      if (background === buffer) background = null;\n      await persistBuckets(buffer, 'background');\n    }));\n  }\n  collect(background, collection, count, caller);\n}\n/** Runs before auth/initialization so reads caused by either are attributed. */\nexport function readCostMiddleware(req: Request, res: Response, next: NextFunction) {\n  const active: CostContext = {\n    buckets: new Map(), closed: false,\n    // Route templates only: never raw URLs, IDs, search strings or usernames.\n    endpoint: () => `${req.method} ${req.baseUrl || ''}${typeof req.route?.path === 'string' ? req.route.path : '/unmatched'}`,\n  };\n  const finish = () => {\n    if (active.closed) return;\n    active.closed = true;\n    keepAlive(persistBuckets(active.buckets, active.endpoint()));\n  };\n  res.once('finish', finish); res.once('close', finish);\n  context.run(active, next);\n}\nexport async function getDurableReadCosts(from?: string, to?: string) {\n  const until = to ? Date.parse(to) : Date.now();\n  const since = from ? Date.parse(from) : until - 24 * 3600000;\n  if (!Number.isFinite(since) || !Number.isFinite(until) || until <= since || until - since > 24 * 3600000 || since < Date.now() - 7 * 86400000 || until > Date.now() + 60000)\n    throw new Error('INVALID_READ_COST_WINDOW');\n  const hours: number[] = [];\n  for (let time = Math.floor(since / 3600000) * 3600000; time < until; time += 3600000) hours.push(time);\n  const base = { from: new Date(since).toISOString(), to: new Date(until).toISOString(), timezone: 'Asia/Tashkent', retentionDays: 7, resolution: 'hour', coverage: 'instrumented reads; not Firebase billing; collection reads without tracking are excluded', bucketPolicy: 'full overlapping UTC hours; reads attributed when recorded' };\n  const client = getBoundedRedisClient();\n  if (!client) return { ...base, available: false, hours: [] };\n  try {\n    const pipeline = client.pipeline();\n    for (const time of hours) pipeline.hgetall(hourKey(time));\n    const rows = await pipeline.exec<Record<string, number | string>[]>();\n    const totals = new Map<string, number>();\n    const windows = hours.map((time, index) => {\n      const values = rows[index] || {};\n      for (const [field, value] of Object.entries(values)) if (Number.isFinite(Number(value))) add(totals, field, Number(value));\n      const group = (kind: string) => Object.fromEntries(Object.entries(values).filter(([key]) => key.startsWith(kind + ':')).map(([key, value]) => [key.slice(kind.length + 1), Number(value)]));\n      return { utcHour: new Date(time).toISOString(), tashkentHour: new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Tashkent', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', hourCycle: 'h23' }).format(time), observed: Object.keys(values).length > 0, totalReads: Number(values.totalReads || 0), requestsWithReads: Number(values.requestsWithReads || 0), byEndpoint: group('endpoint'), byCollection: group('collection'), byCaller: group('caller') };\n    });\n    const group = (kind: string) => Object.fromEntries([...totals].filter(([key]) => key.startsWith(kind + ':')).map(([key, value]) => [key.slice(kind.length + 1), value]));\n    return { ...base, available: true, totalReads: totals.get('totalReads') || 0, requestsWithReads: totals.get('requestsWithReads') || 0, byEndpoint: group('endpoint'), byCollection: group('collection'), byCaller: group('caller'), hours: windows };\n  } catch { return { ...base, available: false, hours: [] }; }\n}\n", "export interface MatchdayGate {\n  overrideStatus?: string;\n  isOpen?: boolean;\n  isLocked?: boolean;\n  expiresAt?: string | null;\n}\n\nexport interface MatchdayControlOverview {\n  competitionId: string;\n  currentMatchday: number;\n  updatedAt: string | null;\n  totalMatchdays: number;\n  rounds: { matchday: number; isOpen: boolean; deadlineAt: string | null; fixtureCount: number; unfinished: { id: string; status: string }[] }[];\n}\nexport type MatchdayControlAction = 'SELECT' | 'OPEN' | 'LOCK' | 'EXTEND' | 'RESTART';\n\n// null means no explicit round rule: the competition's active round applies.\nexport function resolveMatchdayGate(lock?: MatchdayGate | null, now = Date.now()): boolean | null {\n  if (!lock) return null;\n  if (lock.overrideStatus === 'FORCE_LOCKED' || lock.overrideStatus === 'PAUSED' || lock.isLocked || lock.isOpen === false) return false;\n  if (lock.expiresAt && (!Number.isFinite(Date.parse(lock.expiresAt)) || Date.parse(lock.expiresAt) <= now)) return false;\n  if (lock.overrideStatus === 'FORCE_OPEN' || lock.isOpen === true) return true;\n  return null;\n}\n", "/** Owner-confirmed 2026/27 domestic allocations: 32 UCL and 32 UEL places. */\nexport const SEASON_2026_27_ALLOCATION:Readonly<Record<string,number>>=Object.freeze({\n  'comp-premier-league-2026':7,\n  'comp-la-liga-2026':7,\n  'comp-serie-a-2026':6,\n  'comp-bundesliga-2026':6,\n  'comp-ligue-1-2026':6,\n});\nexport function withSeasonQualificationPolicy<T extends {id:string;formatConfig?:any}>(competition:T,seasonId:string):T {\n  if(seasonId!=='season-2026-27')return competition;\n  const count=SEASON_2026_27_ALLOCATION[competition.id];\n  if(count!=null)return {...competition,formatConfig:{...competition.formatConfig,qualificationSpots:count,europaQualificationSpots:count}};\n  if(competition.id==='comp-champions-league-2026'||competition.id==='comp-europa-league-2026'){\n    