        },\n      };\n    }\n\n    async get() {\n      const col = getCol(this.colName);\n      let docs = Object.entries(col).map(([id, data]) => ({\n        id,\n        ref: new MemDocRef(this.colName, id),\n        exists: true,\n        data: () => JSON.parse(JSON.stringify(data)),\n      }));\n\n      // Apply where filters\n      for (const f of this.filters) {\n        docs = docs.filter((d) => {\n          const documentId = f.field === '__name__' || (f.field instanceof FieldPath && f.field.isEqual(FieldPath.documentId()));\n          const val = documentId ? d.id : d.data()[String(f.field)];\n          if (f.op === '==' || f.op === '===') return val === f.val;\n          if (f.op === '!=') return val !== f.val;\n          if (f.op === '>') return val > f.val;\n          if (f.op === '>=') return val >= f.val;\n          if (f.op === '<') return val < f.val;\n          if (f.op === '<=') return val <= f.val;\n          if (f.op === 'in') return Array.isArray(f.val) && f.val.includes(val);\n          return true;\n        });\n      }\n\n      // Apply orderBy\n      for (const o of this.orderBys) {\n        docs.sort((a, b) => {\n          const isDocIdField =\n            o.field === '__name__' ||\n            (typeof o.field === 'object' && o.field !== null) ||\n            String(o.field).includes('documentId');\n          const vA = isDocIdField ? a.id : a.data()[o.field];\n          const vB = isDocIdField ? b.id : b.data()[o.field];\n          if (vA < vB) return o.dir === 'asc' ? -1 : 1;\n          if (vA > vB) return o.dir === 'asc' ? 1 : -1;\n          return 0;\n        });\n      }\n\n      // Apply startAfter cursor\n      if (this.cursorVal) {\n        const idx = docs.findIndex((d) => d.id === this.cursorVal);\n        if (idx !== -1) {\n          docs = docs.slice(idx + 1);\n        }\n      }\n\n      // Apply limit\n      if (this.limitVal !== null) {\n        docs = docs.slice(0, this.limitVal);\n      }\n\n      return {\n        docs,\n        size: docs.length,\n        empty: docs.length === 0,\n      };\n    }\n  }\n\n  class MemCollectionRef extends MemQuery {\n    doc(id?: string) {\n      const docId = id || `doc_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;\n      return new MemDocRef(this.colName, docId);\n    }\n\n    async add(data: any) {\n      const docId = `doc_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;\n      const docRef = new MemDocRef(this.colName, docId);\n      await docRef.set(data);\n      return docRef;\n    }\n  }\n\n  class MemBatch {\n    private operations: Array<() => Promise<void>> = [];\n\n    create(docRef: any, data: any) {\n      this.operations.push(async () => {\n        if ((await docRef.get()).exists) throw new Error('ALREADY_EXISTS');\n        await docRef.set(data);\n      });\n      return this;\n    }\n\n    set(docRef: any, data: any, options?: any) {\n      this.operations.push(() => docRef.set(data, options));\n      return this;\n    }\n\n    update(docRef: any, data: any) {\n      this.operations.push(() => docRef.update(data));\n      return this;\n    }\n\n    delete(docRef: any) {\n      this.operations.push(() => docRef.delete());\n      return this;\n    }\n\n    async commit() {\n      const commit = txQueue.then(async () => {\n        const backup = JSON.parse(JSON.stringify(store));\n        try { for (const op of this.operations) await op(); }\n        catch (error) {\n          for (const key of Object.keys(store)) delete store[key];\n          Object.assign(store, backup);\n          throw error;\n        }\n      });\n      txQueue = commit.catch(() => {});\n      await commit;\n    }\n  }\n\n  return {\n    collection(name: string) {\n      return new MemCollectionRef(name);\n    },\n    batch() {\n      return new MemBatch();\n    },\n    async runTransaction(updateFunction: (transaction: any) => Promise<any>) {\n      // Serialize transactions in-memory to emulate Firestore transactional isolation\n      return new Promise((resolve, reject) => {\n        txQueue = txQueue.then(async () => {\n          try {\n            const writes: Array<() => Promise<void>> = [];\n            const tx = {\n              async get(docRef: any) {\n                return await docRef.get();\n              },\n              set(docRef: any, data: any, options?: any) {\n                writes.push(async () => {\n                  await docRef.set(data, options);\n                });\n                return tx;\n              },\n              update(docRef: any, data: any) {\n                writes.push(async () => {\n                  await docRef.update(data);\n                });\n                return tx;\n              },\n              delete(docRef: any) {\n                writes.push(async () => {\n                  await docRef.delete();\n                });\n                return tx;\n              },\n            };\n\n            const result = await updateFunction(tx);\n            // Atomic commit\n            for (const write of writes) {\n              await write();\n            }\n            resolve(result);\n          } catch (err) {\n            reject(err);\n          }\n        });\n      });\n    },\n    async listCollections() {\n      return Object.keys(store).map((name) => new MemCollectionRef(name));\n    },\n  };\n}\n", "export const COLLECTIONS = {\n  USERS: 'users',\n  SEASONS: 'seasons',\n  LEAGUES: 'leagues',\n  CLUBS: 'clubs',\n  SEASON_LEAGUE_CLUBS: 'season_league_clubs',\n  CLUB_MEMBERSHIPS: 'club_memberships',\n  CLUB_OCCUPANCIES: 'club_occupancies',\n  USER_MEMBERSHIPS: 'user_memberships',\n  COMPETITIONS: 'competitions',\n  COMPETITION_PARTICIPANTS: 'competition_participants',\n  FIXTURES: 'fixtures',\n  RESULT_SUBMISSIONS: 'result_submissions',\n  DISPUTES: 'disputes',\n  STANDINGS: 'standings',\n  NOTIFICATIONS: 'notifications',\n  AUDIT_LOGS: 'audit_logs',\n  MATCHDAY_LOCKS: 'matchday_locks',\n} as const;\n\nexport const ACTIVE_MEMBERSHIP_STATUS = 'active' as const;\n\nexport interface FirestoreUserDoc {\n  id: string;\n  telegramId: string;\n  username: string;\n  firstName: string;\n  lastName: string;\n  photoUrl?: string;\n  isAdmin: boolean;\n  adminPermissions?: import('../../types').AdminPermissions;\n  isSuspended: boolean;\n  createdAt: string;\n  updatedAt: string;\n}\n\nexport interface FirestoreSeasonDoc {\n  id: string;\n  name: string;\n  status: 'UPCOMING' | 'ACTIVE' | 'COMPLETED' | 'ARCHIVED';\n  startDate?: string;\n  endDate?: string;\n  createdAt: string;\n}\n\nexport interface FirestoreLeagueDoc {\n  id: string;\n  name: string;\n  country: string;\n  tier: number;\n  logo: string;\n  createdAt: string;\n}\n\nexport interface FirestoreClubDoc {\n  id: string;\n  name: string;\n  shortName: string;\n  leagueId: string;\n  country: string;\n  logo: string;\n  isActive: boolean;\n  createdAt: string;\n  isTaken?: boolean;\n  claimedByUserId?: string;\n  managerUsername?: string;\n}\n\nexport interface FirestoreClubMembershipDoc {\n  id: string;\n  seasonId: string;\n  clubId: string;\n  userId: string;\n  claimedAt: string;\n  status: 'active' | 'revoked' | 'transferred';\n  updatedAt?: string;\n}\n\nexport interface FirestoreCompetitionDoc {\n  id: string;\n  seasonId: string;\n  leagueId?: string;\n  name: string;\n  type: string;\n  scheduleMode: string;\n  status: string;\n  formatConfig?: any;\n  hasFixtures?: boolean;\n  fixtureCount?: number;\n  fixturesCount?: number;\n  generationStatus?: string;\n  currentMatchday?: number;\n  totalMatchdays?: number;\n  isMatchdayOpen?: boolean;\n  matchdayOpenedAt?: string;\n  matchdayDurationHours?: number;\n  nextMatchdayOpenAt?: string;\n  adminOverrideStatus?: 'AUTO' | 'FORCE_OPEN' | 'FORCE_LOCKED' | 'PAUSED';\n  createdAt: string;\n  updatedAt?: string;\n}\n\nexport interface FirestoreMatchdayLockDoc {\n  id: string; // Formatted strictly as: `${seasonId}*${competitionId}*${matchday}`\n  seasonId: string;\n  competitionId: string;\n 