ring;\n}\n\nexport interface FirestoreNotificationDoc {\n  id: string;\n  userId: string;\n  type: string;\n  title: string;\n  message: string;\n  isRead: boolean;\n  createdAt: string;\n}\n\nexport interface FirestoreStandingsDoc {\n  competitionId: string;\n  seasonId?: string;\n  updatedAt: string;\n  rows: import('../../types').StandingsRow[];\n  confirmedFixtureIds?: string[];\n  totalPlayed?: number;\n}\n\nexport interface FirestoreAuditLogDoc {\n  id: string;\n  actorUserId: string;\n  actorUsername: string;\n  action: string;\n  entityType: string;\n  entityId: string;\n  oldValueJson?: string | null;\n  newValueJson?: string | null;\n  ipAddress?: string | null;\n  createdAt: string;\n}\n", "import type { Database } from 'sql.js';\n\n/** Preserve the existing schema, custom columns, indexes and triggers. Fail closed on unfamiliar DDL. */\nexport function migrateFixturesTableIfNeeded(db: Database): { migrated: boolean; recordsPreserved: number; reason?: string } {\n  const ddl = db.exec(\"SELECT sql FROM sqlite_master WHERE type='table' AND name='fixtures'\")[0]?.values[0]?.[0];\n  if (!ddl) return { migrated: false, recordsPreserved: 0, reason: 'fixtures table does not exist' };\n  const columns = db.exec('PRAGMA table_xinfo(fixtures)')[0].values;\n  const names = columns.map(c => String(c[1]));\n  const metadata = ['source_fixture_id', 'source_winner_slot', 'home_source_fixture_id', 'away_source_fixture_id', 'home_source_winner_slot', 'away_source_winner_slot'];\n  const missing = metadata.filter(name => !names.includes(name));\n  const needsNullable = columns.some(c => ['home_club_id', 'away_club_id'].includes(String(c[1])) && Number(c[3]) === 1);\n  const scalar = (sql: string) => Number(db.exec(sql)[0]?.values[0]?.[0] || 0);\n  const dirty = scalar(\"SELECT count(*) FROM fixtures WHERE home_club_id IN ('TBD','') OR away_club_id IN ('TBD','')\");\n  if (!needsNullable && !missing.length && !dirty) return { migrated: false, recordsPreserved: 0, reason: 'already up-to-date' };\n  const count = scalar('SELECT count(*) FROM fixtures');\n  const fk = scalar('PRAGMA foreign_keys');\n  const quote = (name: string) => '\"' + name.replace(/\"/g, '\"\"') + '\"';\n  const schemaObjects = db.exec(\"SELECT sql FROM sqlite_master WHERE tbl_name='fixtures' AND type IN ('index','trigger') AND sql IS NOT NULL\")[0]?.values || [];\n  const originalViolations = JSON.stringify(db.exec('PRAGMA foreign_key_check'));\n  let transaction = false;\n  try {\n    db.run('PRAGMA foreign_keys=OFF');\n    db.run('BEGIN IMMEDIATE');\n    transaction = true;\n    if (needsNullable) {\n      let replacement = String(ddl).replace(/^CREATE\\s+TABLE\\s+(?:IF\\s+NOT\\s+EXISTS\\s+)?(?:\"fixtures\"|`fixtures`|\\[fixtures\\]|fixtures)/i, 'CREATE TABLE fixtures_migration_temp');\n      for (const name of ['home_club_id', 'away_club_id']) {\n        const pattern = new RegExp('((?:\"' + name + '\"|`' + name + '`|\\\\[' + name + '\\\\]|\\\\b' + name + '\\\\b)[^,]*?)\\\\s+NOT\\\\s+NULL(?:\\\\s+ON\\\\s+CONFLICT\\\\s+\\\\w+)?', 'i');\n        replacement = replacement.replace(pattern, '$1');\n      }\n      if (replacement === String(ddl)) throw new Error('Unrecognized fixtures schema');\n      db.run(replacement);\n      const tempCols = db.exec('PRAGMA table_xinfo(fixtures_migration_temp)')[0].values;\n      if (tempCols.some(c => ['home_club_id','away_club_id'].includes(String(c[1])) && Number(c[3]) === 1)) throw new Error('Nullable migration could not preserve schema');\n      const writable = columns.filter(c => Number(c[6]) === 0).map(c => String(c[1]));\n      const projection = writable.map(name => ['home_club_id','away_club_id'].includes(name) ? `CASE WHEN ${quote(name)} IN ('TBD','') THEN NULL ELSE ${quote(name)} END` : quote(name)).join(',');\n      const fields = writable.map(quote).join(',');\n      db.run(`INSERT INTO fixtures_migration_temp (${fields}) SELECT ${projection} FROM fixtures`);\n      if (scalar('SELECT count(*) FROM fixtures_migration_temp') !== count || db.exec(`SELECT ${projection} FROM fixtures EXCEPT SELECT ${fields} FROM fixtures_migration_temp`).length) throw new Error('Fixture data preservation check failed');\n      db.run('DROP TABLE fixtures');\n      db.run('ALTER TABLE fixtures_migration_temp RENAME TO fixtures');\n      for (const [sql] of schemaObjects) db.run(String(sql));\n    } else if (dirty) {\n      db.run(\"UPDATE fixtures SET home_club_id = CASE WHEN home_club_id IN ('TBD','') THEN NULL ELSE home_club_id END, away_club_id = CASE WHEN away_club_id IN ('TBD','') THEN NULL ELSE away_club_id END WHERE home_club_id IN ('TBD','') OR away_club_id IN ('TBD','')\");\n    }\n    for (const name of missing) db.run(`ALTER TABLE fixtures ADD COLUMN ${quote(name)} TEXT`);\n    if (JSON.stringify(db.exec('PRAGMA foreign_key_check')) !== originalViolations) throw new Error('Migration changed foreign key integrity');\n    db.run('COMMIT');\n    transaction = false;\n    return { migrated: true, recordsPreserved: count };\n  } catch (error) {\n    if (transaction) db.run('ROLLBACK');\n    throw error;\n  } finally {\n    db.run(`PRAGMA foreign_keys=${fk}`);\n  }\n}\n", "import fs from 'fs';\nimport path from 'path';\nimport { fileURLToPath } from 'url';\nimport initSqlJs, { Database, SqlValue } from 'sql.js';\nimport { migrateFixturesTableIfNeeded } from './migrateFixtures';\n\nfunction getModuleDir(): string {\n  try {\n    if (typeof __dirname !== 'undefined' && __dirname) {\n      return __dirname;\n    }\n  } catch {}\n  try {\n    if (typeof import.meta !== 'undefined' && import.meta.url) {\n      return path.dirname(fileURLToPath(import.meta.url));\n    }\n  } catch {}\n  return process.cwd();\n}\n\nlet dbInstance: Database | null = null;\nconst IS_HOSTED = Boolean(process.env.VERCEL || process.env.VERCEL_ENV || process.env.K_SERVICE || process.env.AWS_LAMBDA_FUNCTION_NAME || process.env.NODE_ENV === 'production');\nconst IS_SERVERLESS = Boolean(process.env.VERCEL || process.env.AWS_LAMBDA_FUNCTION_NAME || process.env.LAMBDA_TASK_ROOT);\nconst DEFAULT_DATA_DIR = IS_HOSTED || IS_SERVERLESS ? '/tmp/data' : path.resolve(process.cwd(), 'data');\nconst DATA_DIR = process.env.DATA_DIR || DEFAULT_DATA_DIR;\nconst DB_FILE = process.env.DB_FILE || path.join(DATA_DIR, 'efootball.sqlite');\nconst SCHEMA_FILE = path.resolve(process.cwd(), 'src', 'server', 'db', 'schema.sql');\n\nexport function getDbFilePath(): string {\n  return DB_FILE;\n}\n\nlet isSaving = false;\nlet needsSave = false;\n\nexport function resolveSqlWasmPath(): string {\n  const modDir = getModuleDir();\n  const candidates = [\n    // 1. In node_modules (local dev, tsx, standard node environment)\n    path.resolve(process.cwd(), 'node_modules', 'sql.js', 'dist', 'sql-wasm.wasm'),\n    path.join(modDir, '..', 'node_modules', 'sql.js', 'dist', 'sql-wasm.wasm'),\n    // 2. In same directory as compiled serverless handler (e.g., /var/task/api/sql-wasm.wasm)\n    path.join(modDir, 'sql-wasm.wasm'),\n    // 3. In api/ folder relative to project root / task root\n    path.resolve(process.cwd(), 'api', 'sql-wasm.wasm'),\n    // 4. In parent directory (e.g. if modDir is /var/task/api, check /var/task/sql-wasm.wasm)\n    path.join(modDir, '..', 'sql-wasm.wasm'),\n    path.join(modDir, '..', 'api', 'sql-wasm.wasm'),\n    path.resolve(process.cwd(), 'sql-wasm.wasm'),\n    // 5. In dist/ folder\n    path.resolve(process.cwd(), 'dist', 'sql-wasm.wasm'),\n    path.join(modDir, '..', 'dist', 'sql-wasm.wasm'),\n    // 6. In public/ folder\n    path.resolve(process.cwd(), 'public', 'sql-wasm.wasm'),\n  ];\n\n  for (const candidate of candidates) {\n    try {\n      if (fs.existsSync(candidate)) {\n        const stats = fs.statSync(candidate);\n        if (stats.isFile() && stats.size > 10000) {\n          return candidate;\n        }\n      }\n    } catch {}\n  }\n\n  throw new Error(\n    `[DB] Could not locate sql-wasm.wasm in any expected location. Checked:\\n` +\n      candidates.map((c) => ` - ${c}`).join('\\n')\n  );\n}\n\nfunction isValidSqliteHeader(buffer: Buffer): boolean {\n  if (!buffer || buffer.length < 100) return false;\n  const headerString = buffer.subarray(0, 16).toString('utf-8');\n  return headerString === 'SQLite format 3\\0';\n}\n\nexport function resolveBundledDbPath(): string | null {\n  // A repository database is never runtime user data on any hosted platform.\n  // Guard the resolver itself so every current/future fallback is covered.\n  if (IS_HOSTED) return null;\n  const modDir = getModuleDir();\n  const candidates = [\n    path.resolve(process.cwd(), 'data', 'efootball.sqlite'),\n    path.join(modDir, 'data', 'efootball.sqlite'),\n    path.join(modDir, '..', 'data', 'efootball.sqlite'),\n    path.resolve(process.cwd(), 'api', 'data', 'efootball.sqlite'),\n    path.resolve(process.cwd(), 'api', 'efootball.sqlite'),\n    path.join(modDir, 'efootball.sqlite'),\n  ];\n\n  for (const candidate of candidates) {\n    try {\n      if (fs.existsSync(candidate)) {\n        const stats = fs.statSync(candidate);\n        if (stats.isFile() && stats.size > 1000) {\n          const buf = fs.readFileSync(candidate);\n          if (isValidSqliteHeader(buf)) {\n            return candidate;\n          }\n        }\n      }\n    } catch {}\n  }\n  return null;\n}\n\nexport async function initDatabase(): Promise<Database> {\n  if (dbInstance) {\n    return dbInstance;\n  }\n  if (IS_HOSTED && [path.resolve(process.cwd(), 'data/efootball.sqlite'), path.resolve(process.cwd(), 'api/data/efootball.sqlite')].includes(path.resolve(DB_FILE))) {\n    throw new Error('BUNDLED_DATABASE_FORBIDDEN: configure a separate runtime DB_FILE or DATA_DIR');\n  }\n\n  try {\n    if (!fs.existsSync(DATA_DIR)) {\n      fs.mkdirSync(DATA_DIR, { recursive: true });\n    }\n  } catch (err) {\n    console.warn(` [DB] Could not create DATA_DIR ${DATA_DIR}, falling back to /tmp/data:`, err);\n  }\n\n  // If running on serverless and target DB_FILE does not exist in /tmp/data, copy pre-seeded SQLite from repo\n  if (IS_SERVERLESS && !fs.existsSync(DB_FILE)) {\n    const hosted = process.env.NODE_ENV === 'production' || Boolean(process.env.VERCEL || process.env.K_SERVICE || process.env.AWS_LAMBDA_FUNCTION_NAME);\n    const bundledDbPath = hosted ? null : resolveBundledDbPath();\n    if (bundledDbPath && fs.existsSync(bundledDbPath)) {\n      try {\n        fs.copyFileSync(bundledDbPath, DB_FILE);\n        console.log(` [DB] Copied bundled database from ${bundledDbPath} to serverless location: ${DB_FILE}`);\n      } catch (err) {\n        console.warn(' [DB] Could not copy bundled DB to serverless path:', err);\n      }\n    }\n  }\n\n  const wasmPath = resolveSqlWasmPath();\n  let SQL: any;\n  try {\n    const wasmFileBuffer = fs.readFileSync(wasmPath);\n    const wasmBinary = new Uint8Array(wasmFileBuffer);\n    SQL = await initSqlJs({\n      locateFile: () => wasmPath,\n      wasmBinary,\n    });\n  } catch (err1) {\n    try {\n      SQL = await initSqlJs({\n        locateFile: () => wasmPath,\n      });\n    } catch (err2) {\n      SQL = await initSqlJs({});\n    }\n  }\n\n  if (fs.existsSync(DB_FILE)) {\n    try {\n      const fileBuffer = fs.readFileSync(DB_FILE);\n      if (isValidSqliteHeader(fileBuffer)) {\n        dbInstance = new SQL.Database(fileBuffer);\n        // Test query to ensure DB is not malformed\n        dbInstance.exec('SELECT 1');\n        console.log(` [DB] path=${DB_FILE}`);\n        console.log(' [DB] initialized=true (loaded from disk)');\n      } else {\n        throw new Error('INVALID_SQLITE_FILE: existing database preserved for recovery');\n      }\n    } catch (err) {\n      dbInstance?.close();\n      dbInstance = null;\n      throw err;\n    }\n  } else {\n    // If DB_FILE does not exist, check if bundled repo sqlite file can be loaded directly\n    const bundledDbPath = resolveBundledDbPath();\n    if (bundledDbPath && fs.existsSync(bundledDbPath)) {\n      try {\n        const fileBuffer = fs.readFileSync(bundledDbPath);\n        if (isValidSqliteHeader(fileBuffer)) {\n          dbInstance = new SQL.Database(fileBuffer);\n          console.log(` [DB] Loaded bundled database from: ${bundledDbPath}`);\n        } else {\n          dbInstance = new SQL.Database();\n        }\n      } catch {\n        dbInstance = new SQL.Database();\n      }\n    } else {\n      console.log(` [DB] path=${DB_FILE}`);\n      console.log(' [DB] initialized=true (new)');\n      dbInstance = new SQL.Database();\n    }\n  }\n\n  // Ensure tables and schemas are created\n  if (fs.existsSync(SCHEMA_FILE)) {\n    try {\n      const schemaSql = fs.readFileSync(SCHEMA_FILE, 'utf-8');\n      dbInstance.exec(schemaSql);\n    } catch (err: any) {\n      console.error(' [DB] Schema initialization failed; existing database preserved.');\n      dbInstance.close();\n      dbInstance = null;\n      throw err;\n    }\n  }\n\n  // Gracefully ensure snapshot columns exist on competition_participants if table already existed\n  try {\n    dbInstance.exec(`\n      ALTER TABLE competition_participants ADD COLUMN season_id TEXT;\n    `);\n  } catch {}\n  try {\n    dbInstance.exec(`\n      ALTER TABLE competition_participants ADD COLUMN owner_user_id TEXT;\n    `);\n  } catch {}\n  try {\n    dbInstance.exec(`\n      ALTER TABLE competition_participants ADD COLUMN source_competition_id TEXT;\n    `);\n  } catch {}\n  try {\n    dbInstance.exec(`\n      ALTER TABLE competition_participants ADD COLUMN source_position INTEGER;\n    `);\n  } catch {}\n  try {\n    dbInstance.exec(`\n      ALTER TABLE competition_participants ADD COLUMN qualification_reason TEXT;\n    `);\n  } catch {}\n  try {\n    dbInstance.exec(`\n      ALTER TABLE competition_participants ADD COLUMN qualification_timestamp TEXT;\n    `);\n  } catch {}\n  // Ensure fixtures table supports nullable club IDs and source metadata columns safely and idempotently\n  try {\n    migrateFixturesTableIfNeeded(dbInstance);\n  } catch (migErr) {\n    console.error(' [DB] Error during fixtures table migration:', migErr);\n    dbInstance.close();\n    dbInstance = null;\n    throw migErr;\n  }\n\n  try {\n    dbInstance.exec(`\n      ALTER TABLE fixtures ADD COLUMN fixture_source TEXT DEFAULT 'official_2026_27';\n    `);\n  } catch {}\n  try {\n    dbInstance.exec(`\n      ALTER TABLE fixtures ADD COLUMN source_fixture_id TEXT;\n    `);\n  } catch {}\n  try {\n    dbInstance.exec(`\n      ALTER TABLE fixtures ADD COLUMN source_winner_slot TEXT;\n    `);\n  } catch {}\n  try {\n    dbInstance.exec(`\n      ALTER TABLE club_memberships ADD COLUMN updated_at TEXT;\n    `);\n  } catch {}\n  // Legacy databases enforced one club per user. The claim transaction now enforces\n  // the season entitlement and different-league limit before writing either club.\n  try {\n    dbInstance.exec('DROP INDEX IF EXISTS idx_club_memberships_user_season_active;');\n    dbInstance.exec('CREATE INDEX IF NOT EXISTS idx_club_memberships_user_season_active ON club_memberships(user_id, season_id) WHERE status = \\'active\\';');\n  } catch (err) {\n    console.error('[DB] Club membership index migration failed:', err);\n    throw err;\n  }\n  try {\n    dbInstance.exec(`\n      CREATE TABLE IF NOT EXISTS season_league_clubs (\n        id TEXT PRIMARY KEY,\n        season_id TEXT NOT NULL,\n        league_id TEXT NOT NULL,\n        club_id TEXT NOT NULL,\n        is_active INTEGER NOT NULL DEFAULT 1,\n        created_at TEXT NOT NULL,\n        FOREIGN KEY(season_id) REFERENCES seasons(id),\n        FOREIGN KEY(league_id) REFERENCES leagues(id),\n        FOREIGN KEY(club_id) REFERENCES clubs(id),\n        UNIQUE(season_id, club_id)\n      );\n    `);\n  } catch {}\n  try {\n    dbInstance.exec(`\n      CREATE TABLE IF NOT EXISTS pending_mutations (\n        mutation_id TEXT PRIMARY KEY,\n        entity_type TEXT NOT NULL,\n        entity_id TEXT NOT NULL,\n        operation TEXT NOT NULL,\n        payload TEXT NOT NULL,\n        status TEXT NOT NULL DEFAULT 'PENDING',\n        retry_count INTEGER NOT NULL DEFAULT 0,\n        last_error TEXT,\n        created_at TEXT NOT NULL,\n        updated_at TEXT NOT NULL\n      );\n    `);\n  } catch {}\n  try {\n    dbInstance.exec(`\n      CREATE TABLE IF NOT EXISTS active_occupancies_cache (\n        club_id TEXT NOT NULL,\n        season_id TEXT NOT NULL,\n        user_id TEXT NOT NULL,\n        username TEXT,\n        display_name TEXT,\n        status TEXT NOT NULL DEFAULT 'active',\n        updated_at TEXT NOT NULL,\n        PRIMARY KEY (season_id, club_id)\n      );\n    `);\n  } catch {}\n  try {\n    dbInstance.exec(`\n      CREATE TABLE IF NOT EXISTS competition_standings (\n        competition_id TEXT NOT NULL,\n        club_id TEXT NOT NULL,\n        rank INTEGER NOT NULL,\n        club_name TEXT NOT NULL,\n        short_name TEXT NOT NULL,\n        logo_url TEXT,\n        played INTEGER NOT NULL DEFAULT 0,\n        won INTEGER NOT NULL DEFAULT 0,\n        drawn INTEGER NOT NULL DEFAULT 0,\n        lost INTEGER NOT NULL DEFAULT 0,\n        goals_for INTEGER NOT NULL DEFAULT 0,\n        goals_against INTEGER NOT NULL DEFAULT 0,\n        goal_difference INTEGER NOT NULL DEFAULT 0,\n        points INTEGER NOT NULL DEFAULT 0,\n        form_json TEXT,\n        qualification_status TEXT,\n        manager_username TEXT,\n        updated_at TEXT NOT NULL,\n        PRIMARY KEY (competition_id, club_id)\n      );\n      CREATE INDEX IF NOT EXISTS idx_competition_standings_rank ON competition_standings(competition_id, rank);\n    `);\n  } catch {}\n\n  try {\n    dbInstance.exec(`\n      CREATE TABLE IF NOT EXISTS matchday_locks (\n        id TEXT PRIMARY KEY,\n        season_id TEXT NOT NULL,\n        competition_id TEXT NOT NULL,\n        matchday INTEGER NOT NULL,\n        override_status TEXT NOT NULL,\n        is_open INTEGER NOT NULL,\n        is_locked INTEGER NOT NULL,\n        duration_hours INTEGER,\n        opened_at TEXT,\n        locked_at TEXT,\n        expires_at TEXT,\n        updated_at TEXT NOT NULL\n      );\n      CREATE INDEX IF NOT EXISTS idx_matchday_locks_lookup\n      ON matchday_locks(season_id, competition_id, matchday);\n    `);\n  } catch (err: any) {\n    console.error(' [DB] Critical error ensuring matchday_locks table:', err);\n    dbInstance.close();\n    dbInstance = null;\n    throw err;\n  }\n\n  // Verify matchday_locks table exists after initialization\n  try {\n    const tableCheck = dbInstance.exec(`SELECT name FROM sqlite_master WHERE type='table' AND name='matchday_locks';`);\n    if (!tableCheck || tableCheck.length === 0 || tableCheck[0].values.length === 0) {\n      const err = new Error('Database initialization failed: matchday_locks table does not exist');\n      console.error(' [DB]', err.message);\n      dbInstance.close();\n      dbInstance = null;\n      throw err;\n    }\n  } catch (verifyErr: any) {\n    console.error(' [DB] matchday_locks table verification failed:', verifyErr);\n    if (dbInstance) {\n      dbInstance.close();\n      dbInstance = null;\n    }\n    throw verifyErr;\n  }\n\n  saveDatabaseSync();\n  return dbInstance;\n}\n\nexport { migrateFixturesTableIfNeeded } from './migrateFixtures';\n\nexport function isDatabaseInitialized(): boolean {\n  return dbInstance !== null;\n}\n\nexport function getDb(): Database {\n  if (!dbInstance) {\n    throw new Error('Database is not initialized. Call initDatabase() first.');\n  }\n  return dbInstance;\n}\n\nexport function saveDatabaseSync(): void {\n  if (!dbInstance) return;\n  try {\n    const data = dbInstance.export();\n    const buffer = Buffer.from(data);\n    const targetDir = path.dirname(DB_FILE);\n    if (!fs.existsSync(targetDir)) {\n      fs.mkdirSync(targetDir, { recursive: true });\n    }\n    const tempFile = `${DB_FILE}.${process.pid}.${Date.now()}.tmp`;\n    fs.writeFileSync(tempFile, buffer);\n    fs.renameSync(tempFile, DB_FILE);\n  } catch (err) {\n    console.error(' [DB] Error saving SQLite database to disk:', err);\n  }\n}\n\nexport async function persistDatabase(): Promise<void> {\n  if (isSaving) {\n    needsSave = true;\n    return;\n  }\n\n  isSaving = true;\n  try {\n    saveDatabaseSync();\n  } finally {\n    isSaving = false;\n    if (needsSave) {\n      needsSave = false;\n      await persistDatabase();\n    }\n  }\n}\n\nexport function queryGet<T = Record<string, any>>(sql: string, params: SqlValue[] = []): T | null {\n  const db = getDb();\n  const stmt = db.prepare(sql);\n  try {\n    stmt.bind(params);\n    if (stmt.step()) {\n      const row = stmt.getAsObject() as Record<string, any>;\n      return row as T;\n    }\n    return null;\n  } finally {\n    stmt.free();\n  }\n}\n\nexport function queryAll<T = Record<string, any>>(sql: string, params: SqlValue[] = []): T[] {\n  const db = getDb();\n  const stmt = db.prepare(sql);\n  const rows: T[] = [];\n  try {\n    stmt.bind(params);\n    while (stmt.step()) {\n      const row = stmt.getAsObject() as Record<string, any>;\n      rows.push(row as T);\n    }\n    return rows;\n  } finally {\n    stmt.free();\n  }\n}\n\nexport function queryRun(sql: string, params: SqlValue[] = []): { changes: number } {\n  const db = getDb();\n  db.run(sql, params);\n  const changes = db.getRowsModified();\n  // Only persist to disk when not in an active transaction to prevent snapshot reset\n  if (transactionDepth === 0) {\n    saveDatabaseSync();\n  }\n  return { changes };\n}\n\nlet transactionDepth = 0;\n\nexport function dbTransaction<T>(callback: () => T): T {\n  const db = getDb();\n  const isTopLevel = transactionDepth === 0;\n  transactionDepth++;\n  \n  if (isTopLevel) {\n    db.exec('BEGIN TRANSACTION;');\n  } else {\n    db.exec(`SAVEPOINT sp_${transactionDepth};`);\n  }\n\n  try {\n    const result = callback();\n    if (isTopLevel) {\n      db.exec('COMMIT;');\n      saveDatabaseSync();\n    } else {\n      db.exec(`RELEASE SAVEPOINT sp_${transactionDepth};`);\n    }\n    transactionDepth--;\n    return result;\n  } catch (error) {\n    if (isTopLevel) {\n      try {\n        db.exec('ROLLBACK;');\n      } catch {}\n    } else {\n      try {\n        db.exec(`ROLLBACK TO SAVEPOINT sp_${transactionDepth};`);\n      } catch {}\n    }\n    transactionDepth--;\n    throw error;\n  }\n}\n\nexport interface SqliteFixtureUpsertInput {\n  id: string;\n  seasonId?: string;\n  competitionId?: string;\n  matchday?: number;\n  roundName?: string | null;\n  homeClubId?: string | null;\n  awayClubId?: string | null;\n  scheduledAt?: string;\n  status?: string;\n  homeScore?: number | null;\n  awayScore?: number | null;\n  winnerClubId?: string | null;\n  resultConfirmedAt?: string | null;\n  fixtureSource?: string;\n  sourceFixtureId?: string | null;\n  sourceWinnerSlot?: string | null;\n  createdAt?: string;\n  updatedAt?: string;\n}\n\nexport function upsertFixtureToSqlite(fixture: SqliteFixtureUpsertInput): void {\n  const existing = queryGet<{\n    id: string;\n    season_id: string;\n    competition_id: string;\n    matchday: number;\n    round_name: string | null;\n    home_club_id: string | null;\n    away_club_id: string | null;\n    scheduled_at: string;\n    status: string;\n    home_score: number | null;\n    away_score: number | null;\n    winner_club_id: string | null;\n    result_confirmed_at: string | null;\n    fixture_source: string;\n    source_fixture_id: string | null;\n    source_winner_slot: string | null;\n    created_at: string;\n    updated_at: string;\n  }>('SELECT * FROM fixtures WHERE id = ?', [fixture.id]);\n\n  const now = new Date().toISOString();\n  const seasonId = fixture.seasonId || existing?.season_id || 'season-2026-27';\n  const competitionId = fixture.competitionId || existing?.competition_id || '';\n  const matchday = fixture.matchday !== undefined ? fixture.matchday : (existing?.matchday ?? 1);\n  const roundName = fixture.roundName !== undefined ? fixture.roundName : (existing?.round_name ?? `Matchday ${matchday}`);\n  const homeClubId = fixture.homeClubId !== undefined ? fixture.homeClubId : (existing?.home_club_id ?? null);\n  const awayClubId = fixture.awayClubId !== undefined ? fixture.awayClubId : (existing?.away_club_id ?? null);\n  const scheduledAt = fixture.scheduledAt || existing?.scheduled_at || now;\n  const status = fixture.status || existing?.status || 'SCHEDULED';\n  const homeScore = fixture.homeScore !== undefined ? fixture.homeScore : (existing?.home_score ?? null);\n  const awayScore = fixture.awayScore !== undefined ? fixture.awayScore : (existing?.away_score ?? null);\n  const winnerClubId = fixture.winnerClubId !== undefined ? fixture.winnerClubId : (existing?.winner_club_id ?? null);\n  const resultConfirmedAt = fixture.resultConfirmedAt !== undefined ? fixture.resultConfirmedAt : (existing?.result_confirmed_at ?? null);\n  const fixtureSource = fixture.fixtureSource || existing?.fixture_source || 'official_2026_27';\n  const sourceFixtureId = fixture.sourceFixtureId !== undefined ? fixture.sourceFixtureId : (existing?.source_fixture_id ?? null);\n  const sourceWinnerSlot = fixture.sourceWinnerSlot !== undefined ? fixture.sourceWinnerSlot : (existing?.source_winner_slot ?? null);\n  const createdAt = existing?.created_at || fixture.createdAt || now;\n  const updatedAt = fixture.updatedAt || now;\n\n  queryRun(\n    `INSERT OR REPLACE INTO fixtures (\n      id, season_id, competition_id, matchday, round_name,\n      home_club_id, away_club_id, scheduled_at, status,\n      home_score, away_score, winner_club_id, result_confirmed_at,\n      fixture_source, source_fixture_id, source_winner_slot,\n      created_at, updated_at\n    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,\n    [\n      fixture.id,\n      seasonId,\n      competitionId,\n      matchday,\n      roundName,\n      homeClubId,\n      awayClubId,\n      scheduledAt,\n      status,\n      homeScore,\n      awayScore,\n      winnerClubId,\n      resultConfirmedAt,\n      fixtureSource,\n      sourceFix