n    id: 'comp-dfl-supercup-2026',\n    seasonId: 'season-2026-27',\n    leagueId: 'league-bundesliga',\n    name: 'DFL-Supercup',\n    type: 'SUPER_CUP',\n    scheduleMode: 'GENERATED_SCHEDULE',\n    formatConfig: { teams: 2, singleLeg: true },\n  },\n\n  // --- EUROPEAN COMPETITIONS (32 Clubs Each) ---\n  {\n    id: 'comp-champions-league-2026',\n    seasonId: 'season-2026-27',\n    name: 'UEFA Champions League',\n    type: 'EUROPEAN_LEAGUE_PHASE',\n    scheduleMode: 'GENERATED_SCHEDULE',\n    formatConfig: { leaguePhaseTeams: 32, matchesPerTeam: 8, directQualifiers: 8, playoffTeams: 16, knockoutTeams: 16 },\n  },\n  {\n    id: 'comp-europa-league-2026',\n    seasonId: 'season-2026-27',\n    name: 'UEFA Europa League',\n    type: 'EUROPEAN_LEAGUE_PHASE',\n    scheduleMode: 'GENERATED_SCHEDULE',\n    formatConfig: { leaguePhaseTeams: 32, matchesPerTeam: 8, directQualifiers: 8, playoffTeams: 16, knockoutTeams: 16 },\n  },\n  {\n    id: 'comp-uefa-super-cup-2026',\n    seasonId: 'season-2026-27',\n    name: 'UEFA Super Cup',\n    type: 'SUPER_CUP',\n    scheduleMode: 'GENERATED_SCHEDULE',\n    formatConfig: { teams: 2, singleLeg: true },\n  },\n];\n\n/** Boot catalog is insert-only: existing tournament state is never reconciled. */\nexport function seedMissingStaticCatalog(): void {\n  dbTransaction(() => {\n    const now = new Date().toISOString();\n    queryRun('INSERT OR IGNORE INTO seasons (id,name,status,start_date,end_date,created_at) VALUES (?,?,?,?,?,?)',\n      [SEED_SEASON.id, SEED_SEASON.name, SEED_SEASON.status, SEED_SEASON.startDate, SEED_SEASON.endDate, now]);\n    for (const l of SEED_LEAGUES) queryRun('INSERT OR IGNORE INTO leagues (id,name,country,tier,logo_url,created_at) VALUES (?,?,?,?,?,?)',\n      [l.id,l.name,l.country,l.tier,l.logoUrl,now]);\n    for (const c of SEED_CLUBS) {\n      queryRun('INSERT OR IGNORE INTO clubs (id,name,short_name,country,league_id,logo_url,active,created_at) VALUES (?,?,?,?,?,?,1,?)',\n        [c.id,c.name,c.shortName,c.country,c.leagueId,c.logoUrl,now]);\n      queryRun('INSERT OR IGNORE INTO season_league_clubs (id,season_id,league_id,club_id,is_active,created_at) VALUES (?,?,?,?,1,?)',\n        [`slc-${SEED_SEASON.id}-${c.id}`,SEED_SEASON.id,c.leagueId,c.id,now]);\n    }\n    for (const c of SEED_COMPETITIONS) queryRun('INSERT OR IGNORE INTO competitions (id,season_id,league_id,name,type,schedule_mode,status,format_config_json,created_at) VALUES (?,?,?,?,?,?,?, ?,?)',\n      [c.id,c.seasonId,c.leagueId || null,c.name,c.type,c.scheduleMode,'upcoming',JSON.stringify(c.formatConfig),now]);\n  });\n}\n\nexport function seedDatabase(): {\n  seasonsCreated: number;\n  leaguesCreated: number;\n  clubsCreated: number;\n  competitionsCreated: number;\n  skipped: number;\n} {\n  return dbTransaction(() => {\n    let seasonsCreated = 0;\n    let leaguesCreated = 0;\n    let clubsCreated = 0;\n    let competitionsCreated = 0;\n    let skipped = 0;\n\n    const now = new Date().toISOString();\n\n    // 1. Season\n    const existingSeason = queryGet('SELECT id FROM seasons WHERE id = ?', [SEED_SEASON.id]);\n    if (!existingSeason) {\n      queryRun(\n        'INSERT INTO seasons (id, name, status, start_date, end_date, created_at) VALUES (?, ?, ?, ?, ?, ?)',\n        [SEED_SEASON.id, SEED_SEASON.name, SEED_SEASON.status, SEED_SEASON.startDate, SEED_SEASON.endDate, now]\n      );\n      seasonsCreated++;\n    } else {\n      queryRun(\n        'UPDATE seasons SET name = ?, status = ?, start_date = ?, end_date = ? WHERE id = ?',\n        [SEED_SEASON.name, SEED_SEASON.status, SEED_SEASON.startDate, SEED_SEASON.endDate, SEED_SEASON.id]\n      );\n    }\n\n    // 2. Leagues\n    for (const league of SEED_LEAGUES) {\n      const existingLeague = queryGet('SELECT id FROM leagues WHERE id = ?', [league.id]);\n      if (!existingLeague) {\n        queryRun(\n          'INSERT INTO leagues (id, name, country, tier, logo_url, created_at) VALUES (?, ?, ?, ?, ?, ?)',\n          [league.id, league.name, league.country, league.tier, league.logoUrl, now]\n        );\n        leaguesCreated++;\n      } else {\n        skipped++;\n      }\n    }\n\n    // 3. Clubs\n    const activeClubIds = new Set(SEED_CLUBS.map((c) => c.id));\n    for (const club of SEED_CLUBS) {\n      const existingClub = queryGet('SELECT id FROM clubs WHERE id = ?', [club.id]);\n      if (!existingClub) {\n        queryRun(\n          'INSERT INTO clubs (id, name, short_name, country, league_id, logo_url, active, created_at) VALUES (?, ?, ?, ?, ?, ?, 1, ?)',\n          [club.id, club.name, club.shortName, club.country, club.leagueId, club.logoUrl, now]\n        );\n        clubsCreated++;\n      } else {\n        queryRun(\n          'UPDATE clubs SET name = ?, short_name = ?, country = ?, league_id = ?, logo_url = ?, active = 1 WHERE id = ?',\n          [club.name, club.shortName, club.country, club.leagueId, club.logoUrl, club.id]\n        );\n      }\n\n      // Ensure membership in season_league_clubs for 2026/27\n      const slcId = `slc-${SEED_SEASON.id}-${club.id}`;\n      queryRun(\n        `INSERT INTO season_league_clubs (id, season_id, league_id, club_id, is_active, created_at)\n         VALUES (?, ?, ?, ?, 1, ?)\n         ON CONFLICT(season_id, club_id) DO UPDATE SET league_id = excluded.league_id, is_active = 1`,\n        [slcId, SEED_SEASON.id, club.leagueId, club.id, now]\n      );\n    }\n\n    // Deactivate any clubs not in the 2026/27 top flights\n    const allDbClubs = queryAll<{ id: string }>('SELECT id FROM clubs');\n    for (const c of allDbClubs) {\n      if (!activeClubIds.has(c.id)) {\n        queryRun('UPDATE clubs SET active = 0 WHERE id = ?', [c.id]);\n        queryRun(\n          'UPDATE season_league_clubs SET is_active = 0 WHERE club_id = ? AND season_id = ?',\n          [c.id, SEED_SEASON.id]\n        );\n        // Remove from 2026/27 competition participants\n        queryRun(\n          'DELETE FROM competition_participants WHERE club_id = ? AND season_id = ?',\n          [c.id, SEED_SEASON.id]\n        );\n      }\n    }\n\n    // 4. Competitions\n    for (const comp of SEED_COMPETITIONS) {\n      const existingComp = queryGet<{ id: string }>('SELECT id FROM competitions WHERE id = ?', [comp.id]);\n      if (!existingComp) {\n        queryRun(\n          'INSERT INTO competitions (id, season_id, league_id, name, type, schedule_mode, status, format_config_json, created_at) VALUES (?, ?, ?, ?, ?, ?, \"upcoming\", ?, ?)',\n          [\n            comp.id,\n            comp.seasonId,\n            comp.leagueId || null,\n            comp.name,\n            comp.type,\n            comp.scheduleMode,\n            JSON.stringify(comp.formatConfig),\n            now,\n          ]\n        );\n        competitionsCreated++;\n      } else {\n        queryRun(\n          'UPDATE competitions SET schedule_mode = ?, format_config_json = ? WHERE id = ?',\n          [comp.scheduleMode, JSON.stringify(comp.formatConfig), comp.id]\n        );\n        skipped++;\n      }\n\n      // Sync active participants for leagues and domestic cups\n      if ((comp.type === 'LEAGUE' || comp.type === 'KNOCKOUT') && comp.leagueId) {\n        // Clean out any stale participants not belonging to the active league\n        queryRun(\n          `DELETE FROM competition_participants \n           WHERE competition_id = ? AND club_id NOT IN (\n             SELECT club_id FROM season_league_clubs WHERE league_id = ? AND season_id = ? AND is_active = 1\n           )`,\n          [comp.id, comp.leagueId, comp.seasonId]\n        );\n\n        const leagueClubs = queryAll<{ club_id: string }>(\n          `SELECT slc.club_id \n           FROM season_league_clubs slc \n           JOIN clubs c ON slc.club_id = c.id\n           WHERE slc.league_id = ? AND slc.season_id = ? AND slc.is_active = 1 \n           ORDER BY c.name ASC`,\n          [comp.leagueId, comp.seasonId]\n        );\n\n        for (let i = 0; i < leagueClubs.length; i++) {\n          const clubId = leagueClubs[i].club_id;\n          const partId = `part-${comp.id}-${clubId}`;\n          queryRun(\n            `INSERT INTO competition_participants (id, competition_id, club_id, season_id, seed_number, created_at)\n             VALUES (?, ?, ?, ?, ?, ?)\n             ON CONFLICT(competition_id, club_id) DO UPDATE SET seed_number = excluded.seed_number`,\n            [partId, comp.id, clubId, comp.seasonId, i + 1, now]\n          );\n        }\n      }\n    }\n\n    console.log(\n      ` [SEED] Done: Created ${seasonsCreated} season, ${leaguesCreated} leagues, ${clubsCreated} clubs, ${competitionsCreated} competitions. Skipped ${skipped} existing records.`\n    );\n\n    return { seasonsCreated, leaguesCreated, clubsCreated, competitionsCreated, skipped };\n  });\n}\n\n/**\n * Authoritative 2026/27 Roster Safe Repair Migration\n *\n * It must:\n * 1. Load authoritative 2026/27 roster.\n * 2. Set all existing season-2026-27 season_league_clubs records to inactive / synchronize with active roster.\n * 3. Insert/activate ONLY the correct 2026/27 clubs.\n * 4. Preserve the global clubs table.\n * 5. Preserve users.\n * 6. Preserve Telegram accounts.\n * 7. Preserve historical seasons.\n * 8. Preserve historical ownership.\n * 9. Preserve audit logs.\n */\n/** Compatibility entry point: roster reconciliation is no longer destructive.\n * Existing clubs, participants, competitions, fixtures and results are preserved.\n */\nexport function repairSeason202627Roster(): { activatedClubs: number; deactivatedClubs: number; totalActive: number } {\n  seedMissingStaticCatalog();\n  return { activatedClubs: 0, deactivatedClubs: 0,\n    totalActive: queryGet<{ n: number }>('SELECT count(*) n FROM clubs WHERE active = 1')?.n || 0 };\n}\n", "import { filterRetiredFixtures, isRetiredFixture } from './retiredFixtureService';\nimport { Fixture, StandingsRow } from '../../types';\nimport {\n  ReadModelKeys,\n  redisGetFresh,\n  redisGetLkg,\n  redisSetRaw,\n} from '../readModel/readModelStore';\n\nexport interface FixtureTombstone {\n  fixtureId: string;\n  seasonId: string;\n  competitionId?: string;\n  deletedAt: string;\n  restoredAt?: string;\n  restoredBy?: string;\n  deletedBy?: string;\n  reason?: string;\n  homeClubId?: string | null;\n  awayClubId?: string | null;\n}\n\nfunction tombstoneKey(seasonId: string): string {\n  return `efluz:v1:season:${seasonId}:fixture-tombstones`;\n}\n\nasync function getAllFixtureTombstones(seasonId = 'season-2026-27'): Promise<FixtureTombstone[]> {\n  const key = tombstoneKey(seasonId);\n  const snap = (await redisGetFresh<FixtureTombstone[]>(key)) || (await redisGetLkg<FixtureTombstone[]>(key));\n  return Array.isArray(snap?.data) ? snap!.data : [];\n}\n\nexport async function getFixtureTombstones(seasonId = 'season-2026-27'): Promise<FixtureTombstone[]> {\n  return (await getAllFixtureTombstones(seasonId)).filter(row => !row.restoredAt);\n}\n\nexport async function restoreFixtureTombstone(fixtureId: string, seasonId: string, adminId: string): Promise<void> {\n  const existing = await getAllFixtureTombstones(seasonId);\n  if (!existing.some(row => row.fixtureId === fixtureId && !row.restoredAt)) return;\n  const next = existing.map(row => row.fixtureId === fixtureId ? { ...row, restoredAt: new Date().toISOString(), restoredBy: adminId } : row);\n  await redisSetRaw(tombstoneKey(seasonId), { sourceVersion: 'fixture-restore-tombstones', expectedCount: next.length, data: next }, 31536000);\n}\n\nexport async function addFixtureTombstone(input: FixtureTombstone): Promise<void> {\n  const existing = await getAllFixtureTombstones(input.seasonId);\n  const next = [...existing.filter((row) => row.fixtureId !== input.fixtureId), input];\n  await redisSetRaw(tombstoneKey(input.seasonId), {\n    sourceVersion: 'fixture-delete-tombstones',\n    expectedCount: next.length,\n    data: next,\n  }, 31536000);\n}\n\nexport async function filterTombstonedFixtures<T extends { id: string }>(fixtures: T[], seasonId = 'season-2026-27'): Promise<T[]> {\n  fixtures = filterRetiredFixtures(fixtures, seasonId);\n  if (!fixtures.length) return fixtures;\n  const tombstones = await getFixtureTombstones(seasonId);\n  if (!tombstones.length) return fixtures;\n  const ids = new Set(tombstones.map((row) => row.fixtureId));\n  return fixtures.filter((fixture) => !ids.has(fixture.id));\n}\n\nexport async function isFixtureTombstoned(fixtureId: string, seasonId = 'season-2026-27'): Promise<boolean> {\n  if (isRetiredFixture(fixtureId, seasonId)) return true;\n  const tombstones = await getFixtureTombstones(seasonId);\n  return tombstones.some((row) => row.fixtureId === fixtureId);\n}\n\nasync function patchFixtureSnapshot(key: string, fixtureId: string): Promise<Fixture[] | null> {\n  const snap = (await redisGetFresh<Fixture[]>(key)) || (await redisGetLkg<Fixture[]>(key));\n  if (!Array.isArray(snap?.data)) return null;\n  const next = snap!.data.filter((fixture) => fixture.id !== fixtureId);\n  if (next.length === snap!.data.length) return next;\n  await redisSetRaw(key, {\n    sourceVersion: 'fixture-delete-filtered',\n    expectedCount: next.length,\n    data: next,\n  }, 86400);\n  return next;\n}\n\nexport async function removeFixtureFromDurableSnapshots(\n  fixtureId: string,\n  competitionId: string | undefined,\n  seasonId = 'season-2026-27'\n): Promise<Fixture[]> {\n  await patchFixtureSnapshot(ReadModelKeys.adminFixtures(seasonId), fixtureId);\n  if (!competitionId) return [];\n  return (await patchFixtureSnapshot(ReadModelKeys.competitionFixtures(competitionId, seasonId), fixtureId)) || [];\n}\n\nexport async function getVisibleCompetitionFixtures(\n  competitionId: string,\n  seasonId = 'season-2026-27'\n): Promise<Fixture[]> {\n  const key = ReadModelKeys.competitionFixtures(competitionId, seasonId);\n  const snap = (await redisGetFresh<Fixture[]>(key)) || (await redisGetLkg<Fixture[]>(key));\n  if (!Array.isArray(snap?.data)) return [];\n  return filterTombstonedFixtures(snap!.data, seasonId);\n}\n\nexport async function rebuildStandingsSnapshotFromFixtures(\n  competitionId: string,\n  seasonId: string,\n  fixtures: Fixture[]\n): Promise<StandingsRow[] | null> {\n  const standingsKey = ReadModelKeys.standings(competitionId, seasonId);\n  const current = (await redisGetFresh<StandingsRow[]>(standingsKey)) || (await redisGetLkg<StandingsRow[]>(standingsKey));\n  if (!Array.isArray(current?.data) || current!.data.length === 0) return null;\n\n  const byClub = new Map<string, StandingsRow>();\n  for (const old of current!.data) {\n    byClub.set(old.clubId, {\n      ...old,\n      position: 0,\n      played: 0,\n      won: 0,\n      drawn: 0,\n      lost: 0,\n      goalsFor: 0,\n      goalsAgainst: 0,\n      goalDifference: 0,\n      points: 0,\n      form: [],\n    });\n  }\n\n  const confirmed = fixtures\n    .filter((fixture) => fixture.competitionId === competitionId && fixture.status === 'CONFIRMED' && fixture.homeClubId && fixture.awayClubId && fixture.homeScore != null && fixture.awayScore != null)\n    .sort((a, b) => Number(a.matchday || 0) - Number(b.matchday || 0) || String(a.resultConfirmedAt || '').localeCompare(String(b.resultConfirmedAt || '')) || a.id.localeCompare(b.id));\n\n  for (const fixture of confirmed) {\n    const home = byClub.get(fixture.homeClubId!);\n    const away = byClub.get(fixture.awayClubId!);\n    const hs = Number(fixture.homeScore);\n    const as = Number(fixture.awayScore);\n    if (home) {\n      home.played++; home.goalsFor += hs; home.goalsAgainst += as;\n      if (hs > as) { home.won++; home.points += 3; home.form.push('W'); }\n      else if (hs === as) { home.drawn++; home.points += 1; home.form.push('D'); }\n      else { home.lost++; home.form.push('L'); }\n    }\n    if (away) {\n      away.played++; away.goalsFor += as; away.goalsAgainst += hs;\n      if (as > hs) { away.won++; away.points += 3; away.form.push('W'); }\n      else if (as === hs) { away.drawn++; away.points += 1; away.form.push('D'); }\n      else { away.lost++; away.form.push('L'); }\n    }\n  }\n\n  const rows = Array.from(byClub.values()).map((row) => ({ ...row, goalDifference: row.goalsFor - row.goalsAgainst, form: row.form.slice(-5) }));\n  rows.sort((a, b) => b.points - a.points || b.goalDifference - a.goalDifference || b.goalsFor - a.goalsFor || a.clubName.localeCompare(b.clubName));\n  rows.forEach((row, index) => { row.position = index + 1; });\n\n  await redisSetRaw(standingsKey, {\n    sourceVersion: 'fixture-derived-recomputed',\n    expectedCount: rows.length,\n    data: rows,\n  }, 86400);\n  return rows;\n}\n\nexport async function refreshDerivedCompetitionState(\n  competitionId: string | undefined,\n  seasonId = 'season-2026-27'\n): Promise<void> {\n  if (!competitionId) return;\n  const fixtures = await getVisibleCompetitionFixtures(competitionId, seasonId);\n  if (fixtures.length > 0) await rebuildStandingsSnapshotFromFixtures(competitionId, seasonId, fixtures);\n}\n", "export interface TrophyRecord {\n  competitionId: string;\n  competitionName: string;\n  seasonId: string;\n  clubId: string;\n  clubName: string;\n  winnerUserId?: string;\n  winnerUsername?: string;\n  decidedBy: 'FINAL' | 'LEAGUE_TABLE' | 'ONE_MATCH_FINAL';\n  confirmedAt?: string | null;\n}\n\nexport interface PlayerTrophy extends TrophyRecord {\n  id: string;\n}\n\nexport interface PlayerTrophyCabinet {\n  trophies: PlayerTrophy[];\n  stale: boolean;\n}\n\nexport function trophyId(seasonId: string, competitionId: string): string {\n  return `${seasonId}__${competitionId}`;\n}\n\nexport function seasonLabel(seasonId: string): string {\n  const match = /^season-(\\d{4})-(\\d{2})$/.exec(seasonId);\n  return match ? `${match[1]}/${match[2]}` : seasonId;\n}\n", "import { Fixture } from '../../types';\nimport { queryAll } from '../db';\nimport { SEED_CLUBS, SEED_COMPETITIONS } from '../db/seed';\nimport {\n  DOMESTIC_LEAGUE_CONFIG,\n  ReadModelKeys,\n  getCompetitionStandingsFromReadModel,\n  redisGetFresh,\n  redisGetLkg,\n} from '../readModel/readModelStore';\n\nimport type { TrophyRecord } from '../../types/trophies';\nexport type { TrophyRecord } from '../../types/trophies';\n\nexport interface SeasonAwardLeader {\n  clubId: string;\n  clubName: string;\n  userId?: string;\n  username?: string;\n  value: number;\n}\n\nexport interface SeasonAward {\n  id: 'MOST_WINS' | 'MOST_GOALS' | 'BEST_DEFENCE' | 'LONGEST_UNBEATEN' | 'LONGEST_WIN_STREAK';\n  label: string;\n  description: string;\n  unit: string;\n  leaders: SeasonAwardLeader[];\n}\n\ntype OwnerEntry = {\n  id: string;\n  ownerUserId?: string | null;\n  ownerUsername?: string | null;\n  ownerDisplayName?: string | null;\n};\n\ntype ClubAggregate = {\n  clubId: string;\n  matches: number;\n  wins: number;\n  draws: number;\n  losses: number;\n  goalsFor: number;\n  goalsAgainst: number;\n  points: number;\n  longestUnbeaten: number;\n  longestWinStreak: number;\n};\n\nconst clubMap = new Map(SEED_CLUBS.map((club) => [club.id, club]));\nconst competitionMap = new Map(SEED_COMPETITIONS.map((competition) => [competition.id, competition]));\nconst domesticLeagueIds = new Set(Object.keys(DOMESTIC_LEAGUE_CONFIG));\n\nfunction normalizeSqliteFixture(row: any, seasonId: string): Fixture {\n  const home = row.home_club_id ? clubMap.get(row.home_club_id) : undefined;\n  const away = row.away_club_id ? clubMap.get(row.away_club_id) : undefined;\n  return {\n    id: row.id,\n    seasonId: row.season_id || seasonId,\n    competitionId: row.competition_id,\n    competitionName: competitionMap.get(row.competition_id)?.name || row.competition_id,\n    matchday: Number(row.matchday || 1),\n    roundName: row.round_name || undefined,\n    homeClubId: row.home_club_id || null,\n    awayClubId: row.away_club_id || null,\n    homeClub: home ? { ...home, active: true, createdAt: '' } as any : null,\n    awayClub: away ? { ...away, active: true, createdAt: '' } as any : null,\n    scheduledAt: row.scheduled_at || '',\n    status: row.status || 'SCHEDULED',\n    homeScore: row.home_score ?? null,\n    awayScore: row.away_score ?? null,\n    winnerClubId: row.winner_club_id || null,\n    resultConfirmedAt: row.result_confirmed_at || null,\n    createdAt: row.created_at || '',\n    updatedAt: row.updated_at || '',\n  } as Fixture;\n}\n\nasync function loadSeasonFixtures(seasonId: string): Promise<{ fixtures: Fixture[]; source: string }> {\n  const key = ReadModelKeys.adminFixtures(seasonId);\n  const fresh = await redisGetFresh<Fixture[]>(key);\n  const snapshot = fresh || (await redisGetLkg<Fixture[]>(key));\n  if (Array.isArray(snapshot?.data) && snapshot!.data.length > 0) {\n    return { fixtures: snapshot!.data, source: fresh ? 'redis' : 'redis_stale' };\n  }\n\n  const rows = queryAll<any>(\n    `SELECT * FROM fixtures WHERE season_id = ? OR season_id IS NULL ORDER BY matchday ASC, scheduled_at ASC, id ASC`,\n    [seasonId]\n  );\n  return { fixtures: rows.map((row) => normalizeSqliteFixture(row, seasonId)), source: 'sqlite' };\n}\n\nasync function loadOwners(seasonId: string): Promise<OwnerEntry[]> {\n  const key = ReadModelKeys.clubsWithOwners(seasonId);\n  const snapshot = (await redisGetFresh<OwnerEntry[]>(key)) || (await redisGetLkg<OwnerEntry[]>(key));\n  if (Array.isArray(snapshot?.data) && snapshot!.data.length > 0) return snapshot!.data;\n\n  const rows = queryAll<any>(\n    `SELECT cm.club_id, cm.user_id, u.username, u.first_name, u.last_name\n       FROM club_memberships cm\n       LEFT JOIN users u ON u.id = cm.user_id\n      WHERE cm.season_id = ? AND cm.status = 'active'`,\n    [seasonId]\n  );\n  return rows.map((row) => ({\n    id: row.club_id,\n    ownerUserId: row.user_id,\n    ownerUsername: row.username || null,\n    ownerDisplayName: [row.first_name, row.last_name].filter(Boolean).join(' ') || row.username || row.user_id,\n  }));\n}\n\nfunction fixtureTime(fixture: Fixture): number {\n  const value = fixture.resultConfirmedAt || fixture.scheduledAt || fixture.updatedAt || fixture.createdAt || '';\n  const timestamp = Date.parse(value);\n  return Number.isFinite(timestamp) ? timestamp : 0;\n}\n\nfunction confirmedForClub(fixtures: Fixture[], clubId: string): Fixture[] {\n  return fixtures\n    .filter((fixture) =>\n      fixture.status === 'CONFIRMED' &&\n      (fixture.homeClubId === clubId || fixture.awayClubId === clubId) &&\n      fixture.homeScore !== null && fixture.homeScore !== undefined &&\n      fixture.awayScore !== null && fixture.awayScore !== undefined\n    )\n    .sort((a, b) => fixtureTime(a) - fixtureTime(b) || a.id.localeCompare(b.id));\n}\n\nfunction aggregateClub(fixtures: Fixture[], clubId: string): ClubAggregate {\n  const matches = confirmedForClub(fixtures, clubId);\n  const aggregate: ClubAggregate = {\n    clubId,\n    matches: 0,\n    wins: 0,\n    draws: 0,\n    losses: 0,\n    goalsFor: 0,\n    goalsAgainst: 0,\n    points: 0,\n    longestUnbeaten: 0,\n    longestWinStreak: 0,\n  };\n  let unbeaten = 0;\n  let winStreak = 0;\n\n  for (const fixture of matches) {\n    const isHome = fixture.homeClubId === clubId;\n    const gf = Number(isHome ? fixture.homeScore : fixture.awayScore) || 0;\n    const ga = Number(isHome ? fixture.awayScore : fixture.homeScore) || 0;\n    aggregate.matches += 1;\n    aggregate.goalsFor += gf;\n    aggregate.goalsAgainst += ga;\n    if (gf > ga) {\n      aggregate.wins += 1;\n      aggregate.points += 3;\n      unbeaten += 1;\n      winStreak += 1;\n    } else if (gf === ga) {\n      aggregate.draws += 1;\n      aggregate.points += 1;\n      unbeaten += 1;\n      winStreak = 0;\n    } else {\n      aggregate.losses += 1;\n      unbeaten = 0;\n      winStreak = 0;\n    }\n    aggregate.longestUnbeaten = Math.max(aggregate.longestUnbeaten, unbeaten);\n    aggregate.longestWinStreak = Math.max(aggregate.longestWinStreak, winStreak);\n  }\n  return aggregate;\n}\n\nfunction resolveWinnerClubId(fixture: Fixture): string | null {\n  if (!Number.isInteger(fixture.homeScore) || !Number.isInteger(fixture.awayScore) ||\n    fixture.homeScore! < 0 || fixture.awayScore! < 0 || !fixture.homeClubId || !fixture.awayClubId || fixture.homeClubId === fixture.awayClubId) return null;\n  if (fixture.winnerClubId && [fixture.homeClubId, fixture.awayClubId].includes(fixture.winnerClubId)) return fixture.winnerClubId;\n  if (fixture.homeScore > fixture.awayScore) return fixture.homeClubId || null;\n  if (fixture.awayScore > fixture.homeScore) return fixture.awayClubId || null;\n  return null;\n}\n\nexport function isCompleteLeagueFixtureSet(fixtures: Fixture[], competitionId: string): boolean {\n  const expectedClubs = DOMESTIC_LEAGUE_CONFIG[competitionId]?.expectedCount;\n  if (!expectedClubs) return false;\n  const competitionFixtures = fixtures.filter((fixture) => fixture.competitionId === competitionId);\n  if (competitionFixtures.length !== expectedClubs * (expectedClubs - 1) / 2) return false;\n  if (competitionFixtures.some((fixture) => fixture.status !== 'CONFIRMED' ||\n    !Number.isInteger(fixture.homeScore) || !Number.isInteger(fixture.awayScore) || fixture.homeScore! < 0 || fixture.awayScore! < 0 ||\n    !fixture.homeClubId || !fixture.awayClubId || fixture.homeClubId === fixture.awayClubId)) return false;\n  const clubIds = Array.from(new Set(competitionFixtures.flatMap((fixture) => [fixture.homeClubId, fixture.awayClubId]).filter(Boolean) as string[]));\n  if (clubIds.length !== expectedClubs) return false;\n  const pairs = new Set(competitionFixtures.map((fixture) => [fixture.homeClubId, fixture.awayClubId].sort().join(':')));\n  return pairs.size === competitionFixtures.length;\n}\n\nasync function deriveLeagueChampion(fixtures: Fixture[], competitionId: string, seasonId: string): Promise<string | null> {\n  if (!isCompleteLeagueFixtureSet(fixtures, competitionId)) return null;\n  try {\n    // Use the same tie-breaker rules and ranking as the official league table.\n    const result = await getCompetitionStandingsFromReadModel(competitionId, seasonId);\n    const expectedClubs = DOMESTIC_LEAGUE_CONFIG[competitionId].expectedCount;\n    if (result.stale || result.degraded || result.standings.length !== expectedClubs ||\n      result.standings.some((row) => row.played !== expectedClubs - 1)) return null;\n    return result.standings.find((row) => row.position === 1)?.clubId || null;\n  } catch { return null; }\n}\n\nexport function isConfirmedFinalFixture(fixture: Fixture): boolean {\n  return fixture.status === 'CONFIRMED' && /^final(?:\\s|$)/i.test(String(fixture.roundName || '').trim());\n}\n\nexport async function getSeasonTrophies(seasonId = 'season-2026-27', options?: { fixtures: Fixture[]; competitionId: string }): Promise<{ trophies: TrophyRecord[]; source: string; unavailableCompetitions: string[] }> {\n  const [{ fixtures, source }, owners] = await Promise.all([\n    options ? Promise.resolve({ fixtures: options.fixtures, source: 'redis' }) : loadSeasonFixtures(seasonId),\n    loadOwners(seasonId),\n  ]);\n  const ownerByClub = new Map(owners.map((owner) => [owner.id, owner]));\n  const grouped = new Map<string, Fixture[]>();\n  for (const fixture of fixtures) {\n    if (fixture.seasonId && fixture.seasonId !== seasonId) continue;\n    if (options && fixture.competitionId !== options.competitionId) continue;\n    if (!fixture.competitionId) continue;\n    const list = grouped.get(fixture.competitionId) || [];\n    list.push(fixture);\n    grouped.set(fixture.competitionId, list);\n  }\n\n  const trophies: TrophyRecord[] = [];\n  const unavailableCompetitions: string[] = [];\n  for (const [competitionId, competitionFixtures] of grouped) {\n    let winnerClubId: string | null = null;\n    let decidedBy: TrophyRecord['decidedBy'] = 'FINAL';\n    let confirmedAt: string | null | undefined = null;\n\n    if (domesticLeagueIds.has(competitionId)) {\n      winnerClubId = await deriveLeagueChampion(fixtures, competitionId, seasonId);\n      if (!winnerClubId && isCompleteLeagueFixtureSet(fixtures, competitionId)) unavailableCompetitions.push(competitionId);\n      decidedBy = 'LEAGUE_TABLE';\n      confirmedAt = winnerClubId ? competitionFixtures.map((fixture) => fixture.resultConfirmedAt || '').sort().at(-1) || null : null;\n    } else {\n      const finals = competitionFixtures\n        .filter(isConfirmedFinalFixture)\n        .sort((a, b) => Number(b.matchday || 0) - Number(a.matchday || 0));\n      let finalFixture = finals[0];\n      const definition = competitionMap.get(competitionId);\n      if (!finalFixture && definition?.type === 'SUPER_CUP' && definition.formatConfig.teams === 2 && competitionFixtures.length === 1 && competitionFixtures[0].status === 'CONFIRMED') {\n        finalFixture = competitionFixtures[0];\n        decidedBy = 'ONE_MATCH_FINAL';\n      }\n      if (finalFixture) {\n        winnerClubId = resolveWinnerClubId(finalFixture);\n        confirmedAt = finalFixture.resultConfirmedAt;\n      }\n    }\n\n    if (!winnerClubId) continue;\n    const owner = ownerByClub.get(winnerClubId);\n    trophies.push({\n      competitionId,\n      competitionName: competitionMap.get(competitionId)?.name || competitionFixtures[0]?.competitionName || competitionId,\n      seasonId,\n      clubId: winnerClubId,\n      clubName: clubMap.get(winnerClubId)?.name || winnerClubId,\n      winnerUserId: owner?.ownerUserId || undefined,\n      winnerUsername: owner?.ownerUsername || undefined,\n      decidedBy,\n      confirmedAt,\n    });\n  }\n\n  trophies.sort((a, b) => a.competitionName.localeCompare(b.competitionName));\n  return { trophies, source, unavailableCompetitions };\n}\n\nfunction leadersFor(\n  rows: ClubAggregate[],\n  owners: Map<string, OwnerEntry>,\n  selector: (row: ClubAggregate) => number,\n  direction: 'MAX' | 'MIN'\n): SeasonAwardLeader[] {\n  if (rows.length === 0) return [];\n  const values = rows.map(selector);\n  const target = direction === 'MAX' ? Math.max(...values) : Math.min(...values);\n  return rows\n    .filter((row) => selector(row) === target)\n    .map((row) => {\n      const owner = owners.get(row.clubId);\n      return {\n        clubId: row.clubId,\n        clubName: clubMap.get(row.clubId)?.name || row.clubId,\n        userId: owner?.ownerUserId || undefined,\n        username: owner?.ownerUsername || undefined,\n        value: selector(row),\n      };\n    });\n}\n\nexport async function getSeasonAwards(seasonId = 'season-2026-27'): Promise<{ awards: SeasonAward[]; source: string }> {\n  const [{ fixtures, source }, ownerEntries] = await Promise.all([loadSeasonFixtures(seasonId), loadOwners(seasonId)]);\n  const owners = new Map(ownerEntries.map((entry) => [entry.id, entry]));\n  const leagueFixtures = fixtures.filter((fixture) => domesticLeagueIds.has(fixture.competitionId) && fixture.status === 'CONFIRMED');\n  const clubIds = Array.from(new Set(leagueFixtures.flatMap((fixture) => [fixture.homeClubId, fixture.awayClubId]).filter(Boolean) as string[]));\n  const rows = clubIds.map((clubId) => aggregateClub(leagueFixtures, clubId)).filter((row) => row.matches > 0);\n\n  return {\n    source,\n    awards: [\n      { id: 'MOST_WINS', label: 'Most Wins', description: 'Most confirmed domestic-league victories.', unit: 'wins', leaders: leadersFor(rows, owners, (row) => row.wins, 'MAX') },\n      { id: 'MOST_GOALS', label: 'Most Goals', description: 'Most goals scored in confirmed domestic-league matches.', unit: 'goals', leaders: leadersFor(rows, owners, (row) => row.goalsFor, 'MAX') },\n      { id: 'BEST_DEFENCE', label: 'Best Defence', description: 'Fewest goals conceded among clubs that have played.', unit: 'conceded', leaders: leadersFor(rows, owners, (row) => row.goalsAgainst, 'MIN') },\n      { id: 'LONGEST_UNBEATEN', label: 'Longest Unbeaten', description: 'Longest domestic-league run without defeat.', unit: 'matches', leaders: leadersFor(rows, owners, (row) => row.longestUnbeaten, 'MAX') },\n      { id: 'LONGEST_WIN_STREAK', label: 'Longest Win Streak', description: 'Longest consecutive domestic-league winning run.', unit: 'matches', leaders: leadersFor(rows, owners, (row) => row.longestWinStreak, 'MAX') },\n    ],\n  };\n}\n\nexport async function getPlayerSeasonInsights(\n  userId: string,\n  seasonId = 'season-2026-27',\n  fallbackClubIds: string[] = []\n) {\n  const [{ fixtures, source }, ownerEntries, trophyResult, awardResult] = await Promise.all([\n    loadSeasonFixtures(seasonId),\n    loadOwners(seasonId),\n    getSeasonTrophies(seasonId),\n    getSeasonAwards(seasonId),\n  ]);\n  const ownedClubIds = ownerEntries.filter((owner) => owner.ownerUserId === userId).map((owner) => owner.id);\n  const clubIds = Array.from(new Set([...ownedClubIds, ...fallbackClubIds].filter(Boolean)));\n  const confirmed = fixtures\n    .filter((fixture) => fixture.status === 'CONFIRMED' && clubIds.some((clubId) => fixture.homeClubId === clubId || fixture.awayClubId === clubId))\n    .sort((a, b) => fixtureTime(a) - fixtureTime(b) || a.id.localeCompare(b.id));\n\n  const summary = {\n    matchesPlayed: 0,\n    wins: 0,\n    draws: 0,\n    losses: 0,\n    goalsScored: 0,\n    goalsConceded: 0,\n    goalDifference: 0,\n    winRate: 0,\n    points: 0,\n    longestUnbeaten: 0,\n    longestWinStreak: 0,\n  };\n  let unbeaten = 0;\n  let wins = 0;\n  const form: Array<'W' | 'D' | 'L'> = [];\n  const competitionBreakdown = new Map<string, { competitionId: string; competitionName: string; matches: number; wins: number; draws: number; losses: number; goalsFor: number; goalsAgainst: number }>();\n\n  const resultForFixture = (fixture: Fixture) => {\n    const clubId = clubIds.find((id) => fixture.homeClubId === id || fixture.awayClubId === id)!;\n    const isHome = fixture.homeClubId === clubId;\n    const gf = Number(isHome ? fixture.homeScore : fixture.awayScore) || 0;\n    const ga = Number(isHome ? fixture.awayScore : fixture.homeScore) || 0;\n    const outcome: 'W' | 'D' | 'L' = gf > ga ? 'W' : gf === ga ? 'D' : 'L';\n    return { clubId, isHome, gf, ga, outcome };\n  };\n\n  for (const fixture of confirmed) {\n    const result = resultForFixture(fixture);\n    summary.matchesPlayed += 1;\n    summary.goalsScored += result.gf;\n    summary.goalsConceded += result.ga;\n    form.push(result.outcome);\n    if (result.outcome === 'W') {\n      summary.wins += 1;\n      summary.points += 3;\n      unbeaten += 1;\n      wins += 1;\n    } else if (result.outcome === 'D') {\n      summary.draws += 1;\n      summary.points += 1;\n      unbeaten += 1;\n      wins = 0;\n    } else {\n      summary.losses += 1;\n      unbeaten = 0;\n      wins = 0;\n    }\n    summary.longestUnbeaten = Math.max(summary.longestUnbeaten, unbeaten);\n    summary.longestWinStreak = Math.max(summary.longestWinStreak, wins);\n\n    const entry = competitionBreakdown.get(fixture.competitionId) || {\n      competitionId: fixture.competitionId,\n      competitionName: fixture.competitionName || competitionMap.get(fixture.competitionId)?.name || fixture.competitionId,\n      matches: 0, wins: 0, draws: 0, losses: 0, goalsFor: 0, goalsAgainst: 0,\n    };\n    entry.matches += 1;\n    entry.goalsFor += result.gf;\n    entry.goalsAgainst += result.ga;\n    if (result.outcome === 'W') entry.wins += 1;\n    else if (result.outcome === 'D') entry.draws += 1;\n    else entry.losses += 1;\n    competitionBreakdown.set(fixture.competitionId, entry);\n  }\n\n  summary.goalDifference = summary.goalsScored - summary.goalsConceded;\n  summary.winRate = summary.matchesPlayed ? Math.round((summary.wins / summary.matchesPlayed) * 1000) / 10 : 0;\n\n  const recentMatches = confirmed.slice(-5).reverse().map((fixture) => {\n    const result = resultForFixture(fixture);\n    const opponentId = result.isHome ? fixture.awayClubId : fixture.homeClubId;\n    return {\n      id: fixture.id,\n      competitionId: fixture.competitionId,\n      competitionName: fixture.competitionName || competitionMap.get(fixture.competitionId)?.name || fixture.competitionId,\n      roundName: fixture.roundName || `Matchday ${fixture.matchday}`,\n      opponentClubId: opponentId,\n      opponentName: opponentId ? clubMap.get(opponentId)?.name || opponentId : 'TBD',\n      goalsFor: result.gf,\n      goalsAgainst: result.ga,\n      outcome: result.outcome,\n      confirmedAt: fixture.resultConfirmedAt,\n    };\n  });\n\n  const nextFixture = fixtures\n    .filter((fixture) =>\n      !['CONFIRMED', 'CANCELLED'].includes(fixture.status) &&\n      clubIds.some((clubId) => fixture.homeClubId === clubId || fixture.awayClubId === clubId)\n    )\n    .sort((a, b) => Number(a.matchday || 0) - Number(b.matchday || 0) || fixtureTime(a) - fixtureTime(b))[0];\n\n  let nextMatch: any = null;\n  if (nextFixture) {\n    const myClubId = clubIds.find((clubId) => nextFixture.homeClubId === clubId || nextFixture.awayClubId === clubId)!;\n    const opponentId = nextFixture.homeClubId === myClubId ? nextFixture.awayClubId : nextFixture.homeClubId;\n    nextMatch = {\n      id: nextFixture.id,\n      competitionId: nextFixture.competitionId,\n      competitionName: nextFixture.competitionName || competitionMap.get(nextFixture.competitionId)?.name || nextFixture.competitionId,\n      roundName: nextFixture.roundName || `Matchday ${nextFixture.matchday}`,\n      myClubId,\n      opponentClubId: opponentId,\n      opponentName: opponentId ? clubMap.get(opponentId)?.name || opponentId : 'TBD',\n      scheduledAt: nextFixture.scheduledAt,\n      status: nextFixture.status,\n    };\n  }\n\n  const trophies = trophyResult.trophies.filter((trophy) => trophy.winnerUserId === userId);\n  const awardsHeld = awardResult.awards\n    .map((award) => ({ ...award, leaders: award.leaders.filter((leader) => leader.userId === userId || clubIds.includes(leader.clubId)) }))\n    .filter((award) => award.leaders.length > 0);\n\n  return {\n    seasonId,\n    source,\n    clubIds,\n    summary,\n    form: form.slice(-5).reverse(),\n    recentMatches,\n    nextMatch,\n    trophies,\n    awardsHeld,\n    competiti