l(fixtureId).catch(() => {});\n  await refreshDerivedCompetitionState(result.fixture.competitionId, result.fixture.seasonId || 'season-2026-27').catch(() => {});\n  return result;\n}\n\nexport async function deleteFixture(\n  adminUserId: string,\n  adminUsername: string,\n  fixtureId: string,\n  reason: string\n): Promise<{ success: boolean; message: string }> {\n  const before = await getFixtureByIdFirestore(fixtureId, adminUserId).catch(() => null);\n  const seasonId = before?.seasonId || 'season-2026-27';\n  const competitionId = before?.competitionId;\n  const result = await adminDeleteFixtureFirestore(adminUserId, adminUsername, fixtureId, reason);\n  await addFixtureTombstone({ fixtureId, seasonId, competitionId, deletedAt: new Date().toISOString(), deletedBy: adminUserId, reason }).catch(() => {});\n  await removeFixtureFromDurableSnapshots(fixtureId, competitionId, seasonId).catch(() => []);\n  await refreshDerivedCompetitionState(competitionId, seasonId).catch(() => {});\n  if (competitionId) {\n    const { syncCompetitionTrophy } = await import('./playerTrophyService');\n    await syncCompetitionTrophy(competitionId, seasonId).catch((error: unknown) => {\n      console.warn('[PLAYER_TROPHY_DELETE_SYNC_FAILED]', fixtureId, error instanceof Error ? error.message : String(error));\n    });\n  }\n  return result;\n}\n\nexport async function getAllAdminUsers(): Promise<User[]> {\n  return await getAllUsersFirestore();\n}\n\nexport async function getUserDetail(targetUserId: string): Promise<any> {\n  return await adminGetUserDetailFirestore(targetUserId);\n}\n\nexport async function setUserAdminRole(\n  adminUserId: string,\n  adminUsername: string,\n  targetUserId: string,\n  isAdmin: boolean,\n  adminPermissions?: import(\"../../types\").AdminPermissions\n): Promise<{ success: boolean; message: string; user: User }> {\n  return await adminSetUserAdminFirestore(adminUserId, adminUsername, targetUserId, isAdmin, adminPermissions);\n}\n\nexport async function setUserSuspension(\n  adminUserId: string,\n  adminUsername: string,\n  targetUserId: string,\n  isSuspended: boolean,\n  reason?: string\n): Promise<{ success: boolean; message: string; user: User }> {\n  return await adminSetUserSuspensionFirestore(adminUserId, adminUsername, targetUserId, isSuspended, reason);\n}\n\nexport async function deleteUser(\n  adminUserId: string,\n  adminUsername: string,\n  targetUserId: string,\n  reason?: string\n): Promise<{ success: boolean; message: string }> {\n  return await adminDeleteUserFirestore(adminUserId, adminUsername, targetUserId, reason);\n}\n\nexport async function getResultSubmissions(filter?: {\n  fixtureId?: string;\n  userId?: string;\n  limit?: number;\n}): Promise<any[]> {\n  return await adminGetResultSubmissionsFirestore(filter);\n}\n\nexport async function deleteResultSubmission(\n  adminUserId: string,\n  adminUsername: string,\n  submissionId: string,\n  notes?: string\n): Promise<{ success: boolean; message: string }> {\n  return await adminDeleteResultSubmissionFirestore(adminUserId, adminUsername, submissionId, notes);\n}\n\nexport async function getAuditLogs(limit = 50): Promise<AuditLog[]> {\n  return await getAuditLogsFirestore(limit);\n}\n", "import {\n  createNotificationFirestore,\n  getUserNotificationsFirestore,\n  markNotificationsReadFirestore,\n} from '../firebase/firestoreStore';\nimport { Notification } from '../../types';\n\nexport async function createNotification(\n  userId: string,\n  type: string,\n  title: string,\n  message: string,\n  data?: Record<string, unknown>\n): Promise<void> {\n  await createNotificationFirestore(userId, type, title, message, data);\n}\n\nexport async function getUserNotifications(userId: string, limit = 20): Promise<Notification[]> {\n  return await getUserNotificationsFirestore(userId, limit);\n}\n\nexport async function markNotificationsAsRead(userId: string): Promise<void> {\n  await markNotificationsReadFirestore(userId);\n}\n", "/**\n * Telegram Bot Service for EFL UZ\n * Handles:\n * 1. /start welcome flow (welcome sticker + personalized HTML message + WebApp launch button)\n * 2. Official group (@efleagueuz) membership verification for club claiming\n */\n\nexport interface TelegramMembershipResult {\n  isMember: boolean;\n  status?: string;\n  error?: string;\n  cached?: boolean;\n}\n\n// Cache configuration:\n// - Positive member cache: ~5 minutes to prevent spamming Telegram API\n// - Negative non-member cache: 20 seconds (15-30s) so newly joined users can quickly re-check\nconst POSITIVE_MEMBERSHIP_CACHE_TTL_MS = 5 * 60 * 1000;\nconst NEGATIVE_MEMBERSHIP_CACHE_TTL_MS = 20 * 1000;\n\nconst membershipCache = new Map<string, { isMember: boolean; status: string; timestamp: number }>();\n\nexport function clearTelegramMembershipCache(telegramUserId?: string | number): void {\n  if (telegramUserId !== undefined) {\n    membershipCache.delete(String(telegramUserId));\n  } else {\n    membershipCache.clear();\n  }\n}\n\n/**\n * Verifies if a Telegram user is an active member of @efleagueuz.\n * Supports:\n * - 'creator' -> member\n * - 'administrator' -> member\n * - 'member' -> member\n * - 'restricted' (with is_member: true) -> member\n * - 'left', 'kicked', 'restricted' (is_member: false), or 'user not found' -> NOT a member\n * - Temporary network/server failure -> fail-open (DO NOT falsely label user as non-member)\n *\n * @param telegramUserId User's Telegram ID\n * @param forceRefresh When true, bypasses the cache and queries Telegram getChatMember immediately\n */\nexport async function verifyTelegramGroupMembership(\n  telegramUserId: string | number,\n  forceRefresh?: boolean\n): Promise<TelegramMembershipResult> {\n  const userIdStr = String(telegramUserId).trim();\n  if (!userIdStr) {\n    return { isMember: false, status: 'empty_user_id' };\n  }\n\n  // Check cache only if forceRefresh is not requested\n  if (!forceRefresh) {\n    const cached = membershipCache.get(userIdStr);\n    if (cached) {\n      const ttl = cached.isMember ? POSITIVE_MEMBERSHIP_CACHE_TTL_MS : NEGATIVE_MEMBERSHIP_CACHE_TTL_MS;\n      if (Date.now() - cached.timestamp < ttl) {\n        return { isMember: cached.isMember, status: cached.status, cached: true };\n      }\n    }\n  }\n\n  const botToken = process.env.TELEGRAM_BOT_TOKEN?.trim();\n  const groupUsername = (process.env.TELEGRAM_GROUP_USERNAME || '@efleagueuz').trim();\n\n  // If no bot token configured (e.g. local dev sandbox without Telegram credentials)\n  if (!botToken) {\n    const isDev = process.env.ENABLE_DEV_AUTH === 'true' || process.env.NODE_ENV !== 'production';\n    if (isDev) {\n      console.log(`[TELEGRAM MEMBERSHIP] No TELEGRAM_BOT_TOKEN set in dev environment. Allowing user ${userIdStr} in sandbox.`);\n      return { isMember: true, status: 'dev_mock_allowed' };\n    }\n    console.warn(`[TELEGRAM MEMBERSHIP] TELEGRAM_BOT_TOKEN is missing in production.`);\n    return { isMember: true, status: 'fail_open_no_token' };\n  }\n\n  const url = `https://api.telegram.org/bot${botToken}/getChatMember?chat_id=${encodeURIComponent(groupUsername)}&user_id=${encodeURIComponent(userIdStr)}`;\n\n  try {\n    const controller = new AbortController();\n    const timeoutId = setTimeout(() => controller.abort(), 6000);\n\n    const response = await fetch(url, {\n      method: 'GET',\n      headers: { 'Accept': 'application/json' },\n      signal: controller.signal,\n    });\n    clearTimeout(timeoutId);\n\n    const data: any = await response.json();\n\n    if (data && data.ok && data.result) {\n      const status = data.result.status;\n      const isRestrictedMember = status === 'restricted' && Boolean(data.result.is_member);\n      const isMember = ['creator', 'administrator', 'member'].includes(status) || isRestrictedMember;\n\n      membershipCache.set(userIdStr, {\n        isMember,\n        status: status || 'unknown',\n        timestamp: Date.now(),\n      });\n\n      return { isMember, status };\n    }\n\n    // Definitive non-member response from Telegram API\n    // e.g. \"Bad Request: user not found\" or \"PARTICIPANT_ID_INVALID\"\n    const description = (data?.description || '').toLowerCase();\n    if (\n      description.includes('user not found') ||\n      description.includes('participant_id_invalid') ||\n      description.includes('not a member') ||\n      description.includes('chat not found')\n    ) {\n      membershipCache.set(userIdStr, {\n        isMember: false,\n        status: 'left_or_not_found',\n        timestamp: Date.now(),\n      });\n      return { isMember: false, status: 'left_or_not_found' };\n    }\n\n    // If Telegram returned 429 Too Many Requests or 5xx server error, fail-open\n    console.warn(`[TELEGRAM MEMBERSHIP CHECK] Non-definitive Telegram response for user ${userIdStr}:`, data);\n    return { isMember: true, status: 'fail_open_transient_error' };\n  } catch (err: any) {\n    // Temporary network failure or timeout: DO NOT incorrectly label user as non-member\n    console.warn(`[TELEGRAM MEMBERSHIP CHECK] Network failure querying Telegram for user ${userIdStr}: ${err.message}`);\n    return { isMember: true, status: 'fail_open_network_timeout' };\n  }\n}\n\nexport interface TelegramSendMessageOptions {\n  parse_mode?: string | null;\n  reply_markup?: any;\n  message_thread_id?: number | null;\n  reply_to_message_id?: number | null;\n  signal?: AbortSignal;\n}\n\nexport async function answerTelegramCallback(queryId: string, text: string, showAlert = false): Promise<void> {\n  const token = process.env.TELEGRAM_BOT_TOKEN?.trim();\n  if (!token) return;\n  await fetch(`https://api.telegram.org/bot${token}/answerCallbackQuery`, {\n    method: 'POST', headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify({ callback_query_id: queryId, text: text.slice(0, 180), show_alert: showAlert }),\n    signal: AbortSignal.timeout(1500),\n  }).catch(() => undefined);\n}\n\n/**\n * Sends a Telegram text message using the Bot API\n */\nexport async function sendTelegramMessage(\n  chatId: number | string,\n  text: string,\n  options: TelegramSendMessageOptions = {}\n): Promise<{ ok: boolean; result?: any; error?: string; error_code?: number; parameters?: { retry_after?: number } }> {\n  const botToken = process.env.TELEGRAM_BOT_TOKEN?.trim();\n  if (!botToken) {\n    return { ok: false, error: 'TELEGRAM_BOT_TOKEN is not configured' };\n  }\n\n  const url = `https://api.telegram.org/bot${botToken}/sendMessage`;\n  try {\n    const body: Record<string, any> = {\n      chat_id: chatId,\n      text,\n    };\n    if (options.parse_mode === null) {\n      // Explicit plain text: do not set parse_mode\n    } else if (options.parse_mode !== undefined) {\n      body.parse_mode = options.parse_mode;\n    } else {\n      // Preserve standard HTML default as before\n      body.parse_mode = 'HTML';\n    }\n    if (options.reply_markup) {\n      body.reply_markup = options.reply_markup;\n    }\n    if (options.message_thread_id) {\n      body.message_thread_id = options.message_thread_id;\n    }\n    if (options.reply_to_message_id) {\n      body.reply_parameters = { message_id: options.reply_to_message_id, allow_sending_without_reply: true };\n    }\n\n    const res = await fetch(url, {\n      signal: options.signal || AbortSignal.timeout(10000),\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(body),\n    });\n    const data: any = await res.json();\n    if (!data.ok) console.warn('[TELEGRAM_SEND_REJECTED]', JSON.stringify({ chatId, threadId: options.message_thread_id || null, errorCode: data.error_code, reason: String(data.description || data.error || 'unknown').replace(/bot[0-9]+:[A-Za-z0-9_-]+/g, 'bot[redacted]').slice(0, 240) }));\n    return { ...data, error: data.description || data.error };\n  } catch (err: any) {\n    return { ok: false, error: err.message };\n  }\n}\n\n/**\n * Sends a Telegram sticker using the Bot API\n */\nexport async function sendTelegramPhoto(chatId: number | string, photo: Buffer, caption: string): Promise<{ ok: boolean; result?: any; error?: string; error_code?: number; parameters?: { retry_after?: number } }> {\n  const token = process.env.TELEGRAM_BOT_TOKEN?.trim();\n  if (!token) return { ok: false, error: 'TELEGRAM_BOT_TOKEN is not configured' };\n  const form = new FormData();\n  form.set('chat_id', String(chatId));\n  form.set('caption', caption);\n  form.set('parse_mode', 'HTML');\n  form.set('photo', new Blob([new Uint8Array(photo)], { type: 'image/png' }), 'efluz-matchday.png');\n  try {\n    const response = await fetch(`https://api.telegram.org/bot${token}/sendPhoto`, { method: 'POST', body: form, signal: AbortSignal.timeout(10000) });\n    const data: any = await response.json();\n    return { ...data, error: data.description || data.error };\n  } catch { return { ok: false, error: 'PHOTO_DELIVERY_UNKNOWN' }; }\n}\n\nexport async function sendTelegramSticker(\n  chatId: number | string,\n  stickerFileId: string\n): Promise<{ ok: boolean; result?: any; error?: string }> {\n  const botToken = process.env.TELEGRAM_BOT_TOKEN?.trim();\n  if (!botToken) {\n    return { ok: false, error: 'TELEGRAM_BOT_TOKEN is not configured' };\n  }\n\n  const url = `https://api.telegram.org/bot${botToken}/sendSticker`;\n  try {\n    const res = await fetch(url, {\n      signal: AbortSignal.timeout(10000),\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({\n        chat_id: chatId,\n        sticker: stickerFileId,\n      }),\n    });\n    const data: any = await res.json();\n    return data;\n  } catch (err: any) {\n    return { ok: false, error: err.message };\n  }\n}\n\n/**\n * Handles the /start command from Telegram\n * 1. Sends welcome sticker if TELEGRAM_WELCOME_STICKER_FILE_ID is configured\n * 2. Sends personalized welcome message with WebApp launch button and group link\n */\nexport async function handleTelegramStart(\n  chatId: number | string,\n  fromUser?: { id: number | string; first_name?: string; last_name?: string; username?: string },\n  options: TelegramSendMessageOptions = {}\n): Promise<{ ok: boolean; stickerSent?: boolean; messageSent: boolean; error?: string }> {\n  const botToken = process.env.TELEGRAM_BOT_TOKEN?.trim();\n  if (!botToken) {\n    console.warn('[TELEGRAM BOT /start] Missing TELEGRAM_BOT_TOKEN');\n    return { ok: false, messageSent: false, error: 'TELEGRAM_BOT_TOKEN is missing' };\n  }\n\n  const stickerFileId = process.env.TELEGRAM_WELCOME_STICKER_FILE_ID?.trim();\n  let stickerSent = false;\n\n  // 1. Send welcome sticker if configured\n  if (stickerFileId && Number(chatId) > 0) {\n    try {\n      const stickerRes = await sendTelegramSticker(chatId, stickerFileId);\n      stickerSent = Boolean(stickerRes && stickerRes.ok);\n    } catch (err: any) {\n      console.warn('[TELEGRAM BOT] Failed to send welcome sticker:', err.message);\n    }\n  }\n\n  // 2. Format personalized welcome message\n  const rawFirstName = fromUser?.first_name || 'Foydalanuvchi';\n  const cleanFirstName = rawFirstName.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n  const webAppUrl = process.env.TELEGRAM_WEBAPP_URL?.trim() || process.env.APP_URL?.trim() || 'https://efluz.vercel.app';\n  const groupUsername = (process.env.TELEGRAM_GROUP_USERNAME || '@efleagueuz').trim();\n  const groupUrl = groupUsername.startsWith('@')\n    ? `https://t.me/${groupUsername.slice(1)}`\n    : `https://t.me/${groupUsername}`;\n\n  const welcomeText =\n`Assalomu alaykum, <b>${cleanFirstName}</b>!\n\n\u26BD <b>EFL UZ</b> \u2014 eFootball O\u2018zbekiston Rasmiy Ligasi platformasiga xush kelibsiz!\n\n\uD83C\uDFC6 <b>Top 5 Yevropa Ligalari:</b>\n\u2022 \uD83C\uDDEC\uD83C\uDDE7 Premier League\n\u2022 \uD83C\uDDEA\uD83C\uDDF8 La Liga\n\u2022 \uD83C\uDDEE\uD83C\uDDF9 Serie A\n\u2022 \uD83C\uDDE9\uD83C\uDDEA Bundesliga\n\u2022 \uD83C\uDDEB\uD83C\uDDF7 Ligue 1\n\n\u2694\uFE0F <b>Asosiy Imkoniyatlar:</b>\n\u2022 Sevimli klubingizni tanlang va boshqaring\n\u2022 Real-vaqt matchmarkaz va eFootball bahslari\n\u2022 Ikki tomonlama natija tasdiqlash va hakamlik\n\u2022 UEFA Chempionlar Ligasi saralash tizimi\n\nQuyidagi tugma orqali ilovani oching va o\u2018z klubingizni band qiling!`;\n\n  const replyMarkup = {\n    inline_keyboard: [\n      [\n        {\n          text: '\u26BD Ilovani ochish (EFL UZ)',\n          ...(Number(chatId) > 0 ? { web_app: { url: webAppUrl } } : { url: `https://t.me/${(process.env.TELEGRAM_BOT_USERNAME || 'efluzbot').trim().replace(/^@/, '')}?start=app` }),\n        },\n      ],\n      [\n        {\n          text: `\uD83D\uDCE2 Rasmiy guruh (${groupUsername})`,\n          url: groupUrl,\n        },\n      ],\n    ],\n  };\n\n  const msgRes = await sendTelegramMessage(chatId, welcomeText, {\n    ...options,\n    parse_mode: 'HTML',\n    reply_markup: replyMarkup,\n  });\n\n  return {\n    ok: msgRes.ok,\n    stickerSent,\n    messageSent: msgRes.ok,\n    error: msgRes.error,\n  };\n}\n\n\nlet connectionCheck: { expiresAt: number; value: Record<string, unknown> } | undefined;\nlet connectionInFlight: Promise<Record<string, unknown>> | undefined;\n/** Bounded read-only Telegram inspection, cached per process. No messages or webhook changes. */\nexport async function inspectTelegramConnection(chatId: number | null, threadId: number | null): Promise<Record<string, unknown>> {\n  if (connectionCheck && connectionCheck.expiresAt > Date.now()) return connectionCheck.value;\n  if (connectionInFlight) return connectionInFlight;\n  connectionInFlight = (async () => {\n    const token = process.env.TELEGRAM_BOT_TOKEN?.trim();\n    if (!token) return { configured: false };\n    const signal = AbortSignal.timeout(3500);\n    const read = async (method: string, body = {}) => {\n      try { const response = await fetch(`https://api.telegram.org/bot${token}/${method}`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(body