m '../firebase/firestoreStore';\nimport { getFirestoreDb } from '../firebase/admin';\nimport { COLLECTIONS, FirestoreClubDoc, FirestoreUserDoc } from '../firebase/collections';\nimport { sendTelegramMessage, sendTelegramPhoto } from './telegramBotService';\nimport type { TournamentImageModel } from '../../lib/tournamentImage';\nimport { PRIMARY_OWNER_TELEGRAM_ID } from './telegramAiConfigService';\nimport { decorateAiCustomEmoji } from './telegramAiCustomEmoji';\nimport { createAuditLog } from './adminService';\nimport {\n  redisGetRaw,\n  redisSetRaw,\n  getUpstashClient,\n  memoryRedisStorage,\n  KEY_PREFIX,\n  SCHEMA_VERSION,\n} from '../readModel/readModelStore';\nimport { SEED_CLUBS, SEED_LEAGUES } from '../db/seed';\nimport { queryAll, queryGet } from '../db';\nimport crypto from 'crypto';\nimport { recoverBackupNotifications, pendingBackupNotifications } from './notificationBackupQueue';\nimport { waitUntil, getDeadline } from '@vercel/functions';\n\nexport interface RecipientDirectoryEntry {\n  userId: string;\n  username: string;\n  displayName: string;\n  telegramId: string | number | null; // PRIVATE: Never exposed in API responses!\n  clubId?: string;\n  clubName?: string;\n  leagueId?: string;\n  leagueName?: string;\n  messageable: boolean;\n  updatedAt: string;\n}\n\nexport interface PublicRecipientView {\n  userId: string;\n  username: string;\n  displayName: string;\n  clubId?: string;\n  clubName?: string;\n  leagueId?: string;\n  leagueName?: string;\n  hasTelegram: boolean;\n  messageable: boolean;\n  // NOTE: telegramId is STRICTLY OMITTED to prevent exposing numeric IDs!\n}\n\nexport interface BroadcastRecipientStatus {\n  userId: string;\n  username: string;\n  displayName: string;\n  clubName?: string;\n  status: 'PENDING' | 'SENDING' | 'SENT' | 'FAILED' | 'SKIPPED_NO_TELEGRAM';\n  sentAt?: string;\n  error?: string;\n  retryCount: number;\n}\n\nexport interface TelegramBroadcastRecord {\n  id: string;\n  seasonId: string;\n  title: string;\n  body: string;\n  type: 'NEW_MATCHDAY' | 'UPCOMING_MATCH' | 'COMPETITION_UPDATE' | 'CUSTOM_ALERT';\n  targetAudience: 'ALL_USERS' | 'CLUB_OWNERS' | 'LEAGUE_OWNERS' | 'SELECTED_RECIPIENTS';\n  targetLeagueId?: string;\n  createdById: string;\n  createdByUsername: string;\n  createdAt: string;\n  status: 'QUEUED' | 'PROCESSING' | 'COMPLETED' | 'PARTIALLY_FAILED';\n  metrics: {\n    totalRecipients: number;\n    sentCount: number;\n    failedCount: number;\n    skippedCount: number;\n  };\n  recipients: BroadcastRecipientStatus[];\n  bodyIsHtml?: boolean;\n  replyMarkup?: any;\n}\n\nexport interface NotificationQueueJob {\n  photoModel?: TournamentImageModel;\n  jobId: string;\n  broadcastId: string;\n  userId: string;\n  username: string;\n  displayName: string;\n  telegramId?: string | number; // PRIVATE\n  seasonId?: string;\n  requiresRecipientLookup?: boolean;\n  title: string;\n  body: string;\n  type: string;\n  status: 'QUEUED' | 'SENDING' | 'SENT' | 'FAILED' | 'SKIPPED_NO_TELEGRAM';\n  retryCount: number;\n  maxRetries: number;\n  createdAt: string;\n  availableAt?: number;\n  sentAt?: string;\n  error?: string;\n  bodyIsHtml?: boolean;\n  replyMarkup?: any;\n}\n\nconst BROADCASTS_KEY = `${KEY_PREFIX}:telegram:broadcasts`;\nconst QUEUE_KEY = `${KEY_PREFIX}:telegram:queue`;\nconst PROCESSING_KEY = `${KEY_PREFIX}:telegram:processing`;\nconst WORKER_LOCK = `${KEY_PREFIX}:telegram:worker-lock`;\nconst RECIPIENT_DIR_KEY = `${KEY_PREFIX}:private:recipient-directory`;\n\n// In-memory memory fallback stores\nconst memoryBroadcasts = new Map<string, TelegramBroadcastRecord>();\nconst memoryJobQueue: NotificationQueueJob[] = [];\nconst memoryRecipientDirectory = new Map<string, RecipientDirectoryEntry>();\nlet memoryRecipientSeason = '';\n\nconst MAX_CONTINUATION_HOPS = 256;\nconst DRAIN_BUDGET_MS = 45000;\n\n/** Inspect only the existing Redis queue; no recipient/Firestore refresh. */\nasync function pendingQueueState(): Promise<{ pending: number; nextAt: number }> {\n  const client = getUpstashClient();\n  if (!client) throw new Error('REDIS_REQUIRED');\n  const state: { pending: number; nextAt: number } = await client.eval(`\n    local jobs = redis.call('LRANGE', KEYS[1], 0, -1)\n    local nextAt = 0\n    for _, raw in ipairs(jobs) do\n      local job = cjson.decode(raw)\n      local at = tonumber(job.availableAt or 0)\n      if nextAt == 0 or at < nextAt then nextAt = at end\n      if at == 0 then break end\n    end\n    return cjson.encode({pending=#jobs, nextAt=nextAt})\n  `, [QUEUE_KEY], []);\n  const backupPending = await pendingBackupNotifications();\n  return { pending: state.pending + backupPending, nextAt: backupPending ? 0 : state.nextAt };\n}\n\n/** Bounded batches share the invocation lifetime; a new invocation takes over\n * before its deadline. The hop cap prevents an endlessly failing self-loop.\n */\nexport async function drainNotificationQueue(options: {\n  deadline?: number;\n  hop?: number;\n  continueDrain?: (hop: number) => Promise<void>;\n} = {}): Promise<void> {\n  const hop = options.hop || 0;\n  const deadline = Math.min(options.deadline ?? Date.now() + DRAIN_BUDGET_MS,\n    (getDeadline()?.getTime() ?? Infinity) - 15000);\n  while (Date.now() + 12000 < deadline) {\n    const result = await processNotificationQueue(25, deadline - 12000);\n    // The active lock owner is responsible for continuation.\n    if (result.locked) return;\n    const state = await pendingQueueState();\n    if (!state.pending) return;\n    const delay = Math.max(0, state.nextAt - Date.now());\n    if (Date.now() + delay + 12000 >= deadline) {\n      const wait = Math.max(0, deadline - Date.now() - 12000);\n      if (wait) await new Promise(resolve => setTimeout(resolve, wait));\n      break;\n    }\n    if (delay) await new Promise(resolve => setTimeout(resolve, delay));\n  }\n  if (!(await pendingQueueState()).pending) return;\n  if (hop >= MAX_CONTINUATION_HOPS) {\n    console.warn('[NOTIF_QUEUE] Continuation cap reached; pending jobs preserved for recovery');\n    return;\n  }\n  await (options.continueDrain || triggerNotificationContinuation)(hop + 1);\n}\n\nexport async function triggerNotificationContinuation(hop: number): Promise<void> {\n  if (process.env.VERCEL === '1') {\n    // Use only Vercel-provided project/deployment hosts, never a request Host.\n    // Production uses the public production domain; protected previews may need\n    // VERCEL_AUTOMATION_BYPASS_SECRET for authenticated self-invocation.\n    const host = process.env.VERCEL_ENV === 'production'\n      ? process.env.VERCEL_PROJECT_PRODUCTION_URL || process.env.VERCEL_URL\n      : process.env.VERCEL_URL;\n    const secret = process.env.CRON_SECRET;\n    if (!host || !/^[a-zA-Z0-9.-]+\\.vercel\\.app$/.test(host) || !secret) throw new Error('NOTIFICATION_CONTINUATION_CONFIG_REQUIRED');\n    const headers: Record<string, string> = { authorization: `Bearer ${secret}` };\n    if (process.env.VERCEL_AUTOMATION_BYPASS_SECRET) headers['x-vercel-protection-bypass'] = process.env.VERCEL_AUTOMATION_BYPASS_SECRET;\n    const response = await fetch(`https://${host}/api/internal/telegram-worker?hop=${hop}`, {\n      method: 'POST', headers, redirect: 'error', signal: AbortSignal.timeout(5000),\n    });\n    if (!response.ok) throw new Error(`NOTIFICATION_CONTINUATION_REJECTED_${response.status}`);\n    return;\n  }\n  // Long-lived Cloud Run/local worker: yield before starting the next slice.\n  await new Promise(resolve => setTimeout(resolve, 25));\n  await drainNotificationQueue({ hop });\n}\n\nexport function scheduleNotificationQueueDrain(hop = 0): void {\n  if (process.env.VERCEL !== '1' && !process.env.K_SERVICE) return;\n  const work = drainNotificationQueue({ hop }).catch(error => {\n    console.warn('[NOTIF_QUEUE] Drain interrupted; durable jobs retained for recovery:', error?.message || error);\n  });\n  if (process.env.VERCEL === '1') waitUntil(work);\n  else void work;\n}\n\n/**\n * Rebuilds and populates the Private Redis Recipient Directory.\n * STRICT PRIVACY RULE: Contains telegramId for bot delivery, but NEVER exposed in public APIs!\n */\nexport async function syncRecipientDirectory(seasonId = 'season-2026-27'): Promise<number> {\n  const dirMap = new Map<string, RecipientDirectoryEntry>();\n  const now = new Date().toISOString();\n\n  try {\n    const db = getFirestoreDb();\n    const [usersSnap, occSnap] = await Promise.all([\n      db.collection(COLLECTIONS.USERS).limit(1001).get(),\n      db.collection(COLLECTIONS.CLUB_OCCUPANCIES).where('seasonId', '==', seasonId).get(),\n    ]);\n    trackFirestoreRead(COLLECTIONS.USERS, Math.max(1, usersSnap.size), 'syncRecipientDirectory:users');\n    trackFirestoreRead(COLLECTIONS.CLUB_OCCUPANCIES, Math.max(1, occSnap.size), 'syncRecipientDirectory:owners');\n    if (usersSnap.size > 1000) throw new Error('RECIPIENT_DIRECTORY_TOO_LARGE');\n\n    const occupancyMap = new Map<string, { clubId: string; claimedAt: string }>();\n    for (const doc of occSnap.docs) {\n      const data = doc.data();\n      if (data.userId && data.clubId && !['released', 'inactive'].includes(data.status)) {\n        occupancyMap.set(data.userId, { clubId: data.clubId, claimedAt: data.claimedAt });\n      }\n    }\n\n    const clubsMap = new Map(SEED_CLUBS.map((c) => [c.id, c]));\n    const leaguesMap = new Map(SEED_LEAGUES.map((l) => [l.id, l]));\n\n    for (const doc of usersSnap.docs) {\n      const u = { ...doc.data(), id: doc.id } as FirestoreUserDoc;\n      const occ = occupancyMap.get(u.id);\n      const club = occ ? clubsMap.get(occ.clubId) : undefined;\n      const league = club ? leaguesMap.get(club.leagueId) : undefined;\n\n      const hasTelegram = Boolean(u.telegramId && String(u.telegramId).trim().length > 0);\n\n      const entry: RecipientDirectoryEntry = {\n        userId: u.id,\n        username: u.username || `player_${u.id.substring(0, 6)}`,\n        displayName: [u.firstName, u.lastName].filter(Boolean).join(' ') || u.username || 'EFL Player',\n        telegramId: u.telegramId || null,\n        clubId: club?.id,\n        clubName: club?.name,\n        leagueId: league?.id,\n        leagueName: league?.name,\n        messageable: hasTelegram && !u.isSuspended,\n        updatedAt: now,\n      };\n\n      dirMap.set(u.id, entry);\n    }\n  } catch (error) {\n    // Never replace the directory with an incomplete SQLite fallback during quota exhaustion.\n    throw new Error('RECIPIENT_DIRECTORY_UNAVAILABLE: existing directory preserved');\n  }\n\n  // Persist into private Redis directory\n  const entriesArray = Array.from(dirMap.values());\n  const client = getUpstashClient();\n  if (client) {\n    await client.set(`${RECIPIENT_DIR_KEY}:${seasonId}`, entriesArray);\n  }\n  memoryRecipientDirectory.clear();\n  for (const entry of entriesArray) memoryRecipientDirectory.set(entry.userId, entry);\n  memoryRecipientSeason = seasonId;\n\n  return entriesArray.length;\n}\n\n/**\n * Returns safe recipient list for the Admin Panel UI.\n * STRICT DATA SAFETY RULE: Never expose Telegram numeric IDs in UI or API responses!\n */\nexport async function getSafeEligibleRecipients(\n  filter?: { audience?: string; leagueId?: string },\n  seasonId = 'season-2026-27'\n): Promise<PublicRecipientView[]> {\n  if (memoryRecipientSeason !== seasonId) memoryRecipientDirectory.clear();\n  const client = getUpstashClient();\n  let entries: RecipientDirectoryEntry[] = [];\n\n  if (client) {\n    try {\n      const cached = await client.get<RecipientDirectoryEntry[]>(`${RECIPIENT_DIR_KEY}:${seasonId}`);\n      if (Array.isArray(cached) && cached.length > 0) {\n        entries = cached;\n        memoryRecipientDirectory.clear();\n        for (const entry of cached) memoryRecipientDirectory.set(entry.userId, entry);\n        memoryRecipientSeason = seasonId;\n      }\n    } catch {}\n  }\n\n  if (entries.length === 0) {\n    // A missing snapshot is an explicit admin refresh condition. Never start\n    // an unbounded Firestore scan from a read path during quota exhaustion.\n    if (memoryRecipientDirectory.size === 0) throw new Error('RECIPIENT_DIRECTORY_UNAVAILABLE');\n    entries = Array.from(memoryRecipientDirectory.values());\n  }\n\n  // Apply audience filters\n  let filtered = entries;\n  if (filter?.audience === 'CLUB_OWNERS') {\n    filtered = filtered.filter((r) => Boolean(r.clubId));\n  } else if (filter?.audience === 'LEAGUE_OWNERS' && filter.leagueId) {\n    filtered = filtered.filter((r) => r.leagueId === filter.leagueId && Boolean(r.clubId));\n  }\n\n  // Sanitize: strip telegramId completely!\n  return filtered.map((r) => ({\n    userId: r.userId,\n    username: r.username,\n    displayName: r.displayName,\n    clubId: r.clubId,\n    clubName: r.clubName,\n    leagueId: r.leagueId,\n    leagueName: r.leagueName,\n    hasTelegram: Boolean(r.telegramId),\n    messageable: r.messageable,\n  }));\n}\n\n/**\n * Creates and enqueues a new Telegram notification broadcast with durable Redis queueing.\n */\nexport async function enqueueTelegramBroadcast(params: {\n  adminUserId: string;\n  adminUsername: string;\n  title: string;\n  body: string;\n  type: 'NEW_MATCHDAY' | 'UPCOMING_MATCH' | 'COMPETITION_UPDATE' | 'CUSTOM_ALERT';\n  targetAudience: 'ALL_USERS' | 'CLUB_OWNERS' | 'LEAGUE_OWNERS' | 'SELECTED_RECIPIENTS';\n  targetLeagueId?: string;\n  selectedUserIds?: string[];\n  seasonId?: string;\n  requestId?: string;\n}): Promise<TelegramBroadcastRecord> {\n  const seasonId = params.seasonId || 'season-2026-27';\n  const durableClient = getUpstashClient();\n  if (!durableClient) throw new Error('REDIS_REQUIRED: durable notification storage is unavailable');\n  if (!['ALL_USERS', 'CLUB_OWNERS', 'LEAGUE_OWNERS', 'SELECTED_RECIPIENTS'].includes(params.targetAudience)) throw new Error('INVALID_AUDIENCE');\n  if (params.targetAudience === 'LEAGUE_OWNERS' && !params.targetLeagueId) throw new Error('LEAGUE_REQUIRED');\n  if (typeof params.title !== 'string' || typeof params.body !== 'string' || !params.title.trim() || !params.body.trim() || params.title.length + params.body.length > 3500) throw new Error('INVALID_MESSAGE');\n  await getSafeEligibleRecipients(undefined, seasonId);\n\n  if (params.requestId && !/^[a-zA-Z0-9-]{8,100}$/.test(params.requestId)) throw new Error('INVALID_REQUEST_ID');\n  const requestId = params.requestId || crypto.randomUUID();\n  const broadcastId = `bcast-${crypto.createHash('sha256').update(params.adminUserId + ':' + requestId).digest('hex')}`;\n  const now = new Date().toISOString();\n\n  // 1. Resolve recipients\n  let targetUserIds: string[] = [];\n  if (params.targetAudience === 'SELECTED_RECIPIENTS') {\n    if (!Array.isArray(params.selectedUserIds)) throw new Error('RECIPIENTS_REQUIRED');\n    targetUserIds = [...new Set(params.selectedUserIds)];\n    if (targetUserIds.some(uid => typeof uid !== 'string' || !memoryRecipientDirectory.has(uid))) throw new Error('UNKNOWN_RECIPIENT');\n  } else {\n    const safeRecipients = await getSafeEligibleRecipients(\n      { audience: params.targetAudience, leagueId: params.targetLeagueId },\n      seasonId\n    );\n    targetUserIds = safeRecipients.map((r) => r.userId);\n  }\n\n  if (targetUserIds.length === 0) {\n    throw new Error('No eligible recipients found for this broadcast selection.');\n  }\n\n  // 2. Prepare recipient statuses and queue jobs\n  const recipientStatuses: BroadcastRecipientStatus[] = [];\n  const jobs: NotificationQueueJob[] = [];\n\n  for (const uid of targetUserIds) {\n    const recipient = memoryRecipientDirectory.get(uid);\n    const hasTg = Boolean(recipient?.telegramId && recipient.messageable);\n\n    recipientStatuses.push({\n      userId: uid,\n      username: recipient?.username || 'user',\n      displayName: recipient?.displayName || 'User',\n      clubName: recipient?.clubName,\n      status: hasTg ? 'PENDING' : 'SKIPPED_NO_TELEGRAM',\n      error: hasTg ? undefined : 'User has no connected Telegram account',\n      retryCount: 0,\n    });\n\n    if (hasTg) {\n      jobs.push({\n        jobId: `job-${broadcastId}-${uid}`,\n        broadcastId,\n        userId: uid,\n        username: recipient?.username || 'user',\n        displayName: recipient?.displayName || 'User',\n        telegramId: recipient!.telegramId!,\n        title: params.title,\n        body: params.body,\n        type: params.type,\n        status: 'QUEUED',\n        retryCount: 0,\n        maxRetries: 3,\n        createdAt: now,\n      });\n    }\n  }\n\n  const record: TelegramBroadcastRecord = {\n    id: broadcastId,\n    seasonId,\n    title: params.title,\n    body: params.body,\n    type: params.type,\n    targetAudience: params.targetAudience,\n    targetLeagueId: params.targetLeagueId,\n    createdById: params.adminUserId,\n    createdByUsername: params.adminUsername,\n    createdAt: now,\n    status: jobs.length > 0 ? 'QUEUED' : 'COMPLETED',\n    metrics: {\n      totalRecipients: targetUserIds.length,\n      sentCount: 0,\n      failedCount: 0,\n      skippedCount: recipientStatuses.filter((r) => r.status === 'SKIPPED_NO_TELEGRAM').length,\n    },\n    recipients: recipientStatuses,\n  };\n\n  // One atomic write: a returned broadcast always has a durable queue.\n  const persistedRecord = await durableClient.eval<unknown[], TelegramBroadcastRecord>(`\n    local existing = redis.call('HGET', KEYS[1], ARGV[1])\n    if existing then return existing end\n    redis.call('HSET', KEYS[1], ARGV[1], ARGV[2])\n    local jobs = cjson.decode(ARGV[3])\n    for _, job in ipairs(jobs) do redis.call('RPUSH', KEYS[2], cjson.encode(job)) end\n    return ARGV[2]\n  `, [BROADCASTS_KEY, QUEUE_KEY], [broadcastId, JSON.stringify(record), JSON.stringify(jobs)]);\n  if (persistedRecord.title !== record.title || persistedRecord.body !== record.body || persistedRecord.seasonId !== seasonId ||\n      JSON.stringify(persistedRecord.recipients.map(r => r.userId).sort()) !== JSON.stringify(targetUserIds.slice().sort())) throw new Error('REQUEST_ID_REUSED_WITH_DIFFERENT_CONTENT');\n  memoryBroadcasts.set(broadcastId, persistedRecord);\n\n  scheduleNotificationQueueDrain();\n\n  // Every selected user receives an in-app notification, including users who\n  // do not have a messageable Telegram account. Deterministic document IDs make\n  // retries with the same requestId idempotent.\n  const notificationBatchSize = 400;\n  const notificationDb = getFirestoreDb();\n  for (let i = 0; i < targetUserIds.length; i += notificationBatchSize) {\n    const batch = notificationDb.batch();\n    for (const uid of targetUserIds.slice(i, i + notificationBatchSize)) {\n      batch.set(notificationDb.collection(COLLECTIONS.NOTIFICATIONS).doc(`notif-${broadcastId}-${uid}`), {\n        id: `notif-${broadcastId}-${uid}`,\n        userId: uid,\n        type: params.type,\n        title: params.title,\n        message: params.body,\n        data: { broadcastId },\n        isRead: false,\n        createdAt: now,\n      }, { merge: true });\n    }\n    await batch.commit();\n  }\n\n  // Create audit log\n  await createAuditLog(\n    params.adminUserId,\n    'TELEGRAM_NOTIFICATION_BROADCAST',\n    'BROADCAST',\n    broadcastId,\n    undefined,\n    {\n      broadcastId,\n      title: params.title,\n      type: params.type,\n      recipientsTotal: targetUserIds.length,\n      queuedJobs: jobs.length,\n      skippedNoTelegram: record.metrics.skippedCount,\n      timestamp: now,\n    },\n    undefined,\n    params.adminUsername,\n    `Enqueued broadcast '${params.title}' for ${targetUserIds.length} recipients (${jobs.length} with Telegram).`\n  ).catch(() => console.warn('[NOTIF_QUEUE] Broadcast persisted; auxiliary audit unavailable'));\n\n  return persistedRecord;\n}\n\n/**\n * Worker function that processes pending notification jobs from Redis / memory queue.\n * Implements Telegram Bot API compliant rate limiting (max 25-30 msg/sec).\n */\nexport async function processNotificationQueue(batchSize = 25, stopClaimingAt = Infinity): Promise<{\n  processed: number;\n  succeeded: number;\n  failed: number;\n  locked?: boolean;\n}> {\n  const client = getUpstashClient();\n  if (!client) throw new Error('REDIS_REQUIRED');\n  const token = crypto.randomUUID();\n  if (!await client.set(WORKER_LOCK, token, { nx: true, ex: 120 })) return { processed: 0, succeeded: 0, failed: 0, locked: true };\n  let processed = 0, succeeded = 0, failed = 0;\n  const deadline = Math.min(Date.now() + 20000, stopClaimingAt);\n  try {\n    try { await recoverBackupNotifications(batchSize); }\n    catch (error: any) { console.warn('[NOTIF_BACKUP_RECOVERY_DEFERRED]', error?.message || error); }\n    // A worker may have died after Telegram accepted a message. Do not blindly resend it.\n    const abandoned = await client.hgetall<Record<string, NotificationQueueJob & { claimedAt?: number }>>(PROCESSING_KEY);\n    for (const job of Object.values(abandoned || {})) {\n      if ((job.claimedAt || 0) + 120000 > Date.now()) continue;\n      const photoRecord = job.photoModel ? await getBroadcastDetails(job.broadcastId) : null;\n      const photoNotDispatched = Boolean(photoRecord?.recipients.find(r => r.userId === job.userId && r.status === 'PENDING'));\n      if (job.requiresRecipientLookup || photoNotDispatched) {\n        job.availableAt = Date.now() + 300000;\n        await client.rpush(QUEUE_KEY, JSON.stringify(job));\n      } else {\n        await updateBroadcastRecipientState(job.broadcastId, job.userId, 'FAILED', 'DELIVERY_UNKNOWN: worker interrupted; verify delivery before creating another broadcast');\n      }\n      await client.hdel(PROCESSING_KEY, job.jobId);\n    }\n    for (let i = 0; i < Math.min(Math.max(batchSize, 1), 25) && Date.now() < deadline; i++) {\n      const job = await client.eval<unknown[], NotificationQueueJob>(`\n        if redis.call('GET', KEYS[3]) ~= ARGV[1] then return nil end\n        local count = redis.call('LLEN', KEYS[1])\n        for i = 1, count do\n          local raw = redis.call('LPOP', KEYS[1])\n          local job = cjson.decode(raw)\n          if tonumber(job.availableAt or 0) <= tonumber(ARGV[2]) then\n            job.claimedAt = tonumber(ARGV[2])\n            redis.call('HSET', KEYS[2], job.jobId, cjson.encode(job))\n            return cjson.encode(job)\n          end\n          redis.call('RPUSH', KEYS[1], raw)\n        end\n        return nil\n      `, [QUEUE_KEY, PROCESSING_KEY, WORKER_LOCK], [token, Date.now()]);\n      if (!job) break;\n      processed++;\n      const record = await getBroadcastDetails(job.broadcastId);\n      const recipient = record?.recipients.find(r => r.userId === job.userId);\n      if (!record || !recipient) throw new Error('BROADCAST_RECORD_MISSING');\n      if (['SENT', 'FAILED', 'SKIPPED_NO_TELEGRAM'].includes(recipient.status)) {\n        await client.hdel(PROCESSING_KEY, job.jobId);\n        continue;\n      }\n      if (recipient.status === 'SENDING') {\n        await updateBroadcastRecipientState(job.broadcastId, job.userId, 'FAILED', 'DELIVERY_UNKNOWN: interrupted send');\n        await client.hdel(PROCESSING_KEY, job.jobId);\n        continue;\n      }\n      if (job.requiresRecipientLookup) {\n        const entries = await client.get<RecipientDirectoryEntry[]>(`${RECIPIENT_DIR_KEY}:${job.seasonId || record.seasonId}`);\n        const entry = Array.isArray(entries) ? entries.find((item) => item.userId === job.userId) : undefined;\n        if (!entry) {\n          // Keep the event durable until the existing directory sync catches up.\n          // This worker never warms the directory through extra Firestore reads.\n          job.availableAt = Date.now() + 300000;\n          await client.rpush(QUEUE_KEY, JSON.stringify(job));\n          await client.hdel(PROCESSING_KEY, job.jobId);\n          continue;\n        }\n        if (!entry.messageable || !entry.telegramId) {\n          await updateBroadcastRecipientState(job.broadcastId, job.userId, 'SKIPPED_NO_TELEGRAM');\n          await client.hdel(PROCESSING_KEY, job.jobId);\n          continue;\n        }\n        job.telegramId = entry.telegramId;\n        job.requiresRecipientLookup = false;\n        // Crash recovery must know when a resolved job may have started sending.\n        await client.hset(PROCESSING_KEY, { [job.jobId]: { ...job, claimedAt: Date.now() } });\n      }\n      let photo: Buffer | undefined;\n      let photoCaption = job.body;\n      if (job.photoModel) {\n        // Also reroute old queued channel jobs. No matchday photo may be sent\n        // to a channel or to a league/delegated admin after this change.\n        job.telegramId = PRIMARY_OWNER_TELEGRAM_ID;\n        await client.hset(PROCESSING_KEY, { [job.jobId]: { ...job, claimedAt: Date.now() } });\n        try {\n          const { renderTournamentImagePng } = await import('./tournamentImageRenderer');\n          photo = await renderTournamentImagePng(job.photoModel);\n          photoCaption = await decorateAiCustomEmoji(job.body, AbortSignal.timeout(3000), 16);\n        } catch {\n          // Rendering happens before dispatch: it is safe to retry here.\n          if (job.retryCount < job.maxRetries) {\n            job.retryCount++;\n            job.availableAt = Date.now() + 30000;\n            await client.rpush(QUEUE_KEY, JSON.stringify(job));\n          } else {\n            await updateBroadcastRecipientState(job.broadcastId, job.userId, 'FAILED', 'PHOTO_RENDER_FAILED');\n            failed++;\n          }\n          await client.hdel(PROCESSING_KEY, job.jobId);\n          continue;\n        }\n      }\n      recipient.status = 'SENDING';\n      record.status = 'PROCESSING';\n      await client.hset(BROADCASTS_KEY, { [record.id]: record });\n      const result = photo ? await sendTelegramPhoto(job.telegramId!, photo, photoCaption) : await sendTelegramMessage(\n        job.telegramId!,\n        formatTelegramMessage(job.title, job.body, job.type, Boolean(job.bodyIsHtml)),\n        { parse_mode: 'HTML', reply_markup: job.replyMarkup }\n      );\n      if (result.ok) {\n        await updateBroadcastRecipientState(job.broadcastId, job.userId, 'SENT', undefined, new Date().toISOString());\n        succeeded++;\n      } else {\n        const errorText = result.error_code\n          ? `TELEGRAM_${result.error_code}: ${result.error || 'Rejected'}${result.parameters?.retry_after ? '; retry after ' + result.parameters.retry_after + ' seconds' : ''}`\n          : 'DELIVERY_UNKNOWN: ' + (result.error || 'No response');\n        const definitelyRejected = Boolean(result.error_code);\n        const retryable = result.error_code === 429 || Boolean(result.error_code && result.error_code >= 500);\n        if (definitelyRejected && retryable && job.retryCount < job.maxRetries) {\n          job.retryCount += 1;\n          const retryAfterSeconds = Math.max(Number(result.parameters?.retry_after || 0), 2 ** job.retryCount);\n          job.availableAt = Date.now() + retryAfterSeconds * 1000;\n          job.status = 'QUEUED';\n          await updateBroadcastRecipientState(job.broadcastId, job.userId, 'PENDING', errorText, undefined, job.retryCount);\n          await client.rpush(QUEUE_KEY, JSON.stringify(job));\n        } else {\n          // Ambiguous timeouts are never retried automatically because Telegram\n          // may have accepted the message before the connection was lost.\n          await updateBroadcastRecipientState(job.broadcastId, job.userId, 'FAILED', errorText, undefined, job.retryCount);\n          failed++;\n        }\n      }\n      await client.hdel(PROCESSING_KEY, job.jobId);\n      await new Promise(resolve => setTimeout(resolve, 50));\n    }\n    return { processed, succeeded, failed };\n  } finally {\n    await client.eval(\"if redis.call('GET', KEYS[1]) == ARGV[1] then return redis.call('DEL', KEYS[1]) end return 0\", [WORKER_LOCK], [token]);\n  }\n}\n\nfunction formatTelegramMessage(title: string, body: string, type: string, bodyIsHtml = false): string {\n  let icon = '\uD83D\uDCE2';\n  if (type === 'NEW_MATCHDAY') icon = '\u26BD';\n  if (type === 'UPCOMING_MATCH') icon = '\u23F0';\n  if (type === 'COMPETITION_UPDATE') icon = '\uD83C\uDFC6';\n\n  // No permanent \"Official Alert\" header/footer. Smart bodies are generated server-side\n  // and may contain a small, controlled HTML subset; admin-entered bodies stay escaped.\n  const safeBody = bodyIsHtml ? body : escapeHtml(body);\n  return `<b>${icon} ${escapeHtml(title)}</b>\\n\\n${safeBody}`;\n}\n\nfunction escapeHtml(str: string): string {\n  return str\n    .replace(/&/g, '&amp;')\n    .replace(/</g, '&lt;')\n    .replace(/>/g, '&gt;')\n    .replace(/\"/g, '&quot;');\n}\n\nasync function updateBroadcastRecipientState(\n  broadcastId: string,\n  userId: string,\n  status: 'PENDING' | 'SENT' | 'FAILED' | 'SKIPPED_NO_TELEGRAM',\n  error?: string,\n  sentAt?: string,\n  retryCount?: number\n) {\n  const bcast = await getBroadcastDetails(broadcastId);\n  if (!bcast) throw new Error('BROADCAST_RECORD_MISSING');\n\n  const r = bcast.recipients.find((rec) => rec.userId === userId);\n  if (r) {\n    r.status = status;\n    if (error) r.error = error;\n    if (sentAt) r.sentAt = sentAt;\n    if (retryCount !== undefined) r.retryCount = retryCount;\n  }\n\n  bcast.metrics.sentCount = bcast.recipients.filter(r => r.status === 'SENT').length;\n  bcast.metrics.failedCount = bcast.recipients.filter(r => r.status === 'FAILED').length;\n  bcast.metrics.skippedCount = bcast.recipients.filter(r => r.status === 'SKIPPED_NO_TELEGRAM').length;\n\n  const totalFinished = bcast.metrics.sentCount + bcast.metrics.failedCount + bcast.metrics.skippedCount;\n  if (totalFinished >= bcast.metrics.totalRecipients) {\n    bcast.status = bcast.metrics.failedCount > 0 ? 'PARTIALLY_FAILED' : 'COMPLETED';\n  }\n\n  // Also persist to Redis if available\n  const client = getUpstashClient();\n  if (client) {\n    await client.hset(BROADCASTS_KEY, { [broadcastId]: bcast });\n  }\n  memoryBroadcasts.set(broadcastId, bcast);\n}\n\n/**\n * Returns past broadcasts list.\n */\nexport async function getBroadcastHistory(limit = 20): Promise<TelegramBroadcastRecord[]> {\n  const client = getUpstashClient();\n  if (client) {\n    try {\n      const records = await client.hgetall<Record<string, TelegramBroadcastRecord>>(BROADCASTS_KEY);\n      if (records) {\n        const list = Object.values(records) as TelegramBroadcastRecord[];\n        return list\n          .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())\n          .slice(0, limit);\n      }\n    } catch {}\n  }\n\n  return Array.from(memoryBroadcasts.values())\n    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())\n    .slice(0, limit);\n}\n\n/** Retry FAILED recipients without re-sending already successful deliveries. */\nexport async function retryFailedBroadcastRecipients(\n  broadcastId: string,\n  userId?: string\n): Promise<{ retried: number; skipped: number }> {\n  const client = getUpstashClient();\n  if (!client) throw new Error('REDIS_REQUIRED');\n  const record = await getBroadcastDetails(broadcastId);\n  if (!record) throw new Error('BROADCAST_NOT_FOUND');\n\n  const directory = await client.get<RecipientDirectoryEntry[]>(`${RECIPIENT_DIR_KEY}:${record.seasonId}`);\n  const byUser = new Map((Array.isArray(directory) ? directory : []).map((entry) => [entry.userId, entry]));\n  const targets = record.recipients.filter((recipient) =>\n    recipient.status === 'FAILED' && (!userId || recipient.userId === userId)\n  );\n  if (userId && targets.length === 0) throw new Error('FAILED_RECIPIENT_NOT_FOUND');\n\n  let retried = 0;\n  let skipped = 0;\n  for (const recipient of targets) {\n    const directoryEntry = byUser.get(recipient.userId);\n    if (!directoryEntry?.messageable || !directoryEntry.telegramId) {\n      skipped++;\n      continue;\n    }\n    const now = new Date().toISOString();\n    const retryNumber = Number(recipient.retryCount || 0) + 1;\n    const job: NotificationQueueJob = {\n      jobId: `job-retry-${broadcastId}-${recipient.userId}-${Date.now()}-${retryNumber}`,\n      broadcastId,\n      userId: recipient.userId,\n      username: recipient.username || directoryEntry.username || 'player',\n      displayName: recipient.displayName || directoryEntry.displayName || 'EFL Player',\n      telegramId: directoryEntry.telegramId,\n      title: record.title,\n      body: record.body,\n      type: record.type,\n      status: 'QUEUED',\n      retryCount: 0,\n      maxRetries: 3,\n      createdAt: now,\n      availableAt: Date.now(),\n      bodyIsHtml: Boolean(record.bodyIsHtml),\n      replyMarkup: record.replyMarkup,\n    };\n    recipient.status = 'PENDING';\n    recipient.retryCount = retryNumber;\n    delete recipient.error;\n    delete recipient.sentAt;\n    await client.rpush(QUEUE_KEY, JSON.stringify(job));\n    retried++;\n  }\n\n  if (retried > 0) {\n    record.metrics.failedCount = Math.max(0, Number(record.metrics.failedCount || 0) - retried);\n    record.status = 'QUEUED';\n    await client.hset(BROADCASTS_KEY, { [record.id]: record });\n    memoryBroadcasts.set(record.id, record);\n    scheduleNotificationQueueDrain();\n  }\n  return { retried, skipped };\n}\n\n/**\n * Returns single broadcast record by ID.\n */\nexport async function getBroadcastDetails(broadcastId: string): Promise<TelegramBroadcastRecord | null> {\n  const client = getUpstashClient();\n  if (client) {\n    try {\n      const record = await client.hget<TelegramBroadcastRecord>(BROADCASTS_KEY, broadcastId);\n      if (record) return record;\n    } catch {}\n  }\n  return memoryBroadcasts.get(broadcastId) || null;\n}\n", "import { getUpstashClient, KEY_PREFIX } from '../readModel/readModelStore';\n\nexport type SmartNotificationEvent =\n  | 'resultVerification'\n  | 'resultConfirmed'\n  | 'resultDisputed'\n  | 'nextOpponent'\n  | 'matchdayOpened'\n  | 'cupProgress'\n  | 'qualification'\n  | 'europeanOutcome';\n\nexport interface SmartNotificationSettings {\n  seasonId: string;\n  enabled: boolean;\n  events: Record<SmartNotificationEvent, boolean>;\n  updatedAt?: string;\n  updatedBy?: string;\n}\n\n// Short cache keeps admin toggles responsive across serverless instances without Firestore reads.\nconst SETTINGS_TTL_MS = 15_000;\nconst memory = new Map<string, { value: SmartNotificationSettings; expiresAt: number }>();\n\nexport const DEFAULT_SMART_NOTIFICATION_EVENTS: Record<SmartNotificationEvent, boolean> = {\n  resultVerification: true,\n  resultConfirmed: true,\n  resultDisputed: true,\n  nextOpponent: true,\n  matchdayOpened: true,\n  cupProgress: true,\n  qualification: true,\n  europeanOutcome: true,\n};\n\nexport function defaultSmartNotificationSettings(seasonId = 'season-2026-27'): SmartNotificationSettings {\n  return {\n    seasonId,\n    enabled: true,\n    events: { ...DEFAULT_SMART_NOTIFICATION_EVENTS },\n  };\n}\n\nfunction settingsKey(seasonId: string): string {\n  return `${KEY_PREFIX}:telegram:smart:settings:${seasonId}`;\n}\n\nfunction normalizeSettings(raw: Partial<SmartNotificationSettings> | null | undefined, seasonId: string): SmartNotificationSettings {\n  const base = defaultSmartNotificationSettings(seasonId);\n  return {\n    seasonId,\n    enabled: typeof raw?.enabled === 'boolean' ? raw.enabled : base.enabled,\n    events: {\n      ...base.events,\n      ...(raw?.events || {}),\n    },\n    updatedAt: raw?.updatedAt,\n    updatedBy: raw?.updatedBy,\n  };\n}\n\nexport async function getSmartNotificationSettings(\n  seasonId = 'season-2026-27'\n): Promise<SmartNotificationSettings> {\n  const cached = memory.get(seasonId);\n  if (cached && cached.expiresAt > Date.now()) return cached.value;\n\n  const client = getUpstashClient();\n  if (!client) {\n    const fallback = defaultSmartNotificationSettings(seasonId);\n    memory.set(seasonId, { value: fallback, expiresAt: Date.now() + SETTINGS_TTL_MS });\n    return fallback;\n  }\n\n  try {\n    const raw = await client.get<SmartNotificationSettings>(settingsKey(seasonId));\n    const value = normalizeSettings(raw, seasonId);\n    memory.set(seasonId, { value, expiresAt: Date.now() + SETTINGS_TTL_MS });\n    return value;\n  } catch (error: any) {\n    console.warn('[SMART_NOTIFY_SETTINGS] Redis read failed, using safe defaults:', error?.message || error);\n    const fallback = defaultSmartNotificationSettings(seasonId);\n    memory.set(seasonId, { value: fallback, expiresAt: Date.now() + SETTINGS_TTL_MS });\n    return fallback;\n  }\n}\n\nexport async function updateSmartNotificationSettings(params: {\n  seasonId?: string;\n  enabled: boolean;\n  events: Record<SmartNotificationEvent, boolean>;\n  updatedBy: string;\n}): Promise<SmartNotificationSettings> {\n  const seasonId = params.seasonId || 'season-2026-27';\n  const value: SmartNotificationSettings = normalizeSettings({\n    enabled: params.enabled,\n    events: params.events,\n    updatedAt: new Date().toISOString(),\n    updatedBy: params.updatedBy,\n  }, seasonId);\n\n  const client = getUpstashClient();\n  const isHosted = Boolean(process.env.VERCEL || process.env.K_SERVICE || process.env.NODE_ENV === 'production');\n  if (!client) {\n    if (isHosted) throw new Error('SMART_NOTIFICATION_SETTINGS_REDIS_UNAVAILABLE');\n    memory.set(seasonId, { value, expiresAt: Number.MAX_SAFE_INTEGER });\n    return value;\n  }\n\n  await client.set(settingsKey(seasonId), value);\n  memory.set(seasonId, { value, expiresAt: Date.now() + SETTINGS_TTL_MS });\n  return value;\n}\n\nexport async function isSmartNotificationEventEnabled(\n  seasonId: string,\n  event?: SmartNotificationEvent | null\n): Promise<boolean> {\n  const settings = await getSmartNotificationSettings(seasonId);\n  if (!settings.enabled) return false;\n  if (!event) return true;\n  return settings.events[event] !== false;\n}\n", "/** Telegram opens inline web_app buttons inside its Mini App WebView. */\nexport function telegramMiniAppButton(text = '\uD83C\uDFDF EFL UZ ilovasini ochish') {\n  const url = process.env.TELEGRAM_WEBAPP_URL?.trim()\n    || process.env.APP_URL?.trim()\n    || 'https://efluz.vercel.app';\n  return { text, web_app: { url } };\n}\n", "import { filterRetiredFixtures } from './retiredFixtureService';\nimport crypto from 'crypto';\nimport { Fixture } from '../../types';\nimport {\n  getUpstashClient,\n  KEY_PREFIX,\n  ReadModelKeys,\n  redisGetFresh,\n  redisGetLkg,\n} from '../readModel/readModelStore';\nimport { scheduleNotificationQueueDrain } from './telegramNotificationQueue';\nimport { isSmartNotificationEventEnabled, SmartNotificationEvent } from './smartNotificationSettingsService';\nimport { telegramMiniAppButton } from './telegramMiniAppButton';\nimport { persistBackupNotification, SMART_ENQUEUE_SCRIPT } from './notificationBackupQueue';\n\ninterface RecipientDirectoryEntry {\n  userId: string;\n  username: string;\n  displayName: string;\n  telegramId: string | number | null;\n  clubId?: string;\n  messageable: boolean;\n}\n\ninterface SmartRecipientStatus {\n  userId: string;\n  username: string;\n  displayName: string;\n  status: 'PENDING';\n  retryCount: number;\n}\n\ninterface SmartBroadcastRecord {\n  id: string;\n  seasonId: string;\n  title: string;\n  body: string;\n  type: 'CUSTOM_ALERT';\n  targetAudience: 'SELECTED_RECIPIENTS';\n  createdById: string;\n  createdByUsername: string;\n  createdAt: string;\n  status: 'QUEUED';\n  metrics: { totalRecipients: number; sentCount: number; failedCount: number; skippedCount: number };\n  recipients: SmartRecipientStatus[];\n  bodyIsHtml?: boolean;\n  replyMarkup?: any;\n}\n\ninterface SmartQueueJob {\n  jobId: string;\n  broadcastId: string;\n  userId: string;\n  username: string;\n  displayName: string;\n  telegramId?: string | number;\n  seasonId?: string;\n  requiresRecipientLookup?: boolean;\n  title: string;\n  body: string;\n  type: 'CUSTOM_ALERT';\n  status: 'QUEUED';\n  retryCount: number;\n  maxRetries: number;\n  createdAt: string;\n  availableAt: number;\n  bodyIsHtml?: boolean;\n  replyMarkup?: any;\n}\n\nconst BROADCASTS_KEY = `${KEY_PREFIX}:telegram:broadcasts`;\nconst QUEUE_KEY = `${KEY_PREFIX}:telegram:queue`;\nconst RECIPIENT_DIR_KEY = `${KEY_PREFIX}:private:recipient-directory`;\nconst SMART_DEDUPE_PREFIX = `${KEY_PREFIX}:telegram:smart:dedupe`;\nconst SMART_DEDUPE_TTL_SECONDS = 7 * 24 * 60 * 60;\n\nfunction inferSmartEvent(eventId: string): SmartNotificationEvent | null {\n  const value = String(eventId || '').toLowerCase();\n  if (value.includes(':verify:')) return 'resultVerification';\n  if (value.includes(':confirmed')) return 'resultConfirmed';\n  if (value.includes(':disputed')) return 'resultDisputed';\n  if (value.startsWith('next-fixture:')) return 'nextOpponent';\n  if (value.startsWith('matchday-open:')) return 'matchdayOpened';\n  if (value.startsWith('cup-advance:') || value.startsWith('cup-champion:')) return 'cupProgress';\n  if (value.includes('qualification') || value.includes('qualified')) return 'qualification';\n  if (value.includes('european') || value.includes('league-phase') || value.includes('playoff')) return 'europeanOutcome';\n  return null;\n}\n\nfunction escapeHtml(value: unknown): string {\n  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;');\n}\n\nfunction ownerId(fixture: Fixture, side: 'home' | 'away'): string | undefined {\n  return side === 'home'\n    ? (fixture.homeOwnerId || fixture.homeOwner?.userId || (fixture as any).homeUser?.id)\n    : (fixture.awayOwnerId || fixture.awayOwner?.userId || (fixture as any).awayUser?.id);\n}\n\nfunction ownerOfClub(fixtures: Fixture[], clubId: string): string | undefined {\n  const fixture = fixtures.find((item) => item.homeClubId === clubId || item.awayClubId === clubId);\n  return fixture ? ownerId(fixture, fixture.homeClubId === clubId ? 'home' : 'away') : undefined;\n}\n\nfunction clubName(fixture: Fixture, side: 'home' | 'away'): string {\n  return side === 'home'\n    ? (fixture.homeClub?.name || fixture.homeClubId || 'Home')\n    : (fixture.awayClub?.name || fixture.awayClubId || 'Away');\n}\n\nfunction contextLine(fixture: Fixture): string {\n  const competition = escapeHtml(fixture.competitionName || fixture.competitionId || 'EFL UZ');\n  const round = fixture.roundName ? escapeHtml(fixture.roundName) : `Matchday ${Number(fixture.matchday || 0)}`;\n  return `<b>${competition}</b> \u2022 ${round}`;\n}\n\nfunction scoreLine(fixture: Fixture): string {\n  const home = escapeHtml(clubName(fixture, 'home'));\n  const away = escapeHtml(clubName(fixture, 'away'));\n  const homeScore = fixture.homeScore ?? '\u2013';\n  const awayScore = fixture.awayScore ?? '\u2013';\n  return `\u26BD <b>${home}</b>  ${homeScore}\u2013${awayScore}  <b>${away}</b>`;\n}\n\nfunction formatTashkentTime(value?: string | null): string | null {\n  if (!value) return null;\n  const parsed = new Date(value);\n  if (Number.isNaN(parsed.getTime())) return escapeHtml(value);\n  try {\n    return new Intl.DateTimeFormat('uz-UZ', {\n      timeZone: 'Asia/Tashkent',\n      day: '2-digit',\n      month: '2-digit',\n      year: 'numeric',\n      hour: '2-digit',\n      minute: '2-digit',\n      hour12: false,\n    }).format(parsed) + ' (Toshkent)';\n  } catch {\n    return `${parsed.toISOString().slice(0, 16).replace('T', ' ')} UTC`;\n  }\n}\n\nasync function opponentText(userId: string | undefined, seasonId: string): Promise<string> {\n  if (!userId) return 'TBD';\n  const recipient = await getCachedRecipient(userId, seasonId);\n  const username = String(recipient?.username || '').replace(/^@+/, '').trim();\n  if (username) return `@${escapeHtml(username)}`;\n  return escapeHtml(recipient?.displayName || 'TBD');\n}\n\nasync function buildMatchCardBody(params: {\n  fixture: Fixture;\n  viewerSide?: 'home' | 'away';\n  deadlineAt?: string | null;\n  footer?: string;\n  showScore?: boolean;\n}): Promise<string> {\n  const fixture = params.fixture;\n  const seasonId = fixture.seasonId || 'season-2026-27';\n  const homeUser = await opponentText(ownerId(fixture, 'home'), seasonId);\n  const awayUser = await opponentText(ownerId(fixture, 'away'), seasonId);\n  const deadline = formatTashkentTime(params.deadlineAt || fixture.scheduledAt);\n  const home = escapeHtml(clubName(fixture, 'home'));\n  const away = escapeHtml(clubName(fixture, 'away'));\n  const matchup = params.showScore\n    ? scoreLine(fixture)\n    : `\u26BD <b>${home}</b>  vs  <b>${away}</b>`;\n  const viewer = params.viewerSide === 'home' ? `\uD83C\uDFAE Siz: <b>${home}</b>` : params.viewerSide === 'away' ? `\uD83C\uDFAE Siz: <b>${away}</b>` : '';\n  return [\n    `\uD83C\uDFDF ${contextLine(fixture)}`,\n    '',\n    matchup,\n    `\uD83D\uDC64 ${homeUser}  \u2022  ${awayUser}`,\n    viewer,\n    deadline ? `\u23F3 <b>${deadline}</b>` : '',\n    params.footer ? `\\n${params.footer}` : '',\n  ].filter(Boolean).join('\\n');\n}\n\nconst RESULT_TOPIC_BY_LEAGUE: Record<string, string> = {\n  'league-premier-league': 'https://t.me/efleagueuz/2',\n  'league-la-liga': 'https://t.me/efleagueuz/3',\n  'league-serie-a': 'https://t.me/efleagueuz/4',\n  'league-bundesliga': 'https://t.me/efleagueuz/5',\n  'league-ligue-1': 'https://t.me/efleagueuz/6',\n};\n\nfunction resultTopicUrl(fixture: Fixture): string {\n  const competition = `${fixture.competitionId || ''} ${fixture.competitionName || ''}`.toLowerCase();\n  if (competition.includes('super')) return 'https://t.me/efleagueuz/2335';\n  if (competition.includes('champions') || competition.includes('ucl')) return 'https://t.me/efleagueuz/7';\n  if (competition.includes('cup') || competition.includes('pokal') || competition.includes('copa') || competition.includes('coppa') || competition.includes('coupe')) return 'https://t.me/efleagueuz/8';\n  const leagueId = fixture.homeClub?.leagueId || fixture.awayClub?.leagueId || '';\n  return RESULT_TOPIC_BY_LEAGUE[leagueId] || 'https://t.me/efleagueuz';\n}\n\nasync function fixtureReplyMarkup(fixture: Fixture, opponentUserId?: string, includeResultAction = true) {\n  const rows: any[][] = [];\n  if (opponentUserId) {\n    const opponent = await getCachedRecipient(opponentUserId, fixture.seasonId || 'season-2026-27');\n    const username = String(opponent?.username || '').replace(/^@+/, '').trim();\n    if (username) rows.push([{ text: `\uD83D\uDC64 @${username}`, url: `https://t.me/${username}` }]);\n  }\n  if (includeResultAction) rows.push([{ text: '\uD83D\uDCF8 Natijani yuborish', url: resultTopicUrl(fixture) }]);\n  rows.push([telegramMiniAppButton()]);\n  return { inline_keyboard: rows };\n}\n\nasync function getCompetitionFixtureSnapshot(competitionId: string, seasonId: string): Promise<Fixture[]> {\n  const key = ReadModelKeys.competitionFixtures(competitionId, seasonId);\n  const snapshot = (await redisGetFresh<Fixture[]>(key)) || (await redisGetLkg<Fixture[]>(key));\n  return Array.isArray(snapshot?.data) ? filterRetiredFixtures(snapshot!.data, seasonId) : [];\n}\n\nasync function getCachedRecipient(userId: string, seasonId: string): Promise<RecipientDirectoryEntry | null> {\n  const client = getUpstashClient();\n  if (!client) return null;\n  try {\n    const entries = await client.get<RecipientDirectoryEntry[]>(`${RECIPIENT_DIR_KEY}:${seasonId}`);\n    if (!Array.isArray(entries) || entries.length === 0) return null;\n    return entries.find((entry) => entry.userId === userId) || null;\n  } catch (error: any) {\n    console.warn('[SMART_NOTIFY] Recipient directory read failed:', error?.message || error);\n    return null;\n  }\n}\n\nasync function getCachedRecipientByClubId(clubId: string, seasonId: string): Promise<RecipientDirectoryEntry | null> {\n  const client = getUpstashClient();\n  if (!client) return null;\n  try {\n    const entries = await client.get<RecipientDirectoryEntry[]>(`${RECIPIENT_DIR_KEY}:${seasonId}`);\n    if (!Array.isArray(entries) || entries.length === 0) return null;\n    return entries.find((entry) => entry.clubId === clubId) || null;\n  } catch (error: any) {\n    console.warn('[SMART_NOTIFY] Club recipient lookup failed:', error?.message || error);\n    return null;\n  }\n}\n\nexport async function enqueueSmartTelegramNotification(params: {\n  userId: string;\n  seasonId: string;\n  eventId: string;\n  title: string;\n  body: string;\n  replyMarkup?: any;\n}): Promise<boolean> {\n  const event = inferSmartEvent(params.eventId);\n  if (!(await isSmartNotificationEventEnabled(params.seasonId, event))) {\n    console.info('[SMART_NOTIFY_DISABLED]', JSON.stringify({ event, eventId: params.eventId, seasonId: params.seasonId }));\n    return false;\n  }\n\n  const client = getUpstashClient();\n  const recipient = await getCachedRecipient(params.userId, params.seasonId);\n  if (recipient && (!recipient.messageable || !recipient.telegramId)) {\n    console.info('[SMART_NOTIFY] Recipient not messageable', { userId: params.userId, seasonId: params.seasonId });\n    return false;\n  }\n\n  const digest = crypto.createHash('sha256').update(`${params.eventId}:${params.userId}`).digest('hex');\n  const broadcastId = `smart-${digest}`;\n  const jobId = `job-${broadcastId}-${params.userId}`;\n  const dedupeKey = `${SMART_DEDUPE_PREFIX}:${digest}`;\n  const now = new Date().toISOString();\n  const record: SmartBroadcastRecord = {\n    id: broadcastId,\n    seasonId: params.seasonId,\n    title: params.title,\n    body: params.body,\n    type: 'CUSTOM_ALERT',\n    targetAudience: 'SELECTED_RECIPIENTS',\n    createdById: 'system:smart-notifications',\n    createdByUsername: 'EFL UZ',\n    createdAt: now,\n    status: 'QUEUED',\n    metrics: { totalRecipients: 1, sentCount: 0, failedCount: 0, skippedCount: 0 },\n    recipients: [{ userId: recipient?.userId || params.userId, username: recipient?.username || 'player', displayName: recipient?.displayName || recipient?.username || 'EFL Player', status: 'PENDING', retryCount: 0 }],\n    bodyIsHtml: true,\n    replyMarkup: params.replyMarkup,\n  };\n  const job: SmartQueueJob = {\n    jobId,\n    broadcastId,\n    userId: recipient?.userId || params.userId,\n    username: recipient?.username || 'player',\n    displayName: recipient?.displayName || recipient?.username || 'EFL Player',\n    telegramId: recipient?.telegramId || undefined,\n    seasonId: params.seasonId,\n    requiresRecipientLookup: !recipient,\n    title: params.title,\n    body: params.body,\n    type: 'CUSTOM_ALERT',\n    status: 'QUEUED',\n    retryCount: 0,\n    maxRetries: 3,\n    createdAt: now,\n    availableAt: Date.now(),\n    bodyIsHtml: true,\n    replyMarkup: params.replyMarkup,\n  };\n\n  try {\n    if (!client) throw new Error('PRIMARY_REDIS_UNAVAILABLE');\n    const queued = await client.eval<unknown[], number>(SMART_ENQUEUE_SCRIPT, [dedupeKey, BROADCASTS_KEY, QUEUE_KEY], [SMART_DEDUPE_TTL_SECONDS, broadcastId, JSON.stringify(record), JSON.stringify(job)]);\n    if (Number(queued) === 0) return false;\n    if (Number(queued) !== 1) throw new Error('PRIMARY_QUEUE_WRITE_UNCONFIRMED');\n    scheduleNotificationQueueDrain();\n    console.info('[SMART_NOTIFY_QUEUED]', JSON.stringify({ eventId: params.eventId, userId: params.userId, broadcastId }));\n    return true;\n  } catch (error: any) {\n    try {\n      // Resolve the current recipient again after recovery, including suspension.\n      job.requiresRecipientLookup = true;\n      if (await persistBackupNotification({ dedupeKey, broadcastId, record: JSON.stringify(record), job: JSON.stringify(job) })) {\n        console.info('[SMART_NOTIFY_BACKUP_SAVED]', { broadcastId });\n        scheduleNotificationQueueDrain();\n        return true;\n      }\n    } catch (backupError: any) {\n      console.error('[SMART_NOTIFY_BACKUP_FAILED]', backupError?.message || backupError);\n    }\n    console.error('[SMART_NOTIFY_NOT_PERSISTED]', { broadcastId, reason: error?.message || 'PRIMARY_REDIS_UNAVAILABLE' });\n    return false;\n  }\n}\n\nexport async function notifySmartMatchdayOpened(params: {\n  competitionId: string;\n  seasonId: string;\n  matchday: number;\n  deadlineAt?: string | null;\n}): Promise<number> {\n  const fixtures = await getCompetitionFixtureSnapshot(params.competitionId, params.seasonId);\n  const matchdayFixtures = fixtures.filter((fixture) => Number(fixture.matchday) === Number(params.matchday));\n  if (matchdayFixtures.length === 0) return 0;\n  const tasks: Array<Promise<boolean>> = [];\n\n  for (const fixture of matchdayFixtures) {\n    const homeUserId = ownerId(fixture, 'home');\n    const awayUserId = ownerId(fixture, 'away');\n    if (homeUserId) tasks.push(enqueueSmartTelegramNotification({\n      userId: homeUserId,\n      seasonId: params.seasonId,\n      eventId: `matchday-open:${params.competitionId}:${params.matchday}:${fixture.id}:${params.deadlineAt || ''}`,\n      title: '\uD83D\uDE80 Matchday ochildi',\n      body: await buildMatchCardBody({ fixture, viewerSide: 'home', deadlineAt: params.deadlineAt, footer: 'O\u2018yinni o\u2018tkazing va natijani yuboring.' }),\n      replyMarkup: await fixtureReplyMarkup(fixture, awayUserId),\n    }));\n    if (awayUserId) tasks.push(enqueueSmartTelegramNotification({\n      userId: awayUserId,\n      seasonId: params.seasonId,\n      eventId: `matchday-open:${params.competitionId}:${params.matchday}:${fixture.id}:${params.deadlineAt || ''}`,\n      title: '\uD83D\uDE80 Matchday ochildi',\n      body: await buildMatchCardBody({ fixture, viewerSide: 'away', deadlineAt: params.deadlineAt, footer: 'O\u2018yinni o\u2018tkazing va natijani yuboring.' }),\n      replyMarkup: await fixtureReplyMarkup(fixture, homeUserId),\n    }));\n  }\n  const results = await Promise.allSettled(tasks);\n  return results.filter((result) => result.status === 'fulfilled' && result.value).length;\n}\n\nasync function notifyNextFixtureIfKnown(fixture: Fixture): Promise<void> {\n  const seasonId = fixture.seasonId || 'season-2026-27';\n  const fixtures = await getCompetitionFixtureSnapshot(fixture.competitionId, seasonId);\n  if (fixtures.length === 0) return;\n  const sides: Array<{ userId?: string; clubId: string | null }> = [\n    { userId: ownerId(fixture, 'home'), clubId: fixture.homeClubId },\n    { userId: ownerId(fixture, 'away'), clubId: fixture.awayClubId },\n  ];\n\n  for (const side of sides) {\n    if (!side.userId || !side.clubId) continue;\n    const next = fixtures\n      .filter((candidate) => candidate.id !== fixture.id && (candidate.homeClubId === side.clubId || candidate.awayClubId === side.clubId) && !['CONFIRMED', 'CANCELLED'].includes(candidate.status) && Number(candidate.matchday || 0) >= Number(fixture.matchday || 0))\n      .sort((a, b) => Number(a.matchday || 0) - Number(b.matchday || 0) || String(a.scheduledAt || '').localeCompare(String(b.scheduledAt || '')))[0];\n    if (!next) continue;\n    const viewerSide = next.homeClubId === side.clubId ? 'home' : 'away';\n    const opponentId = ownerId(next, viewerSide === 'home' ? 'away' : 'home');\n    await enqueueSmartTelegramNotification({\n      userId: side.userId,\n      seasonId,\n      eventId: `next-fixture:${fixture.id}:${next.id}`,\n      title: '\uD83C\uDFAF Keyingi raqib tayyor',\n      body: await buildMatchCardBody({ fixture: next, viewerSide, footer: 'Keyingi o\u2018yin tafsilotlari tayyor.' }),\n      replyMarkup: await fixtureReplyMarkup(next, opponentId),\n    });\n  }\n}\n\nexport async function notifySmartCupAdvancement(params: {\n  competitionId: string;\n  seasonId: string;\n  sourceFixtureId: string;\n  targetFixtureId: string;\n  winnerClubId: string;\n}): Promise<boolean> {\n  const recipient = await getCachedRecipientByClubId(params.winnerClubId, params.seasonId);\n  const fixtures = await getCompetitionFixtureSnapshot(params.competitionId, params.seasonId);\n  const source = fixtures.find((fixture) => fixture.id === params.sourceFixtureId);\n  const winnerUserId = recipient?.userId || ownerOfClub(source ? [source] : [], params.winnerClubId);\n  if (!winnerUserId) return false;\n  const target = fixtures.find((fixture) => fixture.id === params.targetFixtureId);\n  const viewerSide = target?.homeClubId === params.winnerClubId ? 'home' : target?.awayClubId === params.winnerClubId ? 'away' : undefined;\n  return enqueueSmartTelegramNotification({\n    userId: winnerUserId,\n    seasonId: params.seasonId,\n    eventId: `cup-advance:${params.sourceFixtureId}:${params.targetFixtureId}:${params.winnerClubId}`,\n    title: '\uD83C\uDFC6 Keyingi bosqichga o\u2018tdingiz',\n    body: target\n      ? await buildMatchCardBody({ fixture: target, viewerSide, footer: 'Bracket yangilandi. Keyingi bosqichga tayyorlaning.' })\n      : `<b>Keyingi bosqich</b>\\n\\nBracket yangilandi. Tafsilotlar EFL UZ ilovasida.`,\n    replyMarkup: target ? await fixtureReplyMarkup(target, viewerSide === 'home' ? ownerId(target, 'away') : ownerId(target, 'home')) : { inline_keyboard: [[telegramMiniAppButton()]] },\n  });\n}\n\nexport async function notifySmartCupChampion(params: {\n  competitionId: string;\n  seasonId: string;\n  sourceFixtureId: string;\n  winnerClubId: string;\n}): Promise<boolean> {\n  const recipient = await getCachedRecipientByClubId(params.winnerClubId, params.seasonId);\n  const fixtures = await getCompetitionFixtureSnapshot(params.competitionId, params.seasonId);\n  const finalFixture = fixtures.find((fixture) => fixture.id === params.sourceFixtureId);\n  const winnerUserId = recipient?.userId || ownerOfClub(finalFixture ? [finalFixture] : [], params.winnerClubId);\n  if (!winnerUserId) return false;\n  const competitionName = finalFixture?.competitionName || params.competitionId;\n  return enqueueSmartTelegramNotification({\n    userId: winnerUserId,\n    seasonId: params.seasonId,\n    eventId: `cup-champion:${params.competitionId}:${params.sourceFixtureId}:${params.winnerClubId}`,\n    title: '\uD83D\uDC51 Chempion!',\n    body: finalFixture\n      ? `${await buildMatchCardBody({ fixture: finalFixture, showScore: true })}\\n\\n\uD83C\uDFC6 <b>${escapeHtml(competitionName)} chempioni!</b>\\nTrophy Cabinet yangilanadi.`\n      : `\uD83C\uDFC6 <b>${escapeHtml(competitionName)}</b>\\n\\nTabriklaymiz \u2014 siz chempion bo\u2018ldingiz!`,\n    replyMarkup: { inline_keyboard: [[telegramMiniAppButton()]] },\n  });\n}\n\nexport async function notifySmartEuropeanZones(params: {\n  competitionId: string;\n  seasonId: string;\n  rows: Array<{ clubId: string; clubName: string; position: number; zone: 'DIRECT_R16' | 'KNOCKOUT_PLAYOFF' | 'ELIMINATED'; zoneLabel: string }>;\n}): Promise<number> {\n  const tasks: Array<Promise<boolean>> = [];\n  let fixtures: Fixture[] | undefined;\n  for (const row of params.rows) {\n    const recipient = await getCachedRecipientByClubId(row.clubId, params.seasonId);\n    if (!recipient && !fixtures) fixtures = await getCompetitionFixtureSnapshot(params.competitionId, params.seasonId);\n    const userId = recipient?.userId || ownerOfClub(fixtures || [], row.clubId);\n    if (!userId) continue;\n    const title = row.zone === 'DIRECT_R16' ? '\uD83C\uDF1F To\u2018g\u2018ridan-to\u2018g\u2018ri yo\u2018llanma' : row.zone === 'KNOCKOUT_PLAYOFF' ? '\u2694\uFE0F Play-off yo\u2018llanmasi' : '\uD83D\uDCCB Liga bosqichi yakunlandi';\n    tasks.push(enqueueSmartTelegramNotification({\n      userId,\n      seasonId: params.seasonId,\n      eventId: `european-zone:${params.competitionId}:${row.clubId}:${row.zone}:${row.position}`,\n      title,\n      body: `\uD83C\uDFDF <b>${escapeHtml(row.clubName)}</b> \u2022 #${row.position}\\n\\n${escapeHtml(row.zoneLabel)}\\n\\nYevrokubok holatingiz EFL UZ ilovasida yangilandi.`,\n      replyMarkup: { inline_keyboard: [[telegramMiniAppButton()]] },\n    }));\n  }\n  const results = await Promise.allSettled(tasks);\n  return results.filter((result) => result.status === 'fulfilled' && result.value).length;\n}\n\nexport async function notifySmartResultLifecycle(fixture: Fixture, actorUserId: string): Promise<void> {\n  const seasonId = fixture.seasonId || 'season-2026-27';\n  const homeOwnerId = ownerId(fixture, 'home');\n  const awayOwnerId = ownerId(fixture, 'away');\n  const owners = [...new Set([homeOwnerId, awayOwnerId].filter(Boolean) as string[])];\n  if (owners.length === 0) return;\n  const status = fixture.status;\n  const revision = fixture.resultConfirmedAt || fixture.updatedAt || `${fixture.homeScore}-${fixture.awayScore}`;\n  const eventBase = `${fixture.id}:${status}:${revision}`;\n\n  if (status === 'PENDING_CONFIRMATION') {\n    const opponentId = owners.find((id) => id !== actorUserId);\n    if (!opponentId) return;\n    await enqueueSmartTelegramNotification({\n      userId: opponentId,\n      seasonId,\n      eventId: `${eventBase}:verify:${actorUserId}`,\n      title: '\u26A1 Natijani tasdiqlang',\n      body: await buildMatchCardBody({ fixture, showScore: true, footer: 'Raqib natijani yubordi. Hisobni tekshirib, o\u2018z natijangizni yuboring.' }),\n      replyMarkup: await fixtureReplyMarkup(fixture, actorUserId),\n    });\n    return;\n  }\n\n  if (status === 'CONFIRMED') {\n    await Promise.all(owners.map(async (userId) => enqueueSmartTelegramNotification({\n      userId,\n      seasonId,\n      eventId: `${eventBase}:confirmed`,\n      title: '\u2705 Natija tasdiqlandi',\n      body: await buildMatchCardBody({ fixture, showScore: true, footer: 'Natija rasmiy tasdiqlandi. Jadval va statistikalar yangilandi.' }),\n      replyMarkup: await fixtureReplyMarkup(fixture, owners.find((id) => id !== userId), false),\n    })));\n    await notifyNextFixtureIfKnown(fixture).catch((error: any) => console.warn('[SMART_NOTIFY] Next fixture lookup failed:', error?.message || error));\n    return;\n  }\n\n  if (status === 'DISPUTED') {\n    await Promise.all(owners.map(async (userId) => enqueueSmartTelegramNotification({\n      userId,\n      seasonId,\n      eventId: `${eventBase}:disputed`,\n      title: '\u26A0\uFE0F Natijalar mos kelmadi',\n      body: await buildMatchCardBody({ fixture, showScore: true, footer: 'Ikki tomon yuborgan natijalar mos kelmadi. Admin ko\u2018rib chiqishi talab qilinadi.' }),\n      replyMarkup: await fixtureReplyMarkup(fixture, owners.find((id) => id !== userId)),\n    })));\n  }\n}\n", "import type { StandingsRow } from '../../types';\n\n/** Pure projection from authoritative fixtures; never reads SQLite or writes a database. */\nexport function projectStandings(\n  clubs: Array<{ id: string; name: string; shortName: string; logoUrl?: string }>,\n  fixtures: Array<{ id: string; homeClubId?: string | null; awayClubId?: string | null; status: string; homeScore?: number | null; awayScore?: number | null; scheduledAt?: string; resultConfirmedAt?: string | null }>,\n  config: any = {}\n): StandingsRow[] {\n  const win=Number(config.pointsForWin ?? 3), draw=Number(config.pointsForDraw ?? 1), loss=Number(config.pointsForLoss ?? 0);\n  const rows: StandingsRow[]=clubs.map(c=>({position:0,clubId:c.id,clubName:c.name,shortName:c.shortName,logoUrl:c.logoUrl,played:0,won:0,drawn:0,lost:0,goalsFor:0,goalsAgainst:0,goalDifference:0,points:0,form:[]}));\n  const byId=new Map(rows.map(row=>[row.clubId,row]));\n  const confirmed=fixtures.filter(f=>f.status==='CONFIRMED').sort((a,b)=>(Date.parse(a.resultConfirmedAt || a.scheduledAt || '') || 0)-(Date.parse(b.resultConfirmedAt || b.scheduledAt || '') || 0)||a.id.localeCompare(b.id));\n  for(const f of confirmed) {\n    if(!f.homeClubId || !f.awayClubId || f.homeClubId===f.awayClubId || !Number.isInteger(f.homeScore) || !Number.isInteger(f.awayScore) || f.homeScore!<0 || f.awayScore!<0) throw new Error(`INVALID_CONFIRMED_RESULT: ${f.id}`);\n    const home=byId.get(f.homeClubId), away=byId.get(f.awayClubId);\n    if(!home || !away) throw new Error(`FIXTURE_PARTICIPANT_MISSING: ${f.id}`);\n    for(const [row,forGoals,againstGoals] of [[home,f.homeScore!,f.awayScore!],[away,f.awayScore!,f.homeScore!]] as const) {\n      row.played++; row.goalsFor+=forGoals; row.goalsAgainst+=againstGoals; row.goalDifference=row.goalsFor-row.goalsAgainst;\n      if(forGoals>againstGoals) {row.won++;row.points+=win;row.form.push('W');}\n      else if(forGoals===againstGoals) {row.drawn++;row.points+=draw;row.form.push('D');}\n      else {row.lost++;row.points+=loss;row.form.push('L');}\n      row.form=row.form.slice(-5);\n    }\n  }\n  const rules: string[]=config.tieBreakers || ['points','goalDifference','goalsFor','headToHead'];\n  if(rules.some(rule=>!['points','goalDifference','goalsFor','headToHead','wins'].includes(rule))) throw new Error('UNSUPPORTED_TIEBREAKER');\n  function rank(group:StandingsRow[],index:number):StandingsRow[] {\n    if(group.length<2 || index>=rules.length) return [...group].sort((a,b)=>a.clubId.localeCompare(b.clubId));\n    const rule=rules[index];\n    const ids=new Set(group.map(r=>r.clubId));\n    const metric=(row:StandingsRow):number[]=>{\n      if(rule!=='headToHead') return [rule==='wins'?row.won:Number(row[rule as keyof StandingsRow])];\n      let points=0,gd=0,gf=0;\n      for(const f of confirmed) if(ids.has(f.homeClubId!) && ids.has(f.awayClubId!)) {\n        if(f.homeClubId!==row.clubId && f.awayClubId!==row.clubId) continue;\n        const own=f.homeClubId===row.clubId?f.homeScore!:f.awayScore!, other=f.homeClubId===row.clubId?f.awayScore!:f.homeScore!;\n        points+=own>other?win:own===other?draw:loss;gd+=own-other;gf+=own;\n      }\n      return [points,gd,gf];\n    };\n    const metrics=new Map(group.map(r=>[r.clubId,metric(r)]));\n    const compare=(a:StandingsRow,b:StandingsRow)=>{\n      const av=metrics.get(a.clubId)!, bv=metrics.get(b.clubId)!;\n      for(let i=0;i<av.length;i++) if(av[i]!==bv[i]) return bv[i]-av[i];\n      return 0;\n    };\n    const ordered=[...group].sort(compare), output:StandingsRow[]=[];\n    for(let start=0;start<ordered.length;) {\n      let end=start+1;while(end<ordered.length && compare(ordered[start],ordered[end])===0)end++;\n      output.push(...rank(ordered.slice(start,end),index+1));start=end;\n    }\n    return output;\n  }\n  return rank(rows,0).map((row,index)=>({...row,position:index+1}));\n}\n", "import { withSeasonQualificationPolicy } from '../../lib/seasonQualificationPolicy';\nimport { getFirestoreDb } from '../firebase/admin';\nimport {\n  COLLECTIONS,\n  FirestoreCompetitionDoc,\n  FirestoreCompetitionParticipantDoc,\n  FirestoreFixtureDoc,\n  FirestoreClubDoc,\n} from '../firebase/collections';\nimport { calculateCompetitionStandingsFirestore, rebuildCompetitionStandingsFirestore, firestoreCircuitBreaker, trackFirestoreRead } from '../firebase/firestoreStore';\nimport { createAuditLog } from '../services/adminService';\nimport { createNotification } from '../services/notificationService';\nimport { enqueueSmartTelegramNotification, notifySmartEuropeanZones } from '../services/smartNotificationService';\nimport { queryAll, queryGet, queryRun } from '../db';\nimport { SEED_CLUBS, SEED_COMPETITIONS, SEED_LEAGUES } from '../db/seed';\nimport {\n  redisGetRaw,\n  redisSetRaw,\n  redisGetFresh,\n  redisGetLkg,\n  invalidateDataset,\n  readThroughReadModel,\n  getUpstashClient,\n  ReadModelKeys,\n  SCHEMA_VERSION,\n} from '../readModel/readModelStore';\nimport crypto from 'crypto';\nimport { projectStandings } from './standingsProjection';\n\nexport interface QualificationResult {\n  seasonId: string;\n  sourceCompetitionId: string;\n  sourceCompetitionName: string;\n  targetCompetitionId: string;\n  targetCompetitionName: string;\n  clubId: string;\n  clubName: string;\n  ownerUserId: string | null;\n  rank: number;\n  reason: string;\n}\n\nexport interface EuropeanQualificationDiff {\n  competitionId: string;\n  competitionName: string;\n  totalTarget: number;\n  retained: Array<{ clubId: string; clubName: string; rank: number; sourceLeague: string }>;\n  added: Array<{ clubId: string; clubName: string; rank: number; sourceLeague: string }>;\n  removed: Array<{ clubId: string; clubName: string; previousReason?: string }>;\n}\n\nexport interface EuropeanQualificationPreview {\n  sourceFingerprint?: string;\n  previewToken: string;\n  seasonId: string;\n  mode: 'provisional' | 'final';\n  canApply: boolean;\n  blockReason?: string;\n  domesticLeaguesCompleted: boolean;\n  unplayedLeagueMatchesCount: number;\n  hasEuropeanStarted: boolean;\n  summary: {\n    ucl: { totalTarget: number; retainedCount: number; addedCount: number; removedCount: number };\n    uel: { totalTarget: number; retainedCount: number; addedCount: number; removedCount: number };\n  };\n  diff: {\n    ucl: EuropeanQualificationDiff;\n    uel: EuropeanQualificationDiff;\n  };\n  projectedQualifications: QualificationResult[];\n  generatedAt: string;\n  expiresAt: string;\n}\n\nexport interface EuropeanStandingsRow {\n  position: number;\n  clubId: string;\n  clubName: string;\n  badgeUrl?: string;\n  played: number;\n  won: number;\n  drawn: number;\n  lost: number;\n  goalsFor: number;\n  goalsAgainst: number;\n  goalDifference: number;\n  points: number;\n  zone: 'DIRECT_R16' | 'KNOCKOUT_PLAYOFF' | 'ELIMINATED';\n  zoneLabel: string;\n}\n\n// ----------------------------------------------------\n// REDIS PREVIEW TOKEN STORE (15-Minute TTL)\n// ----------------------------------------------------\nconst PREVIEW_TOKEN_REDIS_PREFIX = 'qualification:preview:';\nconst PREVIEW_TOKEN_TTL_SECONDS = 900; // 15 minutes\nconst previewTokenCache = new Map<string, { preview: EuropeanQualificationPreview; expiresAt: number }>();\n\nfunction fingerprintSnapshots(snapshots: any[]): string {\n  const canonical = (value: any): any => Array.isArray(value) ? value.map(canonical) :\n    value && typeof value === 'object' ? Object.fromEntries(Object.keys(value).sort().map(k => [k, canonical(value[k])])) : value;\n  const rows = snapshots.map(s => s.docs.map((d: any) => ({ id: d.id, data: d.data() })).sort((a: any,b: any) => a.id.localeCompare(b.id)));\n  return crypto.createHash('sha256').update(JSON.stringify(canonical(rows))).digest('hex');\n}\n\nexport async function saveQualificationPreviewToken(\n  token: string,\n  preview: EuropeanQualificationPreview\n): Promise<void> {\n  const key = `${PREVIEW_TOKEN_REDIS_PREFIX}${token}`;\n  const payload = {\n    preview,\n    token,\n    expiresAt: Date.now() + PREVIEW_TOKEN_TTL_SECONDS * 1000,\n  };\n  const client = getUpstashClient();\n  if (client) {\n    try {\n      await client.set(key, payload, { ex: PREVIEW_TOKEN_TTL_SECONDS });\n    } catch (err: any) {\n      console.warn(`[QUALIFICATION] Failed to write preview token to Upstash Redis:`, err?.message || err);\n      throw new Error('QUALIFICATION_PREVIEW_STORAGE_UNAVAILABLE');\n    }\n  } else if (process.env.NODE_ENV === 'production' || process.env.VERCEL || process.env.K_SERVICE) {\n    throw new Error('REDIS_REQUIRED_FOR_QUALIFICATION_PREVIEW');\n  }\n  previewTokenCache.set(token, payload);\n}\n\nexport async function getQualificationPreviewToken(\n  token: string\n): Promise<EuropeanQualificationPreview | null> {\n  const key = `${PREVIEW_TOKEN_REDIS_PREFIX}${token}`;\n  const client = getUpstashClient();\n  if (client) {\n    try {\n      const data = await client.get<any>(key);\n      if (data && data.preview) {\n        return data.preview;\n      }\n    } catch (err: any) {\n      console.warn(`[QUALIFICATION] Failed to read preview token from Upstash Redis:`, err?.message || err);\n    }\n  }\n  const mem = previewTokenCache.get(token);\n  if (mem && Date.now() <= mem.expiresAt) {\n    return mem.preview;\n  }\n  return null;\n}\n\nexport async function deleteQualificationPreviewToken(token: string): Promise<void> {\n  const key = `${PREVIEW_TOKEN_REDIS_PREFIX}${token}`;\n  previewTokenCache.delete(token);\n  const client = getUpstashClient();\n  if (client) {\n    try {\n      await client.del(key);\n    } catch {}\n  }\n}\n\n/**\n * Previews European Qualification synchronization (provisional vs final).\n * STRICT DATA SAFETY GUARDS:\n * 1. Block participant sync if competition has started.\n * 2. Block finalization until domestic leagues finish.\n * 3. Never do automatic destructive purges.\n */\nexport async function previewEuropeanQualificationSync(\n  seasonId = 'season-2026-27',\n  mode: 'provisional' | 'final' = 'provisional'\n): Promise<EuropeanQualificationPreview> {\n  const db = getFirestoreDb();\n  const now = new Date();\n  const nowIso = now.toISOString();\n\n  // The isolated regression suite uses the SQLite seed with an empty in-memory\n  // Firestore. Materialize the same read-only seed metadata only in that\n  // explicit fallback mode so qualification format guards can be exercised.\n  if (process.env.FIREBASE_FORCE_LOCAL_FALLBACK === 'true') {\n    for (const league of SEED_LEAGUES) {\n      await db.collection(COLLECTIONS.COMPETITIONS).doc(league.id).set({\n        id: league.id,\n        seasonId,\n        type: 'LEAGUE',\n        name: league.name,\n      }, { merge: true });\n    }\n    for (const competition of SEED_COMPETITIONS) {\n      await db.collection(COLLECTIONS.COMPETITIONS).doc(competition.id).set({\n        id: competition.id,\n        seasonId: competition.seasonId || seasonId,\n        leagueId: competition.leagueId,\n        type: competition.type,\n        name: competition.name,\n        formatConfig: competition.formatConfig,\n      }, { merge: true });\n    }\n  }\n\n  // 1. Fetch competitions, participants, fixtures and occupancies\n  const [compSnap, partsSnap, fixSnap, occSnap] = await Promise.all([\n    db.collection(COLLECTIONS.COMPETITIONS).where('seasonId', '==', seasonId).get(),\n    db.collection(COLLECTIONS.COMPETITION_PARTICIPANTS).where('seasonId', '==', seasonId).get(),\n    db.collection(COLLECTIONS.FIXTURES).where('seasonId', '==', seasonId).get(),\n    db.collection(COLLECTIONS.CLUB_OCCUPANCIES).where('seasonId', '==', seasonId).get(),\n  ]);\n\n  const allComps = compSnap.docs.map((d) => withSeasonQualificationPolicy(d.data() as FirestoreCompetitionDoc,seasonId));\n  const leagues = allComps.filter((c) => c.type === 'LEAGUE');\n  const allFixtures = fixSnap.docs.map((d) => d.data() as FirestoreFixtureDoc);\n  const existingParts = partsSnap.docs.map((d) => d.data() as FirestoreCompetitionParticipantDoc);\n\n  const occupancyMap = new Map<string, string>();\n  for (const doc of occSnap.docs) {\n    const data = doc.data();\n    if (data.userId && data.clubId) {\n      occupancyMap.set(data.clubId, data.userId);\n    }\n  }\n\n  const clubsMap = new Map(SEED_CLUBS.map((c) => [c.id, c]));\n\n  // Identify UCL and UEL competitions\n  const uclComp = allComps.find(\n    (c) => c.type === 'EUROPEAN_LEAGUE_PHASE' && (c.name.toLowerCase().includes('champions') || c.id.includes('ucl'))\n  ) || { id: 'comp-champions-league-2026', name: 'UEFA Champions League', seasonId, type: 'EUROPEAN_LEAGUE_PHASE' as const };\n\n  const uelComp = allComps.find(\n    (c) => c.type === 'EUROPEAN_LEAGUE_PHASE' && (c.name.toLowerCase().includes('europa') || c.id.includes('uel'))\n  ) || { id: 'comp-europa-league-2026', name: 'UEFA Europa League', seasonId, type: 'EUROPEAN_LEAGUE_PHASE' as const };\n\n  // SAFETY GUARD 1: Has UCL or UEL competition started?\n  const uclTotal = Number(((uclComp as FirestoreCompetitionDoc).formatConfig as any)?.leaguePhaseTeams);\n  const uelTotal = Number(((uelComp as FirestoreCompetitionDoc).formatConfig as any)?.leaguePhaseTeams);\n  if (!Number.isInteger(uclTotal) || !Number.isInteger(uelTotal) || uclTotal < 2 || uelTotal < 2) throw new Error('EUROPEAN_FORMAT_NOT_CONFIGURED');\n  const europeanFixtures = allFixtures.filter(\n    (f) => f.competitionId === uclComp.id || f.competitionId === uelComp.id\n  );\n  const playedEuropeanFixtures = europeanFixtures.filter(\n    (f) => f.status !== 'SCHEDULED'\n  );\n  const hasEuropeanStarted = playedEuropeanFixtures.length > 0;\n\n  // SAFETY GUARD 2: Check domestic league completion\n  const leagueIds = new Set(leagues.map((l) => l.id));\n  const leagueFixtures = allFixtures.filter((f) => leagueIds.has(f.competitionId));\n  const unplayedLeagueMatchesCount = leagueFixtures.filter((f) => f.status !== 'CONFIRMED').length;\n  const domesticLeaguesCompleted = leagueFixtures.length > 0 && unplayedLeagueMatchesCount === 0;\n\n  let canApply = true;\n  let blockReason: string | undefined;\n\n  if (hasEuropeanStarted) {\n    canApply = false;\n    blockReason = `European competitions have already started (${playedEuropeanFixtures.length} played/in-progress matches). Participant synchronization is strictly blocked to protect active competition integrity.`;\n  } else if (mode === 'final' && !domesticLeaguesCompleted) {\n    canApply = false;\n    blockReason = `Domestic leagues are not finished (${unplayedLeagueMatchesCount} unconfirmed fixtures remaining). Final European qualification sync can only be applied after all domestic league matches are confirmed.`;\n  }\n\n  // Calculate projected qualifications from domestic league standings\n  const projectedUcl: QualificationResult[] = [];\n  const projectedUel: QualificationResult[] = [];\n\n  for (const league of leagues) {\n    const standings = projectStandings(SEED_CLUBS.filter(c => c.leagueId === league.leagueId), allFixtures.filter(f => f.competitionId === league.id), league.formatConfig);\n    if (standings.length === 0) continue;\n\n    const uclConfig = (uclComp as FirestoreCompetitionDoc).formatConfig as any;\n    const uelConfig = (uelComp as FirestoreCompetitionDoc).formatConfig as any;\n    const leagueConfig = league.formatConfig as any;\n    const uclSpots = Number(uclConfig?.qualificationSlots?.[league.id] ?? leagueConfig?.qualificationSpots);\n    const uelSpots = Number(uelConfig?.qualificationSlots?.[league.id] ?? leagueConfig?.europaQualificationSpots ?? leagueConfig?.qualificationSpots);\n    if (!Number.isInteger(uclSpots) || !Number.isInteger(uelSpots) || uclSpots < 0 || uelSpots < 0 || uclSpots + uelSpots > standings.length) {\n      throw new Error(`QUALIFICATION_ALLOCATION_INVALID: ${league.id}`);\n    }\n\n    // UCL spots\n    for (let i = 0; i < Math.min(uclSpots, standings.length); i++) {\n      const row = standings[i];\n      const ownerUserId = occupancyMap.get(row.clubId) || null;\n      projectedUcl.push({\n        seasonId,\n        sourceCompetitionId: league.id,\n        sourceCompetitionName: league.name,\n        targetCompetitionId: uclComp.id,\n        targetCompetitionName: uclComp.name,\n        clubId: row.clubId,\n        clubName: row.clubName,\n        ownerUserId,\n        rank: row.position,\n        reason: `${league.name} Rank #${row.position} (UCL Spot)`,\n      });\n    }\n\n    // UEL spots\n    for (let i = uclSpots; i < Math.min(uclSpots + uelSpots, standings.length); i++) {\n      const row = standings[i];\n      const ownerUserId = occupancyMap.get(row.clubId) || null;\n      projectedUel.push({\n        seasonId,\n        sourceCompetitionId: league.id,\n        sourceCompetitionName: league.name,\n        targetCompetitionId: uelComp.id,\n        targetCompetitionName: uelComp.name,\n        clubId: row.clubId,\n        clubName: row.clubName,\n        ownerUserId,\n        rank: row.position,\n        reason: `${league.name} Rank #${row.position} (UEL Spot)`,\n      });\n    }\n  }\n\n  // Compute Diffs for UCL & UEL against existing participants\n  const existingUclParts = existingParts.filter((p) => p.competitionId === uclComp.id);\n  const existingUclClubIds = new Set(existingUclParts.map((p) => p.clubId));\n  const projectedUclClubIds = new Set(projectedUcl.map((p) => p.clubId));\n\n  const uclDiff: EuropeanQualificationDiff = {\n    competitionId: uclComp.id,\n    competitionName: uclComp.name,\n    totalTarget: uclTotal,\n    retained: projectedUcl\n      .filter((p) => existingUclClubIds.has(p.clubId))\n      .map((p) => ({ clubId: p.clubId, clubName: p.clubName, rank: p.rank, sourceLeague: p.sourceCompetitionName })),\n    added: projectedUcl\n      .filter((p) => !existingUclClubIds.has(p.clubId))\n      .map((p) => ({ clubId: p.clubId, clubName: p.clubName, rank: p.rank, sourceLeague: p.sourceCompetitionName })),\n    removed: existingUclParts\n      .filter((p) => !projectedUclClubIds.has(p.clubId))\n      .map((p) => {\n        const club = clubsMap.get(p.clubId);\n        return { clubId: p.clubId, clubName: club?.name || p.clubId, previousReason: p.qualificationReason };\n      }),\n  };\n\n  const existingUelParts = existingParts.filter((p) => p.competitionId === uelComp.id);\n  const existingUelClubIds = new Set(existingUelParts.map((p) => p.clubId));\n  const projectedUelClubIds = new Set(projectedUel.map((p) => p.clubId));\n\n  const uelDiff: EuropeanQualificationDiff = {\n    competitionId: uelComp.id,\n    competitionName: uelComp.name,\n    totalTarget: uelTotal,\n    retained: projectedUel\n      .filter((p) => existingUelClubIds.has(p.clubId))\n      .map((p) => ({ clubId: p.clubId, clubName: p.clubName, rank: p.rank, sourceLeague: p.sourceCompetitionName })),\n    added: projectedUel\n      .filter((p) => !existingUelClubIds.has(p.clubId))\n      .map((p) => ({ clubId: p.clubId, clubName: p.clubName, rank: p.rank, sourceLeague: p.sourceCompetitionName })),\n    removed: existingUelParts\n      .filter((p) => !projectedUelClubIds.has(p.clubId))\n      .map((p) => {\n        const club = clubsMap.get(p.clubId);\n        return { clubId: p.clubId, clubName: club?.name || p.clubId, previousReason: p.qualificationReason };\n      }),\n  };\n\n  const previewToken = `prev-qual-${Date.now()}-${crypto.randomBytes(6).toString('hex')}`;\n  const expiresAt = new Date(now.getTime() + 15 * 60 * 1000).toISOString();\n\n  if (projectedUcl.length !== uclTotal || projectedUel.length !== uelTotal) {\n    canApply = false;\n    blockReason = 'QUALIFICATION_TOTAL_MISMATCH: review configured league allocations and competition team counts';\n  }\n  const preview: EuropeanQualificationPreview = {\n    sourceFingerprint: fingerprintSnapshots([compSnap, partsSnap, fixSnap, occSnap]),\n    previewToken,\n    seasonId,\n    mode,\n    canApply,\n    blockReason,\n    domesticLeaguesCompleted,\n    unplayedLeagueMatchesCount,\n    hasEuropeanStarted,\n    summary: {\n      ucl: {\n        totalTarget: uclTotal,\n        retainedCount: uclDiff.retained.length,\n        addedCount: uclDiff.added.length,\n        removedCount: uclDiff.removed.length,\n      },\n      uel: {\n        totalTarget: uelTotal,\n        retainedCount: uelDiff.retained.length,\n        addedCount: uelDiff.added.length,\n        removedCount: uelDiff.removed.length,\n      },\n    },\n    diff: {\n      ucl: uclDiff,\n      uel: uelDiff,\n    },\n    projectedQualifications: [...projectedUcl, ...projectedUel],\n    generatedAt: nowIso,\n    expiresAt,\n  };\n\n  await saveQualificationPreviewToken(previewToken, preview);\n\n  return preview;\n}\n\n/**\n * Safely applies European Qualification synchronization using an approved preview token.\n * STRICT DATA SAFETY RULES:\n * - Requires explicit admin confirmation.\n * - Requires valid, non-expired previewToken stored in Redis.\n * - Non-destructive: preserves existing participants where possible, never blind batch delete.\n * - Enforces strict apply-time preconditions (competition not started, domestic leagues completed if final).\n */\nexport async function applyEuropeanQualificationSync(params: {\n  seasonId?: string;\n  previewToken: string;\n  confirmation: boolean;\n  adminUserId: string;\n  adminUsername?: string;\n}): Promise<{\n  success: boolean;\n  message: string;\n  qualificationsApplied: number;\n  participantsAdded: number;\n  participantsRemoved: number;\n}> {\n  if (!params.confirmation) {\n    throw new Error('Explicit admin confirmation is required to apply European qualifications sync.');\n  }\n\n  const preview = await getQualificationPreviewToken(params.previewToken);\n  if (!preview) {\n    throw new Error('Preview token is invalid, expired, or was already applied. Please generate a fresh preview before applying.');\n  }\n\n  if (!preview.canApply) {\n    throw new Error(preview.blockReason || 'Cannot apply qualifications sync: preconditions failed.');\n  }\n\n  if (!preview.sourceFingerprint || Date.parse(preview.expiresAt) <= Date.now() || (params.seasonId && params.seasonId !== preview.seasonId)) {\n    throw new Error('PREVIEW_EXPIRED_OR_SEASON_MISMATCH: generate a new preview');\n  }\n\n  const db = getFirestoreDb();\n\n  // STRICT APPLY-TIME VALIDATION:\n  // 1. Re-check European competitions have not started (played or in-progress fixtures)\n  const activeEuropeanFixSnap = await db\n    .collection(COLLECTIONS.FIXTURES)\n    .where('competitionId', 'in', [preview.diff.ucl.competitionId, preview.diff.uel.competitionId])\n    .where('status', 'in', ['CONFIRMED', 'PLAYING', 'IN_PROGRESS', 'AWAITING_RESULT', 'PENDING_CONFIRMATION', 'DISPUTED'])\n    .limit(1)\n    .get();\n\n  if (!activeEuropeanFixSnap.empty) {\n    throw new Error(\n      'Precondition Failed: European competitions have already started with active or confirmed matches. Modifying participants is strictly prohibited.'\n    );\n  }\n\n  // 2. If mode is final, re-verify all domestic league matches are completed\n  if (preview.mode === 'final') {\n    const unplayedLeaguesSnap = await db\n      .collection(COLLECTIONS.FIXTURES)\n      .where('seasonId', '==', preview.seasonId)\n      .get();\n    const leagueIds = [\n      'comp-premier-league-2026',\n      'comp-la-liga-2026',\n      'comp-serie-a-2026',\n      'comp-bundesliga-2026',\n      'comp-ligue-1-2026',\n    ];\n    const unplayedLeagueMatches = unplayedLeaguesSnap.docs.filter((d) =>\n      leagueIds.includes(d.data().competitionId) && d.data().status !== 'CONFIRMED'\n    ).length;\n    if (unplayedLeagueMatches > 0) {\n      throw new Error(\n        `Precondition Failed: Domestic leagues still have ${unplayedLeagueMatches} unplayed scheduled matches. Final qualification sync cannot be applied.`\n      );\n    }\n  }\n\n  const now = new Date().toISOString();\n  const participantsAdded = preview.diff.ucl.added.length + preview.diff.uel.added.length;\n  const participantsRemoved = preview.diff.ucl.removed.length + preview.diff.uel.removed.length;\n  const notificationsToSend: Array<{ userId: string; title: string; message: string }> = [];\n  await db.runTransaction(async transaction => {\n    const collections = [COLLECTIONS.COMPETITIONS, COLLECTIONS.COMPETITION_PARTICIPANTS, COLLECTIONS.FIXTURES, COLLECTIONS.CLUB_OCCUPANCIES];\n    const snapshots = [];\n    for (const collection of collections) snapshots.push(await transaction.get(db.collection(collection).where('seasonId', '==', preview.seasonId)));\n    const applicationRef = db.collection('qualification_applications').doc(params.previewToken);\n    const application = await transaction.get(applicationRef);\n    if (application.exists) throw new Error('PREVIEW_ALREADY_APPLIED');\n    if (fingerprintSnapshots(snapshots) !== preview.sourceFingerprint) throw new Error('PREVIEW_DATA_CHANGED: refresh and review the new preview');\n    const existing = snapshots[1].docs;\n    for (const q of preview.projectedQualifications) {\n      const matches = existing.filter(d => d.data().competitionId === q.targetCompetitionId && d.data().clubId === q.clubId);\n      if (matches.length > 1) throw new Error('DUPLICATE_PARTICIPANTS: manual review required');\n      const id = matches[0]?.id || `part-${q.targetCompetitionId}-${q.clubId}`;\n      transaction.set(db.collection(COLLECTIONS.COMPETITION_PARTICIPANTS).doc(id), {\n        id, seasonId: preview.seasonId, competitionId: q.targetCompetitionId, clubId: q.clubId,\n        ownerUserId: q.ownerUserId, sourceCompetitionId: q.sourceCompetitionId,\n        sourcePosition: q.rank, qualificationReason: q.reason, qualificationTimestamp: now,\n        createdAt: matches[0]?.data().createdAt || now, updatedAt: now,\n      }, { merge: true });\n    }\n    for (const diff of [preview.diff.ucl, preview.diff.uel]) {\n      for (const removed of diff.removed) {\n        const matches = existing.filter(d => d.data().competitionId === diff.competitionId && d.data().clubId === removed.clubId);\n        if (matches.length !== 1) throw new Error('PARTICIPANT_REMOVAL_AMBIGUOUS');\n        transaction.delete(db.collection(COLLECTIONS.COMPETITION_PARTICIPANTS).doc(matches[0].id));\n      }\n    }\n    transaction.set(applicationRef, { appliedAt: now, adminUserId: params.adminUserId, seasonId: preview.seasonId, sourceFingerprint: preview.sourceFingerprint });\n  });\n\n  // Mirror to SQLite\n  for (const q of preview.projectedQualifications) {\n    try {\n      const partId = `part-${q.targetCompetitionId}-${q.clubId}`;\n      queryRun(\n        `INSERT OR REPLACE INTO competition_participants \n         (id, competition_id, club_id, season_id, owner_user_id, source_competition_id, source_position, qualification_reason, created_at)\n         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,\n        [partId, q.targetCompetitionId, q.clubId, preview.seasonId, q.ownerUserId, q.sourceCompetitionId, q.rank, q.reason, now]\n      );\n    } catch {}\n  }\n\n  // Remove used preview token from Redis and memory\n  for (const diff of [preview.diff.ucl, preview.diff.uel]) {\n    for (const removed of diff.removed) {\n      try { queryRun('DELETE FROM competition_participants WHERE competition_id = ? AND season_id = ? AND club_id = ?', [diff.competitionId, preview.seasonId, removed.clubId]); } catch {}\n    }\n  }\n  await deleteQualificationPreviewToken(params.previewToken);\n\n  // Invalidate competition participants and table caches\n  await invalidateDataset(ReadModelKeys.competitions(preview.seasonId));\n  for (const compId of [preview.diff.ucl.competitionId, preview.diff.uel.competitionId]) {\n    await invalidateDataset(ReadModelKeys.standings(compId, preview.seasonId));\n    await invalidateDataset(ReadModelKeys.competitionFixtures(compId, preview.seasonId));\n    await invalidateDataset(`european:standings:${compId}:${preview.seasonId}`);\n  }\n\n  // Final qualification is an event: notify in-app and Telegram without adding Firestore reads.\n  if (preview.mode === 'final') {\n    for (const q of preview.projectedQualifications) {\n      if (!q.ownerUserId) continue;\n      notificationsToSend.push({\n        userId: q.ownerUserId,\n        title: `\uD83C\uDFC6 ${q.targetCompetitionName} yo\u2018llanmasi`,\n        message: `${q.clubName} ${q.targetCompetitionName} turniriga yo\u2018llanma oldi. ${q.reason}`,\n      });\n    }\n  }\n  await Promise.all(\n    notificationsToSend.map(async (n) => {\n      await Promise.allSettled([\n        createNotification(n.userId, 'QUALIFICATION_CONFIRMED', n.title, n.message),\n        enqueueSmartTelegramNotification({\n          userId: n.userId,\n          seasonId: preview.seasonId,\n          eventId: `qualification:${preview.previewToken}:${n.userId}:${n.title}`,\n          title: n.title,\n          body: n.message,\n        }),\n      ]);\n    })\n  );\n\n  // Write audit log\n  await createAuditLog(\n    params.adminUserId,\n    'EUROPEAN_QUALIFICATIONS_SYNCED',\n    'SEASON',\n    preview.seasonId,\n    undefined,\n    {\n      mode: preview.mode,\n      totalQualified: preview.projectedQualifications.length,\n      participantsAdded,\n      participantsRemoved,\n      previewToken: params.previewToken,\n      timestamp: now,\n    },\n    undefined,\n    params.adminUsername || 'admin',\n    `Applied European qualification sync (${preview.mode}): ${participantsAdded} added, ${participantsRemoved} removed.`\n  ).catch(() => console.warn('[QUALIFICATION] Applied transaction recorded; auxiliary audit unavailable'));\n\n  return {\n    success: true,\n    message: `Successfully applied European qualifications sync (${preview.mode}): ${participantsAdded} added, ${participantsRemoved} removed.`,\n    qualificationsApplied: preview.projectedQualifications.length,\n    participantsAdded,\n    participantsRemoved,\n  };\n}\n\nexport function computeEuropeanStandingsRows(\n  format: any,\n  clubIds: string[],\n  fixtures: any[],\n  seasonId = 'season-2026-27'\n): EuropeanStandingsRow[] {\n  const clubsMap = new Map(SEED_CLUBS.map((c) => [c.id, c]));\n  const uniqueClubIds = [...new Set(clubIds)];\n  const totalTeams = Number(format?.leaguePhaseTeams);\n  const directQualifiers = Number(format?.directQualifiers);\n  const playoffTeams = Number(format?.playoffTeams);\n  if (!Number.isInteger(totalTeams) || totalTeams !== uniqueClubIds.length || !Number.isInteger(directQualifiers) || !Number.isInteger(playoffTeams) || directQualifiers + playoffTeams > totalTeams) {\n    throw new Error('EUROPEAN_FORMAT_PARTICIPANTS_MISMATCH');\n  }\n\n  // Initialize standings map\n  const statsMap = new Map<string, {\n    clubId: string;\n    clubName: string;\n    badgeUrl?: string;\n    played: number;\n    won: number;\n    drawn: number;\n    lost: number;\n    goalsFor: number;\n    goalsAgainst: number;\n    goalDifference: number;\n    points: number;\n  }>();\n\n  for (const cid of uniqueClubIds) {\n    const club = clubsMap.get(cid);\n    statsMap.set(cid, {\n      clubId: cid,\n      clubName: club?.name || cid,\n      badgeUrl: club?.logoUrl,\n      played: 0,\n      won: 0,\n      drawn: 0,\n      lost: 0,\n      goalsFor: 0,\n      goalsAgainst: 0,\n      goalDifference: 0,\n      points: 0,\n    });\n  }\n\n  // Accumulate confirmed fixtures\n  for (const f of fixtures) {\n    const homeScore = f.homeScore ?? f.home_score;\n    const awayScore = f.awayScore ?? f.away_score;\n    const homeClubId = f.homeClubId ?? f.home_club_id;\n    const awayClubId = f.awayClubId ?? f.away_club_id;\n    const fSeasonId = f.seasonId ?? f.season_id;\n    const roundName = f.roundName ?? f.round_name ?? '';\n    const id = f.id;\n\n    if (f.status !== 'CONFIRMED' || !Number.isInteger(homeScore) || !Number.isInteger(awayScore) || homeScore < 0 || awayScore < 0) continue;\n    if ((fSeasonId && fSeasonId !== seasonId) || !homeClubId || !awayClubId) continue;\n    if (/quarter|semi|final|play.?off|round of|knockout/i.test(roundName) || /-r[1-5]-m/.test(id)) continue;\n\n    const home = statsMap.get(homeClubId);\n    const away = statsMap.get(awayClubId);\n\n    if (home) {\n      home.played += 1;\n      home.goalsFor += homeScore;\n      home.goalsAgainst += awayScore;\n      home.goalDifference = home.goalsFor - home.goalsAgainst;\n\n      if (homeScore > awayScore) {\n        home.won += 1;\n        home.points += 3;\n      } else if (homeScore === awayScore) {\n        home.drawn += 1;\n        home.points += 1;\n      } else {\n        home.lost += 1;\n      }\n    }\n\n    if (away) {\n      away.played += 1;\n      away.goalsFor += awayScore;\n      away.goalsAgainst += homeScore;\n      away.goalDifference = away.goalsFor - away.goalsAgainst;\n\n      if (awayScore > homeScore) {\n        away.won += 1;\n        away.points += 3;\n      } else if (homeScore === awayScore) {\n        away.drawn += 1;\n        away.points += 1;\n      } else {\n        away.lost += 1;\n      }\n    }\n  }\n\n  // Sort by Points -> Goal Difference -> Goals For -> Club Name\n  const sorted = Array.from(statsMap.values()).sort((a, b) => {\n    if (b.points !== a.points) return b.points - a.points;\n    if (b.goalDifference !== a.goalDifference) return b.goalDifference - a.goalDifference;\n    if (b.goalsFor !== a.goalsFor) return b.goalsFor - a.goalsFor;\n    return a.clubName.localeCompare(b.clubName);\n  });\n\n  return sorted.map((s, idx) => {\n    const position = idx + 1;\n    let zone: EuropeanStandingsRow['zone'] = 'ELIMINATED';\n    let zoneLabel = 'Eliminated';\n\n    if (position <= directQualifiers) {\n      zone = 'DIRECT_R16';\n      zoneLabel = 'Round of 16 (Direct Qualification)';\n    } else if (position <= directQualifiers + playoffTeams) {\n      zone = 'KNOCKOUT_PLAYOFF';\n      zoneLabel = 'Knockout Play-offs';\n    }\n\n    return {\n      position,\n      clubId: s.clubId,\n      clubName: s.clubName,\n      shortName: clubsMap.get(s.clubId)?.shortName || s.clubName,\n      logoUrl: s.badgeUrl,\n      form: [],\n      badgeUrl: s.badgeUrl,\n      played: s.played,\n      won: s.won,\n      drawn: s.drawn,\n      lost: s.lost,\n      goalsFor: s.goalsFor,\n      goalsAgainst: s.goalsAgainst,\n      goalDifference: s.goalDifference,\n      points: s.points,\n      zone,\n      zoneLabel,\n    };\n  });\n}\n\nexport function calculateEuropeanStandingsFromSqlite(\n  competitionId: string,\n  seasonId = 'season-2026-27'\n): EuropeanStandingsRow[] | null {\n  try {\n    const compRow = queryGet<any>('SELECT * FROM competitions WHERE id = ?', [competitionId]);\n    let formatConfig: any = null;\n    if (compRow && compRow.format_config) {\n      try {\n        formatConfig = typeof compRow.format_config === 'string' ? JSON.parse(compRow.format_config) : compRow.format_config;\n      } catch {}\n    }\n    if (!formatConfig) {\n      const seedComp = SEED_COMPETITIONS.find((c) => c.id === competitionId);\n      formatConfig = seedComp?.formatConfig;\n    }\n    if (!formatConfig) return null;\n\n    let partRows = queryAll<{ club_id: string }>(\n      'SELECT club_id FROM competition_participants WHERE competition_id = ?',\n      [competitionId]\n    );\n    let clubIds = partRows.map((r) => r.club_id);\n    if (clubIds.length === 0) {\n      const { SEED_COMPETITION_PARTICIPANTS } = require('../db/seed');\n      if (SEED_COMPETITION_PARTICIPANTS) {\n        clubIds = SEED_COMPETITION_PARTICIPANTS\n          .filter((p: any) => p.competitionId === competitionId)\n          .map((p: any) => p.clubId);\n      }\n    }\n    if (clubIds.length === 0) return null;\n\n    const fixtures = queryAll<any>(\n      `SELECT * FROM fixtures WHERE competition_id = ? AND (season_id = ? OR season_id IS NULL)`,\n      [competitionId, seasonId]\n    );\n\n    return computeEuropeanStandingsRows(formatConfig, clubIds, fixtures, seasonId);\n  } catch {\n    return null;\n  }\n}\n\n/**\n * Rebuilds UEFA Champions League or Europa League single 32-team league phase standings table.\n */\nexport async function rebuildEuropeanStandings(\n  competitionId: string,\n  seasonId = 'season-2026-27'\n): Promise<EuropeanStandingsRow[]> {\n  const db = getFirestoreDb();\n\n  // 1. Fetch participants and fixtures\n  const [compDoc, partsSnap, fixSnap] = await Promise.all([\n    db.collection(COLLECTIONS.COMPETITIONS).doc(competitionId).get(),\n    db.collection(COLLECTIONS.COMPETITION_PARTICIPANTS).where('competitionId', '==', competitionId).get(),\n    db.collection(COLLECTIONS.FIXTURES).where('competitionId', '==', competitionId).get(),\n  ]);\n\n  // Track Firestore reads accurately with actual document counts\n  trackFirestoreRead(COLLECTIONS.COMPETITIONS, compDoc.exists ? 1 : 0, 'rebuildEuropeanStandings:comp');\n  trackFirestoreRead(COLLECTIONS.COMPETITION_PARTICIPANTS, partsSnap.docs.length, 'rebuildEuropeanStandings:participants');\n  trackFirestoreRead(COLLECTIONS.FIXTURES, fixSnap.docs.length, 'rebuildEuropeanStandings:fixtures');\n\n  const participants = partsSnap.docs.map((d) => d.data() as FirestoreCompetitionParticipantDoc);\n  const fixtures = fixSnap.docs.map((d) => d.data() as FirestoreFixtureDoc);\n\n  let clubIds = participants.map((p) => p.clubId);\n  if (clubIds.length === 0) {\n    throw new Error('EUROPEAN_PARTICIPANTS_NOT_CONFIGURED');\n  }\n  const format = compDoc.data()?.formatConfig as any;\n  const rows = computeEuropeanStandingsRows(format, clubIds, fixtures, seasonId);\n\n  // Save to Redis Read Model (Fresh + LKG permanent)\n  const cacheKey = ReadModelKeys.standings(competitionId, seasonId);\n  await redisSetRaw(\n    cacheKey,\n    {\n      data: rows,\n      schemaVersion: SCHEMA_VERSION,\n      sourceVersion: 'rebuild-european-standings',\n      expectedCount: [...new Set(clubIds)].length,\n    },\n    86400\n  );\n\n  const matchesPerTeam = Number(format?.matchesPerTeam);\n  if (Number.isInteger(matchesPerTeam) && matchesPerTeam > 0 && rows.length > 0 && rows.every((row) => row.played >= matchesPerTeam)) {\n    await notifySmartEuropeanZones({ competitionId, seasonId, rows }).catch((error: any) => {\n      console.warn('[SMART_NOTIFY] European zone notification failed:', error?.message || error);\n    });\n  }\n\n  return rows;\n}\n\n/**\n * Reads European standings through tiered read model:\n * Redis Fresh -> Redis LKG -> SQLite local calculation -> Bounded Firestore fallback\n */\nexport async function getEuropeanStandings(\n  competitionId: string,\n  seasonId = 'season-2026-27'\n): Promise<{ rows: EuropeanStandingsRow[]; source: string; degraded: boolean }> {\n  const cacheKey = ReadModelKeys.standings(competitionId, seasonId);\n\n  // 1. Memory / Redis Fresh\n  const fresh = await redisGetFresh<EuropeanStandingsRow[]>(cacheKey);\n  if (fresh?.data && Array.isArray(fresh.data) && fresh.data.length > 0) {\n    return { rows: fresh.data, source: 'redis-fresh', degraded: false };\n  }\n\n  // 2. Redis LKG (Last-Known-Good)\n  const lkg = await redisGetLkg<EuropeanStandingsRow[]>(cacheKey);\n  if (lkg?.data && Array.isArray(lkg.data) && lkg.data.length > 0) {\n    return { rows: lkg.data, source: 'redis-lkg', degraded: true };\n  }\n\n  // 3. SQLite calculation from locally available fixtures/participants\n  const sqliteRows = calculateEuropeanStandingsFromSqlite(competitionId, seasonId);\n  if (sqliteRows && sqliteRows.length > 0) {\n    redisSetRaw(cacheKey, {\n      data: sqliteRows,\n      schemaVersion: SCHEMA_VERSION,\n      sourceVersion: 'european-sqlite',\n      expectedCount: sqliteRows.length,\n    }, 86400).catch(() => {});\n    return { rows: sqliteRows, source: 'sqlite', degraded: true };\n  }\n\n  // 4. Bounded Firestore fallback only when required\n  const rows = await rebuildEuropeanStandings(competitionId, seasonId);\n  return { rows, source: 'firestore-rebuild', degraded: false };\n}\n\n/**\n * Backwards compatibility wrapper for evaluateSeasonQualifications\n */\nexport async function evaluateSeasonQualifications(seasonId = 'season-2026-27'): Promise<{\n  success: boolean;\n  qualifications: QualificationResult[];\n  participantsAdded: number;\n}> {\n  const preview = await previewEuropeanQualificationSync(seasonId, 'provisional');\n  // Legacy evaluation is preview-only; applying requires explicit admin review.\n\n  return {\n    success: false,\n    qualifications: preview.projectedQualifications,\n    participantsAdded: 0,\n  };\n}\n\nexport const evaluateSeasonQualificationsFirestore = evaluateSeasonQualifications;\n\n/**\n * Resolves and populates Super Cup participants from league champions and cup winners/runners-up.\n */\nexport async function populateSuperCupParticipants(\n  seasonId = 'season-2026-27',\n  superCupCompetitionId: string\n): Promise<{\n  competitionId: string;\n  participants: Array<{ clubId: string; clubName: string; role: string }>;\n}> {\n  const db = getFirestoreDb();\n  const SUPER_CUP_MAP: Record<string, { leagueId: string; cupId?: string; name: string }> = {\n    'comp-community-shield-2026': { leagueId: 'comp-premier-league-2026', cupId: 'comp-fa-cup-2026', name: 'FA Community Shield' },\n    'comp-supercopa-2026': { leagueId: 'comp-la-liga-2026', cupId: 'comp-copa-del-rey-2026', name: 'Supercopa de Espa\u00F1a' },\n    'comp-supercoppa-2026': { leagueId: 'comp-serie-a-2026', cupId: 'comp-coppa-italia-2026', name: 'Supercoppa Italiana' },\n    'comp-dfl-supercup-2026': { leagueId: 'comp-bundesliga-2026', cupId: 'comp-dfb-pokal-2026', name: 'DFL-Supercup' },\n    'comp-trophee-champions-2026': { leagueId: 'comp-ligue-1-2026', cupId: 'comp-coupe-de-france-2026', name: 'Troph\u00E9e des Champions' },\n    'comp-uefa-super-cup-2026': { leagueId: 'comp-champions-league-2026', cupId: 'comp-europa-league-2026', name: 'UEFA Super Cup' },\n  };\n\n  const config = SUPER_CUP_MAP[superCupCompetitionId] || { leagueId: 'comp-premier-league-2026', name: 'Super Cup' };\n\n  // Calculate league standings\n  const leagueStandings = await calculateCompetitionStandingsFirestore(config.leagueId);\n  const leagueChampion = leagueStandings[0];\n\n  let secondClub = leagueStandings[1] || leagueStandings[0];\n  if (config.cupId) {\n    try {\n      const cupFinalSnap = await db\n        .collection(COLLECTIONS.FIXTURES)\n        .where('competitionId', '==', config.cupId)\n        .where('roundName', '==', 'Final')\n        .get();\n      if (!cupFinalSnap.empty) {\n        const finalMatch = cupFinalSnap.docs[0].data() as FirestoreFixtureDoc;\n        if (finalMatch.winnerClubId && finalMatch.winnerClubId !== leagueChampion?.clubId) {\n          const cDoc = await db.collection(COLLECTIONS.CLUBS).doc(finalMatch.winnerClubId).get();\n          if (cDoc.exists) {\n            secondClub = {\n              clubId: finalMatch.winnerClubId,\n              clubName: (cDoc.data() as any)?.name || finalMatch.winnerClubId,\n            } as any;\n          }\n        }\n      }\n    } catch {}\n  }\n\n  const clubsMap = new Map(SEED_CLUBS.map((c) => [c.id, c]));\n  const champClub = leagueChampion\n    ? clubsMap.get(leagueChampion.clubId) || { id: leagueChampion.clubId, name: leagueChampion.clubName }\n    : SEED_CLUBS[0];\n  const chalClub = secondClub\n    ? clubsMap.get(secondClub.clubId) || { id: secondClub.clubId, name: secondClub.clubName }\n    : SEED_CLUBS[1];\n\n  const participants = [\n    { clubId: champClub.id, clubName: champClub.name, role: 'LEAGUE_CHAMPION' },\n    { clubId: chalClub.id, clubName: chalClub.name, role: 'CUP_CHAMPION_OR_RUNNER_UP' },\n  ];\n\n  try {\n    const batch = db.batch();\n    for (const p of participants) {\n      const docRef = db.collection(COLLECTIONS.COMPETITION_PARTICIPANTS).doc(`${superCupCompetitionId}_${p.clubId}`);\n      batch.set(\n        docRef,\n        {\n          id: `${superCupCompetitionId}_${p.clubId}`,\n          competitionId: superCupCompetitionId,\n          clubId: p.clubId,\n          clubName: p.clubName,\n          seasonId,\n          qualificationReason: p.role,\n          sourceCompetitionId: config.leagueId,\n          createdAt: new Date().toISOString(),\n        },\n        { merge: true }\n      );\n    }\n    await batch.commit();\n  } catch (err: any) {\n    console.warn('[SUPER_CUP] Firestore commit error:', err.message);\n  }\n\n  return {\n    competitionId: superCupCompetitionId,\n    participants,\n  };\n}\n", "import { Competition, Fixture } from '../../types';\nimport { ReadModelKeys, redisGetFresh, redisGetLkg } from '../readModel/readModelStore';\nimport { filterTombstonedFixtures } from './fixtureTombstoneService';\n\n/** Only existing complete fixture snapshots are consulted; never fetch Firestore\n * merely to decorate the catalog. Unknown counts retain the catalog value.\n */\nexport async function withVisibleFixtureCounts(competitions: Competition[], seasonId: string): Promise<Competition[]> {\n  return Promise.all(competitions.map(async competition => {\n    if (competition.type !== 'LEAGUE') return competition;\n    const key = ReadModelKeys.competitionFixtures(competition.id, seasonId);\n    const snapshot = (await redisGetFresh<Fixture[]>(key)) || (await redisGetLkg<Fixture[]>(key));\n    if (!Array.isArray(snapshot?.data) || (snapshot.actualCount != null && snapshot.actualCount !== snapshot.data.length)) return competition;\n    const matching = snapshot.data.filter(fixture => fixture.competitionId === competition.id && (!fixture.seasonId || fixture.seasonId === seasonId));\n    const fixtures = await filterTombstonedFixtures(matching, seasonId);\n    return {\n      ...competition,\n      fixtureCount: fixtures.length,\n      fixturesCount: fixtures.length,\n      hasFixtures: fixtures.length > 0,\n      configuredFixtureCount: competition.fixturesCount ?? competition.fixtureCount,\n      fixtureCountSource: 'visible-fixture-snapshot',\n      fixtureCountSnapshotAt: snapshot.generatedAt,\n    } as Competition;\n  }));\n}\n", "import { getFirestoreDb } from '../firebase/admin';\nimport { COLLECTIONS } from '../firebase/collections';\nimport { upsertFixtureToSqlite } from '../db';\nimport { Fixture } from '../../types';\nimport { RETIRED_FIXTURES } from './retiredFixtureService';\nimport { restoreFixtureTombstone } from './fixtureTombstoneService';\nimport { ReadModelKeys, redisGetFresh, redisGetLkg, redisSetRaw, getUpstashClient, getFreshKey, getLkgKey, getDirtyKey, clearProcessMemoryCache, normalizeFixtureSnapshot } from '../readModel/readModelStore';\n\n// One specific recovery explicitly requested by the project owner on 2026-10-04.\n// Not a recurring missing-fixture repair: a durable completion record prevents\n// a later intentional deletion from resurrecting this match. Never reset an\n// existing result, copy deleted submissions, or alter another fixture.\nexport const RESTORATION_ID = 'restore-inter-milan-without-result-20261004';\nconst correction = RETIRED_FIXTURES[0];\nconst fixtureId = correction.retainedFixtureId;\nconst checkpointKey = `approved-restoration:${RESTORATION_ID}`;\n\nasync function publishFixture(key: string, fixture: Fixture): Promise<void> {\n  const client = getUpstashClient();\n  if (client) {\n    const accepted = await client.eval(`\n      local raw = redis.call('GET', KEYS[2]) or redis.call('GET', KEYS[1])\n      if not raw then return 0 end\n      local snapshot = cjson.decode(raw)\n      local changed = cjson.decode(ARGV[1])\n      local found = false\n      for i, row in ipairs(snapshot.data or {}) do\n        if row.id == changed.id then\n          if row.updatedAt and changed.updatedAt and row.updatedAt > changed.updatedAt then return 1 end\n          snapshot.data[i] = changed\n          found = true\n          break\n        end\n      end\n      if not found then table.insert(snapshot.data, changed) end\n      snapshot.generatedAt = ARGV[2]\n      snapshot.sourceVersion = ARGV[3]\n      snapshot.actualCount = #(snapshot.data)\n      snapshot.expectedCount = #(snapshot.data)\n      local value = cjson.encode(snapshot)\n      redis.call('SET', KEYS[2], value)\n      redis.call('SET', KEYS[1], value, 'EX', 86400)\n      redis.call('DEL', KEYS[3])\n      return 1\n    `, [getFreshKey(key), getLkgKey(key), getDirtyKey(key)], [JSON.stringify(fixture), new Date().toISOString(), RESTORATION_ID]);\n    if (Number(accepted) !== 1) throw new Error(`RESTORATION_SNAPSHOT_MISSING: ${key}`);\n    clearProcessMemoryCache();\n  } else {\n    const snapshot = await redisGetFresh<Fixture[]>(key) || await redisGetLkg<Fixture[]>(key);\n    if (!Array.isArray(snapshot?.data)) throw new Error(`RESTORATION_SNAPSHOT_MISSING: ${key}`);\n    const newer = snapshot.data.find(f => f.id === fixture.id && String(f.updatedAt) > String(fixture.updatedAt));\n    if (newer) return;\n    const data = snapshot.data.filter(f => f.id !== fixture.id).concat(fixture);\n    await redisSetRaw(key, { data, sourceVersion: RESTORATION_ID }, 86400);\n  }\n}\n\nexport async function restoreApprovedInterMilanFixture(): Promise<void> {\n  const complete = await redisGetFresh<{ completed: boolean }>(checkpointKey) || await redisGetLkg<{ completed: boolean }>(checkpointKey);\n  if (complete?.data.completed) return;\n  const db = getFirestoreDb();\n  const markerRef = db.collection('maintenance_operations').doc(RESTORATION_ID);\n  const ref = db.collection(COLLECTIONS.FIXTURES).doc(fixtureId);\n  const deletionRef = db.collection(COLLECTIONS.AUDIT_LOGS).doc(`audit_ADMIN_DELETE_FIXTURE_fixture_${fixtureId}`);\n  const now = new Date().toISOString();\n  const restored = await db.runTransaction(async tx => {\n    const marker = await tx.get(markerRef);\n    if (marker.exists && marker.data()?.phase === 'COMPLETED') return null;\n    const current = await tx.get(ref);\n    if (marker.exists) {\n      // Resume cache publication after a previous transaction succeeded.\n      if (current.exists) return { data: current.data()!, actor: String(marker.data()?.actor || 'system-approved-restoration') };\n      tx.set(markerRef, { phase: 'COMPLETED', outcome: 'deleted-after-restoration', completedAt: now }, { merge: true });\n      return null;\n    }\n    if (current.exists) {\n      tx.set(markerRef, { phase: 'COMPLETED', outcome: 'already-present-not-overwritten', completedAt: now });\n      return null;\n    }\n    const deletion = await tx.get(deletionRef);\n    const audit = deletion.exists ? deletion.data()! : null;\n    const original = audit?.oldValueJson ? JSON.parse(audit.oldValueJson) : null;\n    if (audit?.action !== 'ADMIN_DELETE_FIXTURE' || audit.entityId !== fixtureId || original?.id !== fixtureId || original.seasonId !== correction.seasonId || original.competitionId !== correction.competitionId || original.homeClubId !== 'club-inter' || original.awayClubId !== 'club-milan') {\n      throw new Error('RESTORATION_ORIGINAL_NOT_VERIFIED');\n    }\n    const data = {\n      id: fixtureId, competitionId: correction.competitionId, competitionName: 'Serie A', seasonId: correction.seasonId,\n      matchday: correction.matchday, roundName: correction.roundName, scheduledAt: correction.scheduledAt,\n      homeClubId: original.homeClubId, awayClubId: original.awayClubId,\n      status: 'SCHEDULED', homeScore: null, awayScore: null, winnerClubId: null, resultConfirmedAt: null,\n      createdAt: original.createdAt || now, updatedAt: now,\n      restoredAt: now, restorationOperationId: RESTORATION_ID,\n    };\n    const actor = String(audit.actorUserId || 'system-approved-restoration');\n    tx.set(ref, data);\n    tx.set(markerRef, { phase: 'RESTORED', fixtureId, actor, restoredAt: now });\n    tx.set(db.collection(COLLECTIONS.AUDIT_LOGS).doc(`audit_${RESTORATION_ID}`), {\n      action: 'OWNER_REQUESTED_FIXTURE_RESTORE_WITHOUT_RESULT', entityType: 'fixture', entityId: fixtureId,\n      actorUserId: actor, authorization: 'Project owner recovery request 2026-10-04',\n      oldValueJson: audit.oldValueJson, newValueJson: JSON.stringify(data), createdAt: now,\n    });\n    return { data, actor };\n  });\n  if (restored) {\n    const fixture = normalizeFixtureSnapshot(restored.data, correction.seasonId);\n    await restoreFixtureTombstone(fixtureId, correction.seasonId, restored.actor);\n    upsertFixtureToSqlite(fixture);\n    await publishFixture(ReadModelKeys.competitionFixtures(correction.competitionId, correction.seasonId), fixture);\n    await publishFixture(ReadModelKeys.adminFixtures(correction.seasonId), fixture);\n    const { invalidateFirestoreCache } = await import('../firebase/firestoreStore');\n    invalidateFirestoreCache('firestore:fixtures');\n    invalidateFirestoreCache('firestore:club_raw_fixtures');\n    invalidateFirestoreCache(`firestore:fixture:${fixtureId}:`);\n    await markerRef.set({ phase: 'COMPLETED', completedAt: new Date().toISOString() }, { merge: true });\n  }\n  await redisSetRaw(checkpointKey, { data: { completed: true }, sourceVersion: RESTORATION_ID }, 31536000);\n}\n\nlet inFlight: Promise<void> | null = null;\nlet retryAfter = 0;\nexport async function runApprovedFixtureRestoration(competitionId: string, seasonId: string): Promise<void> {\n  if (process.env.VERCEL_ENV !== 'production' || competitionId !== correction.competitionId || seasonId !== correction.seasonId || Date.now() < retryAfter) return;\n  if (!inFlight) inFlight = restoreApprovedInterMilanFixture().catch(error => {\n    retryAfter = Date.now() + 30000;\n    console.error('[APPROVED_FIXTURE_RESTORATION_FAILED]', error.message);\n  }).finally(() => { inFlight = null; });\n  await inFlight;\n}\n", "import { withSeasonQualificationPolicy } from '../../lib/seasonQualificationPolicy';\nimport { filterRetiredFixtures, hasFixtureMatchdayCorrection } from '../services/retiredFixtureService';\n/**\n * DURABLE UPSTASH REDIS READ MODEL STORE\n *\n * Tiered Read Hierarchy:\n * 1. Short-lived in-process memory cache (15s TTL)\n * 2. Fresh Redis snapshot (efluz:v1:fresh:<key>, with TTL)\n * 3. Firestore when refresh is required / missing (with request coalescing)\n * 4. Stale Redis last-known-good snapshot (efluz:v1:lkg:<key>, NO TTL / permanent)\n * 5. Structured 503 error if neither Firestore nor Redis contains data (READ_MODEL_NOT_WARMED)\n *\n * Durability & Resilience Rules:\n * - Two-key storage strategy: fresh key has TTL, LKG key has NO TTL.\n * - Non-destructive invalidation: invalidating clears memory and deletes only fresh key / marks dirty; preserves LKG key.\n * - Authoritative mutations trigger targeted rebuilds. If rebuild fails, previous LKG is served as stale.\n * - LKG protection: validated authoritative data replaces LKG; non-empty LKG is NEVER replaced with empty data.\n * - Domestic league standings must never store an empty array; fallback generates zero-value rows:\n *   Premier League (20), La Liga (20), Serie A (20), Bundesliga (18), Ligue 1 (18).\n * - Club ownership is preserved in owner-neutral snapshots; user-specific fields like isCurrentUserClub\n *   are derived on read per-request and NEVER leaked into shared cache.\n */\n\nimport { Redis } from '@upstash/redis';\nimport { sharedReadRefresh, isReadRefreshUnavailable } from './sharedReadRefresh';\nimport { resolveRedisConfig } from './redisConfig';\nimport { firestoreCircuitBreaker } from '../firebase/circuitBreaker';\nimport { getFirestoreDb } from '../firebase/admin';\nimport { COLLECTIONS, FirestoreFixtureDoc, FirestoreCompetitionDoc } from '../firebase/collections';\nimport { queryAll, queryGet } from '../db';\nimport { trackFirestoreRead } from '../firebase/firestoreStore';\nimport { SEED_COMPETITIONS, SEED_CLUBS, SEED_LEAGUES } from '../db/seed';\nimport { Club, Fixture, Competition, StandingsRow } from '../../types/index';\n\nexport const SCHEMA_VERSION = 'v1';\nexport const KEY_PREFIX = `efluz:${SCHEMA_VERSION}`;\n\nexport interface ReadModelSnapshot<T> {\n  schemaVersion: string;\n  generatedAt: string;\n  sourceVersion: string;\n  expectedCount: number;\n  actualCount: number;\n  data: T;\n  source?: string;\n  stale?: boolean;\n  degraded?: boolean;\n}\n\nexport interface CoreDatasetHealth {\n  key: string;\n  expectedCount: number;\n  actualCount: number;\n  snapshotTimestamp: string | null;\n  snapshotAgeSeconds: number | null;\n  hasFresh: boolean;\n  hasLkg: boolean;\n  isDirty: boolean;\n  status: 'FRESH' | 'LKG_STALE' | 'DIRTY' | 'MISSING';\n}\n\nexport interface ReadModelHealthInfo {\n  firestoreState: 'CLOSED' | 'OPEN' | 'HALF_OPEN';\n  redisState: 'CONNECTED' | 'IN_MEMORY_FALLBACK' | 'ERROR';\n  circuitBreakerState: {\n    state: string;\n    consecutiveFailures: number;\n    resourceExhaustedCount: number;\n    lastFailureTime: number | null;\n    lastError: string | null;\n  };\n  lastSnapshotAt: string | null;\n  snapshotAgeSeconds: number | null;\n  freshKeys: string[];\n  lkgKeys: string[];\n  dirtyKeys: string[];\n  missingKeys: string[];\n  // Spaced aliases matching audit requirements\n  'fresh keys'?: string[];\n  'lkg keys'?: string[];\n  'dirty keys'?: string[];\n  'missing keys'?: string[];\n  warmedKeys?: string[];\n  coreDatasets: Record<string, CoreDatasetHealth>;\n}\n\nexport class ReadModelNotWarmedError extends Error {\n  public readonly errorCode = 'READ_MODEL_NOT_WARMED';\n  public readonly statusCode = 503;\n  public readonly status = 503;\n  constructor(message = 'Read model is not warmed and authoritative database is temporarily unreachable.') {\n    super(message);\n    this.name = 'ReadModelNotWarmedError';\n  }\n}\n\n// Domestic league configuration with expected team counts\nexport const DOMESTIC_LEAGUE_CONFIG: Record<\n  string,\n  { leagueId: string; expectedCount: number; name: string }\n> = {\n  'comp-premier-league-2026': { leagueId: 'league-premier-league', expectedCount: 20, name: 'Premier League' },\n  'comp-la-liga-2026': { leagueId: 'league-la-liga', expectedCount: 20, name: 'La Liga' },\n  'comp-serie-a-2026': { leagueId: 'league-serie-a', expectedCount: 20, name: 'Serie A' },\n  'comp-bundesliga-2026': { leagueId: 'league-bundesliga', expectedCount: 18, name: 'Bundesliga' },\n  'comp-ligue-1-2026': { leagueId: 'league-ligue-1', expectedCount: 18, name: 'Ligue 1' },\n};\n\n// Canonical competition order (1-17, EFL Cup safely omitted)\nexport const CANONICAL_COMPETITION_ORDER: Record<string, number> = {\n  'comp-premier-league-2026': 1,\n  'comp-la-liga-2026': 2,\n  'comp-serie-a-2026': 3,\n  'comp-bundesliga-2026': 4,\n  'comp-ligue-1-2026': 5,\n  'comp-fa-cup-2026': 6,\n  'comp-copa-del-rey-2026': 7,\n  'comp-coppa-italia-2026': 8,\n  'comp-dfb-pokal-2026': 9,\n  'comp-coupe-de-france-2026': 10,\n  'comp-community-shield-2026': 11,\n  'comp-supercopa-espana-2026': 12,\n  'comp-supercoppa-italiana-2026': 13,\n  'comp-dfl-supercup-2026': 14,\n  'comp-champions-league-2026': 15,\n  'comp-europa-league-2026': 16,\n  'comp-uefa-super-cup-2026': 17,\n};\n\n// ----------------------------------------------------\n// KEY RESOLUTION HELPERS (TWO-KEY STRATEGY)\n// ----------------------------------------------------\n\nexport function getRawDatasetKey(key: string): string {\n  return key.replace(/^efluz:v1:(fresh:|lkg:|dirty:)?/, '').replace(/^efluz:v1:/, '');\n}\n\nexport function getFreshKey(datasetKey: string): string {\n  const clean = getRawDatasetKey(datasetKey);\n  return `${KEY_PREFIX}:fresh:${clean}`;\n}\n\nexport function getLkgKey(datasetKey: string): string {\n  const clean = getRawDatasetKey(datasetKey);\n  return `${KEY_PREFIX}:lkg:${clean}`;\n}\n\nexport function getDirtyKey(datasetKey: string): string {\n  const clean = getRawDatasetKey(datasetKey);\n  return `${KEY_PREFIX}:dirty:${clean}`;\n}\n\n// Canonical dataset key generators\nexport const ReadModelKeys = {\n  competitions: (seasonId = 'season-2026-27') => `${KEY_PREFIX}:season:${seasonId}:competitions`,\n  clubsWithOwners: (seasonId = 'season-2026-27') => `${KEY_PREFIX}:season:${seasonId}:clubs-with-owners`,\n  clubAdmission: (seasonId = 'season-2026-27') => `${KEY_PREFIX}:season:${seasonId}:club-admission`,\n  leagueClubs: (leagueId: string, seasonId = 'season-2026-27') => `${KEY_PREFIX}:season:${seasonId}:league:${leagueId}:clubs`,\n  standings: (competitionId: string, seasonId = 'season-2026-27') => `${KEY_PREFIX}:season:${seasonId}:competition:${competitionId}:standings`,\n  competitionFixtures: (competitionId: string, seasonId = 'season-2026-27') => `${KEY_PREFIX}:season:${seasonId}:competition:${competitionId}:fixtures`,\n  fixtures: (competitionId: string, seasonId = 'season-2026-27') => `${KEY_PREFIX}:season:${seasonId}:competition:${competitionId}:fixtures`,\n  adminFixtures: (seasonId = 'season-2026-27') => `${KEY_PREFIX}:season:${seasonId}:admin:fixtures`,\n  userMembership: (userId: string, seasonId = 'season-2026-27') => `${KEY_PREFIX}:season:${seasonId}:user:${userId}:membership`,\n};\n\n// ----------------------------------------------------\n// REDIS CLIENT & IN-MEMORY STORAGE\n// ----------------------------------------------------\n\nlet upstashClient: Redis | null = null;\nlet isUpstashConfigured = false;\nlet reportedRedisConfig = false;\n\n// Persistent memory storage mimicking Redis (for environments without Upstash credentials or offline)\nexport const memoryRedisStorage = new Map<\n  string,\n  { snapshot: ReadModelSnapshot<any>; expiresAt: number | null }\n>();\n\n// Short-lived process memory cache (Level 1: 15 seconds)\nexport const inProcessMemoryCache = new Map<string, { data: any; expiresAt: number }>();\nconst PROCESS_MEMORY_TTL_MS = 15000;\n\n// Request coalescing map\nconst inFlightLoaders = new Map<string, Promise<any>>();\n\n// Track last snapshot generation timestamp\nlet globalLastSnapshotAt: string | null = null;\n\nexport function resetUpstashClient(): void {\n  upstashClient = null;\n  isUpstashConfigured = false;\n  reportedRedisConfig = false;\n}\n\nexport function getUpstashClient(): Redis | null {\n  if (upstashClient) return upstashClient;\n  const config = resolveRedisConfig(process.env);\n  if (!reportedRedisConfig) {\n    reportedRedisConfig = true;\n    console.info('[READ_MODEL_REDIS_CONFIG]', config\n      ? `CONFIGURED: ${config.urlName} / ${config.tokenName}`\n      : 'MISSING_OR_AMBIGUOUS: no single complete Redis REST credential pair');\n  }\n  if (config) {\n    try {\n      upstashClient = new Redis({ url: config.url, token: config.token });\n      isUpstashConfigured = true;\n      return upstashClient;\n    } catch {\n      console.warn('[READ_MODEL_STORE] Redis client configuration is invalid.');\n    }\n  }\n  return null;\n}\n\n// ----------------------------------------------------\n// REDIS LOW-LEVEL PRIMITIVES\n// ----------------------------------------------------\n\n/**\n * Get TTL in seconds for a key:\n * -1 = persists with no expiration (LKG)\n * -2 = key does not exist\n * >0 = seconds remaining\n */\nexport async function redisGetTtl(key: string): Promise<number> {\n  const client = getUpstashClient();\n  if (client) {\n    try {\n      return await client.ttl(key);\n    } catch (err: any) {\n      console.warn(`[READ_MODEL_STORE] Redis ttl error for ${key}:`, err?.message || err);\n    }\n  }\n  const entry = memoryRedisStorage.get(key);\n  if (!entry) return -2;\n  if (entry.expiresAt === null) return -1;\n  const remainingMs = entry.expiresAt - Date.now();\n  if (remainingMs <= 0) {\n    memoryRedisStorage.delete(key);\n    return -2;\n  }\n  return Math.floor(remainingMs / 1000);\n}\n\n/**\n * Reads an exact key directly from Redis / memory.\n */\nexport async function redisGetExact<T>(key: string): Promise<ReadModelSnapshot<T> | null> {\n  const client = getUpstashClient();\n  if (client) {\n    try {\n      const val = await client.get<ReadModelSnapshot<T>>(key);\n      if (val && typeof val === 'object' && 'data' in val) {\n        return val;\n      }\n      return null;\n    } catch (err: any) {\n      console.warn(`[READ_MODEL_STORE] Redis get error for key ${key}:`, err?.message || err);\n    }\n  }\n\n  const entry = memoryRedisStorage.get(key);\n  if (!entry) return null;\n  if (entry.expiresAt && Date.now() > entry.expiresAt) {\n    memoryRedisStorage.delete(key);\n    return null;\n  }\n  return entry.snapshot as ReadModelSnapshot<T>;\n}\n\n/**\n * Reads fresh snapshot for dataset.\n */\nexport async function redisGetFresh<T>(datasetKey: string): Promise<ReadModelSnapshot<T> | null> {\n  const freshKey = getFreshKey(datasetKey);\n  return redisGetExact<T>(freshKey);\n}\n\n/**\n * Reads last-known-good (LKG) snapshot for dataset.\n */\nexport async function redisGetLkg<T>(datasetKey: string): Promise<ReadModelSnapshot<T> | null> {\n  const lkgKey = getLkgKey(datasetKey);\n  return redisGetExact<T>(lkgKey);\n}\n\n/**\n * Checks if a dataset is marked dirty.\n */\nexport async function redisIsDirty(datasetKey: string): Promise<boolean> {\n  const dirtyKey = getDirtyKey(datasetKey);\n  const client = getUpstashClient();\n  if (client) {\n    try {\n      const exists = await client.exists(dirtyKey);\n      if (exists > 0) return true;\n    } catch {\n      // fallback\n    }\n  }\n  const entry = memoryRedisStorage.get(dirtyKey);\n  if (!entry) return false;\n  if (entry.expiresAt && Date.now() > entry.expiresAt) {\n    memoryRedisStorage.delete(dirtyKey);\n    return false;\n  }\n  return true;\n}\n\n/**\n * Universal raw reader:\n * If exact key is requested (e.g. contains :fresh: or :lkg:), returns that exact key.\n * If raw dataset key is requested, attempts to read fresh first, then falls back to LKG.\n */\nexport async function redisGetRaw<T>(key: string): Promise<ReadModelSnapshot<T> | null> {\n  if (key.includes(':fresh:') || key.includes(':lkg:') || key.includes(':dirty:')) {\n    return redisGetExact<T>(key);\n  }\n\n  // 1. Try fresh key\n  const fresh = await redisGetFresh<T>(key);\n  if (fresh && fresh.data !== undefined) {\n    const dirty = await redisIsDirty(key);\n    if (!dirty) {\n      return fresh;\n    }\n  }\n\n  // 2. Fall back to LKG\n  const lkg = await redisGetLkg<T>(key);\n  if (lkg && lkg.data !== undefined) {\n    return lkg;\n  }\n\n  // 3. Fallback: check legacy non-prefixed key in memory\n  const legacy = await redisGetExact<T>(key);\n  if (legacy) return legacy;\n\n  return null;\n}\n\n/**\n * Two-Key Persistence:\n * - fresh key is saved with TTL (ttlSeconds, default 86400).\n * - lkg key is saved with NO TTL (permanent).\n * - validates complete metadata (schemaVersion, generatedAt, sourceVersion, expectedCount, actualCount).\n * - LKG protection: \"never replace non-empty lkg with empty data.\"\n */\nexport async function redisSetRaw<T>(\n  datasetKey: string,\n  snapshot: Partial<ReadModelSnapshot<T>> & { data: T },\n  ttlSeconds = 86400\n): Promise<void> {\n  const cleanKey = getRawDatasetKey(datasetKey);\n  const freshKey = getFreshKey(cleanKey);\n  const lkgKey = getLkgKey(cleanKey);\n  const dirtyKey = getDirtyKey(cleanKey);\n\n  const now = snapshot.generatedAt || new Date().toISOString();\n  globalLastSnapshotAt = now;\n\n  const actualCount = Array.isArray(snapshot.data)\n    ? snapshot.data.length\n    : snapshot.data !== null && snapshot.data !== undefined\n    ? 1\n    : 0;\n\n  const fullSnapshot: ReadModelSnapshot<T> = {\n    schemaVersion: snapshot.schemaVersion || SCHEMA_VERSION,\n    generatedAt: now,\n    sourceVersion: snapshot.sourceVersion || 'authoritative',\n    expectedCount: snapshot.expectedCount !== undefined ? snapshot.expectedCount : actualCount,\n    actualCount,\n    data: snapshot.data,\n  };\n\n  const client = getUpstashClient();\n\n  // Publish fresh + permanent snapshot atomically; do not claim durability on a failed write.\n  if (client) {\n    const accepted = await client.eval(`\n      local old = redis.call('GET', KEYS[2])\n      if old then\n        local ok, previous = pcall(cjson.decode, old)\n        if ok and tonumber(previous.actualCount or 0) > 0 and tonumber(ARGV[3]) == 0 then return 0 end\n        if ok and previous.generatedAt and previous.generatedAt > ARGV[4] then return 0 end\n      end\n      redis.call('SET', KEYS[2], ARGV[1])\n      redis.call('SET', KEYS[1], ARGV[1], 'EX', ARGV[2])\n      redis.call('DEL', KEYS[3])\n      return 1\n    `, [freshKey, lkgKey, dirtyKey], [JSON.stringify(fullSnapshot), Math.max(1, ttlSeconds), actualCount, now]);\n    if (Number(accepted) !== 1) throw new Error(`SNAPSHOT_REJECTED: ${cleanKey}`);\n  } else {\n    if (process.env.NODE_ENV === 'production' || process.env.VERCEL || process.env.K_SERVICE) throw new Error('REDIS_REQUIRED_FOR_DURABLE_SNAPSHOT');\n    const previous = await redisGetLkg<T>(cleanKey);\n    if (previous && (previous.actualCount > 0 && actualCount === 0 || previous.generatedAt > now)) throw new Error(`SNAPSHOT_REJECTED: ${cleanKey}`);\n  }\n  memoryRedisStorage.set(freshKey, { snapshot: fullSnapshot, expiresAt: Date.now() + Math.max(1, ttlSeconds) * 1000 });\n  memoryRedisStorage.set(lkgKey, { snapshot: fullSnapshot, expiresAt: null });\n  memoryRedisStorage.delete(dirtyKey);\n\n  // 4. Update process memory\n  setInProcessMemory(cleanKey, fullSnapshot);\n  setInProcessMemory(freshKey, fullSnapshot);\n  setInProcessMemory(lkgKey, fullSnapshot);\n}\n\n/**\n * Deletes keys directly (used for tests or cleanups).\n */\nexport async function redisDelRaw(...keys: string[]): Promise<void> {\n  if (keys.length === 0) return;\n  for (const k of keys) {\n    inProcessMemoryCache.delete(k);\n    memoryRedisStorage.delete(k);\n    const clean = getRawDatasetKey(k);\n    inProcessMemoryCache.delete(clean);\n    inProcessMemoryCache.delete(getFreshKey(clean));\n    inProcessMemoryCache.delete(getLkgKey(clean));\n  }\n\n  const client = getUpstashClient();\n  if (client) {\n    try {\n      await client.del(...keys);\n    } catch (err: any) {\n      console.warn(`[READ_MODEL_STORE] Redis del error:`, err?.message || err);\n    }\n  }\n}\n\n/**\n * Non-destructive invalidation:\n * - Clears process memory entry.\n * - Deletes only the fresh key or marks it dirty.\n * - PRESERVES the LKG key!\n * - Attempts targeted snapshot rebuild if provided.\n * - If rebuild fails, LKG is kept and served as stale.\n */\nexport async function invalidateDataset(\n  datasetKey: string,\n  targetedRebuild?: () => Promise<void>\n): Promise<void> {\n  const cleanKey = getRawDatasetKey(datasetKey);\n  const freshKey = getFreshKey(cleanKey);\n  const dirtyKey = getDirtyKey(cleanKey);\n\n  // 1. Clear process memory\n  inProcessMemoryCache.delete(datasetKey);\n  inProcessMemoryCache.delete(cleanKey);\n  inProcessMemoryCache.delete(freshKey);\n  inProcessMemoryCache.delete(`${KEY_PREFIX}:${cleanKey}`);\n\n  // 2. Delete ONLY fresh key from Redis & memory\n  const client = getUpstashClient();\n  if (client) {\n    try {\n      await client.del(freshKey);\n      await client.set(dirtyKey, { markedAt: new Date().toISOString() }, { ex: 86400 });\n    } catch (err: any) {\n      console.warn(`[READ_MODEL_STORE] Error invalidating fresh key ${freshKey}:`, err?.message || err);\n    }\n  }\n  memoryRedisStorage.delete(freshKey);\n  memoryRedisStorage.set(dirtyKey, {\n    snapshot: {\n      schemaVersion: SCHEMA_VERSION,\n      generatedAt: new Date().toISOString(),\n      sourceVersion: 'dirty',\n      expectedCount: 0,\n      actualCount: 0,\n      data: true,\n    } as any,\n    expiresAt: Date.now() + 86400000,\n  });\n\n  // Notice: We NEVER delete the LKG key! LKG is preserved!\n\n  // 3. Attempt targeted rebuild after authoritative mutation\n  if (targetedRebuild) {\n    try {\n      await targetedRebuild();\n      // Rebuild succeeded: delete dirty marker\n      if (client) {\n        try {\n          await client.del(dirtyKey);\n        } catch {}\n      }\n      memoryRedisStorage.delete(dirtyKey);\n    } catch (err: any) {\n      console.warn(\n        `[READ_MODEL_STORE] Targeted rebuild failed for ${cleanKey}; preserving existing LKG snapshot as stale. Cause:`,\n        err?.message || err\n      );\n    }\n  }\n}\n\n// ----------------------------------------------------\n// PROCESS MEMORY CACHE (LEVEL 1)\n// ----------------------------------------------------\n\nexport function getFromProcessMemory<T>(key: string): T | null {\n  const cleanKey = getRawDatasetKey(key);\n  const entry = inProcessMemoryCache.get(key) || inProcessMemoryCache.get(cleanKey);\n  if (!entry) return null;\n  if (Date.now() > entry.expiresAt) {\n    inProcessMemoryCache.delete(key);\n    inProcessMemoryCache.delete(cleanKey);\n    return null;\n  }\n  return entry.data as T;\n}\n\nexport function setInProcessMemory<T>(key: string, data: T, ttlMs = PROCESS_MEMORY_TTL_MS): void {\n  const cleanKey = getRawDatasetKey(key);\n  const entry = { data, expiresAt: Date.now() + ttlMs };\n  inProcessMemoryCache.set(key, entry);\n  if (cleanKey !== key) {\n    inProcessMemoryCache.set(cleanKey, entry);\n  }\n}\n\nexport function clearProcessMemoryCache(): void {\n  inProcessMemoryCache.clear();\n  inFlightLoaders.clear();\n}\n\nexport const clearProcessMemoryForTest = clearProcessMemoryCache;\n\nexport function resetMemoryRedisStore(): void {\n  clearProcessMemoryCache();\n  memoryRedisStorage.clear();\n  globalLastSnapshotAt = null;\n}\n\n// ----------------------------------------------------\n// STABLE ADMIN FIXTURE COMPARATOR & CURSOR PAGINATION\n// ----------------------------------------------------\n\nexport function compareAdminFixtures(a: Fixture, b: Fixture, singleCompetition = false): number {\n  if (!singleCompetition) {\n    const orderA = CANONICAL_COMPETITION_ORDER[a.competitionId] ?? 999;\n    const orderB = CANONICAL_COMPETITION_ORDER[b.competitionId] ?? 999;\n    if (orderA !== orderB) {\n      return orderA - orderB;\n    }\n  }\n\n  const mdA = typeof a.matchday === 'number' ? a.matchday : parseInt(String(a.matchday || 0), 10) || 0;\n  const mdB = typeof b.matchday === 'number' ? b.matchday : parseInt(String(b.matchday || 0), 10) || 0;\n  if (mdA !== mdB) {\n    return mdA - mdB;\n  }\n\n  const timeA = a.scheduledAt ? new Date(a.scheduledAt).getTime() : 0;\n  const timeB = b.scheduledAt ? new Date(b.scheduledAt).getTime() : 0;\n  if (timeA !== timeB) {\n    return timeA - timeB;\n  }\n\n  return (a.id || '').localeCompare(b.id || '');\n}\n\nexport interface FixtureSortTuple {\n  competitionOrder: number;\n  matchday: number;\n  scheduledAt: string;\n  id: string;\n}\n\nexport function encodeFixtureCursor(fixture: Fixture): string {\n  const compOrder = CANONICAL_COMPETITION_ORDER[fixture.competitionId] ?? 999;\n  const matchday = typeof fixture.matchday === 'number' ? fixture.matchday : parseInt(String(fixture.matchday || 0), 10) || 0;\n  const scheduledAt = fixture.scheduledAt || '';\n  const id = fixture.id;\n\n  const tuple: FixtureSortTuple = {\n    competitionOrder: compOrder,\n    matchday,\n    scheduledAt,\n    id,\n  };\n  return Buffer.from(JSON.stringify(tuple)).toString('base64url');\n}\n\nexport function decodeFixtureCursor(cursorStr: string): FixtureSortTuple | null {\n  try {\n    const raw = Buffer.from(cursorStr, 'base64url').toString('utf-8');\n    const parsed = JSON.parse(raw);\n    if (parsed && typeof parsed.id === 'string') {\n      return parsed as FixtureSortTuple;\n    }\n  } catch {}\n  return null;\n}\n\n// ----------------------------------------------------\n// TIERED READ MODEL EXECUTION ENGINE\n// ----------------------------------------------------\n\nexport interface TieredReadOptions<T> {\n  key: string;\n  seasonId?: string;\n  ttlSeconds?: number;\n  sourceVersion?: string;\n  expectedCount?: number;\n  firestoreFetcher: () => Promise<T>;\n  validateData?: (data: T) => boolean;\n}\n\nexport interface TieredReadResult<T> {\n  data: T;\n  source: 'memory' | 'memory_stale' | 'redis_fresh' | 'firestore' | 'redis_stale';\n  generatedAt: string;\n  sourceVersion: string;\n  stale?: boolean;\n  degraded?: boolean;\n}\n\n/**\n * Tiered Reader:\n * memory \u2192 fresh Redis \u2192 Firestore refresh \u2192 stale Redis last-known-good\n */\nexport async function readThroughReadModel<T>(options: TieredReadOptions<T>): Promise<TieredReadResult<T>> {\n  const { key, ttlSeconds = 86400, expectedCount, firestoreFetcher, validateData } = options;\n  const cleanKey = getRawDatasetKey(key);\n\n  const breakerStatus = firestoreCircuitBreaker.getStatus();\n  const firestoreHealthy = breakerStatus.state === 'CLOSED' && !breakerStatus.softLimitExceeded;\n  const isDirty = await redisIsDirty(cleanKey);\n\n  // 1. Process Memory Cache (Level 1)\n  const memoryHit = getFromProcessMemory<ReadModelSnapshot<T>>(cleanKey);\n  if (!isDirty && memoryHit && memoryHit.data !== undefined && Date.now() - Date.parse(memoryHit.generatedAt) < ttlSeconds * 1000) {\n    if (!firestoreHealthy) {\n      return {\n        data: memoryHit.data,\n        source: 'memory_stale',\n        generatedAt: memoryHit.generatedAt,\n        sourceVersion: memoryHit.sourceVersion,\n        stale: true,\n        degraded: true,\n      };\n    }\n    return {\n      data: memoryHit.data,\n      source: 'memory',\n      generatedAt: memoryHit.generatedAt,\n      sourceVersion: memoryHit.sourceVersion,\n      stale: false,\n      degraded: false,\n    };\n  }\n\n  // 2. Fresh Redis Snapshot (Level 2)\n  let freshSnapshot: ReadModelSnapshot<T> | null = null;\n  if (!isDirty) {\n    freshSnapshot = await redisGetFresh<T>(cleanKey);\n  }\n\n  // Return valid cached data before reserving a Firestore recovery probe.\n  if (freshSnapshot && freshSnapshot.data !== undefined) {\n    const ageMs = Date.now() - new Date(freshSnapshot.generatedAt).getTime();\n    if (ageMs < ttlSeconds * 1000) {\n      setInProcessMemory(cleanKey, freshSnapshot);\n      return {\n        data: freshSnapshot.data,\n        source: 'redis_fresh',\n        generatedAt: freshSnapshot.generatedAt,\n        sourceVersion: freshSnapshot.sourceVersion,\n        stale: !firestoreHealthy,\n        degraded: !firestoreHealthy,\n      };\n    }\n  }\n\n  const canQueryFirestore = firestoreCircuitBreaker.canExecute();\n\n  // If circuit breaker is OPEN, do NOT hit Firestore; immediately return LKG or fresh snapshot\n  if (!canQueryFirestore) {\n    if (freshSnapshot && freshSnapshot.data !== undefined) {\n      setInProcessMemory(cleanKey, freshSnapshot);\n      return {\n        data: freshSnapshot.data,\n        source: 'redis_fresh',\n        generatedAt: freshSnapshot.generatedAt,\n        sourceVersion: freshSnapshot.sourceVersion,\n        stale: true,\n        degraded: true,\n      };\n    }\n    // Try LKG\n    const lkgSnapshot = await redisGetLkg<T>(cleanKey);\n    if (lkgSnapshot && lkgSnapshot.data !== undefined) {\n      setInProcessMemory(cleanKey, lkgSnapshot);\n      return {\n        data: lkgSnapshot.data,\n        source: 'redis_stale',\n        generatedAt: lkgSnapshot.generatedAt,\n        sourceVersion: lkgSnapshot.sourceVersion,\n        stale: true,\n        degraded: true,\n      };\n    }\n    // Neither Firestore nor Redis has data -> 503\n    throw new ReadModelNotWarmedError(\n      `Firestore circuit breaker is OPEN and no warmed Redis snapshot exists for key: ${key}`\n    );\n  }\n\n  // 3. Firestore Read with Request Coalescing\n  let loader = inFlightLoaders.get(cleanKey) as Promise<T> | undefined;\n  if (!loader) {\n    loader = (async () => {\n      try {\n        const freshData = await firestoreFetcher();\n\n        // Validation guard\n        const isValid = validateData ? validateData(freshData) : Boolean(freshData);\n        if (!isValid) {\n          throw new Error(`Fetched Firestore data failed validation for key ${key}`);\n        }\n\n        const now = new Date().toISOString();\n        const actualCount = Array.isArray(freshData) ? freshData.length : freshData ? 1 : 0;\n        const snapshot: ReadModelSnapshot<T> = {\n          schemaVersion: SCHEMA_VERSION,\n          generatedAt: now,\n          sourceVersion: options.sourceVersion || 'firestore-authoritative',\n          expectedCount: expectedCount ?? actualCount,\n          actualCount,\n          data: freshData,\n        };\n\n        // Persist to fresh (with TTL) and LKG (no TTL)\n        await redisSetRaw(cleanKey, snapshot, ttlSeconds);\n        firestoreCircuitBreaker.recordSuccess();\n\n        return freshData;\n      } catch (err: any) {\n        if (isReadRefreshUnavailable(err)) firestoreCircuitBreaker.cancelProbe();\n        else firestoreCircuitBreaker.recordFailure(err);\n        throw err;\n      } finally {\n        inFlightLoaders.delete(cleanKey);\n      }\n    })();\n    inFlightLoaders.set(cleanKey, loader);\n  }\n\n  try {\n    const resultData = await loader;\n    return {\n      data: resultData,\n      source: 'firestore',\n      generatedAt: new Date().toISOString(),\n      sourceVersion: options.sourceVersion || 'firestore-authoritative',\n      stale: false,\n      degraded: false,\n    };\n  } catch (firestoreErr: any) {\n    // 4. Stale Redis LKG Snapshot on Firestore failure\n    const lkgSnapshot = await redisGetLkg<T>(cleanKey);\n    if (lkgSnapshot && lkgSnapshot.data !== undefined) {\n      console.warn(\n        `[READ_MODEL] Firestore failed for ${key}, serving stale Redis LKG snapshot. Cause:`,\n        firestoreErr?.message || firestoreErr\n      );\n      setInProcessMemory(cleanKey, lkgSnapshot);\n      return {\n        data: lkgSnapshot.data,\n        source: 'redis_stale',\n        generatedAt: lkgSnapshot.generatedAt,\n        sourceVersion: lkgSnapshot.sourceVersion,\n        stale: true,\n        degraded: true,\n      };\n    }\n\n    // 5. Structured 503 if neither Firestore nor Redis has data\n    console.error(`[READ_MODEL] Both Firestore and Redis unavailable for key: ${key}. Error:`, firestoreErr);\n    throw new ReadModelNotWarmedError(\n      `Failed to load authoritative data from Firestore and no Redis snapshot is available for key: ${key}`\n    );\n  }\n}\n\n// ----------------------------------------------------\n// READ-MODEL BUILDERS & SNAPSHOT GENERATORS\n// ----------------------------------------------------\n\n/**\n * Builds and persists snapshot for active competitions catalog.\n */\nexport async function buildCompetitionsSnapshot(seasonId = 'season-2026-27'): Promise<ReadModelSnapshot<Competition[]>> {\n  const db = getFirestoreDb();\n  if (!db) throw new ReadModelNotWarmedError('Firestore unavailable for competition refresh');\n  const docs = await db.collection(COLLECTIONS.COMPETITIONS).where('seasonId', '==', seasonId).get();\n  const competitions = docs.docs.map(d => {\n    const data = d.data();\n    const seed = SEED_COMPETITIONS.find(c => c.id === d.id);\n    const competition = { ...seed, ...data, id: d.id, seasonId } as Competition;\n    if (competition.type === 'EUROPEAN_LEAGUE_PHASE') {\n      const teams = Number(competition.formatConfig?.leaguePhaseTeams || 32);\n      const matchesPerTeam = Number(competition.formatConfig?.matchesPerTeam || 8);\n      if (Number(competition.currentMatchday || 1) <= matchesPerTeam) {\n        const leaguePhaseFixtureCount = (teams * matchesPerTeam) / 2;\n        competition.fixtureCount = leaguePhaseFixtureCount;\n        competition.fixturesCount = leaguePhaseFixtureCount;\n      }\n    }\n    return competition;\n  }).filter(c => !c.id.includes('efl-cup') && String(c.status) !== 'inactive' && !(c as any).hidden);\n  if (!competitions.length) throw new ReadModelNotWarmedError('No authoritative competition catalog');\n  const snapshot: ReadModelSnapshot<Competition[]> = {\n    schemaVersion: SCHEMA_VERSION, generatedAt: new Date().toISOString(),\n    sourceVersion: 'firestore-catalog', expectedCount: competitions.length,\n    actualCount: competitions.length, data: competitions,\n  };\n  await redisSetRaw(ReadModelKeys.competitions(seasonId), snapshot, 3600);\n  return snapshot;\n}\n\n// Patch only one competition inside the durable catalog. Parallel admins managing\n// different leagues must not replace one another's state with an older whole list.\nexport async function patchCompetitionMatchdayCatalog(competition: FirestoreCompetitionDoc): Promise<void> {\n  const key = ReadModelKeys.competitions(competition.seasonId);\n  const clean = getRawDatasetKey(key), fresh = getFreshKey(clean), lkg = getLkgKey(clean);\n  const now = new Date().toISOString(), client = getUpstashClient();\n  if (client) {\n    await client.eval(`\n      local raw = redis.call('GET', KEYS[2]) or redis.call('GET', KEYS[1])\n      if not raw then return 0 end\n      local snapshot = cjson.decode(raw)\n      local patch = cjson.decode(ARGV[1])\n      local found = false\n      for _, item in ipairs(snapshot.data) do\n        if item.id == patch.id then\n          if item.updatedAt and patch.updatedAt and item.updatedAt > patch.updatedAt then return 0 end\n          for k, v in pairs(patch) do item[k] = v end\n          found = true\n        end\n      end\n      if not found then return 0 end\n      snapshot.generatedAt = ARGV[2]\n      snapshot.sourceVersion = 'matchday-control'\n      local updated = cjson.encode(snapshot)\n      redis.call('SET', KEYS[2], updated)\n      redis.call('SET', KEYS[1], updated, 'EX', 3600)\n      redis.call('DEL', KEYS[3])\n      return 1\n    `, [fresh, lkg, getDirtyKey(clean)], [JSON.stringify(competition), now]);\n    memoryRedisStorage.delete(fresh); memoryRedisStorage.delete(lkg);\n  } else {\n    const snapshot = await redisGetFresh<Competition[]>(key) || await redisGetLkg<Competition[]>(key);\n    if (snapshot?.data?.length) await redisSetRaw(key, { ...snapshot, generatedAt: now, data: snapshot.data.map(c => c.id === competition.id && (!c.updatedAt || !competition.updatedAt || c.updatedAt <= competition.updatedAt) ? { ...c, ...competition } as Competition : c) }, 3600);\n  }\n  inProcessMemoryCache.delete(clean); inProcessMemoryCache.delete(key);\n}\n\nexport interface OwnerNeutralClub extends Club {\n  ownerUserId: string | null;\n  ownerUsername: string | null;\n  ownerFirstName?: string | null;\n  ownerLastName?: string | null;\n  ownerDisplayName?: string | null;\n  claimedByUserId?: string | null;\n  claimedByUsername?: string | null;\n  managerUserId?: string | null;\n  managerUsername?: string | null;\n  managerFirstName?: string | null;\n  managerLastName?: string | null;\n  managerDisplayName?: string | null;\n  isClaimed?: boolean;\n  isAvailable?: boolean;\n  isOccupied: boolean;\n  isTaken?: boolean;\n}\n\nexport interface UserMembershipSentinel {\n  hasClub: boolean;\n  clubId: string | null;\n  club: Club | null;\n}\n\n/**\n * Builds owner-neutral clubs snapshot from authoritative Firestore occupancies.\n * Never converts claimed clubs into available clubs.\n * If Firestore fails and no LKG exists, throws READ_MODEL_NOT_WARMED.\n */\nexport async function buildClubsSnapshot(seasonId = 'season-2026-27'): Promise<ReadModelSnapshot<OwnerNeutralClub[]>> {\n  return sharedReadRefresh(ReadModelKeys.clubsWithOwners(seasonId), () => buildClubsSnapshotAuthoritative(seasonId));\n}\n\nasync function getClubsSnapshotForRead(seasonId: string): Promise<ReadModelSnapshot<OwnerNeutralClub[]>> {\n  const key = ReadModelKeys.clubsWithOwners(seasonId);\n  const fresh = await redisGetFresh<OwnerNeutralClub[]>(key);\n  if (Array.isArray(fresh?.data) && fresh.data.length === 96 && !(await redisIsDirty(key))) {\n    firestoreCircuitBreaker.cancelProbe();\n    return fresh;\n  }\n  return buildClubsSnapshot(seasonId);\n}\n\nasync function buildClubsSnapshotAuthoritative(seasonId: string): Promise<ReadModelSnapshot<OwnerNeutralClub[]>> {\n  const occMap = new Map<string, { userId: string }>();\n  const userMap = new Map<string, { username: string | null; firstName?: string | null; lastName?: string | null; displayName?: string | null }>();\n  const existingLkg = await redisGetLkg<OwnerNeutralClub[]>(ReadModelKeys.clubsWithOwners(seasonId));\n\n  let firestoreFailed = false;\n  let occupancyDocumentsSeen = 0;\n  try {\n    const db = getFirestoreDb();\n    if (db) {\n      // 1. Fetch club occupancies bounded by seasonId and active status (avoid unbounded collection scan)\n      const occSnap = await db\n        .collection(COLLECTIONS.CLUB_OCCUPANCIES)\n        .where('seasonId', '==', seasonId)\n        .get();\n      occupancyDocumentsSeen = occSnap.size;\n      trackFirestoreRead(COLLECTIONS.CLUB_OCCUPANCIES, Math.max(1, occSnap.size), 'buildClubsSnapshot');\n\n      for (const doc of occSnap.docs) {\n        const data = doc.data();\n        if (data.clubId && data.userId && !['released', 'inactive'].includes(data.status)) {\n          occMap.set(data.clubId, { userId: data.userId });\n        }\n      }\n\n      // 2. Fetch only the users who own clubs (avoids full USERS collection scan)\n      const ownerUserIds = Array.from(new Set(Array.from(occMap.values()).map((o) => o.userId)));\n      await Promise.all(\n        ownerUserIds.map(async (uid) => {\n          try {\n            const uDoc = await db.collection(COLLECTIONS.USERS).doc(uid).get();\n            trackFirestoreRead(COLLECTIONS.USERS, 1, 'buildClubsSnapshot:owner');\n            if (uDoc.exists) {\n              const uData = uDoc.data();\n              const uname = uData?.username ? String(uData.username).replace(/^@+/, '').trim() : null;\n              const isSynth = uname ? (uname.startsWith('tg_') || uname.startsWith('user_')) : false;\n              const validUname = isSynth ? null : uname;\n              const fname = uData?.firstName ? String(uData.firstName).trim() : null;\n              const lname = uData?.lastName ? String(uData.lastName).trim() : null;\n              const dname = [fname, lname].filter(Boolean).join(' ') || fname || (validUname ? `@${validUname}` : `User #${uid}`);\n              userMap.set(uid, {\n                username: validUname,\n                firstName: fname,\n                lastName: lname,\n                displayName: dname,\n              });\n            }\n          } catch {\n            const previous = existingLkg?.data.find(c => c.ownerUserId === uid);\n            if (previous) {\n              userMap.set(uid, {\n                username: previous.ownerUsername,\n                firstName: previous.ownerFirstName,\n                lastName: previous.ownerLastName,\n                displayName: previous.ownerDisplayName,\n              });\n            }\n          }\n        })\n      );\n    }\n  } catch (err: any) {\n    firestoreCircuitBreaker.recordFailure(err);\n    firestoreFailed = true;\n    console.warn('[READ_MODEL_STORE] Firestore occupancies fetch error in buildClubsSnapshot:', err?.message || err);\n  }\n\n  if (firestoreFailed) {\n    // If Firestore fails, NEVER create an all-available snapshot! Serve LKG if populated, otherwise throw READ_MODEL_NOT_WARMED\n    if (existingLkg && Array.isArray(existingLkg.data) && existingLkg.data.length > 0) {\n      throw new ReadModelNotWarmedError('Authoritative refresh unavailable; preserve last-known-good snapshot');\n    }\n    throw new ReadModelNotWarmedError(\n      'READ_MODEL_NOT_WARMED: Firestore club/occupancy read failed and no populated clubs-with-owners LKG exists.'\n    );\n  }\n\n  // If Firestore succeeded but occupancies are 0 while existing LKG had occupancies, protect LKG against transient wipe\n  if (occMap.size === 0 && occupancyDocumentsSeen === 0 && existingLkg && Array.isArray(existingLkg.data) && existingLkg.data.some((c) => c.isOccupied)) {\n    console.warn('[READ_MODEL_STORE] Firestore returned 0 occupancies while LKG had active owners; preserving LKG snapshot.');\n    throw new ReadModelNotWarmedError('Authoritative refresh unavailable; preserve last-known-good snapshot');\n  }\n\n  // Build owner-neutral clubs for all 96 canonical clubs (strictly omitting private telegram IDs)\n  const neutralClubs: OwnerNeutralClub[] = SEED_CLUBS.map((seed) => {\n    const occ = occMap.get(seed.id);\n    const ownerUserId = occ ? occ.userId : null;\n    const userDetail = ownerUserId ? userMap.get(ownerUserId) : null;\n    const isOccupied = Boolean(ownerUserId);\n\n    return {\n      id: seed.id,\n      name: seed.name,\n      shortName: seed.shortName,\n      country: seed.country,\n      leagueId: seed.leagueId,\n      logoUrl: seed.logoUrl,\n      active: true,\n      createdAt: new Date().toISOString(),\n      ownerUserId,\n      ownerUsername: userDetail?.username || null,\n      ownerFirstName: userDetail?.firstName || null,\n      ownerLastName: userDetail?.lastName || null,\n      ownerDisplayName: userDetail?.displayName || null,\n      claimedByUserId: ownerUserId,\n      claimedByUsername: userDetail?.username || null,\n      managerUserId: ownerUserId,\n      managerUsername: userDetail?.username || null,\n      managerFirstName: userDetail?.firstName || null,\n      managerLastName: userDetail?.lastName || null,\n      managerDisplayName: userDetail?.displayName || null,\n      isClaimed: isOccupied,\n      isAvailable: !isOccupied,\n      isOccupied,\n      isTaken: isOccupied,\n      occupancy: {\n        status: isOccupied ? 'occupied' : 'available',\n        userId: ownerUserId || undefined,\n        username: userDetail?.username || undefined,\n      },\n    };\n  });\n\n  const snapshot: ReadModelSnapshot<OwnerNeutralClub[]> = {\n    schemaVersion: SCHEMA_VERSION,\n    generatedAt: new Date().toISOString(),\n    sourceVersion: `occupancies-${occMap.size}`,\n    expectedCount: 96,\n    actualCount: neutralClubs.length,\n    data: neutralClubs,\n  };\n\n  const key = ReadModelKeys.clubsWithOwners(seasonId);\n  await redisSetRaw(key, snapshot, 86400);\n\n  // Also write per-league snapshots\n  for (const league of SEED_LEAGUES) {\n    const leagueClubs = neutralClubs.filter((c) => c.leagueId === league.id);\n    const expectedLeagueCount = league.id.includes('bundesliga') || league.id.includes('ligue-1') ? 18 : 20;\n    const leagueSnapshot: ReadModelSnapshot<OwnerNeutralClub[]> = {\n      schemaVersion: SCHEMA_VERSION,\n      generatedAt: new Date().toISOString(),\n      sourceVersion: `occupancies-${occMap.size}`,\n      expectedCount: expectedLeagueCount,\n      actualCount: leagueClubs.length,\n      data: leagueClubs,\n    };\n    const leagueKey = ReadModelKeys.leagueClubs(league.id, seasonId);\n    await redisSetRaw(leagueKey, leagueSnapshot, 86400);\n  }\n\n  return snapshot;\n}\n\n/**\n * Derives user-specific fields from an owner-neutral club.\n * Never leaks cross-user state into shared cache.\n */\nexport function enrichClubForUser(club: OwnerNeutralClub, currentUserId?: string): Club & Pick<OwnerNeutralClub, 'ownerUserId' | 'ownerUsername' | 'isOccupied'> {\n  const isCurrentUserClub = Boolean(currentUserId && club.ownerUserId === currentUserId);\n  const isOccupied = Boolean(club.ownerUserId || club.isOccupied || club.isTaken);\n\n  return {\n    id: club.id, name: club.name, shortName: club.shortName, country: club.country,\n    leagueId: club.leagueId, leagueName: club.leagueName, logoUrl: club.logoUrl,\n    active: club.active, stadium: club.stadium, createdAt: club.createdAt,\n    ownerUserId: club.ownerUserId, ownerUsername: club.ownerUsername, isOccupied,\n    owner: club.owner ? { userId: club.owner.userId, username: club.owner.username,\n      firstName: club.owner.firstName, claimedAt: club.owner.claimedAt } : undefined,\n    isCurrentUserClub,\n    isTaken: isOccupied,\n    claimedByUserId: club.ownerUserId,\n    claimedByUsername: club.ownerUsername,\n    managerUsername: club.ownerUsername,\n    occupancy: {\n      status: isCurrentUserClub ? 'owned' : isOccupied ? 'occupied' : 'available',\n      userId: club.ownerUserId || undefined,\n      username: club.ownerUsername || undefined,\n    },\n  };\n}\n\n/**\n * Builds materialized fixture snapshot sorted with stable tuple:\n * 1. canonical numeric competitionOrder\n * 2. numeric matchday\n * 3. scheduledAt\n * 4. fixture id as final tie-breaker\n */\nexport function normalizeFixtureSnapshot(doc: any, seasonId = 'season-2026-27'): Fixture {\n    const homeClubId = doc.homeClubId ?? doc.home_club_id;\n    const awayClubId = doc.awayClubId ?? doc.away_club_id;\n    const competitionId = doc.competitionId ?? doc.competition_id;\n    const competitionName = doc.competitionName ?? doc.competition_name;\n    const scheduledAt = doc.scheduledAt ?? doc.scheduled_at;\n    const homeScore = doc.homeScore ?? doc.home_score;\n    const awayScore = doc.awayScore ?? doc.away_score;\n    const winnerClubId = doc.winnerClubId ?? doc.winner_club_id;\n    const resultConfirmedAt = doc.resultConfirmedAt ?? doc.result_confirmed_at;\n    const roundName = doc.roundName ?? doc.round_name;\n    const createdAt = doc.createdAt ?? doc.created_at;\n    const updatedAt = doc.updatedAt ?? doc.updated_at;\n    const docSeasonId = doc.seasonId ?? doc.season_id;\n\n    const homeClubSeed = SEED_CLUBS.find((c) => c.id === homeClubId);\n    const awayClubSeed = SEED_CLUBS.find((c) => c.id === awayClubId);\n\n    return {\n      id: doc.id,\n      seasonId: docSeasonId || seasonId,\n      competitionId: competitionId,\n      competitionName: competitionName || competitionId,\n      matchday: doc.matchday,\n      roundName: roundName,\n      sourceFixtureId: doc.sourceFixtureId ?? doc.source_fixture_id ?? null,\n      sourceWinnerSlot: doc.sourceWinnerSlot ?? doc.source_winner_slot ?? null,\n      homeSourceFixtureId: doc.homeSourceFixtureId ?? doc.home_source_fixture_id ?? null,\n      awaySourceFixtureId: doc.awaySourceFixtureId ?? doc.away_source_fixture_id ?? null,\n      homeSourceWinnerSlot: doc.homeSourceWinnerSlot ?? doc.home_source_winner_slot ?? null,\n      awaySourceWinnerSlot: doc.awaySourceWinnerSlot ?? doc.away_source_winner_slot ?? null,\n      homeClubId: homeClubId && homeClubId !== 'TBD' ? homeClubId : null,\n      awayClubId: awayClubId && awayClubId !== 'TBD' ? awayClubId : null,\n      homeClub: homeClubId && homeClubId !== 'TBD' ? {\n        id: homeClubId,\n        name: homeClubSeed?.name || homeClubId,\n        shortName: homeClubSeed?.shortName || homeClubId.substring(0, 3).toUpperCase(),\n        country: homeClubSeed?.country || 'England',\n        leagueId: homeClubSeed?.leagueId || 'league-premier-league',\n        logoUrl: homeClubSeed?.logoUrl || '',\n        active: true,\n        createdAt: '',\n      } : undefined,\n      awayClub: awayClubId && awayClubId !== 'TBD' ? {\n        id: awayClubId,\n        name: awayClubSeed?.name || awayClubId,\n        shortName: awayClubSeed?.shortName || awayClubId.substring(0, 3).toUpperCase(),\n        country: awayClubSeed?.country || 'England',\n        leagueId: awayClubSeed?.leagueId || 'league-premier-league',\n        logoUrl: awayClubSeed?.logoUrl || '',\n        active: true,\n        createdAt: '',\n      } : undefined,\n      scheduledAt: scheduledAt,\n      homeScore: homeScore ?? undefined,\n      awayScore: awayScore ?? undefined,\n      winnerClubId: winnerClubId ?? undefined,\n      status: (doc.status || 'SCHEDULED') as any,\n      resultConfirmedAt: resultConfirmedAt || undefined,\n      homeOwnerId: doc.homeOwnerId ?? doc.home_owner_id,\n      awayOwnerId: doc.awayOwnerId ?? doc.away_owner_id,\n      createdAt: createdAt || new Date().toISOString(),\n      updatedAt: updatedAt || createdAt || new Date().toISOString(),\n    };\n}\n\nexport async function buildAdminFixturesSnapshot(seasonId = 'season-2026-27'): Promise<ReadModelSnapshot<Fixture[]>> {\n  const db = getFirestoreDb();\n  let fixDocs: FirestoreFixtureDoc[] = [];\n\n  if (db) {\n    try {\n      const fixSnap = await db.collection(COLLECTIONS.FIXTURES).where('seasonId', '==', seasonId).get();\n      trackFirestoreRead(COLLECTIONS.FIXTURES, fixSnap.docs.length, 'buildAdminFixturesSnapshot');\n      fixDocs = fixSnap.docs\n        .map((d) => ({ id: d.id, ...d.data() } as FirestoreFixtureDoc))\n        .filter((f) => !f.competitionId.includes('efl-cup'));\n    } catch (err: any) {\n      firestoreCircuitBreaker.recordFailure(err);\n      console.warn('[READ_MODEL_STORE] Error fetching fixtures in buildAdminFixturesSnapshot:', err?.message || err);\n      // Fallback to existing LKG snapshot if available\n      const existingLkg = await redisGetLkg<Fixture[]>(ReadModelKeys.adminFixtures(seasonId));\n      if (existingLkg && existingLkg.data) {\n        throw new ReadModelNotWarmedError('Authoritative refresh unavailable; preserve last-known-good snapshot');\n      }\n      throw new ReadModelNotWarmedError('Authoritative fixture read failed and no snapshot exists');\n    }\n  } else throw new ReadModelNotWarmedError('Firestore unavailable for fixture refresh');\n\n  let fixtures: Fixture[] = fixDocs.map(doc => normalizeFixtureSnapshot(doc, seasonId));\n\n  try {\n    const { enrichFixturesWithAuthoritativeOwners } = await import('../firebase/firestoreStore');\n    fixtures = await enrichFixturesWithAuthoritativeOwners(fixtures, seasonId);\n  } catch (enrichErr) {\n    console.warn('[BUILD_FIXTURES_SNAPSHOT] Non-blocking ownership enrichment fallback:', enrichErr);\n  }\n\n  // Sort strictly using stable tuple\n  fixtures.sort((a, b) => compareAdminFixtures(a, b, false));\n\n  const snapshot: ReadModelSnapshot<Fixture[]> = {\n    schemaVersion: SCHEMA_VERSION,\n    generatedAt: new Date().toISOString(),\n    sourceVersion: `fixtures-${fixtures.length}`,\n    expectedCount: fixtures.length,\n    actualCount: fixtures.length,\n    data: fixtures,\n  };\n\n  const key = ReadModelKeys.adminFixtures(seasonId);\n  await redisSetRaw(key, snapshot, 86400);\n\n  // Group and persist per-competition fixture snapshots\n  const compsSet = new Set(fixtures.map((f) => f.competitionId));\n  for (const compId of compsSet) {\n    const compFixtures = fixtures.filter((f) => f.competitionId === compId);\n    compFixtures.sort((a, b) => compareAdminFixtures(a, b, true));\n\n    const compKey = ReadModelKeys.competitionFixtures(compId, seasonId);\n    const compSnapshot: ReadModelSnapshot<Fixture[]> = {\n      schemaVersion: SCHEMA_VERSION,\n      generatedAt: new Date().toISOString(),\n      sourceVersion: `fixtures-${compFixtures.length}`,\n      expectedCount: compFixtures.length,\n      actualCount: compFixtures.length,\n      data: compFixtures,\n    };\n    await redisSetRaw(compKey, compSnapshot, 86400);\n  }\n\n  return snapshot;\n}\n\n/**\n * Generates zero-value standings rows for an active domestic league.\n * Never generates an empty array for an active domestic league.\n */\nexport function generateZeroValueStandings(\n  competitionId: string,\n  seasonId = 'season-2026-27'\n): StandingsRow[] {\n  const config = DOMESTIC_LEAGUE_CONFIG[competitionId];\n  let clubs = config ? SEED_CLUBS.filter((c) => c.leagueId === config.leagueId) : [];\n  if (clubs.length === 0) {\n    clubs = SEED_CLUBS.slice(0, 20);\n  }\n\n  return clubs.map((club, idx) => ({\n    position: idx + 1,\n    clubId: club.id,\n    clubName: club.name,\n    shortName: club.shortName,\n    logoUrl: club.logoUrl,\n    played: 0,\n    won: 0,\n    drawn: 0,\n    lost: 0,\n    goalsFor: 0,\n    goalsAgainst: 0,\n    goalDifference: 0,\n    points: 0,\n    form: [] as Array<'W' | 'D' | 'L'>,\n    streak: '',\n    competitionId,\n    seasonId,\n  }));\n}\n\n/**\n * Builds competition standings snapshot.\n * Ensures active domestic leagues receive exact expected row counts:\n * Premier League: 20\n * La Liga: 20\n * Serie A: 20\n * Bundesliga: 18\n * Ligue 1: 18\n */\nexport async function buildStandingsSnapshot(\n  competitionId: string,\n  seasonId = 'season-2026-27'\n): Promise<ReadModelSnapshot<StandingsRow[]>> {\n  if (['comp-champions-league-2026', 'comp-europa-league-2026'].includes(competitionId)) {\n    const { calculateEuropeanStandingsFromSqlite, rebuildEuropeanStandings } = await import('../tournament/qualificationEngine');\n    const sqliteRows = calculateEuropeanStandingsFromSqlite(competitionId, seasonId);\n    if (sqliteRows && sqliteRows.length > 0) {\n      return {\n        schemaVersion: SCHEMA_VERSION,\n        generatedAt: new Date().toISOString(),\n        sourceVersion: 'european-sqlite-local',\n        expectedCount: sqliteRows.length,\n        actualCount: sqliteRows.length,\n        data: sqliteRows as unknown as StandingsRow[],\n      };\n    }\n    const rows = await rebuildEuropeanStandings(competitionId, seasonId);\n    return { schemaVersion: SCHEMA_VERSION, generatedAt: new Date().toISOString(), sourceVersion: 'european-authoritative', expectedCount: rows.length, actualCount: rows.length, data: rows as unknown as StandingsRow[] };\n  }\n  const config = DOMESTIC_LEAGUE_CONFIG[competitionId];\n  const expectedCount = config ? config.expectedCount : 20;\n  const key = ReadModelKeys.standings(competitionId, seasonId);\n  const existingLkg = await redisGetLkg<StandingsRow[]>(key);\n\n  let rows: StandingsRow[] = [];\n  let firestoreFailed = false;\n\n  try {\n    const db = getFirestoreDb();\n    if (db) {\n      const stdDoc = await db.collection(COLLECTIONS.STANDINGS).doc(competitionId).get();\n      trackFirestoreRead(COLLECTIONS.STANDINGS, stdDoc.exists ? 1 : 0, 'buildStandingsSnapshot');\n      if (stdDoc.exists) {\n        const data = stdDoc.data();\n        if (Array.isArray(data?.rows) && data.rows.length > 0) {\n          rows = data.rows as StandingsRow[];\n        }\n      }\n    }\n  } catch (err: any) {\n    firestoreFailed = true;\n    firestoreCircuitBreaker.recordFailure(err);\n    console.warn(`[READ_MODEL_STORE] Error fetching standings for ${competitionId}:`, err?.message || err);\n  }\n\n  // 1. If Firestore failed: NEVER generate zero-value standings and NEVER overwrite existing populated LKG!\n  if (firestoreFailed) {\n    if (existingLkg && Array.isArray(existingLkg.data) && existingLkg.data.length > 0) {\n      throw new ReadModelNotWarmedError('Authoritative refresh unavailable; preserve last-known-good snapshot');\n    }\n    throw new ReadModelNotWarmedError(\n      `READ_MODEL_NOT_WARMED: Firestore standings retrieval failed for ${competitionId} and no valid LKG snapshot exists.`\n    );\n  }\n\n  // 2. If standings doc in Firestore is missing or has empty rows:\n  if (rows.length === 0) {\n    // If a populated LKG already exists, NEVER overwrite it with zero-value rows!\n    if (existingLkg && Array.isArray(existingLkg.data) && existingLkg.data.length > 0) {\n      throw new ReadModelNotWarmedError('Authoritative refresh unavailable; preserve last-known-good snapshot');\n    }\n\n    // Check if confirmed fixtures exist for this competition\n    let hasConfirmedFixtures = false;\n    try {\n      const db = getFirestoreDb();\n      if (db) {\n        const competition = await db.collection(COLLECTIONS.COMPETITIONS).doc(competitionId).get();\n        if (!competition.exists || competition.data()?.seasonId !== seasonId) {\n          throw new ReadModelNotWarmedError('Cannot initialize standings without an authoritative competition for this season');\n        }\n        const fixSnap = await db\n          .collection(COLLECTIONS.FIXTURES)\n          .where('competitionId', '==', competitionId)\n          .where('status', '==', 'CONFIRMED')\n          .limit(1)\n          .get();\n        hasConfirmedFixtures = !fixSnap.empty;\n      } else {\n        throw new Error('Firestore unavailable: cannot verify empty standings');\n      }\n    } catch (error) {\n      throw error;\n    }\n\n    // Only allow zero standings for a genuinely new competition proven to have no confirmed fixtures and no existing standings\n    if (!hasConfirmedFixtures && config) {\n      rows = generateZeroValueStandings(competitionId, seasonId);\n    } else if (hasConfirmedFixtures) {\n      throw new Error(\n        `Standings for ${competitionId} cannot be zeroed: competition has confirmed fixtures recorded in Firestore.`\n      );\n    }\n  }\n\n  rows.sort((a, b) => a.position - b.position);\n\n  const snapshot: ReadModelSnapshot<StandingsRow[]> = {\n    schemaVersion: SCHEMA_VERSION,\n    generatedAt: new Date().toISOString(),\n    sourceVersion: `standings-${rows.length}`,\n    expectedCount,\n    actualCount: rows.length,\n    data: rows,\n  };\n\n  await redisSetRaw(key, snapshot, 86400);\n  return snapshot;\n}\n\n// ----------------------------------------------------\n// ROUTE-FACING READ-MODEL METHODS\n// ----------------------------------------------------\n\n/**\n * Reads competitions catalog from durable read model.\n */\nexport async function getCompetitionsFromReadModel(\n  seasonId = 'season-2026-27'\n): Promise<{ competitions: Competition[]; source: string; stale: boolean; degraded: boolean; snapshotAt: string }> {\n  const result = await readThroughReadModel<Competition[]>({\n    key: ReadModelKeys.competitions(seasonId),\n    seasonId,\n    expectedCount: 17,\n    firestoreFetcher: async () => {\n      const snap = await buildCompetitionsSnapshot(seasonId);\n      return snap.data;\n    },\n    validateData: (data) => Array.isArray(data) && data.length > 0,\n  });\n\n  return {\n    competitions: await (await import('../services/competitionFixtureCounts')).withVisibleFixtureCounts(result.data.map(c=>withSeasonQualificationPolicy(c,seasonId)), seasonId),\n    source: result.source,\n    stale: Boolean(result.stale),\n    degraded: Boolean(result.degraded),\n    snapshotAt: result.generatedAt,\n  };\n}\n\n/**\n * Reads clubs for admin route with real ownership data preserved.\n */\nexport async function getAdminClubsFromReadModel(\n  seasonId = 'season-2026-27',\n  leagueId?: string,\n  currentUserId?: string\n): Promise<{ clubs: any[]; total: number; source: string; degraded: boolean; stale: boolean; snapshotAt: string }> {\n  const result = await readThroughReadModel<OwnerNeutralClub[]>({\n    key: ReadModelKeys.clubsWithOwners(seasonId),\n    seasonId,\n    expectedCount: 96,\n    firestoreFetcher: async () => {\n      const snap = await getClubsSnapshotForRead(seasonId);\n      return snap.data;\n    },\n    validateData: (data) => Array.isArray(data) && data.length > 0,\n  });\n\n  let clubs = result.data;\n  if (leagueId && leagueId !== 'ALL') {\n    clubs = clubs.filter((c) => c.leagueId === leagueId);\n  }\n\n  const adminClubs = clubs.map((c) => {\n    const isCurrentUserClub = Boolean(currentUserId && c.ownerUserId === currentUserId);\n    return {\n      ...c,\n      seasonId,\n      isOccupied: Boolean(c.ownerUserId),\n      occupiedByUserId: c.ownerUserId,\n      occupiedByUsername: c.ownerUsername,\n      claimedByUserId: c.ownerUserId,\n      claimedByUsername: c.ownerUsername,\n      managerUserId: c.ownerUserId,\n      managerUsername: c.ownerUsername,\n      isTaken: Boolean(c.ownerUserId),\n      isCurrentUserClub,\n      occupancy: {\n        status: isCurrentUserClub ? 'owned' : c.ownerUserId ? 'occupied' : 'available',\n        userId: c.ownerUserId || undefined,\n        username: c.ownerUsername || undefined,\n      },\n    };\n  });\n\n  return {\n    clubs: adminClubs,\n    total: adminClubs.length,\n    source: result.source,\n    degraded: Boolean(result.degraded),\n    stale: Boolean(result.stale),\n    snapshotAt: result.generatedAt,\n  };\n}\n\n/**\n * Reads clubs by league with real owners and user-specific field enrichment.\n * If per-league snapshot is missing but clubs-with-owners LKG exists, derives from LKG without querying Firestore.\n */\nexport async function getLeagueClubsFromReadModel(\n  leagueId: string,\n  seasonId = 'season-2026-27',\n  currentUserId?: string\n): Promise<{ clubs: Club[]; source: string; stale: boolean; degraded: boolean; snapshotAt: string }> {\n  const result = await readThroughReadModel<OwnerNeutralClub[]>({\n    key: ReadModelKeys.clubsWithOwners(seasonId), seasonId, expectedCount: 96,\n    firestoreFetcher: async () => (await getClubsSnapshotForRead(seasonId)).data,\n    validateData: data => Array.isArray(data) && data.length > 0,\n  });\n  return {\n    clubs: result.data.filter(c => c.leagueId === leagueId).map(c => enrichClubForUser(c, currentUserId)),\n    source: result.source, stale: Boolean(result.stale), degraded: Boolean(result.degraded),\n    snapshotAt: result.generatedAt,\n  };\n}\n\n/**\n * Reads available clubs. Claimed clubs NEVER become available even when Firestore fails!\n */\nexport async function getAvailableClubsFromReadModel(\n  seasonId = 'season-2026-27',\n  currentUserId?: string\n): Promise<{ clubs: Club[]; source: string; stale: boolean; degraded: boolean; snapshotAt: string }> {\n  const result = await readThroughReadModel<OwnerNeutralClub[]>({\n    key: ReadModelKeys.clubsWithOwners(seasonId),\n    seasonId,\n    expectedCount: 96,\n    firestoreFetcher: async () => {\n      const snap = await getClubsSnapshotForRead(seasonId);\n      return snap.data;\n    },\n    validateData: (data) => Array.isArray(data) && data.length > 0,\n  });\n\n  // Filter out occupied/claimed clubs; claimed clubs NEVER become available!\n  const availableClubs = result.data\n    .filter((c) => !c.ownerUserId && !c.isOccupied && !c.isTaken)\n    .map((c) => enrichClubForUser(c, currentUserId));\n\n  return {\n    clubs: availableClubs,\n    source: result.source,\n    stale: Boolean(result.stale),\n    degraded: Boolean(result.degraded),\n    snapshotAt: result.generatedAt,\n  };\n}\n\n/**\n * Reads a single club by ID.\n */\nexport async function getClubByIdFromReadModel(\n  clubId: string,\n  seasonId = 'season-2026-27',\n  currentUserId?: string\n): Promise<{ club: Club | null; source: string; stale: boolean; degraded: boolean }> {\n  const result = await readThroughReadModel<OwnerNeutralClub[]>({\n    key: ReadModelKeys.clubsWithOwners(seasonId),\n    seasonId,\n    expectedCount: 96,\n    firestoreFetcher: async () => {\n      const snap = await getClubsSnapshotForRead(seasonId);\n      return snap.data;\n    },\n    validateData: (data) => Array.isArray(data) && data.length > 0,\n  });\n\n  const neutral = result.data.find((c) => c.id === clubId);\n  if (!neutral) {\n    return { club: null, source: result.source, stale: Boolean(result.stale), degraded: Boolean(result.degraded) };\n  }\n\n  const club = enrichClubForUser(neutral, currentUserId);\n  return { club, source: result.source, stale: Boolean(result.stale), degraded: Boolean(result.degraded) };\n}\n\n/**\n * Reads user's active club from read model or derives from clubs-with-owners snapshot.\n * - Represents users with no club using a valid cached sentinel: { hasClub: false, clubId: null, club: null }\n * - Derives membership from clubs-with-owners LKG before querying Firestore.\n */\nexport async function getUserActiveClubFromReadModel(\n  userId: string,\n  seasonId = 'season-2026-27'\n): Promise<Club | null> {\n  // Derive identity from the same versioned ownership snapshot used by club lists.\n  // Never promote an old negative membership sentinel to a new authoritative answer.\n  const result = await readThroughReadModel<OwnerNeutralClub[]>({\n    key: ReadModelKeys.clubsWithOwners(seasonId),\n    seasonId,\n    expectedCount: 96,\n    firestoreFetcher: async () => (await getClubsSnapshotForRead(seasonId)).data,\n    validateData: data => Array.isArray(data) && data.length > 0,\n  });\n  const owner = result.data.find(c => (c.ownerUserId || c.claimedByUserId) === userId);\n  return owner ? enrichClubForUser(owner, userId) : null;\n}\n\nexport async function getUserActiveClubsFromReadModel(userId: string, seasonId = 'season-2026-27'): Promise<Club[]> {\n  const ownership = await getAdminClubsFromReadModel(seasonId);\n  return ownership.clubs.filter((club) => club.ownerUserId === userId).map((club) => enrichClubForUser(club, userId));\n}\n\n/** Membership is optional profile data; its outage must not invalidate verified identity. */\nexport async function getOptionalCurrentClub(userId: string, seasonId = 'season-2026-27') {\n  try {\n    const ownedClubs = await getUserActiveClubsFromReadModel(userId, seasonId);\n    const currentClub = ownedClubs[0] || null;\n    return { currentClub, ownedClubs, currentClubStatus: 'resolved' as const, degraded: false };\n  } catch (error) {\n    if (!(error instanceof ReadModelNotWarmedError)) throw error;\n    return { currentClub: null, ownedClubs: [], currentClubStatus: 'unavailable' as const, degraded: true };\n  }\n}\n\n/**\n * Reads competition standings using Tiered Read-Through:\n * memory \u2192 fresh Redis \u2192 Firestore refresh \u2192 stale Redis last-known-good\n * Returns: { standings, source, stale, degraded, snapshotAt }\n */\nexport async function getCompetitionStandingsFromReadModel(\n  competitionId: string,\n  seasonId = 'season-2026-27'\n): Promise<{\n  standings: StandingsRow[];\n  source: string;\n  stale: boolean;\n  degraded: boolean;\n  snapshotAt: string;\n}> {\n  const config = DOMESTIC_LEAGUE_CONFIG[competitionId];\n  const expectedCount = config ? config.expectedCount : 20;\n\n  const result = await readThroughReadModel<StandingsRow[]>({\n    key: ReadModelKeys.standings(competitionId, seasonId),\n    seasonId,\n    expectedCount,\n    firestoreFetcher: async () => {\n      const snap = await buildStandingsSnapshot(competitionId, seasonId);\n      return snap.data;\n    },\n    validateData: (rows) => Array.isArray(rows) && rows.length > 0,\n  });\n\n  let clubsResult: any = null;\n  try {\n    clubsResult = await readThroughReadModel<OwnerNeutralClub[]>({\n      key: ReadModelKeys.clubsWithOwners(seasonId),\n      seasonId,\n      expectedCount: 96,\n      firestoreFetcher: async () => (await getClubsSnapshotForRead(seasonId)).data,\n      validateData: (data) => Array.isArray(data) && data.length > 0,\n    });\n  } catch {}\n\n  const ownersByClub = new Map<string, OwnerNeutralClub>(\n    clubsResult?.data ? clubsResult.data.map((club: OwnerNeutralClub) => [club.id, club]) : []\n  );\n\n  // Fallback to SQLite membership/user data if needed\n  try {\n    const { queryAll } = await import('../db/index');\n    const localRows = queryAll<any>(\n      `SELECT cm.club_id, cm.user_id, u.username, u.first_name, u.last_name\n       FROM club_memberships cm\n       LEFT JOIN users u ON cm.user_id = u.id\n       WHERE cm.season_id = ? AND cm.status = 'active'`,\n      [seasonId]\n    );\n    for (const r of localRows) {\n      if (r.club_id && !ownersByClub.has(r.club_id)) {\n        const cleanUname = r.username ? r.username.replace(/^@+/, '').trim() : null;\n        const isSynth = cleanUname?.startsWith('tg_') || cleanUname?.startsWith('user_');\n        const validUname = isSynth ? null : cleanUname;\n        const fname = r.first_name || null;\n        const lname = r.last_name || null;\n        const dname = [fname, lname].filter(Boolean).join(' ') || fname || (validUname ? `@${validUname}` : `User #${r.user_id}`);\n        ownersByClub.set(r.club_id, {\n          id: r.club_id,\n          ownerUserId: r.user_id,\n          ownerUsername: validUname,\n          ownerFirstName: fname,\n          ownerLastName: lname,\n          ownerDisplayName: dname,\n          managerUserId: r.user_id,\n          managerUsername: validUname,\n          managerFirstName: fname,\n          managerLastName: lname,\n          managerDisplayName: dname,\n        } as any);\n      }\n    }\n  } catch {}\n\n  const enrichedStandings: StandingsRow[] = (result.data || []).map((row) => {\n    const owner = ownersByClub.get(row.clubId);\n    if (!owner || !owner.ownerUserId) {\n      return {\n        ...row,\n        managerUserId: undefined,\n        managerUsername: undefined,\n        managerFirstName: undefined,\n        managerLastName: undefined,\n        managerDisplayName: undefined,\n      };\n    }\n\n    const cleanUname = owner.ownerUsername ? owner.ownerUsername.replace(/^@+/, '').trim() : null;\n    const isSynth = cleanUname?.startsWith('tg_') || cleanUname?.startsWith('user_');\n    const validUname = isSynth ? null : cleanUname;\n    const fname = owner.ownerFirstName || (owner as any).firstName || undefined;\n    const lname = owner.ownerLastName || (owner as any).lastName || undefined;\n    const dname = owner.ownerDisplayName || (owner as any).displayName || [fname, lname].filter(Boolean).join(' ') || fname || (validUname ? `@${validUname}` : undefined);\n\n    return {\n      ...row,\n      managerUserId: owner.ownerUserId || undefined,\n      managerUsername: validUname || undefined,\n      managerFirstName: fname,\n      managerLastName: lname,\n      managerDisplayName: dname,\n    };\n  });\n\n  return {\n    standings: enrichedStandings,\n    source: result.source,\n    stale: Boolean(result.stale),\n    degraded: Boolean(result.degraded),\n    snapshotAt: result.generatedAt,\n  };\n}\n\n/**\n * Reads competition fixtures from read model.\n * If competition fixtures snapshot is missing but admin-fixtures LKG exists, derives from admin-fixtures without querying Firestore.\n */\nexport async function getCompetitionFixturesFromReadModel(\n  competitionId: string,\n  optionsOrMatchday: number | { matchday?: number; status?: string; seasonId?: string; allowFirestore?: boolean } = {},\n  fallbackSeasonId = 'season-2026-27'\n): Promise<{ fixtures: Fixture[]; source: string; stale: boolean; degraded: boolean; snapshotAt: string }> {\n  const options = typeof optionsOrMatchday === 'number'\n    ? { matchday: optionsOrMatchday, seasonId: fallbackSeasonId }\n    : optionsOrMatchday || {};\n  const seasonId = options.seasonId || fallbackSeasonId;\n  // Explicit one-time owner-approved recovery; durable checkpoint prevents recurrence.\n  const { runApprovedFixtureRestoration } = await import('../services/approvedFixtureRestoration');\n  await runApprovedFixtureRestoration(competitionId, seasonId);\n  let rawFixtures: Fixture[] = [];\n  let source = 'memory';\n  let stale = false;\n  let degraded = false;\n  let generatedAt = new Date().toISOString();\n\n  // 1. Tier-1 memory & 2. Redis fresh\n  const compKey = ReadModelKeys.competitionFixtures(competitionId, seasonId);\n  const adminKey = ReadModelKeys.adminFixtures(seasonId);\n\n  let redisFresh = await redisGetFresh<Fixture[]>(compKey);\n  if (!redisFresh) {\n    const adminFresh = await redisGetFresh<Fixture[]>(adminKey);\n    if (adminFresh && Array.isArray(adminFresh.data)) {\n      redisFresh = {\n        ...adminFresh,\n        data: adminFresh.data.filter((f) => f.competitionId === competitionId),\n      };\n    }\n  }\n\n  if (redisFresh && Array.isArray(redisFresh.data) && redisFresh.data.length > 0) {\n    rawFixtures = redisFresh.data;\n    source = redisFresh.source;\n    stale = Boolean(redisFresh.stale);\n    degraded = Boolean(redisFresh.degraded);\n    generatedAt = redisFresh.generatedAt;\n  }\n\n  // 3. Redis LKG\n  if (rawFixtures.length === 0) {\n    let redisLkg = await redisGetLkg<Fixture[]>(compKey);\n    if (!redisLkg) {\n      const adminLkg = await redisGetLkg<Fixture[]>(adminKey);\n      if (adminLkg && Array.isArray(adminLkg.data)) {\n        redisLkg = {\n          ...adminLkg,\n          data: adminLkg.data.filter((f) => f.competitionId === competitionId),\n        };\n      }\n    }\n    if (redisLkg && Array.isArray(redisLkg.data) && redisLkg.data.length > 0) {\n      rawFixtures = redisLkg.data;\n      source = redisLkg.source;\n      stale = true;\n      degraded = true;\n      generatedAt = redisLkg.generatedAt;\n    }\n  }\n\n  // 4. SQLite local read model\n  if (rawFixtures.length === 0) {\n    try {\n      const conditions: string[] = ['competition_id = ?'];\n      const params: any[] = [competitionId];\n      if (seasonId) {\n        conditions.push('(season_id = ? OR season_id IS NULL)');\n        params.push(seasonId);\n      }\n      if (options.matchday !== undefined && !hasFixtureMatchdayCorrection(competitionId, seasonId)) {\n        conditions.push('matchday = ?');\n        params.push(options.matchday);\n      }\n      if (options.status && options.status !== 'ALL') {\n        conditions.push('status = ?');\n        params.push(options.status);\n      }\n      const sqliteRows = queryAll<any>(\n        `SELECT * FROM fixtures WHERE ${conditions.join(' AND ')} ORDER BY matchday ASC, scheduled_at ASC, id ASC`,\n        params\n      );\n      if (sqliteRows && sqliteRows.length > 0) {\n        rawFixtures = sqliteRows.map((r) => normalizeFixtureSnapshot(r, seasonId));\n        source = 'sqlite';\n        stale = true;\n        degraded = true;\n      }\n    } catch {}\n  }\n\n  // 5. Bounded Firestore query as last online fallback (NEVER a full-season scan!)\n  if (rawFixtures.length === 0) {\n    const db = getFirestoreDb();\n    if (options.allowFirestore !== false && db && firestoreCircuitBreaker.canExecute()) {\n      try {\n        let query: FirebaseFirestore.Query = db.collection(COLLECTIONS.FIXTURES)\n          .where('seasonId', '==', seasonId)\n          .where('competitionId', '==', competitionId);\n        if (options.matchday !== undefined && !hasFixtureMatchdayCorrection(competitionId, seasonId)) {\n          query = query.where('matchday', '==', options.matchday);\n        }\n        if (options.status && options.status !== 'ALL') {\n          query = query.where('status', '==', options.status);\n        }\n        const snap = await query.get();\n        trackFirestoreRead(COLLECTIONS.FIXTURES, Math.max(1, snap.docs.length), 'getCompetitionFixturesBoundedFirestore');\n        rawFixtures = snap.docs.map((d) => normalizeFixtureSnapshot({ id: d.id, ...d.data() }, seasonId));\n        source = 'firestore_bounded';\n        stale = false;\n        degraded = false;\n      } catch (err: any) {\n        firestoreCircuitBreaker.recordFailure(err);\n      }\n    }\n  }\n\n  let fixtures = filterRetiredFixtures(rawFixtures, seasonId);\n  if (options.matchday !== undefined) {\n    fixtures = fixtures.filter((fixture) => Number(fixture.matchday) === Number(options.matchday));\n  }\n  if (options.status && options.status !== 'ALL') {\n    fixtures = fixtures.filter((fixture) => fixture.status === options.status);\n  }\n  if (['comp-champions-league-2026', 'comp-europa-league-2026'].includes(competitionId)) {\n    const leaguePhaseFixtures = fixtures.filter((fixture) => Number(fixture.matchday) >= 1 && Number(fixture.matchday) <= 8);\n    if (leaguePhaseFixtures.length > 0 && leaguePhaseFixtures.some((fixture) => fixture.status !== 'CONFIRMED')) {\n      fixtures = leaguePhaseFixtures;\n    }\n  }\n\n  let clubsResult: any = null;\n  try {\n    clubsResult = await readThroughReadModel<OwnerNeutralClub[]>({\n      key: ReadModelKeys.clubsWithOwners(seasonId),\n      seasonId,\n      expectedCount: 96,\n      firestoreFetcher: async () => (await getClubsSnapshotForRead(seasonId)).data,\n      validateData: (data) => Array.isArray(data) && data.length > 0,\n    });\n  } catch {}\n\n  const ownersByClub = new Map<string, OwnerNeutralClub>(\n    clubsResult?.data ? clubsResult.data.map((club: OwnerNeutralClub) => [club.id, club]) : []\n  );\n  fixtures = fixtures.map((fixture) => {\n    const homeOwner = fixture.homeClubId ? ownersByClub.get(fixture.homeClubId) : undefined;\n    const awayOwner = fixture.awayClubId ? ownersByClub.get(fixture.awayClubId) : undefined;\n    const enrichFixtureClub = (club: Fixture['homeClub'], owner?: OwnerNeutralClub) => club ? ({\n      ...club,\n      claimedByUserId: owner?.ownerUserId || null,\n      claimedByUsername: owner?.ownerUsername || null,\n      managerUsername: owner?.ownerUsername || undefined,\n      isTaken: Boolean(owner?.ownerUserId),\n      occupancy: {\n        status: owner?.ownerUserId ? 'occupied' as const : 'available' as const,\n        userId: owner?.ownerUserId || undefined,\n        username: owner?.ownerUsername || undefined,\n      },\n    }) : club;\n    const toFixtureUser = (owner?: OwnerNeutralClub) => owner?.ownerUserId ? ({\n      id: owner.ownerUserId,\n      username: owner.ownerUsername || '',\n      displayName: owner.ownerUsername ? `@${owner.ownerUsername}` : `User #${owner.ownerUserId}`,\n    }) : null;\n    return {\n      ...fixture,\n      homeClub: enrichFixtureClub(fixture.homeClub, homeOwner),\n      awayClub: enrichFixtureClub(fixture.awayClub, awayOwner),\n      homeOwnerId: homeOwner?.ownerUserId || undefined,\n      awayOwnerId: awayOwner?.ownerUserId || undefined,\n      homeUser: toFixtureUser(homeOwner),\n      awayUser: toFixtureUser(awayOwner),\n    };\n  });\n  if (options.matchday !== undefined) fixtures = fixtures.filter(f => Number(f.matchday) === Number(options.matchday));\n  if (options.status && options.status !== 'ALL') fixtures = fixtures.filter(f => f.status === options.status);\n  try {\n    const { enrichFixturesWithAuthoritativeOwners } = await import('../firebase/firestoreStore');\n    fixtures = await enrichFixturesWithAuthoritativeOwners(fixtures, seasonId);\n  } catch (err) {\n    console.warn('[COMPETITION_FIXTURES] Ownership enrichment fallback:', err);\n  }\n  return {\n    fixtures: fixtures.sort((a,b) => compareAdminFixtures(a,b,true)),\n    source,\n    stale: Boolean(stale || clubsResult?.stale),\n    degraded: Boolean(degraded || clubsResult?.degraded),\n    snapshotAt: generatedAt,\n  };\n}\n\n/**\n * Paginated admin fixtures query via read model.\n */\nexport interface AdminFixturesReadModelOptions {\n  seasonId?: string;\n  competitionId?: string;\n  status?: string;\n  matchday?: number;\n  clubId?: string;\n  userId?: string;\n  search?: string;\n  cursor?: string;\n  limit?: number;\n}\n\nexport interface AdminFixturesReadModelResult {\n  fixtures: Fixture[];\n  total: number;\n  hasMore: boolean;\n  nextCursor?: string;\n  limit: number;\n  source: string;\n  degraded: boolean;\n  stale: boolean;\n  generatedAt: string;\n}\n\nexport async function getAdminFixturesFromReadModel(\n  options: AdminFixturesReadModelOptions = {}\n): Promise<AdminFixturesReadModelResult> {\n  const seasonId = options.seasonId || 'season-2026-27';\n  const limit = Math.min(Math.max(options.limit || 25, 1), 100);\n\n  // 1. Check Redis fresh or LKG snapshot first\n  const redisFresh = await redisGetFresh<Fixture[]>(ReadModelKeys.adminFixtures(seasonId));\n  const redisLkg = !redisFresh ? await redisGetLkg<Fixture[]>(ReadModelKeys.adminFixtures(seasonId)) : null;\n  const snapshotRes = redisFresh || redisLkg;\n\n  if (!snapshotRes || !Array.isArray(snapshotRes.data) || snapshotRes.data.length === 0) {\n    // 2. Redis miss: Fallback to SQLite local read model BEFORE scanning Firestore!\n    try {\n      const { executeAdminFixturesPagedFallback } = await import('../firebase/firestoreStore');\n      const fallbackRes = executeAdminFixturesPagedFallback(options, limit);\n      if (fallbackRes.total > 0 || !firestoreCircuitBreaker.canExecute()) {\n        return {\n          fixtures: fallbackRes.fixtures,\n          total: fallbackRes.total,\n          hasMore: fallbackRes.hasMore,\n          nextCursor: fallbackRes.nextCursor,\n          limit: fallbackRes.limit,\n          source: 'sqlite',\n          degraded: true,\n          stale: true,\n          generatedAt: fallbackRes.generatedAt,\n        };\n      }\n    } catch {}\n  }\n\n  if (!snapshotRes || !Array.isArray(snapshotRes.data) || snapshotRes.data.length === 0) {\n    const hosted = Boolean(process.env.VERCEL || process.env.K_SERVICE || process.env.AWS_LAMBDA_FUNCTION_NAME || process.env.NODE_ENV === 'production');\n    if (hosted) {\n      console.warn('[FIRESTORE_BROAD_READ_BLOCKED]', JSON.stringify({ dataset: 'adminFixtures', seasonId }));\n      throw new ReadModelNotWarmedError(\n        'Admin fixture read model is not warmed. Automatic full-season Firestore scans are disabled in hosted production.'\n      );\n    }\n  }\n\n  let effectiveSnapshotRes = snapshotRes || (await readThroughReadModel<Fixture[]>({\n    key: ReadModelKeys.adminFixtures(seasonId),\n    seasonId,\n    firestoreFetcher: async () => {\n      const snap = await buildAdminFixturesSnapshot(seasonId);\n      return snap.data;\n    },\n    validateData: (fixtures) => Array.isArray(fixtures) && fixtures.length > 0,\n  }));\n\n  // A cup's authoritative refresh may already be newer than an old admin LKG\n  // (for example after a redraw performed before this fix was deployed).\n  // Repair that one slice from Redis without scanning the whole Firestore season.\n  if (await redisIsDirty(ReadModelKeys.adminFixtures(seasonId))) {\n    const cupIds = [\n      'comp-fa-cup-2026', 'comp-copa-del-rey-2026', 'comp-coppa-italia-2026',\n      'comp-dfb-pokal-2026', 'comp-coupe-de-france-2026',\n    ];\n    const candidateIds = options.competitionId ? [options.competitionId] : cupIds;\n    const snapshots = await Promise.all(candidateIds.map(async (cupId) => ({\n      cupId,\n      snapshot: await redisGetFresh<Fixture[]>(ReadModelKeys.competitionFixtures(cupId, seasonId)),\n    })));\n    let merged = effectiveSnapshotRes.data;\n    for (const { cupId, snapshot } of snapshots) {\n      if (!snapshot || !Array.isArray(snapshot.data)) continue;\n      merged = merged.filter((fixture) => fixture.competitionId !== cupId).concat(snapshot.data);\n    }\n    effectiveSnapshotRes = { ...effectiveSnapshotRes, data: merged };\n  }\n\n  let allFixtures = filterRetiredFixtures(effectiveSnapshotRes.data, seasonId).sort((a,b) => compareAdminFixtures(a,b));\n\n  if (options.competitionId && options.competitionId !== 'ALL') {\n    allFixtures = allFixtures.filter((f) => f.competitionId === options.competitionId);\n  }\n  if (options.status && options.status !== 'ALL') {\n    allFixtures = allFixtures.filter((f) => f.status === options.status);\n  }\n  if (options.matchday !== undefined) {\n    allFixtures = allFixtures.filter((f) => f.matchday === options.matchday);\n  }\n  if (options.clubId) {\n    allFixtures = allFixtures.filter((f) => f.homeClubId === options.clubId || f.awayClubId === options.clubId);\n  }\n  if (options.search) {\n    const q = options.search.toLowerCase();\n    allFixtures = allFixtures.filter(\n      (f) =>\n        f.homeClub?.name.toLowerCase().includes(q) ||\n        f.awayClub?.name.toLowerCase().includes(q) ||\n        f.roundName?.toLowerCase().includes(q) ||\n        f.id.toLowerCase().includes(q)\n    );\n  }\n\n  const total = allFixtures.length;\n\n  let startIndex = 0;\n  if (options.cursor) {\n    const tuple = decodeFixtureCursor(options.cursor);\n    if (tuple) {\n      const foundIdx = allFixtures.findIndex(f => {\n        const order = CANONICAL_COMPETITION_ORDER[f.competitionId] ?? 999;\n        if (order !== tuple.competitionOrder) return order > tuple.competitionOrder;\n        const matchday = Number(f.matchday) || 0;\n        if (matchday !== tuple.matchday) return matchday > tuple.matchday;\n        const time = Date.parse(f.scheduledAt) || 0, previous = Date.parse(tuple.scheduledAt) || 0;\n        return time !== previous ? time > previous : f.id.localeCompare(tuple.id) > 0;\n      });\n      startIndex = foundIdx < 0 ? allFixtures.length : foundIdx;\n    } else {\n      const rawIdx = allFixtures.findIndex((f) => f.id === options.cursor);\n      if (rawIdx >= 0) {\n        startIndex = rawIdx + 1;\n      } else throw Object.assign(new Error('INVALID_FIXTURE_CURSOR'), { statusCode: 400 });\n    }\n  }\n\n  const pagedFixtures = allFixtures.slice(startIndex, startIndex + limit);\n  const hasMore = startIndex + limit < allFixtures.length;\n  const nextCursor =\n    hasMore && pagedFixtures.length > 0\n      ? encodeFixtureCursor(pagedFixtures[pagedFixtures.length - 1])\n      : undefined;\n\n  let enrichedPagedFixtures = pagedFixtures;\n  try {\n    const { enrichFixturesWithAuthoritativeOwners } = await import('../firebase/firestoreStore');\n    enrichedPagedFixtures = await enrichFixturesWithAuthoritativeOwners(pagedFixtures, seasonId);\n  } catch {}\n\n  return {\n    fixtures: enrichedPagedFixtures,\n    total,\n    hasMore,\n    nextCursor,\n    limit,\n    source: effectiveSnapshotRes.source,\n    degraded: effectiveSnapshotRes.source === 'redis_stale',\n    stale: effectiveSnapshotRes.source === 'redis_stale',\n    generatedAt: effectiveSnapshotRes.generatedAt,\n  };\n}\n\n// ----------------------------------------------------\n// NON-DESTRUCTIVE INVALIDATION HOOKS\n// ----------------------------------------------------\n\nexport async function invalidateClubReadModels(seasonId = 'season-2026-27'): Promise<void> {\n  await invalidateDataset(ReadModelKeys.clubsWithOwners(seasonId));\n  for (const l of SEED_LEAGUES) {\n    await invalidateDataset(ReadModelKeys.leagueClubs(l.id, seasonId));\n  }\n  await invalidateDataset(ReadModelKeys.adminFixtures(seasonId));\n}\n\n/** Refresh one changed fixture with one document read instead of scanning the season. */\nexport async function refreshChangedFixtureReadModel(fixtureId: string): Promise<void> {\n  const document = await getFirestoreDb().collection(COLLECTIONS.FIXTURES).doc(fixtureId).get();\n  trackFirestoreRead(COLLECTIONS.FIXTURES, document.exists ? 1 : 0, 'refreshChangedFixtureReadModel');\n  if (!document.exists) throw new Error('FIXTURE_NOT_FOUND');\n  const fixture = normalizeFixtureSnapshot({ ...document.data(), id: document.id } as FirestoreFixtureDoc);\n\n  const patchDataset = async (key: string): Promise<boolean> => {\n    const client = getUpstashClient();\n    if (client) {\n      const result = await client.eval(`\n        local raw = redis.call('GET', KEYS[2])\n        if not raw then raw = redis.call('GET', KEYS[1]) end\n        if not raw then return 0 end\n        local snapshot = cjson.decode(raw)\n        local changed = cjson.decode(ARGV[1])\n        local found = false\n        for i, row in ipairs(snapshot.data or {}) do\n          if row.id == changed.id then\n            if row.updatedAt and changed.updatedAt and row.updatedAt > changed.updatedAt then return 1 end\n            snapshot.data[i] = changed\n            found = true\n            break\n          end\n        end\n        if not found then return 0 end\n        snapshot.generatedAt = ARGV[2]\n        snapshot.sourceVersion = ARGV[3]\n        snapshot.actualCount = #(snapshot.data or {})\n        local updated = cjson.encode(snapshot)\n        redis.call('SET', KEYS[2], updated)\n        local ttl = redis.call('TTL', KEYS[1])\n        if ttl and ttl > 0 then redis.call('SET', KEYS[1], updated, 'EX', ttl)\n        else redis.call('SET', KEYS[1], updated, 'EX', 86400) end\n        redis.call('DEL', KEYS[3])\n        return 1\n      `, [getFreshKey(key), getLkgKey(key), getDirtyKey(key)], [JSON.stringify(fixture), new Date().toISOString(), `fixture-patch-${fixture.id}-${fixture.updatedAt || Date.now()}`]);\n      inProcessMemoryCache.delete(getRawDatasetKey(key));\n      inProcessMemoryCache.delete(key);\n      memoryRedisStorage.delete(getFreshKey(key));\n      memoryRedisStorage.delete(getLkgKey(key));\n      return Number(result) === 1;\n    }\n    const existing = (await redisGetFresh<Fixture[]>(key)) || (await redisGetLkg<Fixture[]>(key));\n    if (!existing || !Array.isArray(existing.data)) return false;\n    let found = false;\n    const data = existing.data.map((row) => row.id === fixture.id ? (found = true, fixture) : row);\n    if (!found) return false;\n    await redisSetRaw(key, { ...existing, generatedAt: new Date().toISOString(), sourceVersion: `fixture-patch-${fixture.id}-${fixture.updatedAt || Date.now()}`, data }, 86400);\n    inProcessMemoryCache.delete(getRawDatasetKey(key));\n    inProcessMemoryCache.delete(key);\n    return true;\n  };\n\n  const adminKey = ReadModelKeys.adminFixtures(fixture.seasonId);\n  const competitionKey = ReadModelKeys.competitionFixtures(fixture.competitionId, fixture.seasonId);\n  const [adminPatched, competitionPatched] = await Promise.all([patchDataset(adminKey), patchDataset(competitionKey)]);\n  if (!adminPatched) await invalidateDataset(adminKey);\n  if (!competitionPatched) await invalidateDataset(competitionKey);\n  await invalidateDataset(ReadModelKeys.standings(fixture.competitionId, fixture.seasonId));\n  // Await the trophy snapshot while the serverless invocation is alive. A trophy\n  // failure must not undo a successfully persisted match result.\n  const { syncCompetitionTrophy } = await import('../services/playerTrophyService');\n  await syncCompetitionTrophy(fixture.competitionId, fixture.seasonId, fixture).catch((error: unknown) => {\n    console.warn('[PLAYER_TROPHY_SYNC_FAILED]', fixture.id, error instanceof Error ? error.message : String(error));\n  });\n}\n\nexport async function invalidateFixtureReadModels(\n  competitionId: string,\n  seasonId = 'season-2026-27'\n): Promise<void> {\n  await invalidateDataset(ReadModelKeys.adminFixtures(seasonId));\n  if (competitionId) {\n    await invalidateDataset(ReadModelKeys.competitionFixtures(competitionId, seasonId));\n    await invalidateDataset(ReadModelKeys.standings(competitionId, seasonId));\n  }\n}\n\n/** Replace one cup in the admin snapshot after an authoritative redraw. */\nexport async function replaceCupFixturesInAdminSnapshot(\n  competitionId: string,\n  seasonId: string,\n  cupFixtures: Fixture[]\n): Promise<void> {\n  const key = ReadModelKeys.adminFixtures(seasonId);\n  const previous = await redisGetFresh<Fixture[]>(key) || await redisGetLkg<Fixture[]>(key);\n  if (!previous || !Array.isArray(previous.data)) {\n    await invalidateDataset(key);\n    return;\n  }\n  const fixtures = previous.data.filter((fixture) => fixture.competitionId !== competitionId)\n    .concat(cupFixtures)\n    .sort((a, b) => compareAdminFixtures(a, b));\n  await redisSetRaw(key, {\n    schemaVersion: SCHEMA_VERSION,\n    generatedAt: new Date().toISOString(),\n    sourceVersion: `cup-redraw:${competitionId}`,\n    expectedCount: fixtures.length,\n    data: fixtures,\n  });\n}\n\nexport async function invalidateStandingsReadModels(\n  competitionId: string,\n  seasonId = 'season-2026-27'\n): Promise<void> {\n  await invalidateDataset(ReadModelKeys.standings(competitionId, seasonId));\n}\n\nexport async function invalidateCompetitionReadModels(seasonId = 'season-2026-27'): Promise<void> {\n  await invalidateDataset(ReadModelKeys.competitions(seasonId));\n}\n\nexport async function invalidateUserMembershipReadModel(\n  userId: string,\n  seasonId = 'season-2026-27'\n): Promise<void> {\n  await invalidateDataset(ReadModelKeys.userMembership(userId, seasonId));\n}\n\n// ----------------------------------------------------\n// COMPLETE READ MODEL REBUILD (ADMIN ACTION)\n// ----------------------------------------------------\n\nexport interface RebuildResult {\n  success: boolean;\n  generatedAt: string;\n  warmedLkgKeys: string[];\n  warmedKeys?: string[];\n  counts: {\n    competitions: number;\n    clubs: number;\n    fixtures: number;\n    standings: number;\n    userMemberships?: number;\n    standingsPerLeague?: Record<string, number>;\n  };\n  errors?: string[];\n}\n\n/**\n * Rebuilds all core read models into Redis (both fresh and LKG).\n * Admin-triggered action; never run automatically on production startup.\n */\nexport async function rebuildAllReadModels(seasonId = 'season-2026-27'): Promise<RebuildResult> {\n  const client = getUpstashClient();\n  const hosted = Boolean(process.env.VERCEL || process.env.K_SERVICE || process.env.AWS_LAMBDA_FUNCTION_NAME || process.env.NODE_ENV === 'production');\n  if (hosted && !client) throw new Error('REDIS_NOT_CONFIGURED: Production uchun Redis URL va token juftligini tekshiring.');\n  if (client && await client.ping() !== 'PONG') throw new Error('REDIS_UNAVAILABLE');\n  if (!firestoreCircuitBreaker.canExecute()) throw new Error('FIRESTORE_COOLDOWN: Baza cheklovi faol. Keyinroq qayta urinib ko\u2018ring.');\n  const assertReadable = () => {\n    if (firestoreCircuitBreaker.getStatus().state === 'OPEN') throw new Error('FIRESTORE_COOLDOWN');\n  };\n\n  const warmedLkgKeys: string[] = [];\n  const errors: string[] = [];\n  const standingsPerLeague: Record<string, number> = {};\n\n  // 1. Competitions catalog\n  let compCount = 0;\n  try {\n    assertReadable();\n    const compSnap = await buildCompetitionsSnapshot(seasonId);\n    compCount = compSnap.data.length;\n    warmedLkgKeys.push(getLkgKey(ReadModelKeys.competitions(seasonId)));\n  } catch (err: any) {\n    firestoreCircuitBreaker.recordFailure(err);\n    errors.push(`Competitions rebuild error: ${err.message}`);\n  }\n\n  // 2. Clubs & occupancies (owner-neutral, all 96 clubs)\n  let clubCount = 0;\n  let rebuiltClubs: OwnerNeutralClub[] = [];\n  try {\n    assertReadable();\n    const clubSnap = await buildClubsSnapshot(seasonId);\n    rebuiltClubs = clubSnap.data;\n    clubCount = clubSnap.data.length;\n    warmedLkgKeys.push(getLkgKey(ReadModelKeys.clubsWithOwners(seasonId)));\n    for (const l of SEED_LEAGUES) {\n      warmedLkgKeys.push(getLkgKey(ReadModelKeys.leagueClubs(l.id, seasonId)));\n    }\n  } catch (err: any) {\n    firestoreCircuitBreaker.recordFailure(err);\n    errors.push(`Clubs rebuild error: ${err.message}`);\n  }\n\n  // 3. Admin & competition fixtures (sorted by canonical tuple)\n  let fixtureCount = 0;\n  try {\n    assertReadable();\n    const fixSnap = await buildAdminFixturesSnapshot(seasonId);\n    fixtureCount = fixSnap.data.length;\n    warmedLkgKeys.push(getLkgKey(ReadModelKeys.adminFixtures(seasonId)));\n    const uniqueCompIds = Array.from(new Set(fixSnap.data.map((f) => f.competitionId)));\n    for (const cId of uniqueCompIds) {\n      warmedLkgKeys.push(getLkgKey(ReadModelKeys.competitionFixtures(cId, seasonId)));\n    }\n  } catch (err: any) {\n    firestoreCircuitBreaker.recordFailure(err);\n    errors.push(`Fixtures rebuild error: ${err.message}`);\n  }\n\n  // 4. Standings for the 5 domestic leagues\n  let standingsCount = 0;\n  for (const cId of Object.keys(DOMESTIC_LEAGUE_CONFIG)) {\n    try {\n      assertReadable();\n      const stdSnap = await buildStandingsSnapshot(cId, seasonId);\n      standingsCount += stdSnap.data.length;\n      standingsPerLeague[DOMESTIC_LEAGUE_CONFIG[cId].name] = stdSnap.data.length;\n      warmedLkgKeys.push(getLkgKey(ReadModelKeys.standings(cId, seasonId)));\n    } catch (err: any) {\n    firestoreCircuitBreaker.recordFailure(err);\n      errors.push(`Standings rebuild error for ${cId}: ${err.message}`);\n    }\n  }\n\n  // 5. Active user memberships\n  let membershipCount = 0;\n  try {\n    for (const club of rebuiltClubs) {\n      if (club.ownerUserId) {\n          const occ = { userId: club.ownerUserId };\n          const membershipData: UserMembershipSentinel = {\n            hasClub: true, clubId: club.id, club: enrichClubForUser(club, club.ownerUserId),\n          };\n          const memKey = ReadModelKeys.userMembership(occ.userId, seasonId);\n          const memSnap: ReadModelSnapshot<UserMembershipSentinel> = {\n            schemaVersion: SCHEMA_VERSION,\n            generatedAt: new Date().toISOString(),\n            sourceVersion: `ownership-${club.id}`,\n            expectedCount: 1,\n            actualCount: 1,\n            data: membershipData,\n          };\n          await redisSetRaw(memKey, memSnap, 86400);\n          warmedLkgKeys.push(getLkgKey(memKey));\n          membershipCount++;\n      }\n    }\n  } catch (err: any) {\n    firestoreCircuitBreaker.recordFailure(err);\n    errors.push(`User memberships rebuild error: ${err.message}`);\n  }\n\n  if (errors.length === 0) firestoreCircuitBreaker.recordSuccess();\n  return {\n    success: errors.length === 0,\n    generatedAt: new Date().toISOString(),\n    warmedLkgKeys,\n    warmedKeys: warmedLkgKeys,\n    counts: {\n      competitions: compCount,\n      clubs: clubCount,\n      fixtures: fixtureCount,\n      standings: standingsCount,\n      userMemberships: membershipCount,\n      standingsPerLeague,\n    },\n    errors: errors.length > 0 ? errors : undefined,\n  };\n}\n\n// ----------------------------------------------------\n// READ MODEL HEALTH STATUS\n// ----------------------------------------------------\n\n/**\n * Health endpoint that reads snapshot metadata directly from Redis,\n * surviving Vercel cold starts without relying solely on process memory.\n */\nexport async function getReadModelHealthStatus(seasonId = 'season-2026-27'): Promise<ReadModelHealthInfo> {\n  const cb = firestoreCircuitBreaker.getStatus();\n\n  let redisState: 'CONNECTED' | 'IN_MEMORY_FALLBACK' | 'ERROR' = 'IN_MEMORY_FALLBACK';\n  const client = getUpstashClient();\n  if (client) {\n    try {\n      const ping = await client.ping();\n      redisState = ping === 'PONG' || ping ? 'CONNECTED' : 'ERROR';\n    } catch {\n      redisState = 'ERROR';\n    }\n  }\n\n  // Define core datasets to inspect\n  const coreDatasetDefinitions: Array<{\n    name: string;\n    rawKey: string;\n    expectedCount: number;\n  }> = [\n    { name: 'competitions', rawKey: ReadModelKeys.competitions(seasonId), expectedCount: 17 },\n    { name: 'clubs-with-owners', rawKey: ReadModelKeys.clubsWithOwners(seasonId), expectedCount: 96 },\n    { name: 'admin-fixtures', rawKey: ReadModelKeys.adminFixtures(seasonId), expectedCount: 0 },\n    ...SEED_LEAGUES.map((l) => ({\n      name: `league-${l.id}-clubs`,\n      rawKey: ReadModelKeys.leagueClubs(l.id, seasonId),\n      expectedCount: l.id.includes('bundesliga') || l.id.includes('ligue-1') ? 18 : 20,\n    })),\n    ...Object.entries(DOMESTIC_LEAGUE_CONFIG).map(([compId, conf]) => ({\n      name: `standings-${conf.name}`,\n      rawKey: ReadModelKeys.standings(compId, seasonId),\n      expectedCount: conf.expectedCount,\n    })),\n  ];\n\n  const freshKeys: string[] = [];\n  const lkgKeys: string[] = [];\n  const dirtyKeys: string[] = [];\n  const missingKeys: string[] = [];\n  const coreDatasets: Record<string, CoreDatasetHealth> = {};\n\n  let newestSnapshotTime: string | null = globalLastSnapshotAt;\n\n  for (const def of coreDatasetDefinitions) {\n    const cleanKey = getRawDatasetKey(def.rawKey);\n    const fresh = await redisGetFresh(cleanKey);\n    const lkg = await redisGetLkg(cleanKey);\n    const isDirty = await redisIsDirty(cleanKey);\n\n    const hasFresh = Boolean(fresh && fresh.data !== undefined);\n    const hasLkg = Boolean(lkg && lkg.data !== undefined);\n\n    if (hasFresh) freshKeys.push(getFreshKey(cleanKey));\n    if (hasLkg) lkgKeys.push(getLkgKey(cleanKey));\n    if (isDirty) dirtyKeys.push(getDirtyKey(cleanKey));\n    if (!hasFresh && !hasLkg) missingKeys.push(cleanKey);\n\n    // Pick newest timestamp between fresh, LKG, and existing\n    const snap = fresh || lkg;\n    if (snap?.generatedAt) {\n      if (!newestSnapshotTime || new Date(snap.generatedAt) > new Date(newestSnapshotTime)) {\n        newestSnapshotTime = snap.generatedAt;\n      }\n    }\n\n    const snapTimestamp = snap?.generatedAt || null;\n    const snapAge = snapTimestamp ? Math.floor((Date.now() - new Date(snapTimestamp).getTime()) / 1000) : null;\n    const actualCount = snap?.actualCount ?? 0;\n\n    let status: CoreDatasetHealth['status'] = 'MISSING';\n    if (hasFresh && !isDirty) {\n      status = 'FRESH';\n    } else if (isDirty) {\n      status = 'DIRTY';\n    } else if (hasLkg) {\n      status = 'LKG_STALE';\n    }\n\n    coreDatasets[def.name] = {\n      key: cleanKey,\n      expectedCount: def.expectedCount,\n      actualCount,\n      snapshotTimestamp: snapTimestamp,\n      snapshotAgeSeconds: snapAge,\n      hasFresh,\n      hasLkg,\n      isDirty,\n      status,\n    };\n  }\n\n  const now = Date.now();\n  const snapshotAgeSeconds = newestSnapshotTime\n    ? Math.floor((now - new Date(newestSnapshotTime).getTime()) / 1000)\n    : null;\n\n  return {\n    firestoreState: cb.state as any,\n    redisState,\n    circuitBreakerState: {\n      state: cb.state,\n      consecutiveFailures: cb.consecutiveFailures,\n      resourceExhaustedCount: cb.resourceExhaustedCount,\n      lastFailureTime: cb.lastFailureTime,\n      lastError: cb.lastError,\n    },\n    lastSnapshotAt: newestSnapshotTime,\n    snapshotAgeSeconds,\n    freshKeys,\n    lkgKeys,\n    dirtyKeys,\n    missingKeys,\n    'fresh keys': freshKeys,\n    'lkg keys': lkgKeys,\n    'dirty keys': dirtyKeys,\n    'missing keys': missingKeys,\n    warmedKeys: lkgKeys,\n    coreDatasets,\n  };\n}\n", "import type { Notification } from '../../types';\nimport { getUpstashClient } from '../readModel/readModelStore';\nimport { getFirestoreDb } from '../firebase/admin';\nimport { COLLECTIONS } from '../firebase/collections';\n\nexport type NotificationControl = 'visible' | 'hidden' | 'deleted';\nexport type NotificationControls = Record<string, NotificationControl>;\nconst key = 'efluz:v1:notification-visibility';\nconst local: NotificationControls = {};\nconst defaults = ['MATCH_SCHEDULED', 'RESULT_SUBMITTED', 'RESULT_CONFIRMED', 'DISPUTE_OPENED', 'DISPUTE_RESOLVED', 'CLUB_ASSIGNED', 'NEXT_ROUND_MATCH', 'QUALIFICATION_CONFIRMED', 'COMPETITION_UPDATE', 'SYSTEM'];\n\nexport async function getNotificationControls(): Promise<NotificationControls> {\n  const redis = getUpstashClient();\n  if (redis) return await redis.hgetall<NotificationControls>(key) || {};\n  if (process.env.NODE_ENV === 'production' || process.env.VERCEL || process.env.K_SERVICE) throw new Error('NOTIFICATION_CONTROLS_UNAVAILABLE');\n  return { ...local };\n}\n\nasync function save(field: string, value: NotificationControl): Promise<void> {\n  const redis = getUpstashClient();\n  if (redis) {\n    const accepted = await redis.eval(`\n      if redis.call('HGET', KEYS[1], ARGV[1]) == 'deleted' and ARGV[2] ~= 'deleted' then return 0 end\n      redis.call('HSET', KEYS[1], ARGV[1], ARGV[2])\n      return 1\n    `, [key], [field, value]);\n    if (Number(accepted) !== 1) throw new Error('NOTIFICATION_DELETED');\n    return;\n  }\n  if (process.env.NODE_ENV === 'production' || process.env.VERCEL || process.env.K_SERVICE) throw new Error('NOTIFICATION_CONTROLS_UNAVAILABLE');\n  if (local[field] === 'deleted' && value !== 'deleted') throw new Error('NOTIFICATION_DELETED');\n  local[field] = value;\n}\n\nexport function notificationVisible(notification: Notification, controls: NotificationControls): boolean {\n  const broadcastId = notification.broadcastId || (notification as any).data?.broadcastId\n    || (notification.id.startsWith('notif-') && notification.id.endsWith('-' + notification.userId)\n      ? notification.id.slice(6, -(notification.userId.length + 1)) : undefined);\n  return controls['type:' + notification.type] !== 'hidden'\n    && (!broadcastId || !['hidden', 'deleted'].includes(controls['broadcast:' + broadcastId]))\n    && !['hidden', 'deleted'].includes(controls['notification:' + notification.id])\n    && !(notification as any).hidden && !(notification as any).deleted;\n}\n\nexport async function listAdminNotificationMessages(cursor?: string) {\n  const { getBroadcastHistory } = await import('./telegramNotificationQueue');\n  const controls = await getNotificationControls();\n  const records = (await getBroadcastHistory(Number.MAX_SAFE_INTEGER))\n    .filter(record => !record.createdById?.startsWith('system:'))\n    .sort((a, b) => b.createdAt.localeCompare(a.createdAt) || b.id.localeCompare(a.id));\n  const cursorIndex = cursor ? records.findIndex(record => record.id === cursor) : -1;\n  if (cursor && cursorIndex < 0) throw new Error('INVALID_NOTIFICATION_CURSOR');\n  const page = records.slice(cursorIndex + 1, cursorIndex + 101);\n  const notifications = page.filter(record => controls['broadcast:' + record.id] !== 'deleted').map(record => ({\n    id: record.id, type: record.type, title: record.title, message: record.body, createdAt: record.createdAt,\n    recipientCount: record.metrics.totalRecipients, visibility: controls['broadcast:' + record.id] || 'visible',\n  }));\n  const types = [...new Set([...defaults, ...records.map(record => record.type), ...Object.keys(controls).filter(field => field.startsWith('type:')).map(field => field.slice(5))])].sort();\n  return { notifications, types: types.map(type => ({ type, visible: controls['type:' + type] !== 'hidden' })), limit: 100, nextCursor: page.length === 100 ? page.at(-1)!.id : null };\n}\n\nexport async function setBroadcastVisibility(id: string, visibility: NotificationControl): Promise<void> {\n  const { getBroadcastDetails } = await import('./telegramNotificationQueue');\n  const record = await getBroadcastDetails(id);\n  if (!record || record.createdById?.startsWith('system:')) throw new Error('NOTIFICATION_NOT_FOUND');\n  await save('broadcast:' + id, visibility);\n}\n\nexport async function listAdminNotifications(cursor?: string) {\n  const controls = await getNotificationControls();\n  const collection = getFirestoreDb().collection(COLLECTIONS.NOTIFICATIONS);\n  let query = collection.orderBy('createdAt', 'desc');\n  if (cursor) {\n    const previous = await collection.doc(cursor).get();\n    if (!previous.exists) throw new Error('INVALID_NOTIFICATION_CURSOR');\n    query = query.startAfter(previous);\n  }\n  const snapshot = await query.limit(100).get();\n  const notifications = snapshot.docs.map(doc => {\n    const data = doc.data();\n    return { ...data, id: doc.id, visibility: controls['notification:' + doc.id] || (data.deleted ? 'deleted' : data.hidden ? 'hidden' : 'visible') };\n  }).filter(notification => notification.visibility !== 'deleted');\n  const types = [...new Set([...defaults, ...snapshot.docs.map(doc => String(doc.data().type || 'SYSTEM')), ...Object.keys(controls).filter(key => key.startsWith('type:')).map(key => key.slice(5))])].sort();\n  return { notifications, types: types.map(type => ({ type, visible: controls['type:' + type] !== 'hidden' })), limit: 100, nextCursor: snapshot.docs.length === 100 ? snapshot.docs.at(-1)!.id : null };\n}\n\nexport async function setNotificationTypeVisibility(type: string, visible: boolean): Promise<void> {\n  await save('type:' + type, visible ? 'visible' : 'hidden');\n}\n\nexport async function setNotificationVisibility(id: string, visibility: NotificationControl, actorId: string): Promise<void> {\n  const ref = getFirestoreDb().collection(COLLECTIONS.NOTIFICATIONS).doc(id);\n  const doc = await ref.get();\n  if (!doc.exists) throw new Error('NOTIFICATION_NOT_FOUND');\n  const controls = await getNotificationControls();\n  if (doc.data()?.deleted || controls['notification:' + id] === 'deleted') throw new Error('NOTIFICATION_DELETED');\n  // Keep a durable tombstone so old Redis snapshots cannot restore a removed item.\n  await save('notification:' + id, visibility);\n  await ref.update({ hidden: visibility === 'hidden', deleted: visibility === 'deleted', moderatedAt: new Date().toISOString(), moderatedBy: actorId });\n}\n", "import type { Notification } from '../../types';\nimport { getUpstashClient } from '../readModel/readModelStore';\n\ntype ReadState = Record<string, string>;\nconst localState = new Map<string, ReadState>();\nconst stateKey = (userId: string) => `efluz:v1:user:${userId}:notification-read-state`;\n\nfunction localAllowed(): boolean {\n  return process.env.NODE_ENV !== 'production' && !process.env.VERCEL && !process.env.K_SERVICE;\n}\n\nexport async function getNotificationReadState(userId: string): Promise<ReadState> {\n  const client = getUpstashClient();\n  if (client) return await client.hgetall<ReadState>(stateKey(userId)) || {};\n  if (!localAllowed()) throw new Error('REDIS_REQUIRED_FOR_NOTIFICATION_READ_STATE');\n  return { ...localState.get(userId) };\n}\n\nexport async function persistNotificationReadState(userId: string, readAt: string, notificationId?: string): Promise<void> {\n  const field = notificationId ? `notification:${notificationId}` : 'all';\n  const client = getUpstashClient();\n  if (client) {\n    // Concurrent read acknowledgements cannot move the timestamp backwards.\n    await client.eval(`\n      local old = redis.call('HGET', KEYS[1], ARGV[1])\n      if not old or old < ARGV[2] then redis.call('HSET', KEYS[1], ARGV[1], ARGV[2]) end\n      return 1\n    `, [stateKey(userId)], [field, readAt]);\n    return;\n  }\n  if (!localAllowed()) throw new Error('REDIS_REQUIRED_FOR_NOTIFICATION_READ_STATE');\n  const state = localState.get(userId) || {};\n  if (!state[field] || state[field] < readAt) state[field] = readAt;\n  localState.set(userId, state);\n}\n\nexport function applyNotificationReadState(notifications: Notification[], state: ReadState): Notification[] {\n  return notifications.map(notification => {\n    const readAt = [state.all, state[`notification:${notification.id}`]].filter(Boolean).sort().at(-1);\n    const createdAt = Date.parse(notification.createdAt);\n    const read = readAt && Number.isFinite(createdAt) && Date.parse(readAt) >= createdAt;\n    return read && !notification.isRead ? { ...notification, isRead: true } : notification;\n  });\n}\n", "import { Fixture } from '../../types';\n\nexport function analyzeLeaguePairs(fixtures: Fixture[], clubs: Array<{ id: string; name: string }>) {\n  const names = new Map(clubs.map(club => [club.id, club.name]));\n  const pairs = new Map<string, string[]>();\n  const invalidFixtureIds: string[] = [];\n  for (const fixture of fixtures) {\n    const home = fixture.homeClubId, away = fixture.awayClubId;\n    if (!home || !away || home === away || !names.has(home) || !names.has(away)) {\n      invalidFixtureIds.push(fixture.id); continue;\n    }\n    const key = [home, away].sort().join('|');\n    pairs.set(key, [...(pairs.get(key) || []), fixture.id]);\n  }\n  const missingPairs: Array<{ homeClubId: string; awayClubId: string; homeClubName: string; awayClubName: string }> = [];\n  const ids = [...names.keys()].sort();\n  for (let i = 0; i < ids.length; i++) for (let j = i + 1; j < ids.length; j++) {\n    if (!pairs.has([ids[i], ids[j]].join('|'))) missingPairs.push({\n      homeClubId: ids[i], awayClubId: ids[j],\n      homeClubName: names.get(ids[i])!, awayClubName: names.get(ids[j])!,\n    });\n  }\n  return { missingPairs, invalidFixtureIds };\n}\n", "import { queryAll, queryGet } from '../db';\nimport { StandingsRow } from '../../types';\n\ninterface ClubRaw {\n  id: string;\n  name: string;\n  short_name: string;\n  logo_url: string;\n  manager_user_id?: string | null;\n  manager_username?: string | null;\n  manager_first_name?: string | null;\n  manager_last_name?: string | null;\n}\n\ninterface ConfirmedFixtureRaw {\n  id: string;\n  matchday: number;\n  home_club_id: string;\n  away_club_id: string;\n  home_score: number;\n  away_score: number;\n  result_confirmed_at: string;\n}\n\nexport function calculateCompetitionStandings(competitionId: string): StandingsRow[] {\n  // 1. Fetch competition details\n  const comp = queryGet<{ season_id: string; format_config_json: string }>(\n    'SELECT season_id, format_config_json FROM competitions WHERE id = ?',\n    [competitionId]\n  );\n\n  const seasonId = comp?.season_id || 'season-2026-27';\n\n  let formatConfig: any = {};\n  if (comp?.format_config_json) {\n    try {\n      formatConfig = JSON.parse(comp.format_config_json);\n    } catch {\n      formatConfig = {};\n    }\n  }\n\n  const pointsForWin = formatConfig.pointsForWin ?? 3;\n  const pointsForDraw = formatConfig.pointsForDraw ?? 1;\n  const pointsForLoss = formatConfig.pointsForLoss ?? 0;\n  const tieBreakers = formatConfig.tieBreakers ?? ['points', 'goalDifference', 'goalsFor', 'headToHead'];\n\n  // 2. Fetch all participating clubs for this competition with active owner\n  const clubs = queryAll<ClubRaw>(\n    `SELECT c.id, c.name, c.short_name, c.logo_url,\n            cm.user_id as manager_user_id,\n            u.username as manager_username,\n            u.first_name as manager_first_name,\n            u.last_name as manager_last_name\n     FROM competition_participants cp\n     JOIN clubs c ON cp.club_id = c.id\n     LEFT JOIN club_memberships cm ON c.id = cm.club_id AND cm.season_id = ? AND cm.status = 'active'\n     LEFT JOIN users u ON cm.user_id = u.id\n     WHERE cp.competition_id = ?\n     ORDER BY c.name ASC`,\n    [seasonId, competitionId]\n  );\n\n  // If no competition_participants defined, fallback to clubs from the league\n  let clubList = clubs;\n  if (clubList.length === 0) {\n    clubList = queryAll<ClubRaw>(\n      `SELECT c.id, c.name, c.short_name, c.logo_url,\n              cm.user_id as manager_user_id,\n              u.username as manager_username,\n              u.first_name as manager_first_name,\n              u.last_name as manager_last_name\n       FROM competitions comp\n       JOIN season_league_clubs slc ON comp.league_id = slc.league_id AND comp.season_id = slc.season_id AND slc.is_active = 1\n       JOIN clubs c ON slc.club_id = c.id\n       LEFT JOIN club_memberships cm ON c.id = cm.club_id AND cm.season_id = comp.season_id AND cm.status = 'active'\n       LEFT JOIN users u ON cm.user_id = u.id\n       WHERE comp.id = ?\n       ORDER BY c.name ASC`,\n      [competitionId]\n    );\n  }\n\n  // 3. Fetch all CONFIRMED fixtures for this competition\n  const confirmedFixtures = queryAll<ConfirmedFixtureRaw>(\n    `SELECT id, matchday, home_club_id, away_club_id, home_score, away_score, result_confirmed_at\n     FROM fixtures\n     WHERE competition_id = ? AND status = 'CONFIRMED' AND home_score IS NOT NULL AND away_score IS NOT NULL\n     ORDER BY matchday ASC, result_confirmed_at ASC`,\n    [competitionId]\n  );\n\n  // 4. Accumulate stats per club\n  const statsMap = new Map<\n    string,\n    {\n      clubId: string;\n      clubName: string;\n      shortName: string;\n      logoUrl: string;\n      managerUserId?: string;\n      managerUsername?: string;\n      managerFirstName?: string;\n      managerLastName?: string;\n      managerDisplayName?: string;\n      played: number;\n      won: number;\n      drawn: number;\n      lost: number;\n      goalsFor: number;\n      goalsAgainst: number;\n      goalDifference: number;\n      points: number;\n      form: Array<'W' | 'D' | 'L'>;\n    }\n  >();\n\n  for (const c of clubList) {\n    const fname = c.manager_first_name?.trim() || undefined;\n    const lname = c.manager_last_name?.trim() || undefined;\n    const cleanUname = c.manager_username ? c.manager_username.replace(/^@+/, '').trim() : undefined;\n    const isSyntheticUname = cleanUname?.startsWith('tg_') || cleanUname?.startsWith('user_');\n    const validUname = isSyntheticUname ? undefined : cleanUname;\n    const fullName = [fname, lname].filter(Boolean).join(' ');\n    const displayName = fullName || fname || (validUname ? `@${validUname}` : undefined);\n\n    statsMap.set(c.id, {\n      clubId: c.id,\n      clubName: c.name,\n      shortName: c.short_name,\n      logoUrl: c.logo_url,\n      managerUserId: c.manager_user_id || undefined,\n      managerUsername: validUname,\n      managerFirstName: fname,\n      managerLastName: lname,\n      managerDisplayName: displayName,\n      played: 0,\n      won: 0,\n      drawn: 0,\n      lost: 0,\n      goalsFor: 0,\n      goalsAgainst: 0,\n      goalDifference: 0,\n      points: 0,\n      form: [],\n    });\n  }\n\n  for (const fix of confirmedFixtures) {\n    const home = statsMap.get(fix.home_club_id);\n    const away = statsMap.get(fix.away_club_id);\n\n    if (home) {\n      home.played += 1;\n      home.goalsFor += fix.home_score;\n      home.goalsAgainst += fix.away_score;\n\n      if (fix.home_score > fix.away_score) {\n        home.won += 1;\n        home.points += pointsForWin;\n        home.form.push('W');\n      } else if (fix.home_score === fix.away_score) {\n        home.drawn += 1;\n        home.points += pointsForDraw;\n        home.form.push('D');\n      } else {\n        home.lost += 1;\n        home.points += pointsForLoss;\n        home.form.push('L');\n      }\n    }\n\n    if (away) {\n      away.played += 1;\n      away.goalsFor += fix.away_score;\n      away.goalsAgainst += fix.home_score;\n\n      if (fix.away_score > fix.home_score) {\n        away.won += 1;\n        away.points += pointsForWin;\n        away.form.push('W');\n      } else if (fix.away_score === fix.home_score) {\n        away.drawn += 1;\n        away.points += pointsForDraw;\n        away.form.push('D');\n      } else {\n        away.lost += 1;\n        away.points += pointsForLoss;\n        away.form.push('L');\n      }\n    }\n  }\n\n  // Calculate goal difference & limit form to last 5\n  const rows = Array.from(statsMap.values()).map((row) => {\n    row.goalDifference = row.goalsFor - row.goalsAgainst;\n    row.form = row.form.slice(-5);\n    return row;\n  });\n\n  // Helper for Head-to-Head points between two clubs\n  function getH2HPoints(clubAId: string, clubBId: string): number {\n    let pts = 0;\n    for (const f of confirmedFixtures) {\n      if (f.home_club_id === clubAId && f.away_club_id === clubBId) {\n        if (f.home_score > f.away_score) pts += pointsForWin;\n        else if (f.home_score === f.away_score) pts += pointsForDraw;\n      } else if (f.home_club_id === clubBId && f.away_club_id === clubAId) {\n        if (f.away_score > f.home_score) pts += pointsForWin;\n        else if (f.away_score === f.home_score) pts += pointsForDraw;\n      }\n    }\n    return pts;\n  }\n\n  // 5. Multi-criteria Sorting based on tieBreakers configuration\n  rows.sort((a, b) => {\n    if (b.points !== a.points) {\n      return b.points - a.points;\n    }\n\n    for (const criteria of tieBreakers) {\n      if (criteria === 'goalDifference') {\n        if (b.goalDifference !== a.goalDifference) {\n          return b.goalDifference - a.goalDifference;\n        }\n      } else if (criteria === 'goalsFor') {\n        if (b.goalsFor !== a.goalsFor) {\n          return b.goalsFor - a.goalsFor;\n        }\n      } else if (criteria === 'headToHead') {\n        const h2hA = getH2HPoints(a.clubId, b.clubId);\n        const h2hB = getH2HPoints(b.clubId, a.clubId);\n        if (h2hB !== h2hA) {\n          return h2hB - h2hA;\n        }\n      }\n    }\n\n    // Alphabetical fallback\n    return a.clubName.localeCompare(b.clubName);\n  });\n\n  return rows.map((r, index) => ({\n    position: index + 1,\n    clubId: r.clubId,\n    clubName: r.clubName,\n    shortName: r.shortName,\n    logoUrl: r.logoUrl,\n    managerUserId: r.managerUserId,\n    managerUsername: r.managerUsername,\n    managerFirstName: r.managerFirstName,\n    managerLastName: r.managerLastName,\n    managerDisplayName: r.managerDisplayName,\n    played: r.played,\n    won: r.won,\n    drawn: r.drawn,\n    lost: r.lost,\n    goalsFor: r.goalsFor,\n    goalsAgainst: r.goalsAgainst,\n    goalDifference: r.goalDifference,\n    points: r.points,\n    form: r.form,\n  }));\n}\n", "import { queryRun, queryAll, queryGet, dbTransaction } from './index';\nimport { calculateCompetitionStandings } from '../tournament/standingsEngine';\nimport { StandingsRow } from '../../types';\n\n/**\n * Recomputes standings from local SQLite fixtures & participants for a given competition\n * and atomically persists the materialized snapshot to the `competition_standings` table.\n * Returns the computed standings rows.\n */\nexport function refreshMaterializedStandingsForCompetition(competitionId: string): StandingsRow[] {\n  const standings = calculateCompetitionStandings(competitionId);\n  const now = new Date().toISOString();\n\n  dbTransaction(() => {\n    // Clear previous snapshot for this competition\n    queryRun('DELETE FROM competition_standings WHERE competition_id = ?', [competitionId]);\n\n    // Insert newly calculated standings\n    for (const row of standings) {\n      queryRun(\n        `INSERT OR REPLACE INTO competition_standings (\n          competition_id, club_id, rank, club_name, short_name, logo_url,\n          played, won, drawn, lost, goals_for, goals_against, goal_difference,\n          points, form_json, qualification_status, manager_username, updated_at\n        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,\n        [\n          competitionId,\n          row.clubId,\n          row.position,\n          row.clubName,\n          row.shortName || '',\n          row.logoUrl || '',\n          row.played,\n          row.won,\n          row.drawn,\n          row.lost,\n          row.goalsFor,\n          row.goalsAgainst,\n          row.goalDifference,\n          row.points,\n          JSON.stringify(row.form || []),\n          null,\n          row.managerUsername || null,\n          now,\n        ]\n      );\n    }\n  });\n\n  return standings;\n}\n\n/**\n * Retrieves the materialized standings from SQLite. If no materialized rows exist,\n * automatically computes and caches them.\n */\nexport function getMaterializedStandingsForCompetition(competitionId: string): StandingsRow[] {\n  return refreshMaterializedStandingsForCompetition(competitionId);\n}\n\n/**\n * Helper to update materialized standings in SQLite when a fixture is confirmed or modified.\n */\nexport function updateMaterializedStandingsFromFixture(fixtureId: string): StandingsRow[] | null {\n  const fix = queryGet<{ competition_id: string }>('SELECT competition_id FROM fixtures WHERE id = ?', [fixtureId]);\n  if (!fix?.competition_id) {\n    return null;\n  }\n  return refreshMaterializedStandingsForCompetition(fix.competition_id);\n}\n", "export type OwnedClubRef = { id: string; leagueId: string };\n\n/** One club is free. An active season pass permits one more in another league. */\nexport function checkClubClaimLimit(\n  ownedClubs: OwnedClubRef[],\n  candidate: OwnedClubRef,\n  premiumActive: boolean\n): 'ALREADY_OWNED' | 'SAME_LEAGUE' | 'LIMIT_REACHED' | 'ALLOWED' {\n  if (ownedClubs.some((club) => club.id === candidate.id)) return 'ALREADY_OWNED';\n  if (ownedClubs.some((club) => club.leagueId === candidate.leagueId)) return 'SAME_LEAGUE';\n  if (ownedClubs.length >= (premiumActive ? 2 : 1)) return 'LIMIT_REACHED';\n  return 'ALLOWED';\n}\n", "import { trackFirestoreRead } from '../firebase/firestoreStore';\nimport { getFirestoreDb } from '../firebase/admin';\nimport { firestoreCircuitBreaker } from '../firebase/circuitBreaker';\nimport { SEED_LEAGUES } from '../db/seed';\nimport { ReadModelKeys, ReadModelNotWarmedError, redisGetFresh, redisGetLkg, redisSetRaw } from '../readModel/readModelStore';\n\nexport const CLUB_ADMISSION_LEAGUES = SEED_LEAGUES.map(({ id, name }) => ({ id, name }));\nconst COLLECTION = 'club_admissions';\nconst ADMISSION_CACHE_TTL_SECONDS = 300;\nconst pendingStatusReads = new Map<string, Promise<ClubAdmissionStatus>>();\n\nexport interface ClubAdmissionStatus {\n  seasonId: string;\n  enabled: boolean;\n  stage: number;\n  activeLeagueId: string | null;\n  leagues: typeof CLUB_ADMISSION_LEAGUES;\n  updatedAt: string | null;\n  stale?: boolean;\n}\n\nexport class ClubAdmissionConflict extends Error {\n  constructor(public readonly code: 'ADMISSION_STAGE_CHANGED' | 'ADMISSION_FINISHED') {\n    super(code === 'ADMISSION_FINISHED' ? 'Klub qabuli yakunlangan.' : 'Qabul bosqichi o\u2018zgargan. Sahifani yangilang.');\n  }\n}\n\nexport function admissionStatus(seasonId: string, data?: Record<string, unknown>): ClubAdmissionStatus {\n  const enabled = data?.enabled === true;\n  const rawStage = Number(data?.stage);\n  if (enabled && (!Number.isInteger(rawStage) || rawStage < 0 || rawStage > CLUB_ADMISSION_LEAGUES.length)) {\n    throw new Error('INVALID_CLUB_ADMISSION_STATE');\n  }\n  const stage = enabled ? rawStage : -1;\n  return {\n    seasonId,\n    enabled,\n    stage,\n    activeLeagueId: stage >= 0 ? CLUB_ADMISSION_LEAGUES[stage]?.id || null : null,\n    leagues: CLUB_ADMISSION_LEAGUES,\n    updatedAt: typeof data?.updatedAt === 'string' ? data.updatedAt : null,\n  };\n}\n\nexport async function getClubAdmissionStatus(seasonId: string): Promise<ClubAdmissionStatus> {\n  const pending = pendingStatusReads.get(seasonId);\n  if (pending) return pending;\n  const read = loadClubAdmissionStatus(seasonId);\n  pendingStatusReads.set(seasonId, read);\n  try {\n    return await read;\n  } finally {\n    if (pendingStatusReads.get(seasonId) === read) pendingStatusReads.delete(seasonId);\n  }\n}\n\nasync function loadClubAdmissionStatus(seasonId: string): Promise<ClubAdmissionStatus> {\n  const key = ReadModelKeys.clubAdmission(seasonId);\n  const fresh = await redisGetFresh<ClubAdmissionStatus>(key);\n  if (fresh?.data) {\n    return { ...admissionStatus(seasonId, fresh.data as unknown as Record<string, unknown>), stale: !firestoreCircuitBreaker.isHealthy() };\n  }\n\n  const lastKnown = async () => {\n    const snapshot = await redisGetLkg<ClubAdmissionStatus>(key);\n    return snapshot?.data ? { ...admissionStatus(seasonId, snapshot.data as unknown as Record<string, unknown>), stale: true } : null;\n  };\n  // Every admission mutation publishes this durable snapshot. A cached UI status\n  // must not probe an exhausted database on each cold server; claims revalidate in a transaction.\n  const saved = await lastKnown();\n  if (saved) return saved;\n  if (!firestoreCircuitBreaker.canExecute()) {\n    const cached = await lastKnown();\n    if (cached) return cached;\n    throw new ReadModelNotWarmedError('Club admission state is not cached while Firestore is unavailable.');\n  }\n\n  let status: ClubAdmissionStatus;\n  try {\n    const doc = await getFirestoreDb().collection(COLLECTION).doc(seasonId).get();\n    trackFirestoreRead(COLLECTION, 1, 'getClubAdmissionStatus');\n    status = admissionStatus(seasonId, doc.data());\n    firestoreCircuitBreaker.recordSuccess();\n  } catch (error) {\n    firestoreCircuitBreaker.recordFailure(error);\n    const cached = await lastKnown();\n    if (cached) return cached;\n    throw new ReadModelNotWarmedError('Club admission state is not cached and Firestore could not be read.');\n  }\n\n  try {\n    await redisSetRaw(key, { data: status, sourceVersion: `club-admission-${status.updatedAt || 'disabled'}` }, ADMISSION_CACHE_TTL_SECONDS);\n  } catch (error) {\n    console.warn('[CLUB_ADMISSION] Could not cache admission state:', error);\n  }\n  return status;\n}\n\n// Both admin transitions and claims read the same document in Firestore transactions.\n// A concurrent stage change therefore retries a claim against the new stage.\nexport async function advanceClubAdmission(seasonId: string, expectedStage: number, actorId: string): Promise<ClubAdmissionStatus> {\n  const db = getFirestoreDb();\n  const ref = db.collection(COLLECTION).doc(seasonId);\n  const status = await db.runTransaction(async (transaction) => {\n    const current = admissionStatus(seasonId, (await transaction.get(ref)).data());\n    if (current.stage !== expectedStage) throw new ClubAdmissionConflict('ADMISSION_STAGE_CHANGED');\n    if (current.stage >= CLUB_ADMISSION_LEAGUES.length) throw new ClubAdmissionConflict('ADMISSION_FINISHED');\n    const stage = current.stage + 1;\n    const updatedAt = new Date().toISOString();\n    transaction.set(ref, { seasonId, enabled: true, stage, updatedAt, updatedBy: actorId });\n    return admissionStatus(seasonId, { enabled: true, stage, updatedAt });\n  });\n  try {\n    await redisSetRaw(ReadModelKeys.clubAdmission(seasonId), { data: status, sourceVersion: `club-admission-${status.updatedAt}` }, ADMISSION_CACHE_TTL_SECONDS);\n  } catch (error) {\n    // The Firestore transaction has committed; a cache failure must not report the mutation as failed.\n    console.warn('[CLUB_ADMISSION] Stage changed but cache update failed:', error);\n  }\n  return status;\n}\n\nexport function assertClubAdmissionOpen(status: ClubAdmissionStatus, leagueId: string): void {\n  if (status.enabled && status.activeLeagueId !== leagueId) {\n    const active = status.leagues.find((league) => league.id === status.activeLeagueId);\n    throw new ClubAdmissionConflictError(active ? `Hozir faqat ${active.name} klublari uchun qabul ochiq.` : 'Bu mavsum uchun klub qabuli yakunlangan.');\n  }\n}\n\nexport class ClubAdmissionConflictError extends Error {\n  readonly code = 'CLUB_ADMISSION_CLOSED';\n}\n", "import { queryAll, queryRun, isDatabaseInitialized } from '../db';\nimport { SEED_CLUBS } from '../db/seed';\n\nexport interface OccupancyRecord {\n  clubId: string;\n  seasonId: string;\n  status: 'active';\n  claimedByUserId: string;\n  claimedAt?: string;\n  username?: string;\n  displayName?: string;\n  updatedAt: string;\n}\n\n// In-memory persistent mirror of active season occupancy snapshot\nconst memoryOccupancySnapshot = new Map<string, OccupancyRecord>(); // key: `${seasonId}_${clubId}`\n\nexport function updateOccupancyRecord(record: OccupancyRecord): void {\n  const key = `${record.seasonId}_${record.clubId}`;\n  memoryOccupancySnapshot.set(key, record);\n\n  try {\n    queryRun(\n      `INSERT OR REPLACE INTO active_occupancies_cache \n       (club_id, season_id, user_id, username, display_name, status, updated_at)\n       VALUES (?, ?, ?, ?, ?, ?, ?)`,\n      [\n        record.clubId,\n        record.seasonId,\n        record.claimedByUserId,\n        record.username || null,\n        record.displayName || null,\n        record.status,\n        record.updatedAt,\n      ]\n    );\n  } catch {\n    // Non-blocking SQLite persistence\n  }\n}\n\nexport function removeOccupancyRecord(seasonId: string, clubId: string): void {\n  const key = `${seasonId}_${clubId}`;\n  memoryOccupancySnapshot.delete(key);\n\n  try {\n    queryRun(\n      `DELETE FROM active_occupancies_cache WHERE season_id = ? AND club_id = ?`,\n      [seasonId, clubId]\n    );\n  } catch {}\n}\n\nexport function getLocalOccupancySnapshot(seasonId = 'season-2026-27'): OccupancyRecord[] {\n  // If memory has entries for this season, return them\n  const memRecords: OccupancyRecord[] = [];\n  for (const [k, v] of memoryOccupancySnapshot.entries()) {\n    if (k.startsWith(`${seasonId}_`)) {\n      memRecords.push(v);\n    }\n  }\n\n  if (memRecords.length > 0) {\n    return memRecords;\n  }\n\n  // Otherwise hydrate from SQLite active_occupancies_cache or club_memberships\n  if (!isDatabaseInitialized()) {\n    return memRecords;\n  }\n  try {\n    const cachedRows = queryAll<any>(\n      `SELECT club_id, season_id, user_id, username, display_name, status, updated_at\n       FROM active_occupancies_cache\n       WHERE season_id = ? AND status = 'active'`,\n      [seasonId]\n    );\n\n    if (cachedRows.length > 0) {\n      for (const r of cachedRows) {\n        const rec: OccupancyRecord = {\n          clubId: r.club_id,\n          seasonId: r.season_id,\n          status: 'active',\n          claimedByUserId: r.user_id,\n          username: r.username || undefined,\n          displayName: r.display_name || undefined,\n          updatedAt: r.updated_at,\n        };\n        memoryOccupancySnapshot.set(`${seasonId}_${r.club_id}`, rec);\n        memRecords.push(rec);\n      }\n      return memRecords;\n    }\n\n    // Baseline fallback: check club_memberships directly\n    const memRows = queryAll<any>(\n      `SELECT cm.club_id, cm.season_id, cm.user_id, u.username, u.first_name, u.last_name, cm.claimed_at as updated_at\n       FROM club_memberships cm\n       LEFT JOIN users u ON cm.user_id = u.id\n       WHERE cm.season_id = ? AND cm.status = 'active'`,\n      [seasonId]\n    );\n\n    for (const r of memRows) {\n      const displayName = `${r.first_name || ''} ${r.last_name || ''}`.trim() || r.username || r.user_id;\n      const rec: OccupancyRecord = {\n        clubId: r.club_id,\n        seasonId: r.season_id,\n        status: 'active',\n        claimedByUserId: r.user_id,\n        username: r.username || undefined,\n        displayName,\n        updatedAt: r.updated_at || new Date().toISOString(),\n      };\n      memoryOccupancySnapshot.set(`${seasonId}_${r.club_id}`, rec);\n      memRecords.push(rec);\n    }\n  } catch (err) {\n    console.warn('[OCCUPANCY_SNAPSHOT] SQLite hydration error:', err);\n  }\n\n  return memRecords;\n}\n\nexport function syncOccupanciesFromFirestoreDocs(\n  seasonId: string,\n  occupancies: Array<{ clubId: string; userId: string; username?: string; displayName?: string }>\n): void {\n  const now = new Date().toISOString();\n  for (const occ of occupancies) {\n    updateOccupancyRecord({\n      clubId: occ.clubId,\n      seasonId,\n      status: 'active',\n      claimedByUserId: occ.userId,\n      username: occ.username,\n      displayName: occ.displayName,\n      updatedAt: now,\n    });\n  }\n}\n\nexport function isClubOccupiedLocally(seasonId: string, clubId: string): boolean {\n  const snapshot = getLocalOccupancySnapshot(seasonId);\n  return snapshot.some((r) => r.clubId === clubId);\n}\n\nexport function loadSnapshotFromFile(): void {\n  try {\n    getLocalOccupancySnapshot('season-2026-27');\n  } catch (err: any) {\n    console.warn('[OCCUPANCY_SNAPSHOT] Load error:', err.message);\n  }\n}\n\nexport function getUserOccupiedClubIdLocally(seasonId: string, userId: string): string | null {\n  const snapshot = getLocalOccupancySnapshot(seasonId);\n  const found = snapshot.find((r) => r.claimedByUserId === userId);\n  return found ? found.clubId : null;\n}\n\nexport function getClubOccupantUserIdLocally(seasonId: string, clubId: string): string | null {\n  const snapshot = getLocalOccupancySnapshot(seasonId);\n  const found = snapshot.find((r) => r.clubId === clubId);\n  return found ? found.claimedByUserId : null;\n}\n", "/**\n * Centralized production safety guard for EFL UZ.\n * DEFAULT-DENY POLICY: Strictly prevents test users, test matches, test results,\n * or test mutations from modifying any production or hosted database.\n */\n\nimport { getFirebaseStatus, initializeFirebaseAdmin } from '../firebase/admin';\n\nexport const PROD_PROJECT_ID = 'gen-lang-client-0195097895';\nexport const PROD_DATABASE_ID = 'ai-studio-efluz-4c6c88a6-697e-4fdf-82ed-45fec68ca34d';\n\nexport const SYNTHETIC_ID_PATTERNS = [\n  'audit-',\n  'test-',\n  'test_',\n  'admin_test',\n  'admin-test',\n  'admin-offline',\n  'admin-audit',\n  'offline-test',\n  'fix-retry-test',\n  'user_a_',\n  'user_b_',\n  'notif_b_',\n  'spoofed_',\n] as const;\n\n/**\n * Checks whether the current process is running in any hosted environment.\n * Every hosted environment is treated as unsafe for test mutations, including ais-dev-* Cloud Run services.\n */\nexport function isHostedEnvironment(): boolean {\n  return Boolean(\n    (process.env.K_SERVICE && process.env.K_SERVICE.trim() !== '') ||\n    process.env.VERCEL ||\n    process.env.VERCEL_ENV ||\n    process.env.AWS_LAMBDA_FUNCTION_NAME ||\n    process.env.NODE_ENV === 'production'\n  );\n}\n\n/**\n * Checks whether the process is connected to the real production project or database.\n */\nexport function isConnectedToProductionFirestore(): boolean {\n  // Under forced local fallback, we are connected to the isolated in-memory mock\n  if (process.env.FIREBASE_FORCE_LOCAL_FALLBACK === 'true') {\n    return false;\n  }\n\n  // If hosted in production, treat as connected to production\n  if (isHostedEnvironment()) {\n    return true;\n  }\n\n  const status = getFirebaseStatus();\n  if (status.authMode === 'local_fallback') {\n    return false;\n  }\n\n  // Under verified local emulator for test project, we are not on production\n  if (\n    process.env.FIRESTORE_EMULATOR_HOST &&\n    (status.projectId?.startsWith('demo-') || status.projectId?.startsWith('test-'))\n  ) {\n    return false;\n  }\n\n  // Otherwise, we are connected to real Firestore\n  return true;\n}\n\n/**\n * Checks whether the process or configuration targets the real production project or database.\n */\nexport function isTargetingProductionProjectOrDb(): boolean {\n  if (process.env.FIREBASE_FORCE_LOCAL_FALLBACK === 'true') {\n    return false;\n  }\n\n  const status = getFirebaseStatus();\n  const envProjectId =\n    process.env.FIREBASE_PROJECT_ID ||\n    process.env.GCLOUD_PROJECT ||\n    process.env.GOOGLE_CLOUD_PROJECT;\n  const envDbId = process.env.FIRESTORE_DATABASE_ID || process.env.FIREBASE_DATABASE_ID;\n\n  if (\n    status.projectId === PROD_PROJECT_ID ||\n    status.databaseId === PROD_DATABASE_ID ||\n    envProjectId === PROD_PROJECT_ID ||\n    envDbId === PROD_DATABASE_ID\n  ) {\n    return true;\n  }\n  return false;\n}\n\n/**\n * Checks if a string contains any recognized synthetic or test pattern.\n */\nexport function isSyntheticIdentifier(id: string | null | undefined): boolean {\n  if (!id || typeof id !== 'string') return false;\n  const lower = id.toLowerCase();\n  return SYNTHETIC_ID_PATTERNS.some((pattern) => lower.includes(pattern));\n}\n\n/**\n * Validates if test mutations are permitted under strict default-deny policy.\n * Test mutations may be allowed ONLY when one of these is true:\n * 1. FIREBASE_FORCE_LOCAL_FALLBACK === \"true\", and getFirestoreDb is guaranteed\n *    to return the isolated in-memory implementation;\n * 2. FIRESTORE_EMULATOR_HOST is configured and the Firebase project ID begins with \"demo-\" or \"test-\".\n *\n * ALLOW_TEST_WRITES alone must NEVER authorize Firestore writes.\n * Any hosted environment is strictly unsafe.\n */\nexport function isTestSafe(): boolean {\n  // Path 1: Local In-Memory Fallback\n  if (process.env.FIREBASE_FORCE_LOCAL_FALLBACK === 'true') {\n    // Hosted production environments are strictly forbidden from enabling test fallback\n    if (\n      process.env.NODE_ENV === 'production' ||\n      process.env.VERCEL === '1' ||\n      process.env.AWS_LAMBDA_FUNCTION_NAME !== undefined\n    ) {\n      return false;\n    }\n    const { info } = initializeFirebaseAdmin();\n    if (info.authMode === 'local_fallback' && info.projectId === 'test-local-fallback') {\n      return true;\n    }\n    return false;\n  }\n\n  // Hosted environments (Cloud Run, Vercel, production) are NEVER safe for test mutations\n  if (isHostedEnvironment()) {\n    return false;\n  }\n\n  // Path 2: Verified Local Emulator with demo- or test- project\n  if (process.env.FIRESTORE_EMULATOR_HOST) {\n    const projId =\n      process.env.FIREBASE_PROJECT_ID ||\n      process.env.GCLOUD_PROJECT ||\n      process.env.GOOGLE_CLOUD_PROJECT ||\n      '';\n    if (projId.startsWith('demo-') || projId.startsWith('test-')) {\n      return true;\n    }\n  }\n\n  return false;\n}\n\n/**\n * Throws a fatal safety violation if the environment is not verified safe for test mutations.\n */\nexport function assertTestEnvironmentSafe(actionName = 'test_mutation'): void {\n  if (!isTestSafe()) {\n    const reasons: string[] = [];\n    if (isHostedEnvironment()) reasons.push('hosted environment detected (K_SERVICE/VERCEL/NODE_ENV=production)');\n    if (isTargetingProductionProjectOrDb()) reasons.push('production project/database targeted');\n    if (process.env.ALLOW_TEST_WRITES === 'true') reasons.push('ALLOW_TEST_WRITES is deprecated and cannot authorize writes');\n    if (process.env.FIREBASE_FORCE_LOCAL_FALLBACK !== 'true' && !process.env.FIRESTORE_EMULATOR_HOST) {\n      reasons.push('neither FIREBASE_FORCE_LOCAL_FALLBACK=true nor FIRESTORE_EMULATOR_HOST is configured');\n    }\n\n    const errorMsg = `PRODUCTION_SAFETY_VIOLATION: Test mutation \"${actionName}\" is strictly prohibited. Production database cannot be modified by test helpers or mock data. Violations: [${reasons.join('; ')}]`;\n    console.error(`[CRITICAL PRODUCTION BLOCKED] ${errorMsg}`);\n    throw new Error(errorMsg);\n  }\n}\n\n/**\n * Checks if an entity ID or username indicates a synthetic/test record.\n * If so, verifies that test mutations are safe, otherwise blocks immediately.\n */\nexport function guardAgainstTestEntityCreation(entityType: string, entityId: string, entityNameOrUsername?: string): void {\n  if (isSyntheticIdentifier(entityId) || isSyntheticIdentifier(entityNameOrUsername)) {\n    assertTestEnvironmentSafe(`create_${entityType}:${entityId}`);\n  }\n}\n\n/**\n * Production guard to reject synthetic actor IDs or entity IDs before any mutation.\n * When connected to the real production project/database or running in a hosted environment,\n * rejects any synthetic identifier with a fatal error before any Firestore or SQLite write.\n */\nexport function assertNoSyntheticIdsInProduction(\n  actionName: string,\n  ids: Array<string | null | undefined>\n): void {\n  // If connected to real production, hosted environment, or outside safe test sandbox, strictly reject synthetic IDs\n  if (!isConnectedToProductionFirestore()) {\n    return;\n  }\n\n  for (const id of ids) {\n    if (isSyntheticIdentifier(id)) {\n      const errorMsg = `PRODUCTION_SAFETY_VIOLATION: Synthetic identifier \"${id}\" rejected in production/hosted environment during \"${actionName}\". Mutation blocked before persistence.`;\n      console.error(`[CRITICAL PRODUCTION BLOCKED] ${errorMsg}`);\n      throw new Error(errorMsg);\n    }\n  }\n}\n", "import { randomUUID } from 'node:crypto';\nimport { getUpstashClient, KEY_PREFIX } from '../readModel/readModelStore';\n\nexport type OutboxMutationStatus = 'PENDING' | 'SYNCING' | 'SYNCED' | 'FAILED';\n\nexport interface DurableOutboxMutation<T = any> {\n  mutationId: string;\n  revision?: string;\n  operation: string;\n  entityType: string;\n  entityId: string;\n  userId?: string;\n  adminUserId?: string;\n  seasonId: string;\n  competitionId?: string;\n  payload: T;\n  createdAt: string;\n  updatedAt: string;\n  retryCount: number;\n  nextRetryAt: number;\n  lastError: string | null;\n  status: OutboxMutationStatus;\n}\n\nexport class DurablePersistenceUnavailableError extends Error {\n  public readonly code = 'DURABLE_PERSISTENCE_UNAVAILABLE';\n  public readonly statusCode = 503;\n  public readonly status = 503;\n\n  constructor(message = 'Durable persistence is temporarily unavailable. Mutation was not accepted; retry when service recovers.') {\n    super(message);\n    this.name = 'DurablePersistenceUnavailableError';\n  }\n}\n\nexport const OUTBOX_KEYS = {\n  mutation: (mutationId: string) => `${KEY_PREFIX}:outbox:mutation:${mutationId}`,\n  pending: () => `${KEY_PREFIX}:outbox:pending`,\n  all: () => `${KEY_PREFIX}:outbox:all`,\n};\n\nexport function isRedisOutboxConfigured(): boolean {\n  return getUpstashClient() !== null;\n}\n\n/**\n * Persists a complete replayable mutation to the durable Redis outbox.\n * Throws DurablePersistenceUnavailableError if Redis client is not available or write fails.\n */\nexport async function persistDurableMutation<T = any>(\n  mutation: DurableOutboxMutation<T>\n): Promise<void> {\n  const client = getUpstashClient();\n  if (!client) {\n    throw new DurablePersistenceUnavailableError(\n      'Durable Redis outbox is not configured. Local ephemeral storage cannot acknowledge mutations.'\n    );\n  }\n\n  const mutationKey = OUTBOX_KEYS.mutation(mutation.mutationId);\n  const pendingKey = OUTBOX_KEYS.pending();\n  const allKey = OUTBOX_KEYS.all();\n\n  try {\n    mutation.revision = randomUUID();\n    const rawJson = JSON.stringify(mutation);\n    await client.eval(`\n      -- EFL_OUTBOX_PERSIST_V1: validate all key types before publishing.\n      local recordType = redis.call('TYPE', KEYS[1]).ok\n      local pendingType = redis.call('TYPE', KEYS[2]).ok\n      local allType = redis.call('TYPE', KEYS[3]).ok\n      if recordType ~= 'none' and recordType ~= 'string' then return redis.error_reply('OUTBOX_RECORD_TYPE_INVALID') end\n      if pendingType ~= 'none' and pendingType ~= 'zset' then return redis.error_reply('OUTBOX_PENDING_TYPE_INVALID') end\n      if allType ~= 'none' and allType ~= 'set' then return redis.error_reply('OUTBOX_ALL_TYPE_INVALID') end\n      redis.call('SET', KEYS[1], ARGV[1])\n      if ARGV[4] == 'PENDING' or ARGV[4] == 'SYNCING' then\n        redis.call('ZADD', KEYS[2], ARGV[2], ARGV[3])\n      else redis.call('ZREM', KEYS[2], ARGV[3]) end\n      redis.call('SADD', KEYS[3], ARGV[3])\n      return 1\n    `, [mutationKey, pendingKey, allKey], [rawJson, mutation.nextRetryAt, mutation.mutationId, mutation.status]);\n    console.log(`[DURABLE_OUTBOX] Persisted mutation ${mutation.mutationId} (${mutation.operation}) to Redis`);\n  } catch (err: any) {\n    console.error(`[DURABLE_OUTBOX] Failed to persist mutation ${mutation.mutationId} to Redis:`, err?.message || err);\n    throw new DurablePersistenceUnavailableError(\n      `Failed to persist mutation to durable Redis outbox: ${err?.message || 'Upstash error'}`\n    );\n  }\n}\n\n/**\n * Retrieves a mutation record by ID from durable Redis outbox.\n */\nexport async function getDurableMutation<T = any>(\n  mutationId: string\n): Promise<DurableOutboxMutation<T> | null> {\n  const client = getUpstashClient();\n  if (!client) return null;\n\n  try {\n    const raw = await client.get<any>(OUTBOX_KEYS.mutation(mutationId));\n    if (!raw) return null;\n    if (typeof raw === 'string') {\n      try {\n        return JSON.parse(raw);\n      } catch {\n        return null;\n      }\n    }\n    return raw as DurableOutboxMutation<T>;\n  } catch (err: any) {\n    console.warn(`[DURABLE_OUTBOX] Failed to read mutation ${mutationId}:`, err?.message || err);\n    return null;\n  }\n}\n\n/**\n * Retrieves due pending mutations from durable Redis outbox.\n * Bounded by score <= now (prevents picking items that are in backoff cooldown)\n * and bounded by batch size limit.\n */\nexport async function getDuePendingMutations(limit = 25): Promise<DurableOutboxMutation[]> {\n  const client = getUpstashClient();\n  if (!client) return [];\n\n  try {\n    const now = Date.now();\n    const members = await client.zrange<string[]>(\n      OUTBOX_KEYS.pending(),\n      0,\n      now,\n      { byScore: true, offset: 0, count: limit }\n    );\n\n    if (!members || members.length === 0) return [];\n\n    const mutations: DurableOutboxMutation[] = [];\n    for (const id of members) {\n      const mut = await getDurableMutation(id);\n      if (mut && (mut.status === 'PENDING' || mut.status === 'SYNCING')) {\n        mutations.push(mut);\n      }\n    }\n\n    // Sort FIFO by creation time\n    return mutations.sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());\n  } catch (err: any) {\n    console.warn('[DURABLE_OUTBOX] Error retrieving due pending mutations:', err?.message || err);\n    return [];\n  }\n}\n\n/** Change receipt + pending index atomically, and never acknowledge an older\n * revision over a newly accepted edit with the same logical mutation ID. */\nasync function transitionMutation(mut: DurableOutboxMutation, expectedRevision: string): Promise<boolean> {\n  const client = getUpstashClient();\n  if (!client) return false;\n  return Number(await client.eval(`\n    -- EFL_OUTBOX_TRANSITION_V1\n    local raw = redis.call('GET', KEYS[1])\n    if not raw then return 0 end\n    local current = cjson.decode(raw)\n    if (current.revision or '') ~= ARGV[2] then return 0 end\n    local pendingType = redis.call('TYPE', KEYS[2]).ok\n    if pendingType ~= 'none' and pendingType ~= 'zset' then return redis.error_reply('OUTBOX_PENDING_TYPE_INVALID') end\n    redis.call('SET', KEYS[1], ARGV[1])\n    if ARGV[4] == 'SYNCED' or ARGV[4] == 'FAILED' then\n      redis.call('ZREM', KEYS[2], ARGV[3])\n    else redis.call('ZADD', KEYS[2], ARGV[5], ARGV[3]) end\n    return 1\n  `, [OUTBOX_KEYS.mutation(mut.mutationId), OUTBOX_KEYS.pending()],\n  [JSON.stringify(mut), expectedRevision, mut.mutationId, mut.status, mut.nextRetryAt])) === 1;\n}\n\nasync function matchingMutation(id: string, expectedRevision?: string): Promise<DurableOutboxMutation | null> {\n  const mut = await getDurableMutation(id);\n  if (!mut || (expectedRevision !== undefined && (mut.revision || '') !== expectedRevision)) return null;\n  return mut;\n}\n\nexport async function markMutationSyncing(mutationId: string, expectedRevision?: string): Promise<boolean> {\n  try {\n    const mut = await matchingMutation(mutationId, expectedRevision);\n    if (!mut || (mut.status !== 'PENDING' && mut.status !== 'SYNCING')) return false;\n    mut.status = 'SYNCING';\n    mut.updatedAt = new Date().toISOString();\n    return await transitionMutation(mut, mut.revision || '');\n  } catch (err: any) { console.warn('[DURABLE_OUTBOX] Sync receipt deferred:', err?.message); return false; }\n}\n\nexport async function markMutationSynced(mutationId: string, expectedRevision?: string): Promise<boolean> {\n  try {\n    const mut = await matchingMutation(mutationId, expectedRevision);\n    if (!mut) return false;\n    mut.status = 'SYNCED'; mut.lastError = null; mut.updatedAt = new Date().toISOString();\n    return await transitionMutation(mut, mut.revision || '');\n  } catch (err: any) { console.warn('[DURABLE_OUTBOX] Completion receipt deferred:', err?.message); return false; }\n}\n\nexport async function markMutationRetryable(mutationId: string, errorMessage: string, expectedRevision?: string): Promise<boolean> {\n  try {\n    const mut = await matchingMutation(mutationId, expectedRevision);\n    if (!mut) return false;\n    const retryCount = (mut.retryCount || 0) + 1;\n    const backoffMs = Math.min(300000, 3000 * Math.pow(2, Math.min(retryCount, 6)));\n    mut.status = 'PENDING'; mut.retryCount = retryCount; mut.nextRetryAt = Date.now() + backoffMs;\n    mut.lastError = errorMessage; mut.updatedAt = new Date().toISOString();\n    return await transitionMutation(mut, mut.revision || '');\n  } catch (err: any) { console.warn('[DURABLE_OUTBOX] Retry receipt deferred:', err?.message); return false; }\n}\n\nexport async function markMutationFailed(mutationId: string, errorMessage: string, expectedRevision?: string): Promise<boolean> {\n  try {\n    const mut = await matchingMutation(mutationId, expectedRevision);\n    if (!mut) return false;\n    mut.status = 'FAILED'; mut.lastError = errorMessage; mut.updatedAt = new Date().toISOString();\n    return await transitionMutation(mut, mut.revision || '');\n  } catch (err: any) { console.warn('[DURABLE_OUTBOX] Failure receipt deferred:', err?.message); return false; }\n}\n\n/**\n * Returns summary stats of durable Redis outbox.\n */\nexport async function getDurableOutboxStats(): Promise<{\n  total: number;\n  pending: number;\n  syncing: number;\n  synced: number;\n  failed: number;\n}> {\n  const client = getUpstashClient();\n  if (!client) {\n    return { total: 0, pending: 0, syncing: 0, synced: 0, failed: 0 };\n  }\n\n  try {\n    const members = await client.smembers<string[]>(OUTBOX_KEYS.all());\n    if (!members || members.length === 0) {\n      return { total: 0, pending: 0, syncing: 0, synced: 0, failed: 0 };\n    }\n\n    let pending = 0;\n    let syncing = 0;\n    let synced = 0;\n    let failed = 0;\n\n    for (const id of members) {\n      const mut = await getDurableMutation(id);\n      if (!mut) continue;\n      if (mut.status === 'PENDING') pending++;\n      else if (mut.status === 'SYNCING') syncing++;\n      else if (mut.status === 'SYNCED') synced++;\n      else if (mut.status === 'FAILED') failed++;\n    }\n\n    return {\n      total: members.length,\n      pending,\n      syncing,\n      synced,\n      failed,\n    };\n  } catch (err: any) {\n    console.warn('[DURABLE_OUTBOX] Failed to get stats:', err?.message || err);\n    return { total: 0, pending: 0, syncing: 0, synced: 0, failed: 0 };\n  }\n}\n", "import { getFirestoreDb } from '../firebase/admin';\nimport {\n  COLLECTIONS,\n  FirestoreCompetitionDoc,\n  FirestoreFixtureDoc,\n  FirestoreCompetitionParticipantDoc,\n  FirestoreClubDoc,\n} from '../firebase/collections';\nimport { createAuditLog } from '../services/adminService';\nimport { notifySmartCupAdvancement, notifySmartCupChampion } from '../services/smartNotificationService';\nimport {\n  redisGetRaw,\n  redisSetRaw,\n  invalidateDataset,\n  invalidateFixtureReadModels,\n  refreshChangedFixtureReadModel,\n  getLkgKey,\n  ReadModelKeys,\n  ReadModelSnapshot,\n  SCHEMA_VERSION,\n} from '../readModel/readModelStore';\nimport { SEED_CLUBS, SEED_LEAGUES } from '../db/seed';\nimport { queryAll, queryGet, queryRun } from '../db';\nimport { firestoreCircuitBreaker } from '../firebase/firestoreStore';\n\nexport interface DomesticCupConfig {\n  id: string;\n  name: string;\n  country: string;\n  leagueId: string;\n  expectedTeams: number;\n}\n\nexport const DOMESTIC_CUPS: Record<string, DomesticCupConfig> = {\n  'comp-fa-cup-2026': {\n    id: 'comp-fa-cup-2026',\n    name: 'FA Cup',\n    country: 'England',\n    leagueId: 'league-premier-league',\n    expectedTeams: 20,\n  },\n  'comp-copa-del-rey-2026': {\n    id: 'comp-copa-del-rey-2026',\n    name: 'Copa del Rey',\n    country: 'Spain',\n    leagueId: 'league-la-liga',\n    expectedTeams: 20,\n  },\n  'comp-coppa-italia-2026': {\n    id: 'comp-coppa-italia-2026',\n    name: 'Coppa Italia',\n    country: 'Italy',\n    leagueId: 'league-serie-a',\n    expectedTeams: 20,\n  },\n  'comp-dfb-pokal-2026': {\n    id: 'comp-dfb-pokal-2026',\n    name: 'DFB-Pokal',\n    country: 'Germany',\n    leagueId: 'league-bundesliga',\n    expectedTeams: 18,\n  },\n  'comp-coupe-de-france-2026': {\n    id: 'comp-coupe-de-france-2026',\n    name: 'Coupe de France',\n    country: 'France',\n    leagueId: 'league-ligue-1',\n    expectedTeams: 18,\n  },\n};\n\nexport function isDomesticCup(competitionId: string): boolean {\n  if (competitionId.toLowerCase().includes('efl-cup') || competitionId.toLowerCase().includes('carabao')) {\n    return false;\n  }\n  return Boolean(DOMESTIC_CUPS[competitionId]);\n}\n\nexport function validateDomesticCupId(competitionId: string): DomesticCupConfig {\n  if (competitionId.toLowerCase().includes('efl-cup') || competitionId.toLowerCase().includes('carabao')) {\n    throw new Error('EFL Cup is strictly excluded from domestic cup administration.');\n  }\n  const cup = DOMESTIC_CUPS[competitionId];\n  if (!cup) {\n    throw new Error(`Invalid domestic cup ID '${competitionId}'. Must be one of: ${Object.keys(DOMESTIC_CUPS).join(', ')}`);\n  }\n  return cup;\n}\n\nexport interface CupBracketNode {\n  id: string; // Alias for fixtureId\n  fixtureId: string;\n  matchday: number;\n  roundName: string;\n  homeClubId: string | null;\n  homeClubName: string;\n  homeClubBadge?: string;\n  awayClubId: string | null;\n  awayClubName: string;\n  awayClubBadge?: string;\n  status: string;\n  homeScore: number | null;\n  awayScore: number | null;\n  homePenaltyScore?: number | null;\n  awayPenaltyScore?: number | null;\n  winnerClubId: string | null;\n  winnerClubName?: string;\n  scheduledAt: string;\n  resultConfirmedAt: string | null;\n  sourceFixtureId?: string | null;\n  sourceWinnerSlot?: string | null;\n  homeSourceFixtureId?: string | null;\n  awaySourceFixtureId?: string | null;\n  homeSourceWinnerSlot?: string | null;\n  awaySourceWinnerSlot?: string | null;\n}\n\nexport interface CupBracketRound {\n  roundNumber: number;\n  roundName: string;\n  matches: CupBracketNode[];\n  fixtures: CupBracketNode[]; // Alias for matches\n  matchesCount: number;\n  totalMatches: number; // Alias for matchesCount\n  completedCount: number;\n  completedMatches: number; // Alias for completedCount\n}\n\nexport interface DomesticCupDetails {\n  competition: {\n    id: string;\n    name: string;\n    type: string;\n    seasonId: string;\n    status: string;\n    hasFixtures: boolean;\n    fixtureCount: number;\n    fixturesCount: number; // Alias\n    currentMatchday: number;\n    isMatchdayOpen: boolean;\n    nextMatchdayOpenAt?: string;\n    matchdayOverrideStatus?: string;\n  };\n  totalTeams: number;\n  totalParticipants: number; // Alias\n  participantsCount: number; // Alias\n  expectedTeams: number; // Alias\n  participants: Array<{\n    clubId: string;\n    clubName: string;\n    badgeUrl?: string;\n    seedNumber?: number;\n    ownerUserId?: string;\n    ownerUsername?: string;\n  }>;\n  rounds: CupBracketRound[];\n  fixturesCount: number;\n  totalFixtures: number; // Alias\n  completedFixturesCount: number;\n  completedFixtures: number; // Alias\n  totalMatches: number; // Alias\n  completedMatches: number; // Alias\n  bracketStatus: 'NOT_GENERATED' | 'IN_PROGRESS' | 'COMPLETED';\n  currentRound?: number;\n  currentRoundName?: string;\n  isMatchdayLocked?: boolean;\n  source: 'firestore' | 'redis-lkg' | 'sqlite';\n  degraded: boolean;\n}\n\nexport interface BracketPreviewMatch {\n  roundNumber: number;\n  roundName: string;\n  matchIndex: number;\n  fixtureId: string;\n  homeClubId: string | null;\n  homeClubName: string;\n  awayClubId: string | null;\n  awayClubName: string;\n  homeClub?: { id: string | null; name: string } | null;\n  awayClub?: { id: string | null; name: string } | null;\n  sourceFixtureId?: string | null;\n  sourceWinnerSlot?: string | null;\n  homeSourceFixtureId?: string | null;\n  awaySourceFixtureId?: string | null;\n  homeSourceWinnerSlot?: string | null;\n  awaySourceWinnerSlot?: string | null;\n}\n\nexport interface BracketPreviewRound {\n  roundNumber: number;\n  roundName: string;\n  matchesCount: number;\n  totalMatches: number;\n  pairings: Array<{\n    homeClub: { id: string | null; name: string };\n    awayClub: { id: string | null; name: string };\n    fixtureId?: string;\n  }>;\n  matches: BracketPreviewMatch[];\n}\n\nexport interface BracketPreviewResult {\n  competitionId: string;\n  competitionName: string;\n  totalTeams: number;\n  totalParticipants: number; // Alias\n  prelimMatches: number;\n  byeTeamsCount: number;\n  totalRounds: number;\n  roundsCount: number; // Alias\n  existingFixturesCount: number;\n  canGenerate: boolean;\n  blockReason?: string;\n  previewMatches: BracketPreviewMatch[];\n  rounds: BracketPreviewRound[];\n}\n\n/**\n * Returns complete domestic cup details including bracket nodes, participants, and matchday controls.\n */\nexport async function getDomesticCupDetails(\n  competitionId: string,\n  seasonId = 'season-2026-27'\n): Promise<DomesticCupDetails> {\n  const cupConfig = validateDomesticCupId(competitionId);\n\n  // 1. Try tiered read from Read Model (Memory -> Fresh Redis -> Firestore -> LKG Redis)\n  const cacheKey = `cup:bracket:${competitionId}:${seasonId}`;\n  const rawLkg = await redisGetRaw<DomesticCupDetails>(cacheKey);\n\n  if (rawLkg?.data && (!firestoreCircuitBreaker.canExecute() || rawLkg.data.rounds?.length > 0)) {\n    // If circuit breaker is open or we have valid LKG data\n    if (!firestoreCircuitBreaker.canExecute()) {\n      return {\n        ...rawLkg.data,\n        source: 'redis-lkg',\n        degraded: true,\n      };\n    }\n  }\n\n  // 2. Fetch authoritative details from Firestore\n  try {\n    const db = getFirestoreDb();\n    const [compDoc, partSnap, fixSnap, occSnap] = await Promise.all([\n      db.collection(COLLECTIONS.COMPETITIONS).doc(competitionId).get(),\n      db.collection(COLLECTIONS.COMPETITION_PARTICIPANTS).where('competitionId', '==', competitionId).get(),\n      db.collection(COLLECTIONS.FIXTURES).where('competitionId', '==', competitionId).get(),\n      db.collection(COLLECTIONS.CLUB_OCCUPANCIES).where('seasonId', '==', seasonId).get(),\n    ]);\n\n    const compData = compDoc.exists ? (compDoc.data() as FirestoreCompetitionDoc) : null;\n    const occupancyUserMap = new Map<string, string>();\n    for (const d of occSnap.docs) {\n      const occ = d.data();\n      if (occ.clubId && occ.userId) {\n        occupancyUserMap.set(occ.clubId, occ.userId);\n      }\n    }\n\n    const clubsMap = new Map(SEED_CLUBS.map((c) => [c.id, c]));\n\n    // Participants\n    const participants: DomesticCupDetails['participants'] = [];\n    if (!partSnap.empty) {\n      for (const d of partSnap.docs) {\n        const part = d.data() as FirestoreCompetitionParticipantDoc;\n        const club = clubsMap.get(part.clubId);\n        participants.push({\n          clubId: part.clubId,\n          clubName: club?.name || part.clubId,\n          badgeUrl: club?.logoUrl,\n          seedNumber: part.seedNumber,\n          ownerUserId: part.ownerUserId || occupancyUserMap.get(part.clubId),\n        });\n      }\n    } else {\n      // Fallback: populate from league clubs\n      const leagueClubs = SEED_CLUBS.filter((c) => c.leagueId === cupConfig.leagueId);\n      for (const c of leagueClubs) {\n        participants.push({\n          clubId: c.id,\n          clubName: c.name,\n          badgeUrl: c.logoUrl,\n          ownerUserId: occupancyUserMap.get(c.id),\n        });\n      }\n    }\n\n    // Fixtures & Rounds\n    const fixtures = fixSnap.docs.map((d) => d.data() as FirestoreFixtureDoc);\n    const roundMap = new Map<number, CupBracketNode[]>();\n\n    const getRoundTitle = (md: number, totalRounds: number) => {\n      if (md === totalRounds) return 'Final';\n      if (md === totalRounds - 1) return 'Semi-Finals';\n      if (md === totalRounds - 2) return 'Quarter-Finals';\n      if (md === totalRounds - 3) return 'Round of 16';\n      return `Round ${md}`;\n    };\n\n    const maxMatchday = Math.max(1, ...fixtures.map((f) => f.matchday || 1));\n\n    for (const f of fixtures) {\n      const md = f.matchday || 1;\n      const rawHomeId = f.homeClubId;\n      const rawAwayId = f.awayClubId;\n      const homeClubId = (!rawHomeId || rawHomeId === 'TBD') ? null : rawHomeId;\n      const awayClubId = (!rawAwayId || rawAwayId === 'TBD') ? null : rawAwayId;\n      const homeClub = homeClubId ? clubsMap.get(homeClubId) : null;\n      const awayClub = awayClubId ? clubsMap.get(awayClubId) : null;\n      const winnerClub = f.winnerClubId ? clubsMap.get(f.winnerClubId) : null;\n\n      const node: CupBracketNode = {\n        id: f.id,\n        fixtureId: f.id,\n        matchday: md,\n        roundName: f.roundName || getRoundTitle(md, maxMatchday),\n        homeClubId,\n        homeClubName: homeClub?.name || 'TBD',\n        homeClubBadge: homeClub?.logoUrl,\n        awayClubId,\n        awayClubName: awayClub?.name || 'TBD',\n        awayClubBadge: awayClub?.logoUrl,\n        status: f.status,\n        homeScore: f.homeScore,\n        awayScore: f.awayScore,\n        homePenaltyScore: (f as any).homePenaltyScore ?? null,\n        awayPenaltyScore: (f as any).awayPenaltyScore ?? null,\n        winnerClubId: f.winnerClubId,\n        winnerClubName: winnerClub?.name,\n        scheduledAt: f.scheduledAt,\n        resultConfirmedAt: f.resultConfirmedAt || null,\n        sourceFixtureId: (f as any).sourceFixtureId || null,\n        sourceWinnerSlot: (f as any).sourceWinnerSlot || null,\n        homeSourceFixtureId: (f as any).homeSourceFixtureId || null,\n        awaySourceFixtureId: (f as any).awaySourceFixtureId || null,\n        homeSourceWinnerSlot: (f as any).homeSourceWinnerSlot || null,\n        awaySourceWinnerSlot: (f as any).awaySourceWinnerSlot || null,\n      };\n\n      if (!roundMap.has(md)) {\n        roundMap.set(md, []);\n      }\n      roundMap.get(md)!.push(node);\n    }\n\n    const rounds: CupBracketRound[] = Array.from(roundMap.entries())\n      .sort(([a], [b]) => a - b)\n      .map(([roundNumber, matches]) => {\n        const sortedMatches = matches.sort((a, b) => a.fixtureId.localeCompare(b.fixtureId));\n        const completedCount = sortedMatches.filter((m) => m.status === 'CONFIRMED').length;\n        return {\n          roundNumber,\n          roundName: sortedMatches[0]?.roundName || `Round ${roundNumber}`,\n          matches: sortedMatches,\n          fixtures: sortedMatches,\n          matchesCount: sortedMatches.length,\n          totalMatches: sortedMatches.length,\n          completedCount,\n          completedMatches: completedCount,\n        };\n      });\n\n    const completedCount = fixtures.filter((f) => f.status === 'CONFIRMED').length;\n    const bracketStatus = fixtures.length === 0\n      ? 'NOT_GENERATED'\n      : (completedCount === fixtures.length ? 'COMPLETED' : 'IN_PROGRESS');\n\n    const result: DomesticCupDetails = {\n      competition: {\n        id: competitionId,\n        name: compData?.name || cupConfig.name,\n        type: compData?.type || 'KNOCKOUT',\n        seasonId: compData?.seasonId || seasonId,\n        status: compData?.status || 'active',\n        hasFixtures: fixtures.length > 0,\n        fixtureCount: fixtures.length,\n        fixturesCount: fixtures.length,\n        currentMatchday: compData?.currentMatchday || 1,\n        isMatchdayOpen: compData?.isMatchdayOpen ?? true,\n        nextMatchdayOpenAt: comp